-- =========================================================
-- Playas - H2 in-memory database (Oracle compatibility mode)
-- Loaded automatically on startup by util.JPAUtil
-- =========================================================
DROP ALL OBJECTS;

CREATE TABLE CCAA (ID NUMBER(2) NOT NULL, NOMBRE VARCHAR2(255), PRIMARY KEY (ID));
CREATE TABLE PROVINCIA (ID NUMBER(2) NOT NULL, NOMBRE VARCHAR2(255), CCAA NUMBER(2), PRIMARY KEY (ID));
CREATE TABLE MUNICIPIO (ID NUMBER(5) NOT NULL, NOMBRE VARCHAR2(255), PROVINCIA NUMBER(2), PRIMARY KEY (ID));
CREATE TABLE PLAYA (ID NUMBER(6) NOT NULL, NOMBRE VARCHAR2(255), DESCRIPCION VARCHAR2(2048), MUNICIPIO NUMBER(5), PRIMARY KEY (ID));
CREATE TABLE IMAGES (ID NUMBER(6) NOT NULL, PLAYA NUMBER(6), PRIMARY KEY (ID));
CREATE TABLE USUARIO (ID NUMBER(4) NOT NULL, NICK VARCHAR2(64), PASS VARCHAR2(64), PRIMARY KEY (ID));
CREATE TABLE PUNTO (ID NUMBER(6) NOT NULL, USUARIO NUMBER(4), PLAYA NUMBER(6), PUNTOS NUMBER(1), PRIMARY KEY (ID));

-- Replace the Oracle triggers AUTOPUNTO / AUTOUSUARIO (JPA now uses these sequences directly)
CREATE SEQUENCE SEQ_USUARIO START WITH 2 INCREMENT BY 1;
CREATE SEQUENCE SEQ_PUNTO START WITH 63 INCREMENT BY 1;

