-- Foreign keys
ALTER TABLE PROVINCIA ADD FOREIGN KEY (CCAA) REFERENCES CCAA (ID);
ALTER TABLE MUNICIPIO ADD FOREIGN KEY (PROVINCIA) REFERENCES PROVINCIA (ID);
ALTER TABLE PLAYA ADD FOREIGN KEY (MUNICIPIO) REFERENCES MUNICIPIO (ID);
ALTER TABLE IMAGES ADD FOREIGN KEY (PLAYA) REFERENCES PLAYA (ID);
ALTER TABLE PUNTO ADD FOREIGN KEY (PLAYA) REFERENCES PLAYA (ID);
ALTER TABLE PUNTO ADD FOREIGN KEY (USUARIO) REFERENCES USUARIO (ID);
