INSERT INTO MUNICIPIO (ID, NOMBRE, PROVINCIA) VALUES (48913, 'Zierbena', 48);
INSERT INTO MUNICIPIO (ID, NOMBRE, PROVINCIA) VALUES (48043, 'Gorliz', 48);
INSERT INTO MUNICIPIO (ID, NOMBRE, PROVINCIA) VALUES (48057, 'Lekeitio', 48);
INSERT INTO MUNICIPIO (ID, NOMBRE, PROVINCIA) VALUES (48077, 'Plentzia', 48);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1, 'Cala Junco', 'Playa rodeada de invernaderos que le restan atractivo, por lo que carece de cualquier servicio para su uso turístico. Se accede por un camino de tierra con una cuesta pronunciada', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2, 'Censo', 'Playa objeto de regeneración medioambiental en 2001. Dispone de paseo marítimo y carril bici.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3, 'El Lance de la Virgen', 'Esta playa de grava y arena se encuentra situada junto al pueblo de El Lance de la Virgen, pero tiene mucha afluencia de turismo.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (4, 'Guainos', 'Playa de arena oscura con un entorno descuidado y muy poco utilizada por bañistas y visitantes.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (5, 'La Alcazaba', 'Pequeña playa de arena negra con muy poca afluencia de visitantes y ausencia total de instalaciones y servicios. ', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (6, 'La Caracola', 'Playa de arena y grava que dispone de paseo marítimo y servicios básicos.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (7, 'La Gaviota', 'Playa carente de infraestructuras y atractivo turístico.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (8, 'La Habana', 'La Playa de la Habana se encuentra actualmente en regresión debido al mal estado de su entorno natural y a la abundancia de invernaderos que se amontonan en la zona.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (9, 'La Juana', 'Playa de difícil acceso ubicada al borde de unos acantilados, muy poco utilizada para el baño, donde predominan los invernaderos de plásticos que caracterizan la zona.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (10, 'Playa de Poniente', 'Extensa playa con un alto grado de ocupación por la cantidad de servicios que ofrece y por ser una de las playas más limpias de la zona.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (11, 'San Nicolás', 'Playa ubicada junto al Puerto de Adra, que cuenta con todo tipo de infraestructuras propias de una playa urbana.', 4003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (12, 'Costacabana', 'La Playa de Costacabana está localizada muy cerca del aeropuerto. Compuesta de arena gruesa y grava, cuenta con un paseo marítimo.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (13, 'El Bobar', 'Playa poco apreciada para su uso público, tanto por su composición como por su localización, muy próxima a la carretera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (14, 'El Perdigal', 'Playa en estado virgen, muy tranquila.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (15, 'El Toyo', 'Playa urbana continuación de la playa de Retamar. Regenerada con motivo de los Juegos del Mediterráneo (2005).', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (16, 'La Almadraba de Monteleva', 'Esta playa de arena se encuentra en el poblado de La Almadraba de Monteleva y es la continuación de la Playa de Las Salinas de Cabo de Gata. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (17, 'La Fabriquilla', 'Es la última playa del término municipal de Almería, lindando con Níjar, y se caracteriza por resultar muy tranquila para los bañistas. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (18, 'La Garrofa', 'Pequeña playa de grava. Se accede a través de una propiedad privada, el camping La Garrofa, que cuenta con un club de buceo.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (19, 'Las Amoladeras', 'Esta playa se localiza dentro de los límites del Parque Natural del Cabo de Gata-Níjar, por lo que se encuentra protegida. Recientemente ha sido declarado Reserva de la Biosfera. En el extremo próximo a Torre García se encuentran los restos romanos de una antigua fábrica de Salazón.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (20, 'Las Olas', 'Playa carente de interés por el estado de su entorno natural algo deficiente.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (21, 'Las Salinas de Cabo de Gata', 'Playa con una excelente arena, localizada muy cerca de una zona de marismas por lo que alberga gran cantidad de aves muy interesantes. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (22, 'Nueva Almería', 'Esta playa se encuentra unida a la Playa de San Miguel, y comparte todos sus servicios, instalaciones y ofertas de ocio.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (23, 'Retamar', 'La Playa de Retamar toma su nombre de una urbanización cercana, y cuenta con los equipamientos propios de una playa preparada para el turismo.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (24, 'Zapillo', 'Playa urbana que presenta un elevado grado de ocupación y dotada de infraestructuras, servicios y ofertas de ocio muy atractivas para el turismo.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (25, 'San Miguel de Cabo de Gata', 'Playa tranquila de excelente calidad con buenos servicios y entorno natural privilegiado. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar. Declarada Reserva de la Biosfera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (26, 'San Telmo', 'Playa de difícil acceso por un terraplén pronunciado algo peligroso que carece de cualquier tipo de servicio. ', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (27, 'Torregarcía', 'Esta playa debe su nombre al Santuario Torre García, situado en la misma playa, y está ubicada en el límite sur del Parque Natural del Cabo de Gata-Níjar. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (28, 'Balanegra', 'Única playa en el término municipal de Berja. Se encuentra ubicada en una zona semiurbana donde abundan los invernaderos de plásticos.', 4029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (29, 'El Algarrobico', 'Playa aislada en estado casi virgen donde se puede disfrutar de aguas cristalinas y una gran tranquilidad. Perteneciente al Parque Natural Marítimo Terrestre Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (30, 'El Ancón', 'Playa urbana con gran calidad y disponibilidad de sus servicios e infraestructuras.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (31, 'La Galera', 'Playa con una composición muy irregular, en la que se alternan piedras con arena de color gris y grava. Recibe a un reducido número de bañistas.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (32, 'Las Martinicas', 'La Playa de las Martinicas se sitúa entre el puerto industrial y el puerto pesquero de Carboneras y tiene una gran afluencia de practicantes de submarinismo.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (33, 'Los Barquicos', 'Playa urbana localizada en pleno casco urbano del pueblo de Carboneras.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (34, 'Los Muertos', 'La Playa de los Muertos se localiza en el límite norte del Parque Natural de Cabo de Gata y se encuentra muy cercana a una fábrica de cemento. Pertenece al Parque Natural Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de La Biosfera.', 4032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (53, 'El Palmer', 'Playa de piedras que dispone de los servicios que ofrece el único hotel cercano a la playa y que son de uso exclusivo para sus clientes. La playa esta ocupada parcialmente por una escollera.', 4041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (54, 'Garrucha', 'Playa totalmente equipada y con servicios de calidad.', 4049);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (300401, 'Bordenares', 'Esta playa se encuentra apartada de núcleos urbanos y con un bajo grado de ocupación.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (56, 'Cueva del Lobo', 'Playa localizada en el complejo turístico de Pueblo Indalo, totalmente equipada.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (57, 'El Cantal', 'Playa de carácter urbano que dispone de todo tipo de servicios e instalaciones que contribuyen al alto grado de ocupación que presenta. ', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (58, 'El Descargador', 'Playa con gran afluencia que dispone de todo el equipamiento necesario para el uso público.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (59, 'El Sombrerico', 'La Playa del Sombrerico se encuentra apartada de núcleos urbanos y con un bajo grado de ocupación.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (60, 'La Rumina', 'Playa de arena gris y grava, ubicada en un entorno urbano de casas bajas conocidas como El Palmeral y que presenta un alto grado de ocupación.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (61, 'Las Granatillas', 'Pequeña playa aislada carente de cualquier tipo de infraestructura ni servicio de uso público, pero que presenta la peculiaridad del color rojizo de su arena.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (62, 'Marina de la Torre', 'Playa de arena gris que cuenta con un buen equipamiento para el uso del público que la visita.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (55, 'Castillo de Macenas', 'Extensa playa de rocas y arena gris con un buen entorno natural, pero que no presenta gran afluencia de visitantes.', 4064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (68, 'Cala Chica', 'Playa aislada con un difícil acceso a través de caminos de tierra entre montañas escarpadas, lo que hace que presente un bajo grado de ocupación. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (69, 'Cala de Enmedio', 'La Cala de Enmedio tiene difícil acceso a través de caminos de tierra, ofreciendo un entorno privilegiado de aguas cristalinas, excelente arena y mucha tranquilidad. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (84, 'Los Genoveses', 'Excelente playa de algo más de un kilómetro, rodeada de vegetación (eucaliptos), y donde puede practicarse el submarinismo. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (85, 'Peñón Blanco', 'Playa frecuentada por caravanas de veraneantes situada frente al peñón de la Isleta del Moro, nombre con el que también se le conoce a la playa. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (86, 'Playazo de Rodalquilar', 'Playa de arena fina en pleno desierto de Almería, a la que se accede desde un camino de tierra cercano al pueblo de Rodalquilar. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (87, 'San José', 'Playa ubicada en el pueblo de San José, con buenos servicios y equipamientos para el uso turístico. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar. Declarada Reserva de la Biosfera y Zona especialmente protegida de importancia para el Mediterráneo.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (63, 'Aguamarga', 'La Playa de Aguamarga dispone de los servicios e instalaciones necesarias para el veraneo familiar. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (64, 'Ancón de Cabo de Gata', 'Playa virgen que puede verse desde lo alto de la carretera que recorre el Cabo de Gata con unas bonitas vistas. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (65, 'Cala Arena', 'Playa de difícil acceso localizada en una zona aislada entre acantilados. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (66, 'Calas del Barronal', 'Playa rústica de carácter aislado a la que se accede caminando por caminos de tierra y bordeando las calas contiguas. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (67, 'Cala Carbón', 'La Cala Carbón es otra de las pequeñas calas incluidas en el Parque Natural de Cabo de Gata, aislada y con difícil acceso a través de caminos de tierra. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de La Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (70, 'Cala de la Media Luna', 'Pequeña cala de arena muy frecuentada por bañistas, aunque se encuentra en una zona aislada y carente de servicios. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (71, 'Cala de la Polacra', 'Playa ubicada dentro del Parque Natural de Cabo de Gata, aislada, de difícil acceso y con una baja afluencia de visitantes. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (72, 'Cala de los Amarillos', 'Pequeña playa rodeada de grandes acantilados a la que se puede acceder desde la Playa de Los Genoveses. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (73, 'Cala de Mónsul', 'Junto con la Playa de Los Genoveses, es una de las playas más conocidas y con mayor afluencia de las localizadas dentro del Parque Natural de Cabo de Gata . Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (74, 'Cala del Carnaje', 'Recóndita playa frecuentada por pescadores con caña y a la que se accede caminando un largo trecho por caminos de tierra. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (75, 'Cala del Cuervo', 'Playa aislada en la que se ubica un camping y que presenta un bajo nivel de ocupación. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (76, 'Cala del Plomo', 'Pequeña playa de arena y piedras a la que, a pesar de encontrarse aislada de cualquier asentamiento urbano, se puede llegar en coche. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (77, 'Cala Higuera', 'Playa compuesta de piedras que no guarda ningún atractivo desde el punto de vista del turismo. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (78, 'Cala Príncipe', 'A Cala Príncipe se accede tras caminar alrededor de un kilómetro por caminos escarpados que conducen a esta pequeña y tranquila cala virgen. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (79, 'Cala Rajá', 'Cala de difícil acceso a través de un camino que hay que recorrer a pie, aislada y con un bajo grado de ocupación. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (80, 'Cala San Pedro', 'Playa aislada con muy poca afluencia de visitantes puesto que para acceder hay que caminar más de 3 kilómetros por senderos de tierra. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (81, 'El Arco', 'Playa de arena localizada dentro del Parque Natural de Cabo de Gata que no presenta especial interés turístico. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (82, 'El Embarcadero', 'Playa de piedras que suele ser frecuentada por equipos de submarinistas al ser sus fondos marinos el atractivo principal de esta desértica playa. Pertenece al Parque Natural Marítimo terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (83, 'Las Negras', 'Playa rodeada de un paisaje con mucho encanto, ya que se encuentra abrigada por el pequeño y pintoresco pueblo de las Negras. Pertenece al Parque Natural Marítimo Terrestre de Cabo de Gata-Níjar, recientemente declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (300402, 'Cala del Bergantín', 'Playa apartada de núcleos urbanos y con bajo grado de ocupación. Su acceso es por un sendero desde el playazo de Rodalquilar y pertenece al Parque Natural Marítimo Terreste de Cabo de Gata-Níjar. Recientemente ha sido declarado Reserva de la Biosfera.', 4066);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (161, 'Punta Candor', 'Playa amplia de arena dorada, salvaje y muy cuidada, con una longitud de un kilómetro y medio que se encuentra rodeada de vegetación natural en toda su extensión.', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (156, 'Aguadulce', 'Contigua a Playa Ballena. Playa de carácter aislado con un bajo grado de ocupación y con total ausencia de instalaciones y servicios disponibles para su uso público.', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (157, 'El Rompidillo', 'Playa urbana localizada entre el Puerto de Rota y el Puerto Militar, donde sopla un fuerte viento, por lo que resulta muy interesante para los aficionados al Wind-Surf y a la vela.', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (158, 'La Ballena', 'Playa de arena de gran extensión que dispone de una gran cantidad de servicios e instalaciones, así como de alquiler de hamacas, sombrillas, o incluso de embarcaciones náuticas. El extremo norte de esta playa es lo que se tiende a denominar ''Las Tres Piedras''', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (159, 'La Costilla', 'La Playa de la Costilla es posiblemente la playa más concurrida de Rota, ya que se encuentra ubicada en el mismo casco urbano y dispone de todo tipo de servicios.', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (301101, 'Galeones', 'Playa urbana localizada entre Pico Barro  (terminación de la playa del Rompidillo) y el dique de la separación de la Base Naval (playa del Almirante)', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (162, 'Camposoto', 'Playa rústica ubicada en un entorno plano y semisalvaje donde el viento sopla con intensidad y a la que se llega en coche atravesando las marismas. Está dividida en dos tramos: Camposoto, con más servicios y menos salvaje, y El Castillo, más natural.', 11031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (163, 'El Castillo', 'La Playa del Castillo es una continuación de la Playa Camposoto, en estado natural con dunas y marismas de gran valor paisajístico y solo accesible a pie desde dicha playa o a nado desde Sancti-Petri, lo que la convierte en una de las playas más apreciadas por su estado natural virgen.', 11031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201101, 'Playa de la Casería', 'Playa de fango, poco arenosa. Se encuentra al noroeste de San Fernando, bañada por las aguas de la Bahía', 11031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (171, 'Bajo de Guía', 'La Playa Bajo de Guía de arena fina y dorada resulta excelente para la práctica de la vela o cualquier otro deporte relacionado con el viento. ', 11032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (172, 'La Calzada', 'La Playa de La Calzada es una playa muy ancha, donde se realizan las famosas carreras de caballos organizadas todos los veranos, por lo que también se la conoce como El Hipódromo. También se encuentran referencias a ella como Playa de La Media Legua y Playa de Las Piletas.', 11032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (173, 'La Jara', 'La Playa de la Jara se encuentra protegida por unos macizos rocosos que la convierten en una playa muy tranquila donde resulta fácil la navegación de embarcaciones de recreo. ', 11032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (174, 'Bonanza', 'Esta playa está ubicada en la desembocadura del Río Guadalquivir, donde se encuentran las Salinas y Marismas que pertenecen al espacio protegido del Entorno de Doñana. ', 11032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (147, 'La Alcaidesa', 'A esta playa se accede desde la urbanización de La Alcaidesa, y dispone de todos los servicios que le proporciona la misma urbanización, incluido un gran campo de golf.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (150, 'La Hacienda', 'Playa de gran extensión y arena gris carente de servicios. Únicamente tiene como característica destacable la gran tranquilidad que reina en la zona.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (164, 'Campamento', 'Playa ubicada entre las barriadas de Campamento y  Puente Mayorga, a las afueras de Algeciras. Cuenta con aseos, teléfono, papeleras, sillas anfibias para discapacitados y servicio de limpieza diaria.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (165, 'El Cabrero', 'Playa virgen de arena oscura situada a las afueras de Torreguadiaro, que dispone de una gran explanada a lo largo de la playa donde suelen situarse autocaravanas.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (166, 'Guadalquitón', 'Playa de gran extensión aislada de cualquier núcleo urbano y carente de todo tipo de servicios. En la zona de Guadalquitón se han encontrado restos arqueológicos, además de ser el último bosque de alcornoques junto al litoral mediterráneo en Europa.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (167, 'Guadarranque', 'Playa ubicada en la barriada de Guadarranque, a las afueras de Algeciras, en un entorno  industrial y bastante descuidado. En loa alrededores se localiza el Yacimiento Arqueológico de Carteia', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (168, 'Sotogrande', 'La Playa de Sotogrande destaca por su urbanización exclusiva, donde se practican cantidad de deportes y presenta una variada gama de opciones para el ocio.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (169, 'Torrecarbonera', 'La Playa de Torrecarbonera es una playa con un entorno en estado natural, muy apropiada para apartarse un poco de la civilización ya que su principal característica es el aislamiento que se respira en ella.', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (170, 'Torreguadiaro', 'La Playa de Torreguadiaro es una playa de arena y pequeñas piedras ubicada en una zona de pescadores en la que destacan los lujosos apartamentos de Sotogrande y su Puerto Deportivo. ', 11033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (183, 'El Palmar', 'Playa kilométrica donde puede disfrutarse de una gran tranquilidad alterada únicamente por el viento de la zona, ideal para practicar el Wind-Surf.', 11039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201106, 'Playa Mangueta', 'Playa aislada, con vegetación dispersa.l', 11039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (117, 'Cortadura', 'Playa muy próxima a la autovía a las afueras de Cádiz, en la que se forman unas dunas características con una excelente superficie de arena.', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (118, 'El Chato', 'Esta playa, junto con la Playa de la Anegada, también se conoce con el nombre de Playa Urrutia y está localizada entre la Playa Cortadura y la Playa de Camposoto, siendo el acceso a través de la primera. ', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (119, 'La Anegada', 'La Playa de la Anegada es una playa en estado natural, con su superficie en dos niveles y muy irregular, que forma parte de una zona militar donde está restringido el paso.', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (120, 'La Caleta', 'Es la playa más frecuentada de Cádiz ya que esta en pleno casco urbano y cuenta con todo tipo de servicios.', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (121, 'La Victoria', 'Es el arenal de Cádiz por excelencia, siendo una playa muy concurrida por todos los servicios con que cuentan los bañistas.', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (122, 'Santa María del Mar', 'Santa María del Mar es la playa más pequeña y recogida de todas a la que se accede por rampas o por las escaleras en forma de caracol que separan esta playa de la Playa de la Victoria.', 11012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (123, 'El Puerco', 'Es la continuación de la Playa de la Barrosa, aunque en este caso apenas cuenta con servicios. Está resguardada por pequeños acantilados con escaleras de acceso a la playa.', 11015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (124, 'La Barrosa', 'Playa urbanizada y muy frecuentada, aunque recomendable por resultar muy cómoda por la amplitud y variedad de servicios disponibles, así como por la calidad de su arena.', 11015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (125, 'Sancti-Petri', 'Fantástica playa para la práctica del Wind-Surf, sobre todo cerca del puerto pesquero, donde se forman espectaculares corrientes de viento entre esta playa y la del Castillo. En la zona residencial es idónea para la práctica de submarinismo y la pesca.', 11015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (126, 'Punta de Piedras', 'La Playa Punta de Piedras es una playa en estado natural, con dunas, pinares costeros y acantilados de gran belleza. ', 11015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (94, 'Los Nardos', 'Playa de tamaño mediano donde se alternan rocas, grava y arena y que resulta muy poco turística. ', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (95, 'Mar Rabiosa', 'Playa urbana situada frente a un pequeño islote, accesible a pie cuando baja la marea, que se conoce como El Pichirrichi.', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (96, 'Mar Serena', 'El nombre de la playa apunta la principal característica de la misma, razón por lo que acoge una gran cantidad de bañistas, que es la tranquilidad de sus aguas.', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (88, 'Cala Cerrada', 'Cala aislada en forma de concha muy atractiva por las rocas que la forman y sobre todo por la transparencia de sus aguas.', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (89, 'Cala Cuartel', 'Pequeña cala tranquila y agradable ubicada en una zona residencial del pueblo de San Juan de los Terrenos.', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (90, 'Cala de la Tía Antonia', 'Pequeña cala de arena dorada muy frecuentada por familias y habitantes del pueblo en el que se encuentra, San Juan de los Terrenos. ', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (91, 'Calipso', 'Pequeña playa urbanizada que presenta un elevado grado de ocupación.', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (92, 'La Carolina', 'Playa ubicada muy cerca del pueblo de San Juan de los Terrenos carente de servicios e infraestructuras. ', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (93, 'La Entrevista', 'Playa ubicada entre los núcleos urbanos de Pozo del Esparto y Bellavista, carente de interés desde el punto de vista turístico. La vegetación presente en las inmediaciones de la playa es un palmeral (Phoenix dactilífera)', 4075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (105, 'El Playazo', 'El Playazo es de las playas más destacadas de la zona por disponer de un completo aquipamiento para el uso turístico.', 4100);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (106, 'Las Marinas', 'La Playa de las Marinas está dotada con todo tipo de servicios e infraestructuras.', 4100);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (107, 'Puerto Rey', 'Playa de gran longitud y carácter urbano con total disponibilidad de equipamientos y servicios que hacen que cuente con un elevado grado de ocupación, sobre todo durante el periodo estival.', 4100);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (47, 'Levante Almerimar', 'Playa regenerada con arena de color oscuro que dispone de gran cantidad de servicios para el uso público.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (48, 'Poniente Almerimar', 'Playa regenerada con arena de color oscuro que dispone de gran cantidad de servicios para el uso público.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100401, 'San Miguel', 'Playa dotada de todo tipo de servicios. Playa caracterizada por el sistema dunar y la vegetación que la constituyen. Fondo de Poseidonias.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100402, 'Punta Entinas Sabinar', 'Playa muy tranquila localizada en el entorno protegido de Punta Entinas Sabinar, en una zona carente de cualquier tipo de construcción. Pertenece al Paraje Natural Punta Entinas Sabinar. Ocupa los términos municipales de El Ejido y Roquetas de Mar.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (49, 'Balerma', 'Playa compuesta de piedras de pequeño tamaño a la qua acuden los veraneantes de la ciudad de El Ejido.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (50, 'Cerrillos', 'Playa muy tranquila, en el entorno protegido de Punta Entinas Sabinar, carente de cualquier tipo de construcción. Aunque no posee explícitamente un área reservada para submarinismo, la zona tiene fondos marinos de gran interés. La playa continúa en el T.M. de Roquetas de Mar.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (51, 'Los Baños - Punta de Baños', 'Playa de baja calidad debido al estado del entorno natural, y al poco atractivo que presenta. Es propicia para la práctica del Surf dada su ubicación en el tramo de Punta de culo de perro.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (52, 'Peña del Moro', 'Playa localizada en la Punta del Moro, desde donde puede verse un castillo del siglo XVIII que constituye el principal atractivo de la zona.', 4902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (35, 'Cabezo Negro', 'Pequeña cala de piedras y de difícil acceso que destaca por sus aguas transparentes y la tranquilidad del entorno. ', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (36, 'Cala Cristal', 'Aunque no existe una zona reservada especialmente para el submarinismo, la Cala Cristal resulta muy recomendable para la práctica del buceo y la pesca por la cantidad de rocas que presenta. ', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (41, 'Embarcadero Viejo', 'El Embarcadero Viejo acoge unas ruinas mineras que constituyen la única edificación que se encuentra en la playa. Recomendable para la pesca y el buceo.', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (42, 'Fábrica del Duro', 'Esta playa se encuentra en la misma desembocadura del río Almanzora, en su margen izquierda, y se caracteriza por su tranquilidad y buen entorno natural. La vegetación cercana a la playa está representada, sobre todo, por vegetación halófila (carrizos)', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (43, 'Peñón Cortado', 'Cala ubicada entre rocas de difícil acceso, muy interesante por las formas que adoptan las rocas, así como por la claridad de sus aguas. ', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (44, 'Pozo del Esparto', 'Esta playa de carácter urbano toma su nombre del núcleo urbano de Pozo del Esparto que se extiende a lo largo de toda la franja de arena y grava. ', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (45, 'Quitapellejos', 'Playa de arena y grava ubicada en una zona aislada de edificaciones, en la que no se registra gran afluencia de gente.', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (46, 'Villaricos', 'La Playa de Villaricos tiene su extremo sur en la desembocadura del río Almanzora, y agrupa pequeñas calas, por pertenecer todas ellas al mismo núcleo urbano. Agrupa las playas de Cala de la Esperanza, Cala Verde y Villaricos (Cala de la Luz Eléctrica)', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (37, 'Cala de la Dolores', 'La Cala de la Dolores carece de interés turístico y presenta un aspecto poco acogedor por el estado de su entorno natural. ', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (38, 'Cala Invencible', 'Cala bastante rocosa con interés para los que quieran observar los fondos marinos. Existe un mirador - paseo marítimo parcial - junto antiguo Cuartel de la Guardia Civil', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (39, 'Cala Panizo', 'La Cala Panizo se localiza junto a un complejo urbanístico conocido como El Portichuelo, aunque carece de infraestructuras y servicios de playa.', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (40, 'El Calón', 'Playa de arena negra rodeada de una zona residencial, pero carente de servicios e instalaciones.', 4035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (97, 'Aguadulce', 'La Playa de Aguadulce es una de las playas con mayor grado de ocupación del sur de Almería y que cuenta con una gran oferta de ocio para los turistas.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (98, 'Cerrillos', 'Playa de carácter aislado al encontrarse ubicada en el entorno protegido de Punta Entinas Sabinar. Pertenece al Paraje Natural Punta Entinas Sabinar. Esta playa continúa en el T.M. de El Ejido, con el mismo nombre. Existen praderas de Poseidonias en el fondo.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (99, 'La Bajadilla', 'Playa totalmente equipada, localizada a continuación de la playa  Urbanización Roquetas de Mar. Presenta un alto grado de ocupación, aunque sin saturaciones.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100, 'La Romanilla', 'Playa equipada con servicios propios de una playa urbanizada que presenta un elevado grado de ocupación.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101, 'Las Salinas', 'Playa tranquila en la que el viento sopla con fuerza, lo que hace que sea una idónea para la práctica de deportes como el surf.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (102, 'Los Bajos', 'Playa ventosa, carente de construcciones ni infraestructuras, a la que se accede por un camino de tierra que une Roquetas y Aguadulce. ', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103, 'Playa Serena', 'La playa Serena se extiende a lo largo del campo de golf de Roquetas y está dotada con todo tipo de servicios e instalaciones para su uso turístico.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (104, 'Urbanización Roquetas de Mar', 'Es una de las playas más equipadas de la zona, ubicada junto a un gran complejo urbanístico con todo tipo de ofertas para el ocio. Alta ocupación durante la época estival.', 4079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (110, 'Getares', 'Playa rodeada de montañas con mucha vegetación, que toma su nombre de la urbanización en la que se encuentra, y que cuenta con varios servicios que la hacen muy cómoda para su uso. ', 11004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (108, 'Cala Arenas', 'La Cala Arenas es una sucesión de tres calas de similares características compuestas de rocas y grava a las que se accede desde un camino con mucha vegetación que parte de la urbanización de Getares.', 11004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (109, 'El Rinconcillo', 'Se trata de la playa más grande de Algeciras. Su gran longitud y la disponibilidad de equipamientos y servicios la convierten en la playa más visitada por los habitantes de la zona.', 11004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (111, 'Cañillos', 'Playa rústica de gran extensión compuesta por arena fina. Con vientos muy fuertes, apenas existen equipamientos ni servicios disponibles.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (112, 'Caños de Meca', 'La Playa del Faro de Trafalgar,  situada dentro del entorno de Caños de Meca, cuenta con una extensa franja de arena dorada y aguas muy claras.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (113, 'El Carmen', 'Playa urbana situada al lado del Puerto de Barbate, con un gran paseo marítimo y muy bien equipada, donde se practica el Wind-Surf y la pesca con caña.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (114, 'Hierbabuena', 'Playa próxima al Puerto de Barbate, con vistas al Parque Natural de la Breña y Marismas de Barbate, con dunas de arena y frondosos pinares. Se practica, entre otros, el buceo, la pesca y el wind-surf.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (115, 'Zahara de los Atunes', 'Esta playa se extiende desde Zahara hasta el Cabo de Plata, donde toma el nombre de una bonita urbanización, La Atlanterra. Dispone de todo tipo de equipamientos para practicar la vela, el Wind-Surf y la pesca.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (116, 'Zahora', 'Excelente playa de arena fina y fuerte viento, con preciosas vistas del Cabo de Trafalgar. Adecuada para la práctica del surf, el Wind-Surf, la vela y la pesca.', 11007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (153, 'Palmones', 'Playa muy cercana a Algeciras rodeada de un entorno industrial que le resta atractivo. Paseo marítimo transversal a la playa, a lo largo de la desembocadura del río', 11008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (132, 'Cala del Aceite', 'Cala de arena fina y aguas turquesas resguardada del viento de la zona por unos acantilados y a la que se accede mediante unas escalerillas.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (133, 'Calas de Poniente', 'Como Calas de Poniente se conocen a siete calas de reducido tamaño en estado virgen: Cala Encendida, Cala Aspero, Cala Pato, Cala Medina y Cala Frailecillo, todas ellas de gran belleza y características similares.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (134, 'Calas del Quinto y Camacho', 'Las conocidas como Calas del Quinto son tres calas de reducido tamaño denominadas Cala Melchor, Cala Pitones y Cala Sudario, todas ellas en medio de un entorno natural y bordeadas por cortados de tierra rojiza.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (135, 'Castilnovo', 'La Playa de Castilnovo es una playa virgen, de aspecto salvaje, donde las olas y el viento tienen una gran fuerza para la práctica del Wind-Surf.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (136, 'Fuente del Gallo', 'Playa recorrida por un abrupto acantilado, donde desaparece por completo la arena durante la marea alta, y que resulta apta para la práctica del Wind-Surf. ', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (137, 'La Fontanilla', 'Comienza en el núcleo urbano de Conil hasta las calas de Cabo Roche. Dispone de gran variedad de servicios e instalaciones para el público.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (138, 'Los Bateles', 'Playa ubicada frente a Conil de la Frontera donde se puede disfrutar de una gran variedad de servicios, y que resulta muy recomendable para la práctica del Wind-Surf.', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (139, 'Roche', 'Playa de gran extensión y excelente arena ubicada en una tranquila zona de residencias unifamiliares, que apenas dispone de servicios y equipamientos para el uso del público. ', 11014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (127, 'Camarón', 'Playa de arena con gran cantidad de servicios e instalaciones disponibles para su uso público, y en la que se practican todo tipo de deportes: Wind-Surf, vela, golf, footing...', 11016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (128, 'Cruz del Mar', 'Playa muy visitada con todo tipo de servicios localizada en la parte sur del Puerto de Chipiona, lugar en el que se encuentran los típicos corrales de pesca.', 11016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (129, 'De Regla', 'Playa cosmopolita ubicada en pleno centro urbano de Chipiona junto al Monasterio de Nuestra Señora de Regla, con una gran oferta para el ocio', 11016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (130, 'Las Canteras', 'La Playa de las Canteras, ubicada en el Faro de Chipiona, presenta un sustrato rocoso de gran belleza natural utilizado como corrales de pesca, que no hace muy recomendable el baño debido a las rocas.  Zona ideal para la práctica del buceo con tubo.', 11016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (131, 'Montijo', 'La Playa del Montijo es una de las playas más rocosas de la zona. Las rocas se mezclan con arena blanca, dándole un aspecto rústico muy agradable para pasear a caballo.', 11016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (146, 'El Burgo', 'Esta playa se caracteriza por su gran dimensión y arena gris, siendo una zona tranquila. ', 11022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (148, 'La Atunara', 'Actualmente esta playa se conoce con el nombre de Sobrevela. Playa de oscura arena que alberga un Puerto Pesquero que recibe el mismo nombre.', 11022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (149, 'La Atunara', 'Playa situada entre la Playa de Santa Bárbara y la Playa de la Atunara, con poco atractivo turístico, pero bien equipada. ', 11022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (151, 'Playa de Levante', 'Playa de la ciudad, muy concurrida por visitantes y lugareños.', 11022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (152, 'Playa de Poniente', 'Reducida playa de arena muy próxima a la carretera frente a La Línea de la Concepción, lo que hace que sea muy transitada.', 11022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201107, 'La Calita', 'De aspecto salvaje, limpia y bien cuidada, que presenta salientes rocosos en el agua e intercalados en la arena, por lo que es ideal para la práctica de pesca con arpón y submarinismo. En las inmediaciones del Castillo de Santa Catalina, que la separa de la playa de La Muralla.', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (141, 'La Muralla', 'Se trata de una cala arenosa encajada entre acantilados, en las inmediaciones del Castillo de Santa Catalina, que la separa de la playa de La Calita.', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (142, 'La Puntilla', 'Playa ubicada en la desembocadura del Río Guadalete y separada de éste por un espigón, donde puede disfrutarse de unas aguas tranquilas para el baño, aunque resulta algo ventosa. Excelente para volar cometas.', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (143, 'Playa de Levante', 'La Playa de Los Toruños es una playa aislada de núcleos urbanos, en excelente estado ambiental, en el Parque Natural de la Bahía de Cádiz, donde sopla fuerte el viento y puede practicarse el deporte de vela y Wind-Surf. ', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (140, 'Fuentebravía', 'Esta playa se encuentra ubicada en una zona residencial de la cual toma su nombre, y que presenta un alto grado de ocupación. En ella puede practicarse el submarinismo, la pesca y el Wind-Surf. ', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (144, 'Santa Catalina', 'Playa de arena y de gran extensión que recibe un elevado número de visitantes, en la que puede disfrutarse de deportes náuticos, pesca, Wind-Surf, kayak, motonáutica, etc.', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (145, 'Valdelagrana', 'Playa muy conocida y visitada por el turismo que frecuenta esta zona de Cádiz, ya que dispone de todo tipo de equipamientos, servicios e infraestructuras para el uso del público. ', 11027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101101, 'Puntalillo', 'Situada entre playa Piedras Gordas/ Los Corrales y  La Costilla. Posee muy buenos equipamientos.', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (160, 'Piedras Gordas', 'Playa de arena, con cierto aspecto salvaje, desde donde puede contemplarse el Sistema Dunar de Rota, los Pinares Costeros protegidos por la Junta de Andalucía y los Corrales de Rota declarados Monumento Natural por la Junta de Andalucía..', 11030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (154, 'La Cachucha', 'Playa de arena dorada, situada en el núcleo urbano de Puerto Real, en la misma Bahía de Cádiz. ', 11028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201102, 'El Conchal', 'Playa familiar al resguardo de los vientos de Levante', 11028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201103, 'La Ministra', 'Playa familiar de la barriada de Río San Pedro', 11028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201104, 'Calita de la Bocana del Río', 'Playa excluida del Plan de Playas por tener mucha corriente sus aguas. Utilizada por pescadores', 11028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201105, 'La Media Luneta', 'Playa en el núcleo urbano de Puerto Real, de arena dorada.', 11028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (175, 'Atlanterra', 'Es la continuación de la Playa de Zahara de los Atunes. También conocida con el nombre de Atlanterra, que toma de una urbanización cercana de casas unifamiliares en el Cabo de la Plata . Dispone de todos los servicios.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (176, 'Bolonia', 'Esta playa salvaje de arena blanca esta considerada como el paraíso del Wind-Surf por el fuerte viento que reina. Protegida por la Junta de Andalucía.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (177, 'El Cañuelo', 'La Playa del Cañuelo es una playa con un entorno en estado natural, con vegetación excelsa, arena fina, aguas cristalinas y a la que se llega desde el Faro de Camarina.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (178, 'Los Alemanes', 'Playa de carácter semiurbana, de arena fina y dorada, con un grado medio de ocupación, que se extiende desde el Cabo de la Plata al Cabo de Gracia. Protegido por la Junta de Andalucía.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (179, 'Los Lances Norte', 'Esta playa posee las mejores condiciones para la práctica del kite-surf y el wind-surf, además de todos los equipamientos necesarios, incluyendo varios clubs de estos deportes.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (180, 'Los Lances Sur', 'Playa excelente para la práctica del kite-surf y el wind-surf debido a sus condiciones del viento reinante y a sus equipamientos y variedad de servicios. Protegido por la Junta de Andalucía.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (181, 'Playa Chica', 'Pequeña playa ubicada entre el puerto y la Isla de Tarifa con bonitas vistas aunque con no demasiado encanto para disfrutar de un baño dado el lugar en el que se encuentra y el viento reinante en la zona. Protegido por la Junta de Andalucía.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (182, 'Valdevaqueros', 'Playa rústica, muy grande, limpia y de aguas azules y formaciones dunares donde sopla un viento excelente para la práctica del Wind-Surf. Protegido por la Junta de Andalucía.', 11035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (184, 'Cala Chilches', 'Playa aislada de grava y arena, sin equipamientos ni servicios. ', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (185, 'El Cuervo', 'Estrecha franja de arena junto a la carretera N-340. No tiene equipamientos. ', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (186, 'El Gaiterillo', 'Pequeña playa muy estrecha es una zona aislada junto a la carretera N-340. ', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (187, 'La Playiya', 'Playa aislada sin servicios ni equipamientos, a la que se accede a pie desde la carretera N-340.', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (188, 'El Ruso', 'Playa aislada junto a la carretera N-340. No ofrece servicios. ', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (189, 'La Rábita', 'Playa de grava en cuyo entorno se extienden cultivos intensivos de invernadero.', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (190, 'Pozuelo', 'Playa larga y estrecha con algunos equipamientos. El entorno está bastante degradado, presentando un aspecto poco acogedor.', 18006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (191, 'Barranco de Enmedio', 'Forma parte de una sucesión de pequeñas playas en la zona menos urbanizada de Almuñécar: Calabajío, Cabria, Curumbico y Barranco de Enmedio .Al estar algo alejada del núcleo principal de Almuñécar, la afluencia de público es moderada.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (192, 'Cabria', 'Forma parte de una sucesión de pequeñas playas en la zona menos urbanizada de Almuñecar: Calbajío, Cabria, Curumbico y Barranco de Enmedio. Al estar algo alejada del núcleo principal de Almuñécar, la afluencia de público es moderada. Ofrece algunos servicios de hosteleria.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (193, 'Calabajío', 'Forma parte de una sucesión de pequeñas playas en la zona menos urbanizada de Almuñécar: Calabajío, Cabria, Curumbico y Barranco de Enmedio.Al estar algo alejada del núcleo principal de Almuñécar, la afluencia de público es moderada.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (194, 'Calaiza', 'Playa constituida por una sucesión de pequeñas calas de muy difícil acceso, por lo que la afluencia de bañistas es muy baja.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (195, 'Caletilla', 'Pequeña playa muy estrecha, en el núcleo principal de Almuñecar, colindante con la playa de San Cristóbal. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (196, 'Cantarrijan', 'Situada en el Paraje Natural de Maro Cerro Gordo, es una playa pequeña bastante frecuentada, a pesar de que su acceso es complicado. Cuenta con ciertos servicios.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (197, 'Cotobro', 'Playa estrecha en zona urbanizada, con edificaciones dispersas por la ladera de la montaña. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (198, 'Curumbico', 'Forma parte de una sucesión de pequeñas playas en la zona menos urbanizada de Almuñecar: Calabajío, Cabria, Curumbico y Barranco de Enmedio .Al estar algo alejada del núcleo principal de Almuñecar, la afluencia de público es moderada. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (199, 'El Muerto', 'Formada por una playa principal y una pequeña cala, unidas entre si por una senda peatonal, y otra senda une a ambas con la Playa de Cotobro. Se accede a ella desde la playa de Cotobro.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200, 'La Herradura', 'Playa urbana de ambiente familiar. Está muy bien equipada y cuenta con un alto nivel de servicios. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201, 'Los Berengueles', 'Pequeña playa junto al puerto deportivo de Marina del Este, con gran afluencia de público, procedente en su mayoría de las urbanizaciones cercanas a la playa. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202, 'Pozuelo', 'Playa pequeña en zona urbanizada, con alta afluencia de público. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203, 'Puerta del Mar', 'Extensa playa del núcleo urbano de Almuñécar, con buen nivel de servicios.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204, 'San Cristóbal', 'Playa de 1 Km. de largo con buenos servicios. Zona urbanizada con edificaciones de gran altura y paseo marítimo.', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205, 'Tesorillo', 'Playa muy pequeña y muy frecuentada, en zona urbanizada. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (206, 'Velilla', 'Playa bastante extensa con un alto grado de urbanización en su entorno. Ofrece todo tipo de servicios. ', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201801, 'El Rincón de La China', 'Pequeña cala situada a poniente de la playa de San Cristobal', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201802, 'La Veintiuna', 'Playa situada entre la de San Cristobal y Cotobro', 18017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (207, 'La Rijana', 'Se trata de una pequeña cala junto a la carretera N-340 aislada y sin equipamientos. ', 18093);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (208, 'Sotillo', 'Playa extensa con defensas artificiales en algunos tramos. Tiene paseo marítimo y algunos servicios. ', 18093);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (214, 'La Chucha', 'Playa relativamente tranquila, con pequeñas urbanizaciones en su entorno. Tiene pocos servicios. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (215, 'La Joya', 'Pequeña cala aislada de difícil acceso. No tiene servicios.', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (216, 'Pelaillo', 'Es una de las playas más concurridas de Motril. Tiene paseo marítimo jalonado por edificios relativamente altos. Buen nivel de servicios. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (217, 'Torrenueva', 'Playa muy concurrida con buenos servicios. Tiene paseo marítimo y el frente litoral está ocupado por edificaciones altas. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (212, 'Carchuna', 'Playa muy extensa (3 Km), por lo que a pesar de tener bastante afluencia, ofrece un aspecto tranquilo. Está rodeada de cultivos intensivos de invernaderos. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (213, 'Granada', 'Playa larga, de arena fina y muy concurrida.', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (210, 'Azucenas', 'Larga franja de arena entre el Puerto de Motril y Torrenueva. Apenas cuenta con equipamientos. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (211, 'Calahonda', 'Playa turística bien equipada junto a la zona urbanizada de Calahonda, con mucha afluencia de público. ', 18140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (218, 'Castillo de Baños', 'Playa muy estrecha, de piedras. Sin equipamientos, junto al núcleo urbano de Castillo de Baños.', 18162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (340, 'El Chorrillo', 'Se trata de un conjunto de 3 calas denominadas genéricamente Los Chorrillos. Buenos servicios, tiene acceso desde el Balcón de Europa.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (341, 'El Playazo', 'Playa larga y amplia, no muy frecuentada, ya que esta apartada de la zona más urbana. Ofrece algunos servicios.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (342, 'El Salón', 'Pequeña playa urbana situada en un acantilado, con algunas palmeras. Buenos servicios.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (343, 'La Caleta', 'Pequeña playa apartada en un paisaje natural', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (344, 'La Caletilla', 'Pequeña playa con acantilado y buenos servicios', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (345, 'La Torrecilla', 'Pequeña playa urbana con Paseo Marítimo peatonal, gran afluencia de público y buen nivel de equipamientos y servicios.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (346, 'Las Alberquillas', 'Playa rodeada de vegetación enclavada en un paraje natural. difícil acceso.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (347, 'Maro', 'Playa de aspecto salvaje, con presencia de vegetación en un paisaje natural.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (348, 'Molino de Papel', 'Playa de rocas, aislada, en un entorno natural de interés. De difícil acceso.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (357, 'Calaceite', 'Playa pequeña situada junto a la carretera N-340. No cuenta apenas con ningún equipamiento.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (358, 'El Cenicero', 'Playa situada en la zona del Morche, que ofrece numerosos servicios.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (359, 'El Morche', 'Playa urbanizada con buenos equipamientos. Cuenta con Paseo Marítimo.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (360, 'El Peñoncillo', 'Playa extensa y poco urbanizada, muy próxima a la carretera N-340. Tiene algunos servicios. Forma una unidad con la playa de Mazagarrobo.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (361, 'Ferrara', 'Playa muy extensa y bien equipada, con ambiente familiar', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (362, 'Mazagarrobo', 'Playa estrecha junto a la carretera N-340, con baja afluencia de público y pocos equipamientos y servicios. Forma una unidad con la playa del Peñoncillo.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (363, 'Wilches', 'Playa muy pequeña y aislada, junto a la carretera N-340.', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202904, 'Playa El Sillón', 'Pequeña playa encajada entre acantilados', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202905, 'Río Torrox', 'Playa de grava en la desembocadura del río Torrox', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202906, 'Playa Chica', 'Playa pequeña encajada junto al Faro y restos arqueológicos', 29091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (364, 'Almayate', 'Playa muy extensa en una zona muy poco urbanizada. Apenas ofrece servicios y es muy poco frecuentada.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (365, 'Bajamar', 'Playa estrecha, sin apenas servicios.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (366, 'Benajarafe', 'Junto con la playa de Valle Niza, forma una extensa playa de arena oscura. En general no tiene buenos equipamientos, excepto en las zonas donde se asientan las urbanizaciones próximas.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (367, 'Chilches', 'Playa muy extensa y muy estrecha en algunos tramos, junto a la carretera N-340. Existen varias urbanizaciones en la zona, de donde procede la mayoría de los usuarios de la playa.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (368, 'La Caleta', 'Junto al Puerto de La Caleta de Vélez, se extiende esta playa de un kilómetro de longitud. Muy concurrida y con buenos servicios.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (369, 'Las Arenas', 'Forma parte de la playa de Torre del Mar en su extremo más oriental', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (370, 'Pijil', 'La playa de Pijil pertenece al barrio de Lagos. Es una estrecha franja de grava sin apenas servicios.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (371, 'Torre del Mar', 'Playa urbana de Torre del Mar. Es muy extensa y ofrece toda clase de servicios. Ambiente familiar.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (372, 'Valle Niza', 'Junto con la playa de Benajarafe, forma una extensa playa de arena oscura. En general no tiene buenos equipamientos, excepto en las zonas donde se asientan las urbanizaciones próximas.', 29094);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (353, 'El Bajondillo', 'Playa con un alto nivel de servicios, ambiente familiar y muy frecuentada.', 29901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (354, 'La Carihuela', 'Playa con un alto nivel de servicios, ambiente familiar y muy frecuentada.', 29901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (355, 'Los Álamos', 'Playa familiar. Es la más alejada del centro de Torremolinos.', 29901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (356, 'Playamar', 'Playa urbana de Torremolinos, muy bien equipada, con centros comerciales próximos y gran número de restaurantes y chiringuitos.', 29901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (249, 'Algarrobo', 'Playa de grava y arena con alto grado de ocupación, en una zona urbanizada con edificios altos. Posee buenos equipamientos. ', 29005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (250, 'Mezquitilla', 'Junto con la playa de Algarrobo, forma el frente litoral conocido como Algarrobo-Costa.', 29005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (296, 'Peñón del Cuervo', 'Pequeña playa junto a la carretera, sin apenas equipamientos ni servicios. El Peñón del Cuervo separa la playa en dos, y ofrece una estampa muy característica de la playa.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (297, 'San Andrés', 'Playa continuación de la Misericordia', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (282, 'Baños del Carmen', 'Se trata de una estrecha franja de alrededor de 5 m. en algunos tramos, sin apenas equipamientos.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (283, 'Campo de Golf', 'Playa cercana al Club de Golf de Málaga y al Aeropuerto. Es más conocida como Playa de San Julián.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (284, 'El Candado', 'Pequeña playa junto al Puerto Deportivo de El Candado. ', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (285, 'El Chanquete', 'Playa situada en la zona de El Palo. Ambiente familiar y buenos servicios. ', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (286, 'El Palo', 'Playa urbana de ambiente familiar con buenos equipamientos. ', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (287, 'Fábrica del Cemento', 'Playa pequeña junto a una fábrica de cementos en el barrio de la Araña. No tiene equipamientos', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (288, 'Guadalhorce', 'Playa junto a la desembocadura del río Guadalhorce, con escasa afluencia de público. ', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (289, 'Guadalmar', 'Forma parte de la zona conocida como playa de San Julián, cerca de la desembocadura del río Guadalhorce. Presenta un alto grado de urbanización', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (290, 'Huelín', 'Playa situada junto al Puerto de Málaga. Se trata de una franja de arena oscura muy estrecha junto a la que discurre un Paseo Marítimo.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (291, 'La Araña', 'Playa estrecha, en el barrio de La Araña. Aunque no ofrece buenos servicios, tiene una afluencia considerable de vecinos de la zona.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (292, 'La Caleta', 'Playa urbana de Málaga, muy cuidada y bien equipada.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (293, 'La Malagueta', 'Playa urbana situada en el centro de Málaga, muy popular entre los habitantes de la ciudad. ', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (294, 'La Misericordia', 'Playa en las afueras del núcleo urbano de Málaga, relativamente poco frecuentada, junto a la Central Térmica.', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (295, 'Pedregalejo', 'Sucesión de playas urbanas muy cuidadas y bien equipadas, con ambiente familiar. Están protegidas por defensas artificiales', 29067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (349, 'Cala del Moral', 'Playa familiar muy concurrida, con todo tipo de servicios. La zona está muy urbanizada y cuenta con Paseo Marítimo.', 29082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (350, 'Los Rubios', 'Playa situada en el barrio de Los Judíos. Junto con la playa de El Rincón de la Victoria y la de Torre de Benagalbón, abarcan todo el litoral del término municipal.', 29082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (351, 'Rincón de la Victoria', 'Extensa playa en la zona urbana de El Rincón de la Victoria. Ofrece todo tipo de servicios.', 29082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (352, 'Torre de Benagalbón', 'Situada junto a la urbanización del mismo nombre, esta playa es continuación de la playa de El Rincón de la Victoria, aunque no tiene Paseo Marítimo', 29082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (374, 'Beciella', 'Playa aislada y tranquila que presenta un grado medio de ocupación. Está compuesta por bolos y arena y no dispone de equipamientos.', 33013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (376, 'El Viso', 'Playa enclavada dentro de los extensos arenales del concejo de Caravia. No dispone de equipamientos y cuenta con un grado medio de ocupación.', 33013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (373, 'Arenal de Morís', 'Extensa playa en forma de concha y de arena dorada. Muy turística y concurrida, ofrece un buen nivel de equipamientos.', 33013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103302, 'Huelgues', 'Playa en el entorno de la Ciudad Residencial de Perlora, que presenta un grado medio de ocupación. Es de arena y solamente dispone de algunos equipamientos.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (383, 'Xivares 1 y 2', 'Extensa playa de arena blanca enclavada en un atractivo paisaje de alto interés turístico.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (377, 'Candás', 'Enclavada junto al puerto de Candás, es una playa dotada con toda la oferta hostelera necesaria y con gran afluencia de público.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (378, 'Carranques 1 y 2', 'Playa ubicada en un entorno paisajístico de interés con calas, cuevas y abundante vegetación.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (379, 'La Palmera', 'Es la playa del turístico pueblo de Candás. Disfruta de arena fina y ofrece todo tipo de equipamientos y la posibilidad de realizar diferentes deportes acuáticos.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (380, 'Rebolleres', 'Playa compuesta por bolos en un entorno un tanto degradado. No dispone de equipamientos y es poco frecuentada por el público.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (381, 'Taluxa', 'Recóndita cala de pequeño tamaño de arena y grava que es poco frecuentada, probablemente por el acceso complicado que tiene.Es habitual ver en ella pescadores.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (382, 'Tranqueru', 'Se encuentra rodeada de acantilados y en una zona de alto valor ecológico. No dispone de equipamientos y es muy frecuentada por pescadores.', 33014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (393, 'Arnao', 'Bonita playa de arena blanca y fina, y aguas tranquilas para el baño. Se encuentra enclavada en un bonito entorno, muy próxima al área recreativa de Arnao.', 33017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (394, 'Figueras', 'Playa situada en un bello entorno, cuenta con escasa ocupación.', 33017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (395, 'San Román', 'A esta playa se accede a través de la playa de Figueras en bajamar', 33017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (396, 'Armazá', 'Esta playa pedregosa y aislada tiene en su lado occidental un mirador situado en lo alto de la punta del Castello.', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (397, 'A Figueira', 'Figueira es una playa pedregosa típica de la costa occidental, que prácticamente desaparece en las pleamares y que se encuentra cerrada al este por el islote Illones.', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (398, 'Arnelles', 'Playa situada cerca del Puerto de Ortiguera que cuenta con algunos servicios.', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (399, 'El Barco', 'Pequeña playa, aislada y de difícil acceso que no cuenta con servicios.', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (400, 'Foxos', 'La playa de Foxos se encuentra en la desembocadura del Navia. Está encerrada por un abrupto acantilado.', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (401, 'Torbas', 'Extensa playa de cantos y arenas, situada en un entorno rural', 33018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103301, 'Salmoriera', 'Pequeña playa en forma de concha y de arena dorada. Muy turística y de mediana concurrencia, se encuentra a continuación de la de La Isla, con la que comparte algunos servicios.', 33019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (375, 'La Espasa', 'Situada en la desembocadura del río Espasa, que divide los concejos de Caravia y Colunga, es una playa extensa que está compuesta por arena dorada y ofrece un buen nivel de servicios.', 33019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (402, 'La Griega', 'Extensa formación de arena dorada, en la que desemboca el río Libardón. Presenta fuerte oleaje, ocupación media y un buen nivel de equipamientos. Como dato curioso, se pueden ver en ella huellas fosilizadas de dinosaurios.', 33019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (403, 'La Isla', 'Playa urbana de arena dorada enfrente de la cual se sitúa el islote del que recibe su nombre. Dispone de paseo marítimo y buenos equipamientos.', 33019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (404, 'Lastres', 'Playa del pueblo pesquero de Lastres que tiene un alto interés turístico. Ofrece un nivel bajo de servicios.', 33019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103303, 'Sancidiello', 'Situada al este del Cabo Vidío, es una de las playas recostadas al pie de impresionantes acantilados verticales del entorno de este Cabo.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103304, 'Gradas', 'Playa enclavada en el ámbito de los importantes acantilados verticales situados al este del Cabo Vidío. ', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103305, 'Pumarín', 'Enclavada en la zona occidental del concejo, se encuentra en el grupo de playas de  la localidad de Santa Marina', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103306, 'El Aguaduz', 'Playa ubicada en un entorno paisajístico de interés con calas, pedreros y abundante vegetación, situada en la zona occidental del concejo y en la localidad de Ballota. ', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (405, 'Río Cabo', 'El río Cabo que desemboca en la margen occidental de esta playa de Ballota sirve de límite entre el concejo de Valdés y el de Cudillero.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (406, 'Albuerne', 'Albuerne es una playa de cantos con algo de arena, encerrada por acantilados que superan los 50 m. de altura.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (407, 'Calabón', 'Esta playa de difícil acceso comparte el sector occidental, compuesto por una hilera de islotes, restos de una antigua punta fracturada de cuarzo y pizarra llamada la Forcada, con la playa de La Gueirúa.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (408, 'El Castrillón', 'Pequeña playa, poco frecuentada, situada entre las puntas Gavilán y Garita. No ofrece ningún tipo de servicios.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (409, 'El Castro', 'Pequeña cala de difícil acceso, a la que se llega a través de una vaguada abierta por un arroyo, situada entre las localidades de Castañeras y Santa Marina.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (410, 'El Riego', 'Pequeña cala de piedras en la que destaca la presencia de tres peñones colonizados por gaviotas. No dispone de equipamientos.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (411, 'El Silencio', 'Probablemente sea la playa más bella de todo el occidente, y aún a pesar de su belleza se conserva intacta a la presión turística. Espectaculares islotes de diferentes tamaños la cierran por sus márgenes', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (412, 'Gueirúa', 'Pequeña playa enclavada en un bello entorno, con escasa afluencia de público y sin servicios.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (413, 'La Barquera', 'Esta playa perteneciente al Paisaje Protegido de la Costa Occidental, además de su belleza paisajística destaca por su riqueza pesquera.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (414, 'La Concha de Artedo', 'Extensa playa muy resguardada por los acantilados que la rodean. Es una playa de aguas cristalinas que presenta siempre una alta afluencia de público.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (415, 'La Corvera', 'Pequeña playa enclavada en un atractivo entorno con baja ocupación y difícil acceso, característica de la costa occidental asturiana.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (416, 'La Cueva', 'Playa de bolos en forma de concha, a la que se accede  a través de un sendero labrado en un acantilado que supera los 80 metros de altura.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (417, 'L''Airín', 'Es una extensa playa con predominio de cantos, en la que la arena adquiere diversas y bellísimas tonalidades. El islote del Fariñón la separa de la playa de Saliencia.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (418, 'Las Rubias', 'Playa de gran belleza aislada y enclavada a los pies de altos acantilados. Presenta escasa afluencia de público debido probablemente al difícil acceso que tiene.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (419, 'Los Botes', 'Pequeña cala aislada compuesta por bolos y que presenta un fuerte oleaje. No dispone de equipamientos.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (420, 'Oleiros', 'Playa situada a los pies de altos acantilados, rodeada de pinares y refugiada al fondo de la ensenada de Oleiros. Disfruta de aguas limpias y cristalinas pero sufre fuerte oleaje.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (421, 'Peña Doria', 'Pequeña playa que reúne pocas condiciones para el baño debido al fuerte oleaje y viento', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (422, 'Portiella', 'Cala pequeña y con escaso interés para el baño, en ella se encuentra un caladero de marisco.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (423, 'Puerto Chico', 'Cala muy pequeña encajada entre acantilados que presenta escasa afluencia de público y no ofrece ningún servicio.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (424, 'Ribera del Molín', 'Playa de tipo rural de gran belleza, tranquila y solitaria compuesta por bolos y que presenta un fuerte oleaje.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (425, 'Salencia', 'Pequeña playa de tipo rural en la que desemboca el arroyo de Yendebarcas.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (426, 'San Pedro de Bocamar', 'Playa que, aunque situada en una zona aislada, muestra una alta afluencia de público y cuenta con buenos servicios.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (427, 'Vallina', 'Se puede acceder a esta alargada y estrecha playa desde Oviñana o desde Valdredo. Esta playa es casi exclusivamente frecuentada por pescadores.', 33021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103310, 'Monellos', 'Se encuentra rodeada de acantilados de baja altura en el fondo de una bonita cala situada al oeste de la localidad de Viavélez', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (428, 'Porcía', 'Playa con forma triangular con alta ocupación y que posee marismas y dunas de pequeña extensión, así como zonas arboladas', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (429, 'Cambaredo', 'Playa estrecha, alargada y pedregosa, de gran valor ecológico. Con escasa afluencia de público Se encuentra rodeada por elevados acantilados repoblados de pinos al igual que la gran mayoría de las playas occidentales.', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (430, 'Castelo', 'Es tal vez la más interesante de este conjunto de playas labradas dentro de la formación geológica de la serie de los cabos. Bellísima ensenada de gravas cuarcíticas, donde los materiales dominantes son las pizarras y el cuarzo.', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (431, 'Pormenande', 'Es una playa de gran belleza y muy segura, a pesar de ser pedregosa. Un pequeño tómbolo la une por su margen derecho al islote El Rego, a cuya cima se puede llegar por un sendero.', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (432, 'Torbas', 'Pequeña playa situada en una pequeña ensenada al este del cabo Blanco, que destaca por su importancia paisajística y por la calidad de sus aguas.', 33023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (433, 'Arbeyal', 'Playa de pequeño tamaño que gracias a una regeneración ha recuperado su buen estado. Ofrece arena dorada, aguas tranquilas y buenos servicios.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (434, 'Cagonera y Serín', 'Situada en las inmediaciones del cabo de San Lorenzo, es una playa que tiene fuerte oleaje y baja afluencia de público, a consecuencia probablemente de encontrarse aislada.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (435, 'Cervigón', 'Playa colindante con la de San Lorenzo en la ciudad de Gijón. Denota una alta afluencia de público y dispone de bastantes equipamientos.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (436, 'Estaño', 'Playa semiurbana de pequeñas dimensiones compuesta por arena y grava. Ofrece un nivel medio de servicios.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (437, 'Peñarrubia', 'Playa muy estrecha y rodeada de altos acantilados. Tiene un grado alto de ocupación.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (438, 'Poniente', 'Playa generada artificialmente en la zona del puerto deportivo de Gijón. Tiene una alta afluencia de público, arena dorada y zona de fondeo.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (439, 'San Lorenzo', 'Playa ubicada en la bahía de Gijón, de gran belleza y muy frecuentada por el público. Goza de excelentes equipamientos: aseos, duchas, alquiler de sombrillas y hamacas, Club Náutico, etc.', 33024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103307, 'El Serrón', 'Esta playa de canto rodado se encuentra situada en el lado norte del Cabo Busto, al pie de un importante acantilado.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (528, 'Barayo', 'La playa Barayo situada en Valdés es una playa de arena de 670 metros de longitud. ', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (529, 'Bozo', 'Pequeña playa aislada situada en la parte occidental del Cabo Busto, presenta una formación de bolos y un oleaje moderado.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (530, 'Cadavedo', 'Playa de tipo rural, en forma de concha, con un alto grado de ocupación en la época estival.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (531, 'Campiecho', 'Playa aislada, de bolos, poco frecuentada por el público. No dispone de servicios.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (532, 'Carretón', 'Playa aislada que tiene un complicado acceso a pie, formada por bolos y con escasa afluencia de público.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (533, 'Castiel', 'Cala encajada entre acantilados a la que se accede difícilmente, lo que hace que prácticamente no sea utilizada por los bañistas.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (534, 'Chousera', 'Playa de reducido tamaño compuesta por bolos y que presenta un fuerte oleaje y una baja ocupación.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (535, 'Churín', 'Playa de muy difícil acceso formada por bolos que presenta un fuerte oleaje. Sin servicios y baja ocupación.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (536, 'Cueva', 'Playa más frecuentada que otras de la zona debido a la cercanía de la población de Cueva. Ofrece escasos equipamientos.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (537, 'Fontanecha', 'Pequeña playa de difícil acceso (se accede a través de un acantilado de unos 75 m.), con poca ocupación, utilizada prácticamente sólo por pescadores.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (538, 'La Escaladina', 'Pequeña cala rocosa de fuerte oleaje poco frecuentada por el público a excepción de pescadores de la zona.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (539, 'La Herbosa', 'El complicado acceso y el fuerte oleaje que presenta esta playa hacen que esté muy poco frecuentada por el público.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (540, 'Las Arreas', 'Está situada inmediatamente al este del faro de Luarca en un entorno degradado por la emisión de residuos urbanos.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (541, 'Los Molinos', 'Playa situada al oeste del Cabo Busto, que debe su nombre a las construcciones que aprovechaban el agua del arroyo Ricante que llega al mar a través de ella. Aislada y agreste, de complicado acceso a pie y fuerte oleaje, es frecuentada por pescadores de la zona.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (542, 'Los Molinos', 'Situada al este del Cabo Busto entre las playas de Santana y Perceberos, el difícil acceso que presenta hace que su público este casi exclusivamente compuesto por pescadores de la zona.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (543, 'Otur', 'Arenal en el que existe un sistema dunar un tanto degradado debido a la alta ocupación que sufre esta playa situada al oeste de Luarca, en las inmediaciones del pueblo de Otur.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (544, 'Perceberos', 'Playa enclavada en un magnífico paisaje dentro del Paisaje Protegido de la Costa Occidental, que cuenta con un acceso bastante complicado.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (545, 'Picón', 'Pequeña y bella cala de bolos a la que se accede andando desde la de Los Molinos. Presenta un fuerte oleaje y escasa afluencia de público. Se encuentra situada inmediatamente al oeste de la playa de Cueva.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (546, 'Plumineru', 'Playa aislada y tranquila compuesta por bolos que presenta un fuerte oleaje y no ofrece ningún tipo de servicio.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (547, 'Portizuelo', 'Enclavada en un paisaje de gran belleza formado por grandes rocas y acantilados, presenta un mayor nivel de ocupación que otras playas de la zona.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (548, 'Primera y Segunda de Luarca', 'Arenal que configura la playa urbana de la villa de Luarca que en verano es muy frecuentado por el turismo. Dispone de buenos equipamientos y de una variada oferta hostelera.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (549, 'Punxeo', 'Situada dentro del Paisaje Protegido de la Costa Occidental, denota escasa afluencia de público y no dispone de infraestructuras.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (550, 'Ribón', 'Playa de gran belleza, con escasos servicios y poca ocupación, situada entre altos acantilados.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (551, 'Sabugo', 'Playa en forma de concha de arena oscura y fuerte oleaje a la que se accede a pie por un camino que desciende el acantilado.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (552, 'Salinas', 'Situada en la turística villa de Luarca, es una playa urbana muy frecuentada por el público que ofrece aguas limpias y un buen nivel de equipamientos.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (553, 'Santa Ana', 'Enclavada en el entorno del Cabo Busto, conforma un paisaje de interés y presenta escasa afluencia de público.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (554, 'Tablizo', 'Playa de arena y cantos, alargada y rectilínea con acantilados que alcanzan los 100 m. de altura, que pertenece al Paisaje Protegido de la Costa Occidental.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (555, 'Tourán', 'Playa de reducidas dimensiones en forma de concha que configura un bello paisaje. Presenta escasa afluencia de público y no dispone de infraestructuras.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (556, 'Turbeiriza', 'Encajada entre acantilados cubiertos de prado, aparece esta pequeña y alargada playa que es muy poco frecuentada por el público.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (557, 'Vallinas', 'Reúne todas las características de las playas de la zona: playa salvaje compuesta por bolos, con baja ocupación y fuerte oleaje, situada en el lado oriental del Cabo Busto.', 33034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (457, 'Andrín', 'Formidable playa situada en un entorno impresionante rodeada de acantilados, en la que es conveniente tener cuidado debido al fuerte oleaje y a las corrientes que se forman en ella.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (458, 'Ballota', 'Enclavada en un entorno de gran belleza, frente a ella se sitúa el islote (Castro Ballota) que la caracteriza.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (459, 'Barro', 'Queda unida a la playa de los Sorraos con la marea alta. Disfruta de arena blanca, aguas cristalinas y un buen nivel de equipamientos', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (460, 'Borizo ', 'Esta playa de arena blanca, muy frecuentada por turistas, se une en bajamar a través de un brazo arenoso a la Isla de Borizo situada frente a ella.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (461, 'Buelna', 'Pequeño arenal en un agradable entorno, muy frecuentado sobre todo por familias. No dispone de equipamientos.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (462, 'Cobijeru', 'Resguardada playa en la que el agua entra por un túnel y que conforma un espléndido paisaje cárstico declarado Monumento Natural.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (463, 'Cué', 'Playa ubicada en un agradable entorno rocoso que disfruta de arena fina blanca y aguas tranquilas y moderada afluencia de público.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (464, 'Cuevas del Mar', 'Ubicada en la desembocadura del río Cuevas, configura un paisaje cárstico muy interesante y de gran belleza.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (465, 'El Portiello de San Martín', 'Pequeña cala resguardada por las grandes rocas que la rodean. El acceso a ella es bastante complicado y tiene un grado bajo de ocupación.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (466, 'El Sablón', 'Situada en el núcleo urbano de Llanes, cuenta con una alta afluencia de público y dispone de paseo marítimo y un buen nivel de equipamientos.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (467, 'Guadamía', 'Situada en la desembocadura del río Guadamía, configura un paisaje cárstico de interés. Presenta fuerte oleaje y corrientes.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (468, 'Gulpiyuri', 'Pequeña playa semicircular formada por una dolina cerrada y rodeada de acantilados.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (469, 'La Acacia', 'Se encuentra aislada por los acantilados colindantes a la playa de La Franca y solamente se accede a ella en barco. Permite disfrutar del entorno en absoluta tranquilidad.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (470, 'La Almenada', 'Playa ubicada en la ensenada que forma el río Vallina al desembocar en el mar. El acceso es complicado y no dispone de equipamientos.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (471, 'La Entrada', 'Playa formada en la desembocadura de la ría de Niembro. Disfruta de arena blanca y aguas tranquilas y tiene escasa afluencia de público.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (472, 'La Huelga', 'Situada en la desembocadura del río San Cecilio, muestra gran afluencia de público al hallarse cerca el pueblo de Hontoria.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (473, 'La Talá', 'Playa de reducido tamaño compuesta por rocas y grava, de fuertes corrientes y oleaje. No ofrece ningún tipo de servicio.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (474, 'La Tayada', 'Pequeña playa enclavada en un atractivo entorno paisajístico declarado Paisaje Protegido. Está formada por arena dorada, la cual desaparece completamente durante la marea alta.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (475, 'Las Cámaras', 'Playa colindante a la de la Palombina. Ofrece arena blanca, paseo marítimo y algunos servicios: duchas, teléfonos, etc.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (476, 'Toranda', 'Bonita playa enclavada en una costa acantilada y rodeada de una zona de prados. Ofrece al visitante arena blanca y aguas cristalinas', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (477, 'Palombina', 'Está enclavada en la localidad de Celorio, zona que ha sufrido un aumento considerable del turismo.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (478, 'Pendueles', 'Rodeada de acantilados, se accede a ella por una escaleras. Es de arena oscura y se caracteriza por el fuerte oleaje.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (479, 'Pestaña', 'Cala de pequeño tamaño a la que se accede a pie desde la playa de Torimbia por un bonito sendero. No ofrece ningún equipamiento', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (480, 'Poo', 'Cercana a la población de Poo y en la ría del mismo nombre, muestra una alta afluencia de público y disfruta de arena blanca y aguas tranquilas.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (481, 'Portiellu de Cué', 'Se accede a ella desde la playa colindante de Toró. Compuesta por arena y rocas, ofrece aguas cristalinas y un grado medio de ocupación.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (482, 'Puerto Chico', 'Resguardada playa de arena y bolos muy popular y con alta afluencia de público. Dispone de paseo marítimo y un nivel aceptable de servicios.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (483, 'San Antolín', 'Extensa playa de arena blanca situada en las cercanías del Monasterio románico de San Antolín de Bedón. Es una playa ventosa y de fuerte oleaje.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (484, 'San Antonio', 'Playa aislada pero con gran afluencia de público a la que se accede andando desde la vecina Cuevas del Mar. Fuerte oleaje y corrientes.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (485, 'San Martín', 'Playa de arena blanca con afloramientos rocosos, frente a la que se sitúan dos islotes. No dispone de equipamiento.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (486, 'Sevalle', 'Playa con forma de concha compuesta por rocas y arena. En sus cercanías se encuentra un sistema de dunas eólicas.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (487, 'Sorraos', 'Playa adyacente a la de Barro, de arena blanca, con alta afluencia de público y dotada de buenos servicios.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (488, 'Torimbia', 'Playa enclavada en un bello entorno, que disfruta de una arena blanca fina y aguas muy limpias que hacen que siempre tenga una alta afluencia de público.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (489, 'Toró', 'Playa semiurbana con alta afluencia de público. Tanto en su superficie como en el agua sobresalen numerosas rocas que la confieren un aspecto singular.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (490, 'Troenzo', 'Playa semiurbana con una alta afluencia de público, que se encuentra muy resguardada dentro de un bonito entorno declarado Paisaje Protegido.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (491, 'Valle', 'Playa semiurbana enclavada en un paisaje de interés a la que se accede a pie. Formada por arena blanca y rocas, no dispone de equipamientos.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (492, 'Vidiago', 'Compuesta por grava y arena, se caracteriza por el viento y el fuerte oleaje que sufre. Ofrece un nivel bajo de servicios.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (493, 'Villanueva', 'Bella playa encajada y rodeada de acantilados cársticos. Sufre fuerte oleaje que incluso llega a formar un sumidero.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (494, 'Xiglu', 'Una pequeña parte de la playa de Barro recibe este nombre. Está situada en un entorno urbano y tiene alta afluencia de público.', 33036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (495, 'Aguilar', 'Extenso arenal de gran interés turístico que la convierte en una playa muy concurrida. Ofrece un buen nivel de equipamientos y una variada oferta hostelera.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (496, 'Campofrío', 'Playa situada en la base de unos acantilados recubiertos de vegetación. Es la prolongación hacia el oeste de la playa de Aguilar y comparte con ella el paseo marítimo y el resto de los servicios.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (497, 'Cazonera', 'Playa compuesta por bolos y rocas, contigua a la de La Atalaya, de la que la separan unos islotes. No ofrece equipamiento alguno.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (498, 'El Focarón', 'Playa de reducidas dimensiones compuesta por bolos y de fuerte oleaje. Poco frecuentada por el público.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (499, 'El Garruncho', 'Pequeña cala de bolos y rocas, situada al oeste del espigón de abrigo del canal de entrada al puerto de S. Esteban de Pravia.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (500, 'La Atalaya', 'Playa aislada con forma de concha separada de la playa contigua, La Cazonera, por unos islotes. No dispone de equipamientos.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (501, 'La Guardada', 'Playa de reducidas dimensiones formada por bolos y de fuerte oleaje. Ofrece un nivel medio de servicios y está poco frecuentada por el público.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (502, 'Las Llanas', 'Aislada playa que goza de gran tranquilidad. Enclavada en un atractivo paisaje acantilado, se accede a través de una larga escalera.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (503, 'Xilo', 'Pequeña playa contigua a la de Aguilar por el este que, en materia de servicios, se beneficia de la proximidad a ésta.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (504, 'Xan-Xun', 'Playa aislada de reducidas dimensiones compuesta por grava y con un grado bajo de ocupación. No dispone de infraestructuras.', 33039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103308, 'La Losera', 'Pequeña cala de canto rodado y piedra, situada al oeste de la localidad de Puerto de Vega.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103309, 'Coedo', 'Recóndita cala de pequeño tamaño de canto rodado y arena, situada en las inmediaciones de la localidad de Andés.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (505, 'El Moro', 'Colindante con la de Navia, es una playa de arena gruesa oscura que presenta un grado medio de ocupación.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (506, 'Fabal', 'Pequeña playa en forma de concha rodeada de acantilados, adyacente al arenal de Frejulfe. Presenta escasa afluencia de público y un fuerte oleaje.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (507, 'Frejulfe', 'Extenso arenal en el que existe un sistema dunar, cercano a la villa pesquera de Puerto de Vega. Presenta un fuerte oleaje, siendo la parte derecha la más apta para el baño.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (508, 'Navia', 'Playa de arena formada en la desembocadura del río Navia. Presenta una gran afluencia de público por su cercanía a la población del mismo nombre y ofrece buenos equipamientos.', 33041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (512, 'Arra', 'Playa colindante con el concejo de Llanes compuesta por bolos y rocas en una zona de acantilados. Zona de buceo adecuada.', 33056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (513, 'La Atalaya', 'Cala de reducidas dimensiones adyacente al puerto de Ribadesella. Se accede fácilmente a pie desde el casco urbano.', 33056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (514, 'Santa Marina', 'Playa situada en la población de Ribadesella, cuenta con una importante oferta turística y un interesante legado cultural. Buen nivel de equipamientos.', 33056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (515, 'Vega', 'Extensa playa que configura un paisaje de interés debido a los acantilados y al complejo dunar, por el que fue nombrada Monumento Natural.', 33056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (516, 'Los Quebrantos', 'Extensa playa de arena oscura unida al Playón de Bayas, en cuya zona occidental desemboca el río Nalón. Ofrece un nivel alto de servicios y tiene una gran afluencia de público.', 33069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (517, 'Peñarronda ', 'Amplio arenal con una roca en el centro que da nombre a la playa. Los aficionados al surf, suelen frecuentar esta playa desde donde se pueden tomar buenas olas.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (518, 'El Figo', 'Pequeña cala de piedras situada en un entorno rocoso y con acantilados, con difícil acceso.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (519, 'El Murallón', 'Pequeña playa situada en un bello entorno. Cuenta con buenos servicios, algunos de ellos compartidos con la playa Grande con la que limita al sur, y alta ocupación .', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (520, 'La Grande', 'Extensa playa con excelentes servicios en la que se practica el surf y donde se celebra un conocido campeonato de este deporte.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (521, 'La Paloma', 'Playa de arena fina situada en un entorno agreste.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (522, 'La Reburdia', 'Pequeña playa mayoritariamente utilizada por los habitantes de la urbanización en la que se ubica. De arena fina, está enclavada entre abruptos acantilados en un entorno rocoso.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (523, 'Mexota', 'Playa de gran belleza, aguas cristalinas y con un original islote, que dispuesto en dirección Norte-Sur divide la playa en dos.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (524, 'Pantorga', 'Playa recogida, ubicada entre acantilados. De arena fina dorada, cuenta con unos islotes que albergan especies protegidas y amenazadas. Es una buena zona para practicar la pesca submarina y el surf.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (525, 'Represas', 'Playa de escaso interés, situada entre acantilados y sin servicios.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (526, 'Sarello', 'Situada en un amplio arenal contiguo a la playa de Serantes por su lado oeste, goza de un agradable entorno rural, donde el permanente verde de las praderas contrasta con el dorado de las arenas y el gris pizarroso de los materiales autóctonos.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (527, 'Serantes', 'Playa rústica con una extensión muy ancha de arena fina dorada. Es una playa tranquila, no excesivamente frecuentada.', 33070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (384, 'Arnao', 'Enclavada en una hondonada y resguardada, es una playa de arena y bolos dotada con buenos servicios y muy frecuentada por el turismo.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (385, 'Bahínas', 'Bonita playa semiurbana de arena oscura, bolos y fuerte oleaje. Ofrece un nivel aceptable de servicios y un grado medio de ocupación.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (386, 'El Cordial', 'Playa aislada con escasa afluencia de público de arena dorada y fuerte oleaje a la que se accede a pie. No dispone de infraestructuras.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (387, 'Munielles', 'Próxima a la localidad de Santa María del Mar, es una playa pequeña de arena oscura y fuerte oleaje. Ofrece un nivel medio de servicios.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (388, 'Playón de Bayas', 'Esta extensa playa divide los concejos de Castrillón y Soto del Barco. Tiene un alto valor ecológico debido al sistema dunar que posee, y es de destacar su peligrosidad por el fuerte oleaje que sufre.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (389, 'Requexinos', 'Playa de arena oscura y fuerte oleaje, contigua a la del Playón de Bayas y rodeada de montes cubiertos de vegetación. Dispone de escasos equipamientos.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (390, 'Salinas', 'Extensa y turística playa de arena dorada muy frecuentada por el público y dotada con todo tipo de servicios, incluido un club náutico.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (391, 'San Juan', 'Playa dentro de una zona de especial protección debido a la vegetación dunar que tiene. Ofrece un buen nivel de equipamientos y tiene una alta afluencia de público.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (392, 'Santa María del Mar', 'Arenal formado en la desembocadura del río Ferrera. Ofrece un buen nivel de equipamientos y denota un alto nivel de ocupación.', 33016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (449, 'Moniello', 'Cala de reducido tamaño, cercana a la población de Luanco, formada por bolos. Dispone de duchas.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (450, 'La Ribera', 'Playa ubicada en el fondo de la bahía de Luanco, muy próxima al puerto, De arena dorada y escaso equipamiento, es poco utilizada por el público.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (451, 'Samarincha', 'Playa semiurbana con escasa afluencia de público formada por bolos. No dispone de infraestructuras.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (452, 'Samarinchina', 'Pequeña cala que presenta una baja afluencia de público y se caracteriza por sus aguas tranquilas y una zona abrigada de fondeo. No dispone de equipamientos.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (453, 'Luanco', 'Playa del pueblo pesquero y turístico de Luanco muy frecuentada por el público, dotada con todo tipo de infraestructuras y con una gran oferta hostelera.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (454, 'Tenrero', 'Interesante playa con un sistema dunar de alto valor ecológico. Formada por arena dorada gruesa y muy frecuentada por el turismo, en sus cercanías se ubican importantes yacimientos paleolíticos.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (455, 'Viodo', 'Cala perteneciente al Paisaje Protegido del Cabo de Peñas a la que se accede difícilmente. No dispone de infraestructuras', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (219, 'La Mamola', 'La playa de La Mamola pertenece al termino municipal de Polopos. Tiene un paseo marítimo con múltiples servicios turísticos.', 18162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (220, 'Casarones', 'Pequeña playa de rocas y grava, muy estrecha, sin ningún tipo de equipamiento ni servicios, en una zona de invernaderos. ', 18170);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (221, 'El Lance', 'Estrecha franja de arena oscura, junto a la carretera N-340. Tiene algunos equipamientos y servicios de hostelería. ', 18170);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (222, 'El Caletón', 'Pequeña cala aislada con buenos fondos marinos. Dispone de acceso peatonal a través de una senda desde la Plaza de La Caleta de Salobreña.', 18173);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (223, 'El Cambrón', 'Pequeña playa junto a la zona urbanizada de Torre del Cambrón. El acceso es difícil y no tiene servicios de ningún tipo. ', 18173);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (224, 'La Charca', 'Playa extensa y relativamente ancha, con ambiente familiar y buenos servicios. Cuenta con paseo marítimo, tras el que se asientan varias urbanizaciones y edificios asociados al turismo.', 18173);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (225, 'La Guardia', 'Playa bastante extensa, rodeada de cultivos agrícolas, con algunos servicios. Está separada de la playa de la Charca por un peñón. ', 18173);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (226, 'Salobreña / La Cagadilla', 'que continúa en el término municipal de Motril. ', 18173);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (227, 'Las Cañas', 'Playa aislada, contigua a la playa de Melicena.', 18177);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (228, 'Los Yesos', 'Estrecha franja de arena junto a la carretera N-340. ', 18177);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (229, 'Melicena', 'Playa tranquila en el núcleo urbano de Melicena con algunos equipamientos. ', 18177);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (209, 'Cambriles', 'La playa pertenece a dos términos municipales: Gualchos-Castell de Ferro y Lújar. No es una playa excesivamente concurrida. Ofrece pocos servicios. ', 18124);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (230, 'Castilla', 'Situada a Poniente de Matalascañas, es una playa bordeada en toda su longitud por un cantil de arenas consolidadas de gran altura', 21005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (231, 'Matalascañas', 'Playa urbana con alto nivel de servicios, limítrofe con la playa del Espacio Natural de Doñana.', 21005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202101, 'Doñana', 'Extensa playa de arena integrada en el Espacio Natural de Doñana', 21005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202104, 'Nuevo Portil', 'Playa bordeada por una duna de cierta altura y con agradables vistas de la flecha de El Rompido.', 21021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (235, 'Espigón', 'Playa apoyada en el dique Juan Carlos I del puerto de Huelva. Está integrada en el Paraje Natural Marismas del Odiel.', 21041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (236, 'Central', 'Playa urbana con buenos servicios e infraestructuras, que enlaza hacia ambos lados con amplias playas naturales.', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (237, 'Del Hoyo', 'Playa bordeada por un bosque de pinos con áreas de descanso.', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (238, 'Islantilla', 'Compartida por los dos términos municipales, esta playa cuenta con excelentes servicios, siendo una de las más concurridas de la zona, y no sólo en época estival, ya que su entorno permite visitarla todo el año. ', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (240, 'Redondela', 'Playa bordeada por un bosque de pinos.', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202105, 'Icona', 'Playa bordeada por un bosque de pinos integrado en el Parque Urbano Litoral', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202106, 'Urbasur', 'Playa bordeada por un bosque de pinos próxima a la urbanización URBASUR', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202107, 'Casita Azul', 'Playa bordeada por un bosque de pinos', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202108, 'Camino de Santana', 'Playa bordeada por un bosque de pinos integrado en el Parque Urbano Litoral', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202109, 'Gaviota', 'Playa conformada recientemente al abrigo del dique portuario. Se accede a través de una pasarela elevada que cruza la gola.', 21042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (241, 'La Antilla', 'Playa urbana con buen nivel de servicios.', 21044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (242, 'Nueva Umbría', 'Playa virgen enclavada en el Paraje Natural Marismas del Piedras y flecha de El Rompido, con escasas infraestructuras, pero muy frecuentada.', 21044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (244, 'Mazagón', 'Se trata de una playa que se desarrolla a lo largo del frente urbano de Mazagón. Hacia Levante del núcleo urbano continúa la playa en su estado natural, bordeado por un acantilado arenoso sobre el que se localiza un valioso sistema dunar.', 21055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (248, 'Punta Umbría', 'Playa urbana con alto nivel de servicios.', 21060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (245, 'El Portil', 'Esta playa se encuentra muy cerca de la Laguna del Portil. Se trata de una playa con ambiente agradable y buenas vistas de la flecha de El Rompido.', 21060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (246, 'La Bota', 'Situada entre pinares y dunas, permite dar agradables paseos y admirar su bello entorno natural. ', 21060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (247, 'Los Enebrales', 'Enclavada en el Paraje Natural de los Enebrales. Al igual que el resto de las playas de la zona, es excelente para dar largos paseos y disfrutar de su bello entorno.', 21060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (232, 'Isla Canela', 'Playa con buena dotación de servicios muy próxima a la desembocadura del río Guadiana', 21010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (233, 'Punta del Moral', 'Playa con buena dotación de servicios y fácil accesibilidad', 21010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (243, 'El Parador', 'Playa bordeada por acantilados arenosos de cierta altura. En sus proximidades está el Parador Nacional de Mazagón.', 21050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202103, 'Rompeculos', 'Playa bordeado por un acantilado arenoso de cierta altura.', 21050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (251, 'Arroyo de la Miel', 'Junto con la playa de Bil Bil, es una zona muy popular, con alto nivel de servicios. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (252, 'Arroyo Hondo', 'Playa con gran afluencia de público, junto al Hotel Costa Azul. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (253, 'Bil Bil', 'Junto con la playa de Arroyo de la Miel, constituye una zona muy frecuentada. Cuenta con paseo marítimo. Alto nivel de servicios.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (254, 'Carvajal', 'Playa altamente ocupada en su zona más occidental.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (255, 'La Morera', 'Pequeña playa, la más tranquila de la zona al estar algo alejada de las zonas más urbanizadas.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (256, 'La Perla', 'Playa muy pequeña, ubicada entre dos espigones artificiales. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (257, 'Las Viborillas', 'Pequeña playa.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (258, 'Las Yucas', 'Playa pequeña de arena y grava.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (259, 'Malapesquera', 'Playa familiar, con alto nivel de servicios. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (260, 'Santa Ana', 'Enclavada en el entorno del Cabo Busto conforma un paisaje de interés. Presenta alta afluencia de público.', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (261, 'Tajo de la Soga', 'Pequeña playa con una afluencia media, cerca del H. Holiday''s World', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (262, 'Torremuelle', 'Playa estrecha entre las Urbanizaciones de Valdeconejos y La Hidalga. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (263, 'Torrequebrada', 'Esta playa no existía prácticamente antes de las obras de mejora realizadas en la década de los 90. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (264, 'Torrevigía', 'Esta playa no existía prácticamente antes de las obras de mejora realizadas en la década de los 90. ', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202907, 'Benalnatura', 'Pequeña playa situada a Levante de la playa de Las Viborillas', 29025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (265, 'Playa Ancha', 'Preciosa y cuidada playa de más de un kilómetro de longitud, con aguas tranquilas y gran afluencia de público. Dotada con un buen número de servicios.', 29041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (266, 'Arroyo de las Cañas', 'La playa se extiende desde el río Velerín hasta el arroyo de las Cañas. Presenta una afluencia de público moderada.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (267, 'Arroyo Vaquero', 'Zona litoral con diversas urbanizaciones.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (268, 'Bahía Dorada', 'Playa muy estrecha situada junto a la Urbanización Bahía Dorada. Se encuentra situada a continuación de la playa de la Galera.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (269, 'Casasola', 'La playa está constituida por una lengua de grava muy estrecha. Posee duna con vegetación de interés botánico', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (270, 'El Cristo', 'Playa del casco urbano, aunque algo retirada del centro, junto al Puerto Deportivo de Estepona. Forma una bonita cala, regenerada recientemente, configurando una zona abrigada y resguardada de los vientos.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (271, 'El Saladillo', 'Playa con buenos servicios que se extiende a lo largo de 3 kilómetros, desde Punta del Saladillo hasta el arroyo de Dos Hermanas', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (272, 'Guadalmansa', 'Playa larga y estrecha, con urbanizaciones y servicios en algunos tramos', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (273, 'La Galera', 'Playa rectilínea con zonas rocosas, bien conservada. Alejada del casco urbano y relativamente poco urbanizada en comparación con otras playas de la zona. Configura un paisaje de interés', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (274, 'La Rada', 'La Playa de La Rada, situada frente al casco urbano, ha sido recientemente regenerada. Es muy extensa y concurrida, cuenta con gran número de servicios.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (275, 'Punta de la Plata', 'Playa extensa y estrecha, con servicios en algunos tramos y que presenta una afluencia de público moderada.', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202901, 'Playa del Río Castor', 'Playa con presencia de bolos y arena', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202902, 'Playa del Padrón', 'Playa con todos los servicios', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202903, 'Playa de los Pinillos', 'Playa estrecha con paseo marítimo recientemente terminado', 29051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (276, 'Castillo', 'Situada antes de cruzar el río Fuengirola, junto al castillo de Sohail, forma parte del gran arenal de Fuengirola.', 29054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (277, 'Boliches-Las Gaviotas', 'Playa en el centro urbano muy popular, bien equipada, con buen nivel de servicios y alta ocupación.', 29054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (279, 'Fuengirola', 'Playa con buen nivel de servicios', 29054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (281, 'Carvajal', 'Playa estrecha, con paseo marítimo. Se extiende desde el espigón de Torreblanca hasta el final del término municipal. La playa forma una unidad con la Playa de Carvajal (Benalmádena)', 29054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (298, 'Chullera', 'Formación rocosa de especial interés paisajístico y riqueza ecológica, con aguas limpias indicadas para la pesca submarina.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (299, 'El Negro', 'Playa rectilínea y larga con lomas suaves perpendiculares al mar. Se extiende desde Cala de la Sardina hasta el arroyo de Alcorrín.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (300, 'La Duquesa', 'Playa contigua al Puerto Deportivo de La Duquesa, se ha visto afectada por la regresión inducida por el puerto.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (301, 'Las Arenas', 'Playa rectilínea, con formaciones areniscas. Apoyada en dos grupos de roquedo hay una pequeña cala llamada Cala de La Sardina.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (302, 'Los Toros', 'Playa de Interés paisajístico debido a su gran apertura y extensión. Su frente litoral está siendo ocupado por urbanizaciones de diversa tipología. Recibe su nombre por el paso de ganado que utilizaba la Cañada Real de Los Barrios a Estepona.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (303, 'Sabinillas', 'Se extiende entre el Puerto Deportivo y el río Manilva. El frente litoral está ocupado por el núcleo de San Luis de Sabinillas.', 29068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (304, 'Artola', 'Playa situada en una zona protegida denominada Dunas de Artola.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (305, 'Cortijo Blanco', 'Playa de bolos junto a la urbanización Cortijo Blanco. ', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (306, 'Costa Bella', 'Junto con El Alicate y Pinomar, configura una zona de playas de casi 2 Km. con un grado de ocupación medio.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (307, 'El Alicate', 'Junto con Costa Bella y Pinomar, configura una zona de playas de casi 2 Km. con un grado de ocupación medio. ', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (308, 'El Ancón', 'Playa situada junto a la urbanización del mismo nombre. Se trata de una playa estrecha con baja afluencia de público.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (309, 'El Cable', 'Playa formada por una franja de arena estrecha, con poca afluencia de público.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (310, 'El Faro', 'Pequeña playa situada en el centro de Marbella, junto al Puerto Deportivo, con buenos servicios y alta ocupación.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (311, 'El Pinillo', 'Playa de ocupación media, con arena fina y formaciones dunares', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (312, 'Fontanilla', 'Playa de 1 Km. de largo situada junto al Puerto Deportivo. Ofrece buenos servicios y tiene una alta ocupación.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (313, 'Guadalmina', 'Playa situada en San Pedro de Alcántara, junto a la urbanización Guadalmina. Tiene una ocupación media, con buenos servicios (hotel, clubs, chiringuitos)', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (314, 'La Adelfa', 'Forma parte de 2 Km. de costa, conocidos en su conjunto como Playa de Los Monteros', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (315, 'La Bajadilla', 'Playa muy popular situada en las cercanías del Puerto pesquero de Marbella.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (316, 'La Venus', 'Playa situada en el casco urbano de Marbella, junto al río Represa. Presenta buenos servicios y alta ocupación.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (317, 'La Víbora', 'Pequeña playa junto al río La Víbora.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (318, 'Las Cañas', 'Estrecha franja de arena de apenas 10 m. de ancho y 1 Km. de largo, con escasos servicios.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (319, 'Las Chapas', 'Playa estrecha junto a la Urbanización Las Chapas', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (320, 'Linda Vista', 'Playa junto a la urbanización Linda Vista, en San Pedro de Alcántara. Presenta una ocupación alta y buenos servicios.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (321, 'Los Monteros', 'Forma parte de 2 Km. de costa, conocidos en su conjunto como Playa de Los Monteros. Semiurbana, junto a la Urbanización Bahía de Marbella, presenta formaciones dunares. Con buenos servicios.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (322, 'Nagüeles', 'Situada en la milla de oro de Marbella, junto al Marbella Club, posee un paseo marítimo de reciente construcción. Buenos servicios y alta ocupación.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (323, 'Nueva Andalucía', 'Playa de arena fina de 1 kilómetro de larga, con alta ocupación y todo tipo de servicios próximos. La zona, junto con Puerto Banús, se conoce como Playa del Duque.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (324, 'Pinomar', 'Junto con Costa Bella y El Alicate, configura una zona de playas de casi 2 Km. con un grado de ocupación medio.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (325, 'Real de Zaragoza', 'Playa extensa y estrecha, situada junto a la Urbanización del mismo nombre.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (326, 'Realejo', 'Forma parte de 2 Km. de costa, conocidos en su conjunto como Playa de Los Monteros', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (327, 'Río Real', 'Forma parte de 2 Km. de costa, conocidos en su conjunto como Playa de Los Monteros.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (328, 'Río Verde', 'Playa situada junto al río Verde y a la urbanización del mismo nombre. Presenta un tipo de arena dorado-rosada. La zona entre el Puerto y la desembocadura del río se conoce como Playa de Puerto Banús. Con buenos servicios.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (329, 'San Pedro de Alcántara', 'Playa urbana regenerada con paseo marítimo, junto al que se pueden encontrar restaurantes y todo tipo de servicios.', 29069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (330, 'Calahonda', 'Playa situada en el extremo oeste del término municipal, junto al Puerto Deportivo de Cabopino. Se trata de una estrecha franja de arena y rocas en una zona muy urbanizada.', 29070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (331, 'El Bombo', 'Playa estrecha en la zona costera, entre la Carretera N-340 y el mar. Presenta un alto grado de urbanización.', 29070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (332, 'El Chaparral', 'Extensa y estrecha franja junto a la carretera N-340.', 29070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (333, 'La Butibamba', 'Playa estrecha junto al arroyo Cala del Moral en una zona muy urbanizada.', 29070);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (334, 'Burriana', 'Playa muy frecuentada, de ambiente familiar. Entorno pintoresco y alto nivel de servicios y equipamientos.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (335, 'Cala del Cañuelo', 'Playa aislada con difícil acceso, enclavada en un paraje natural protegido', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (336, 'Cala del Pino', 'Playa virgen, con difícil acceso. Se encuentra en un paraje natural protegido. Muy poco frecuentada.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (337, 'Calahonda', 'Playa situada en una cala muy cerrada, bien equipada con Paseo Marítimo peatonal.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (338, 'Carabeillo Chico', 'Cala de muy reducidas dimensiones y acceso a pie por una escalera, entre grandes bloques de piedra.', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (339, 'El Carabeo', 'Pequeña playa con acceso a través de una escalera', 29075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200718, 'Cala Turqueta', 'Cala virgen de gran valor y belleza natural. Famosa por el color turquesa y tranquilidad de sus aguas.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200719, 'Cala Macarella', 'Cala amplia y muy conocida por la blancura de su arena y sus aguas cristalinas.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200720, 'Cala Macarelleta', 'Pequeña cala virgen a la que se accede a pie desde Cala Macarella, de aguas cristalinas.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2500, 'Llucalcari', 'Pequeña playa a la que se accede a pie por caminos sin señalizar, de ahí su bajo grado de ocupación.', 7018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2501, 'Cala Deià', 'Playa de grava y rocas ubicada junto al pueblo típico mallorquín de Deiá, muy apreciada por el turismo. ', 7018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2491, 'Racó de Mortix', 'Forma parte del conjunto de calas ubicadas al norte de la isla, formadas por altos acantilados inaccesibles desde tierra, no aptas para el baño. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2492, 'Cala Codolar', 'Forma parte del conjunto de calas ubicadas al norte de la isla, formadas por altos acantilados inaccesibles desde tierra, no aptas para el baño. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2493, 'Cala Capellans', 'Forma parte del conjunto de calas ubicadas al norte de la isla, formadas por altos acantilados inaccesibles desde tierra, no aptas para el baño. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2494, 'Cala Teix', 'Forma parte del conjunto de calas ubicadas al norte de la isla, formadas por altos acantilados inaccesibles desde tierra, no aptas para el baño. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2495, 'Sa Calobra', 'Es de las pocas playas de esta zona a la que se puede llegar en coche, por lo que presenta un elevado grado de ocupación. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2496, 'Cala Fotuda', 'Forma parte del conjunto de calas ubicadas al norte de la isla, formadas por altos acantilados inaccesibles desde tierra, no aptas para el baño. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2497, 'Cala Tuent', 'Playa de grava y arena carente de servicios e instalaciones de playa. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2547, 'Torrent de Pareis', 'Playa muy cercana a la playa Sa Calobra, ambas de pequeño tamaño, aunque con gran afluencia de visitantes. ', 7019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2507, 'Cala Ca''s Xirimié', 'Se trata de un gran acantilado sin accesos por tierra, incluido dentro del espacio protegido de la Serra de Tramuntana, pero sin interés para el turismo de playa. ', 7021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2508, 'Cala de son Pruaga', 'Playa de difícil acceso, más frecuentada por barcos que fondean en la zona que por bañistas.', 7021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2552, 'Cala Estellencs', 'Playa situada al pie de un acantilado vertical, en un entorno sobrecogedor. ', 7021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2332, 'Es Alocs', 'Esta cala virgen ubicada en la costa norte del término municipal de Ferreríes, con un acceso muy complicado, presenta un fondo rocoso y unas aguas muy cristalinas. ', 7023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2333, 'Cala Galdana', 'Cala Galdana es quizá una de las playa más conocidas y visitadas de la isla, totalmente equipada y muy apropiada para disfrutarla en familia. Zona de pic-nic gratuita.', 7023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200710, 'Cala Mitjana', 'Cala de gran belleza y gran valor ambiental. Situada en pleno bosque Mediterráneo, sus aguas son cristalinas y poco profundas. Cuenta con diversas rutas para senderistas.', 7023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2381, 'Sa Torreta', 'Playa aislada ubicada en Illa d''Espalmador, vecina de la Isla de Formentera. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2382, 'Es Racó de S''Alga', 'Es la playa más grande de las tres ubicadas en Illa d''Espalmador, vecina de la Isla de Formentera. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2383, 'Cala de Bosch', 'Una de las tres playas que se ubican en Illa d''Espalmador, vecina de la Isla de Formentera. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2384, 'Ses Illetes', 'Playa situada en un lugar privilegiado, con excelente arena blanca y muy visitada por el turismo.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2385, 'Cavall d''en Borràs', 'Excelente playa situada en una zona protegida, compuesta de arena dorada y que goza de unas aguas cristalinas. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2386, 'Cala Savina', 'Playa poco visitada por el turismo de la isla debido al lugar donde se encuentra ubicada. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2387, 'Caló d''es Moro', 'Playa de rocas idónea para el fondeo de los barcos de recreo. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2388, 'Caló d''en Trull', 'Playa de rocas con difícil acceso, por lo que presenta un bajo grado de ocupación. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2389, 'Cala Saona', 'Es la única playa, considerada como tal, que aparece en el litoral de poniente de la isla de Formentera, situada en una cala. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2390, 'Es Migjorn', 'Es la playa más extensa formada por una sucesión de arenales con interrupciones de rocas, formando sectores diferenciados con nombre propio, según los accidentes geográficos o pequeñas urbanizaciones próximas. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2391, 'Els Arenals', 'Extensa playa de arena dorada.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2392, 'Cala Codolá', 'Playa aislada frecuentada por barcos de recreo que fondean por la zona.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2393, 'Platja de ses Canyes', 'Playa compuesta de grava y arena blanca.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2394, 'Cala en Baster', 'Playa compuesta de grava que recibe poca cantidad de visitantes.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2395, 'Es Pujols', 'Presenta un elevado grado de ocupación debido a los servicios e instalaciones de que dispone. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2396, 'Sa Roqueta', 'Playa localizada al norte de la Isla de Formentera.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2397, 'Ses Salines', 'Gran arenal de más de cuatro kilómetros de longitud protegida como Area Natural de Especial Interés', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2398, 'Platja de Llevant', 'Playa de kilómetro y medio de longitud, aislada de cualquier núcleo urbano y que goza de una finísima arena blanca y aguas cristalinas. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2399, 'Caló d''Es Morts', 'Playa de arena fina, cantos rodados, bolos de grandes dimensiones y piedra, normalmente cubierta de restos de posidonia.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2400, 'Caló de S''Olí', 'Caló de S''Olí se denomina al tramo de costa que comprende desde Punta de Sa Pedrera hasta la Boca de S''Estany d''Es Peix. Dunas, vegetación y piedras se entremezclan hasta el mismo borde del agua, confiriéndole al entorno un aspecto salvaje.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2401, 'Estany d''Es Peix', 'Las arenas de este sector de costa son muy finas y algo fangosas, aunque está comunicado con el mar abierto a través de un estrecho paso llamado Sa Boca.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2402, 'Tramuntana', 'Ubicada en la franja central de la isla, se extiende entre refugios de pescadores tradicionales, escaseando la arena en la zona más occidental y apareciendo en mayor cantidad en la zona próxima a Ses Platgetes.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2403, 'Pas d''En Adolf', 'Situada al norte de la isla de Formentera, paso a la península de Trocadors, de arenas blancas y finas. ', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2404, 'Es Caló', 'En la parte más estrecha del itsmo que une las dos elevaciones de la isla de Formentera, opuestas entre sí. La cercanía de un pinar, la coloración del mar y la rusticidad de los cobertizos de los pescadores artesanales dan al entorno un encanto especial.', 7024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2286, 'Es Vivé', 'Es Vivé toma su nombre de un antiguo vivero de langostas, es un sitio muy turístico y muy bien equipado para el turismo. ', 7026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2287, 'Ses Figueretes', 'Playa urbana, ubicada en el mismo núcleo de Ibiza y con todos los servicios propios de una playa de ciudad.', 7026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2289, 'Talamanca', 'Playa muy cercana a Ibiza, muy bien equipada y muy apreciada por el turismo. ', 7026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200721, 'Punta de Baix', 'Situada en las inmediaciones del Hotel Torre del Mar', 7026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200722, 'Playa d''en Bossa', 'Tramo de la Playa d''en Bossa que corresponde al término municipal de Eivissa', 7026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2437, 'El Arenal', 'Esta playa constituye el final de la extensa playa conocida con el mismo nombre de Playa del Arenal perteneciente al término vecino de Palma de Mallorca.', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2438, 'Cala Blava', 'Playa ubicada en una zona muy tranquila, junto a la urbanización del mismo nombre, Urb. Cala Blava. En invierno queda muy poca arena', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2439, 'Cala Vella', 'Cala formada en un acantilado carente de accesos por tierra, únicamente puede llegarse a ella por mar.', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2440, 'Cala Beltrán', 'Pequeña cala aislada, carente de servicios y de difícil acceso. ', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2441, 'Cala Pi', 'Playa de arena blanca formada al final de un entrante del mar donde suelen fondear gran cantidad de barcos. En otoño e invierno el torrente inunda la playa en gran parte', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2554, 'Caló En Timo', 'Pequeña playa situada al oeste de la baliza de Punta Plana, de 40 metros de longitud por 20 de anchura, muy poco frecuentada. ', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2555, 'Racó de S''Arena', 'Playa situada al sur del Puerto del Club Náutico S''Estanyol, no urbana y ligeramente aislada, frecuentada por vecinos de S''Estanyol. ', 7031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2321, 'Cala es Murtar', 'Cala rodeada de pequeñas edificaciones donde residen los visitantes que generalmente frecuentan esta playa. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2322, 'Cala Tamarells', 'Playa a la que se accede a través de largos caminos de tierra, bien caminando o con vehículo preparado para ello.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2566, 'S''Arenal d''En Mongofre', 'Playa rústica de difícil acceso que goza de una excelente arena dorada y aguas cristalinas. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2567, 'S''Enclusa', 'Playa virgen compuesta de arena que presenta un bajo grado de ocupación debido a su difícil acceso. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2568, 'Cala Caldés', 'Cala aislada de difícil acceso localizada en una zona muy poco frecuentada por el turismo de la zona. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2569, 'Capifort', 'Playa compuesta de arena dorada que goza de una gran tranquilidad y aguas cristalinas.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2570, 'Cala d''En Tortuga', 'Pequeña cala de aspecto totalmente rústico y aislado, lejos del objetivo del turismo de la isla.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2571, 'Cala Morella Nou', 'Cala de grava y arena oscura que presenta un difícil acceso y recibe muy pocos visitantes. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2572, 'Cala de Sa Torreta', 'Cala con forma de media luna compuesta de arena dorada donde fondean barcos.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2573, 'Es grau', 'Playa localizada junto al núcleo urbano del mismo nombre, muy resguardada del oleaje debido a que forma una pequeña bahía y con gran calidad de su arena.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2574, 'Cala Macar de Binillautí', 'Pequeña cala de grava, nada frecuentada por el turismo debido a su difícil acceso y a su falta de servicios. ', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2575, 'Cala Mesquida', 'Cala situada junto al núcleo urbano denominado Sa Mesquida, frecuentada por los residentes en él y que dispone de servicio de limpieza y puesto de la Cruz Roja.', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200706, 'Cala Binidali', 'Pequeña playa balizada de arena dorada', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200707, 'Cala Canutells', 'Pequeña playa balizada de arena dorada', 7032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2361, 'Cala Calderer', 'Pequeña cala aislada y de difícil acceso, que presenta un grado de ocupación muy bajo.', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2362, 'Cala Pregonda', 'Playa virgen a la que se accede desde la playa vecina de Binimel-la, muy tranquila y con un color de arena blanca y aguas transparentes. ', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2557, 'Binimel-La', 'Playa virgen de arena dorada y fina caracterizada por la desembocadura de un torrente de gran tamaño y su variedad de aves acuáticas.', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2558, 'Es Macar Gran', 'Es Macar Gran y Petit son dos calas de grava y pequeño tamaño accesibles únicamente a pie por el GR-233 desde Cala Tirant', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2559, 'Es Macar Petit', 'Es Macar Gran y Petit son dos calas de grava y pequeño tamaño accesibles únicamente a pie por el GR-233 desde Cala Tirant', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2560, 'Tirant', 'Playa de arena con algo más de afluencia de visitantes que las calas de la zona.', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2561, 'Platja Gran', 'Playa ubicada muy cerca del núcleo de Fornells, localizado en la bahía del mismo nombre, y que representa uno de los enclaves con más encanto de la isla de Menorca.', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2562, 'Cala Pudent', 'Playa totalmente virgen que no dispone de accesos para llegar a ella, lo que contribuye a su aislamiento. ', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2563, 'Arenal de S''Olla de Son Saura', 'Playa bastante amplia y tranquila, formada por un gran arenal y rodeada de espesa vegetación de pinos que se extienden hasta la misma arena. ', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2564, 'Arenal d''en Castell', 'Playa ubicada en una pequeña bahía y formada por un gran arenal, que acoge gran cantidad del turismo de la zona ya que se encuentra bien equipada y con disponibilidad de alojamiento. ', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2565, 'Na Macaret', 'Esta pequeña playa es frecuentada por los residentes de la urbanización del mismo nombre, que se extiende a lo largo de la playa con pequeñas construcciones blancas que contribuyen al aspecto isleño de la zona.', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200708, 'Cavalleria', 'Playa rústica aislada', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200709, 'Cala Viola de Ponent', 'Pequeña playa rústica', 7037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2479, 'Muro', 'La Platja de Muro se presenta como una excelente playa de gran longitud con arena de buena calidad, servicios disponibles y poca profundidad, muy indicada para familias con niños y personas con alguna discapacidad.', 7039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2429, 'Caló d''Es Palangres', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2430, 'Cala Ganduf', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2431, 'Cala Donzell', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2421, 'Cala Major', 'Playa de carácter urbano situada en una de las zonas más turísticas de los alrededores de Palma de Mallorca. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2422, 'C''an Pere Antoni', 'Playa situada en el núcleo urbano de Palma de Mallorca, rodeada de edificios y gran actividad marítima, por su cercanía a los diferentes puertos de la zona. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2423, 'Ciudad Jardín', 'Playa urbana muy frecuentada por un turismo familiar que dispone de buenos servicios y accesos, incluso para discapacitados. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2424, 'Cala Gamba', 'Cala urbana con poco atractivo para el turismo debido a su cercanía al aeropuerto y al gran tráfico marítimo que presenta. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2425, 'Caló de son Caios', 'Playa urbana cercana al aeropuerto que carece de interés para los visitantes y los bañistas. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2426, 'Cala Estancia', 'Pequeña playa que presenta un elevado grado de ocupación y donde se puede encontrar un ambiente tranquilo para el baño. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2427, 'Playa de Palma', 'Extensa playa con más de cuatro kilómetros de recorrido, totalmente equipada y que puede considerarse como la playa más turística de Palma, o al menos la más conocida, no sólo por la playa sino por la gran oferta de ocio que presenta.', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2428, 'Cala de Santa María', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2432, 'Cas Pages', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2433, 'Espalmador', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2434, 'Platjes d''es Burrí', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2435, 'Caló d''es Macs', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2436, 'Platjes de S''Olla', 'Playa perteneciente a la Isla de Cabrera, incluida en el Parque Nacional del Archipiélago de Cabrera. ', 7040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2487, 'Platja d?Albercuix', 'Playa de arena ubicada en la Bahía de Pollença, con un alto grado de ocupación y totalmente equipada, incluso con acceso para discapacitados. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2488, 'Port de Pollença', 'Es la playa por excelencia en la zona de la bahía, que dispone de cualquier equipamiento, servicio o actividad que pueda necesitar el turista. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2489, 'Cala Formentor', 'Playa muy visitada por el turismo que acude a esta isla, completamente equipada, tanto para bañistas como para barcos que fondean en ella. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2490, 'Cala Sant Vicens', 'Cala Sant Vicens es el conjunto de tres pequeñas calas rústicas, Cala Molins, la más frecuentada por bañistas por ser de arena fina, Cala Carbó, de grava y piedras y Cala Clara, dominada por un hotel a pie de playa. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2541, 'Cala En Feliu', 'Pequeña cala con un paisaje idílico y un entorno que se presta a la práctica del submarinismo. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2542, 'Cala Murta', 'Cala de acceso complicado si no se hace por mar, con un entorno que se presta a la práctica del submarinismo. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2543, 'Cala en gossalba', 'Situada al norte de Cala Murta, de carácter aislado y con un entorno que se presta a la práctica del submarinismo. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2544, 'Cala Figuera', 'Playa situada camino del faro, con un entorno virgen, arena blanca y fina con gravas y bolos sueltos. ', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2545, 'Cala Boquer', 'Pequeña playa aislada con oleaje moderado', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2546, 'Cala Castell', 'Cala de piedras, cantos y bolos sueltos, situada al pie de un acantilado.', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200704, 'Ca''n Cuarassa', 'Extensa playa de arena y grava de afluencia media', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200705, 'Es Caló', 'Pequeña cala aislada con oleaje moderado', 7042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2281, 'Pont de Baix', 'Playa de arena oscura ubicada en un bonito entorno protegido como Area Natural de Especial Interés. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2282, 'Es Canal de S''Olla', 'Entorno pintoresco donde se asientan los pescadores de la zona, muy peculiar para observar sus tareas y costumbres.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2283, 'Ses Salines', 'Excelente playa de arena fina, con mucho ambiente de gente joven, donde puede encontrarse todo tipo de servicios e infraestructuras de playa. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2284, 'Es Cavallet', 'Playa bien equipada con servicios donde pueden practicarse todo tipo de deportes náuticos.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2285, 'En Bossa', 'La Platja d''En Bossa es un extenso arenal muy concurrido, donde pueden encontrarse todo tipo de ofertas de servicios, alquileres y deportes de playa. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2250, 'S''Estanyol', 'Playa urbana situada a dos kilómetros de Sant Antoni de Portmany, aunque pertenece al término de Sant Josep de Sa Talaia. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2251, 'Pinet', 'Muy frecuentada por visitantes y rodeada de edificaciones que albergan el turismo de la zona. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2252, 'Punta Xinxó', 'Pequeña playa cercana al núcleo de Sant Antoni de Portmany donde puede disfrutarse de alquileres de hamacas, sombrillas, etc.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2253, 'Caló de S''Oli', 'Playa rocosa con poco atractivo para el turismo de la zona.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2254, 'Es Port d''Es Torrent', 'Esta playa urbana compuesta de arena y rodeada de pinos presenta un elevado grado de ocupación durante la época estival. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2255, 'Cala Bassa', 'Cala muy frecuentada que dispone de alquiler de hamacas, sombrillas, embarcaciones náuticas, equipo de salvamento y acceso para discapacitados. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2256, 'Cala Roig', 'Acantilado bajo poco frecuentado por bañistas, pero muy recomendable por sus aguas tranquilas para el fondeo de embarcaciones de recreo. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2257, 'Cala Conta', 'Cala de arena que presenta un alto grado de ocupación y dispone de alquileres náuticos, hamacas, sombrillas y acceso para discapacitados. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2258, 'Sa Figuera Borda', 'Acantilado de muy difícil acceso por tierra, frecuentado únicamente por barcos que fondean en la zona. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2259, 'Cala Codolá', 'Playa de arena y grava con servicios de alquiler de hamacas y sombrillas. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2260, 'Cala Llentia', 'Pequeña playa de apenas treinta metros de longitud, de carácter aislado y bajo grado de ocupación.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2269, 'Cala Truja', 'Pequeño acantilado con un bajo grado de ocupación debido al carácter aislado que presenta. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2270, 'Cala D''Hort', 'Cala aislada que frecuentan bañistas y pescadores de la zona. No cuenta con servicio de vigilancia pero sí con equipo de rescate y farmacia.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2271, 'Cala Llentrisca', 'Cala aislada, con acceso complicado, compuesta de bolos y rodeada de vegetación. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2272, 'Cala d''Es Cubells', 'Playa de grava y aguas tranquilas.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2273, 'Les Ovelles', 'Playa virgen de muy difícil acceso ubicada en una zona montañosa.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2274, 'Sa Caixota', 'Playa aislada a la que se accede a través de unas escaleras de piedra construidas hasta la misma playa.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2275, 'Es Cuco', 'Playa de bolos que carece de instalaciones, pero muy agradable para los visitantes. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2276, 'Cala de Porroig', 'Típica playa frecuentada antiguamente por los pescadores de la zona, donde aún se encuentran los muelles y casas bajas utilizadas para guardar los aperos de pesca. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2277, 'Es Xarco', 'Playa rústica muy frecuentada por familias que acuden a disfrutar de la tranquilidad que reina en la zona. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2278, 'Jondal', 'Playa de bolos.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2279, 'Sa Caleta', 'Playa utilizada en exclusiva por los pescadores de la zona, donde colocan sus embarcaciones, aperos y utensilios de pesca. algo ruidosa por estar sometida al sobrevuelo de aeronaves', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2280, 'Es Codolá', 'Extensa playa algo incómoda para los bañistas ya que está compuesta exclusivamente de bolos, aunque con unas aguas de excelente calidad. Algo ruidosa por estar sometida al sobrevuelo de aeronaves', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200725, 'Es Torrent', 'Pequeña playa cerca de Sa Caixota', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2261, 'Cala Corral', 'Cala que carece de cualquier tipo de servicio con muy poca afluencia de visitantes, salvo barcos que fondean por la zona. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2262, 'Cala Tarida', 'Playa bien equipada.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2263, 'Caló d''Es Serral', 'Playa de arena de reducidas dimensiones que dispone de hamacas, sombrillas, alquileres náuticos y acceso para discapacitados. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2264, 'Cala Molí', 'Playa de arena y grava con varios servicios de alquiler y acceso para discapacitados. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2265, 'Caló d''En Real', 'Playa de rocas con difícil acceso, muy atractiva para fondear con embarcación de recreo. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2266, 'Cala Vedella', 'Doscientos metros de arena oscura, rodeada de vegetación y alquiler de servicios de playa. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2267, 'Caló de S''Oratge', 'Playa de rocas con difícil acceso por tierra, recomendable para el fondeo de los barcos.', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2268, 'Cala Carbó', 'Pequeña cala de arena con un grado de ocupación medio. ', 7048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2314, 'Caló d''En Serra', 'Pequeña cala al pie de acantilado y en un entorno de pinos y sabinas, tranquila y agradable.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2315, 'Port de Portinatx', 'Playa con todos los servicios y comodidades propias de un núcleo turístico. Ideal para turismo familiar. Junto con el Arenal Gran y Port de Portinatx son las playas de Portinatx. Con pinos y sabinas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2316, 'S''Arenal Gran', 'Playa con todos los servicios y comodidades propias de un núcleo turístico. Ideal para turismo familiar. Junto con el Arenal Gran y Port de Portinatx son las playas de Portinatx.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2317, 'S''Arenal Petit de Portinatx', 'Playa con todos los servicios y comodidades propias de un núcleo turístico. Ideal para turismo familiar, Junto con el Arenal Gran y Port de Portinatx son las playas de Portinatx. Con pinos en la misma playa.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2318, 'Cala Xuclá', 'Cala muy tranquila y poco frecuentada, ideal para la pesca en las rocas. Junto con Cala Xarraca y S''Illot des Renclí son las tres playas de la imponente bahía de Xarraca. Rodeada de pinos y cañas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2319, 'S''Illot d''En Renclí', 'Coqueta playita con el islote S''Illot den Renclí a pocos metros de la playa, se puede acceder a nado. Junto con Cala Xarraca y Cala Xuclá son tres pequeñas playas de la imponente bahía de Xarraca, rodeada de pinos y sabinas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2320, 'Cala Xarraca', 'Playa de gran belleza y tranquilidad con el islote Sa Mesquida accesible en velomar, con pinos y sabinas. Junto con S''Illot des Rencli y Cala Xuclá. Son las tres pequeñas playas de la imponente bahía de Xarraca.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2363, 'Caló d''Es Porcs', 'Cala rocosa de gran belleza y tranquilidad, con pinos. Ideal para excursionistas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2366, 'Caló d''En Calders', 'Pequeña cala virgen en un entorno natural y paisajístico inmejorable con pinos y sabinas. Ideal para excursionistas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2367, 'Port de Benirrás', 'Playa en un paisaje excepcional. La roca Cavall Bernat preside imponente la entrada a la cala. Cuenta con acceso para discapacitados.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2368, 'Port de Sant Miquel', 'Playa con todos los servicios y ofertas propias de un núcleo turístico. Ideal para el turismo familiar. Con pinos y sabinas', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2369, 'Caló d''Es Moltons', 'Pequeña y escondida cala con gran atractivo a poca distancia del Port de Sant Miquel donde hay que aparcar para seguir a pie.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2370, 'S''Illa d''En Bosc', 'Esta playa se forma en la unión de la costa de Ibiza con la pequeña Illa d''en Bosc. El lado de la unión es una agradable y tranquila playa con vistas a la cercana y más concurrida Port de Sant Miquel.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2372, 'Cala d''Es Portixol', 'Cala situada en un entorno natural y paisajístico excepcional con pinos y sabinas. Ideal para excursionistas.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2312, 'Cala San Vicente', 'Playa con todos los servicios y comodidades propias de un núcleo turístico. Ideal para turismo familiar.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2313, 'Cala d''Es Jonc', 'Cala muy aislada en un entorno paisajistico y natural excepcional con pinos y sabinas. Bajada a la playa en su último tramo difícil,  para excursionistas avanzados.', 7050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2324, 'Cala Alcaufar', 'Cala de carácter semiurbano que dispone de varios puntos de fondeo de barcos.', 7052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2325, 'Punta Prima', 'Excelente playa ubicada en la punta sureste de la isla de Menorca, que toma su nombre del núcleo urbano en el que se encuentra y que dispone de un total equipamiento en cuanto a servicios, instalaciones y oferta turística.', 7052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2326, 'Binibeca Nou', 'Playa muy resguardada que goza de unas aguas muy tranquilas, tanto para el baño como para el fondeo de los barcos. ', 7052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2290, 'Cala Rotja', 'Cala acantilada con dos pequeñas playas de 20 metros cada una, solitarias. Ideal para excursionistas y cercana a la ciudad de Ibiza.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2291, 'S''Estanyol', 'Playa tranquila en un entorno boscoso de pinos y sabinas, muy cerca de la ciudad de Ibiza. Ideal para excursionistas.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2292, 'Cala Espart', 'Pequeña y solitaria calita con pinos y sabinas, sin servicios. Ideal para excursionistas.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2293, 'Cala Olivera', 'Pequeña cala en un entorno boscoso de pinos y olivos, tranquilo con servicios básicos.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2294, 'Cala Llonga', 'Playa en un entorno paisajístico singular a la vez que dispone de los servicios y comodidades de un núcleo turístico. Buenos accesos y facilidades a personas de movilidad reducida. Ideal para todo tipo de usuarios.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2295, 'Caló de S''Algar', 'Pequeña y tranquila playa en el núcleo turístico de Siesta. Se puede llegar andando desde Santa Eulália.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2296, 'Santa Eulària', 'Playa urbana con todos los servicios y comodidades de una zona turística. Ideal para el turismo familiar.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2297, 'Ses Roquetes', 'Playa urbana, pero que carece de los servicios más elementales para el turismo. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2298, 'Es Riu de Sta Eulària', 'Playa urbana con todos los servicios y comodidades de una zona turística. Ideal para el túrismo familiar. Bonito paseo por la ribera del río con pinos.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2300, 'Es Niu Blau', 'Playa en la desembocadura de un torrente en un agradable ambiente natural con pinos y sabinas. Como otras playas de la zona tiene fondos poco profundos. Se puede llegar andando desde Santa Eulária.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2301, 'Cala Pada', 'Pequeña cala con buenos servicios en zona turístico-residencial. Ideal para turismo familiar. Centro de buceo', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2302, 'S''Argamassa', 'Playa de ambiente tranquilo en zona turístico-residencial, con pinos a pie de playa y predominio de fondos poco profundos.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2303, 'Cala Gat', 'Pequeña cala con total ausencia de servicios e instalaciones para el uso del turismo. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2304, 'Es Caná', 'Playa de carácter semiurbano con un alto grado de ocupación en verano.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2305, 'Cala Nova', 'Playa con equipamiento completo para el uso del turismo, muy concurrida durante el verano. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2306, 'Cala Llenya', 'Playa de arena frecuentada por el turismo de la zona. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2307, 'Cala Mastella', 'Cala muy bien señalizada, rodeada de vegetación que la hace muy agradable para su uso.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2308, 'Cala Boix', 'Playa rústica muy bien señalizada, ubicada en un entorno muy agradable para pasar un buen día de baño. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2309, 'Canal d''En Martí', 'Playa aislada de 170 metros de longitud y aguas tranquilas. ', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2310, 'Es Figueral', 'Playa de calidad con total disponibilidad de servicios playeros, deportes náuticos, ocio y turismo.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2311, 'Cala de S''Aigua Blanca', 'Playa de arena dorada que se desarrolla bajo un acantilado que conduce a la playa a través de una rampa.', 7054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2478, 'Son Serra de Marina', 'Playa situada a lo largo de la urbanización del mismo nombre, muy frecuentada por sus residentes, aunque bastante escasa en servicios. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2535, 'Es Dolç', 'Al oeste del núcleo urbano de Son Serra de Marina se encuentra esta lengua de arena de unos cien metros de longitud y ocho de anchura, limitada en su parte posterior por dunas y formaciones rocosas.', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2536, 'Son Real', 'Es la continuación de la Playa Es Dolç, que se corresponde con la desembocadura del torrente de Son Real. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2537, 'Cala Serralot', 'Playa muy cercana a Son Real, con acceso en Son Serra de Marina, normalmente cubierta de posidonia. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2538, 'S''Arenal d''En Casat', 'Fantástica playa virgen de unos 500 metros de longitud, prácticamente desierta incluso en verano, dado que el acceso se ha de hacer caminando. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2539, 'Son Bauló', 'Playa urbana limítrofe con el casco urbano de Ca''n Picafort formada por un extenso arenal, que se explota con diversas instalaciones desmontables de temporada. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2540, 'Ca''n Picafort', 'Playa urbana que ocupa casi la totalidad del casco urbano de Ca''n Picafort y se explota con diversas instalaciones desmontables de temporada. ', 7055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2350, 'Cala s''Almonia', 'Es una de las zonas del levante de la isla más abruptas y bonitas, de arena blanca y fina con canto rodado y piedras, frecuentada por vecinos del lugar y por algún turista. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2351, 'Caló d''Es Moro', 'Pequeña cala vecina de S''Amonia, accesible desde ésta y situada junto a las casitas de sa Comuna', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2347, 'Cala en Tugores', 'Playa con unos 200 metros de longitud y 15 metros de ancho, básicamente de arena blanca y fina. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2348, 'Es Caragol', 'Cala idílica con una longitud de unos 500 metros y 60 metros de anchura, con arena blanca y fina que al estar aislada el grado de ocupación es muy bajo. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2349, 'Cala Marmols', 'Cala pequeña de arena blanca y fina situada entre cortados espectaculares. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2448, 'Cala Llombards', 'Playa de arena blanca, estrecha pero muy ancha y rodeada de vegetación, que recibe gran cantidad de visitantes. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2449, 'Cala Santanyi', 'Playa muy frecuentada debido a gran calidad de su arena, las aguas transparentes y a las instalaciones y servicios que ofrece. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2450, 'S''Amarador', 'Playa perteneciente al Parque Natural de Mondragó, rodeada de vegetación y muy frecuentada por el turismo. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2451, 'Sa Font de N''Alis', 'Playa rústica ubicada en el Parque Natural de Mondragó, muy apreciada por el turismo familiar de la zona debido a los servicios y a la tranquilidad que ofrece. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2452, 'Caló de Sa Torre', 'Pequeña cala frecuentada por embarcaciones que fondean en la zona y por bañistas que se alojan en hoteles cercanos.', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2453, 'Cala Egos', 'Playa muy resguardada al estar formada en un entrante de mar en la costa, frecuentada por el turismo que acude a los hoteles próximos.', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2454, 'Cala D''Or', 'Esta playa está flanqueada por roquedales de baja altura, termina en un arenal pequeño, coqueto, de grano fino y con poco desnivel. Da nombre al complejo turístico que la rodea', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2455, 'Cala Gran', 'Playa urbana de arena blanca, que presenta un elevado grado de ocupación, sobre todo durante la época estival. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2576, 'Caló Santanyí', 'Playa muy frecuentada debido a la gran calidad de su arena, las aguas transparentes y a las instalaciones y servicios que ofrece. ', 7057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2499, 'En Repic', 'Playa situada en la Ensenada del Puerto de Sóller, muy atractivo para el turismo de la zona. ', 7061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2498, 'Puerto de Sóller', 'Playa muy frecuentada por el turismo por estar situada muy cerca del puerto de Sóller, pintoresco núcleo urbano de la isla de Mallorca. ', 7061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2467, 'Cala Bona', 'Esta playa se caracteriza por estar dividida en tres partes con pequeños diques de piedra, y se encuentra ubicada en una urbanización del mismo nombre. ', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2468, 'Port Roig', 'Playa muy frecuentada rodeada de pequeñas casas y apartamentos de poca altura que hacen muy agradable la zona. ', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2469, 'Port Vell', 'Este bello y tranquilo arenal está formado por guijarros y tostada arena gruesa, cuya orilla semisalvaje está salpicada de pinos, sabinas y tamarindos', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2470, 'Es Ribell', 'Playa rústica muy frecuentada por residentes de urbanizaciones cercanas, compuesta de arena y grava. ', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2517, 'Cala Millor', 'Playa de gran calidad por su arena y sus servicios e instalaciones, ubicada entre los términos de Sant Llorenç des Cardassar y Son Servera.', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2518, 'Es Torrent d''Es Morts', 'Cala de cantos rodados y piedra situada al norte del término de Son Servera, en la Urbanización de los Pinos. ', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200702, 'Es Rajoli', 'Pequeña playa de aguas tranquilas con afluencia media.', 7062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2502, 'Caló de S''Estaca', 'Esta playa dispone de accesos de tipo privado, por lo que presenta una bajo grado de ocupación. ', 7063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2503, 'Sa Font Figuera', 'Playa aislada carente de servicios y muy poco frecuentada por turistas y visitantes. ', 7063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2504, 'Port de Valldemossa', 'Playa de bolos ubicada en el litoral del espacio protegido de la Serra de Tramuntana, al pie de un pequeño núcleo urbano de pescadores. ', 7063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2548, 'Sa Cova', 'Playa de gravas, canto rodado y bolos a la que se accede desde la Urbanización Port des Canonge por un camino de tierra. ', 7063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2323, 'Cala Sant Esteve', 'Cala situada al sur del núcleo urbano d''Es Castell donde la mayoría de los visitantes acceden a ella fondeando sus barcos.', 7064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2505, 'Punta Galera', 'Es otra de las playas pertenecientes al espacio protegido como Área Natural de Especial Interés de la Serra de Tramuntana. ', 7007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2506, 'Cala Banyalbufar', 'Esta cala se encuentra al pie de un gran desmonte del terreno que constituye la única atracción que presenta la playa, su entorno. ', 7007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2549, 'Port D''Es Canonge', 'Playa con bajo grado de ocupación, compuesta de bolos y rocas. ', 7007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2550, 'Son Bunyola', 'Playa con acceso desde Es Port d''Es Canonge por camino y senda, con un entorno rodeado de bosque que alcanza el borde litoral. ', 7007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2551, 'Es Corral Fals', 'Playa de carácter aislado, rodeada de pronunciados taludes cubiertos por vegetación boscosa. ', 7007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2456, 'Cala Ferrera', 'Playa de entorno agradable, que dispone de instalaciones y servicios varios.', 7022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2457, 'Cala Mitjana', 'Cala de carácter aislado, rodeada de vegetación mediterránea y poco frecuentada por el turismo.', 7022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2458, 'Cala Marçal', 'Cala muy tranquila, tanto su ambiente como sus cristalinas aguas, que dispone de infraestructuras y servicios para el uso del visitante. ', 7022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (300701, 'S´Arenal de Portocolom', 'Cerca del Faro de Portocolom, extensión de arena fina y ambiente familiar.', 7022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2352, 'Caló Antena', 'Playa semiurbana de unos 40 metros de ancho y un fondo que llega a los 60 metros, de arena blanca y fina, con instalaciones desmontables. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2353, 'Caló Bota', 'Playa de pequeñas dimensiones situada en una finca privada, en un entorno fantástico. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2354, 'Cala Virgili', 'Playa situada en una finca privada, con acceso a pie, en un entorno fantástico. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2355, 'Cala Pilota', 'Playa situada en una finca privada, ubicada en un entorno fantástico. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2358, 'Cala Falco', 'Playa situada en una finca privada, con acceso privado, muy poco visitada por resultar complejo llegar hasta ella. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2359, 'Cala Petita', 'Pequeña cala muy frecuentada.', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2360, 'Cala Morlanda', 'Situada al sur de Cala Moreira, de costa rocosa, baja y entrecortada, con accesos algo incómodos, frecuentada por los vecinos del lugar. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2356, 'Cala Magraner', 'Es la playa más grande dentro del conjunto de playas de reducido tamaño de este fantástico entorno. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2357, 'Cala Sequer', 'Playa situada en una finca privada, muy poco visitada debido a la complejidad de su acceso. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2459, 'Cala Murada', 'Playa semiurbana muy frecuentada por los residentes de la urbanización del mismo nombre, situada a pie de playa. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2460, 'Cala Tropicana', 'Playa de arena blanca, rodeada de hoteles y vegetación, con un elevado grado de ocupación, sobre todo en la época estival. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2461, 'Cala Domingos', 'Se trata de una playa muy concurrida que ofrece todo tipo de servicios e infraestructuras y se encuentra rodeada de hoteles y apartamentos. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2462, 'Cala Estany', 'Cala cercana a la urbanización S''Estany D''En Mas, de ahí su nombre, que presenta un alto grado de ocupación y donde fondean gran cantidad de barcos. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2463, 'Porto Cristo', 'Esta playa se encuentra en el mismo núcleo urbano de Porto Cristo, donde existe un puerto marítimo de recreo muy atractivo para el turismo de la zona. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2511, 'Cala Varques', 'Playa bastante amplia, que ronda los 70 metros de anchura.', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2512, 'Cala Mandia', 'Cala Mandia se encuentra situada en la Urbanización Porto Cristo Novo, a unos 3 kilómetros de Porto Cristo. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2513, 'Cala Anguila', 'Vecina de Cala Mandia, a unos 300 metros al norte de ésta, situada también en la Urbanización Porto Cristo Novo. ', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2514, 'Cala Moreia', 'Cala Moreia pertenece al núcleo urbano de S''Illot, situada justo en el límite del término municipal lindando con el de Sant Llorenç des Cardassar, y está totalmente equipada.', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200701, 'Cala Rafalino', 'Cala virgen a unos 500 metros de la urbanización Cala Morlanda', 7033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2375, 'Cala Salada', 'Playa de dimensiones moderadas y arena dorada situada frente a Sa Conillera. ', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (456, 'Xagó', 'Extensa playa con un interesante complejo dunar. Presenta un alto nivel de ocupación y una discreta oferta hostelera.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (440, 'Aguilera', 'Arena dorada gruesa, fuerte oleaje y poca afluencia de público.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (441, 'San Pedro de Antromero', 'Playa de gran valor geológico e interesante por los restos fósiles de huellas de dinosaurios que aparecen en ella.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (442, 'Aramar', 'Formada por bolos y rocas, esta playa situada en una ensenada cerrada por islotes ', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (443, 'Bañugues', 'Enclavada en una ensenada en la cual se localizan interesantes yacimientos del Paleolítico. Dispone de zona de fondeo, duchas y servicio de limpieza.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (444, 'Carriciega', 'Playa de arena dorada enclavada dentro del Paisaje Protegido del Cabo de Peñas, que sufre fuerte oleaje y denota un bajo nivel de ocupación.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (445, 'El Dique', 'Pequeña playa de arena y grava con bajo nivel de ocupación. No ofrece ningún tipo de servicio.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (446, 'El Bigaral', 'Playa de reducidas dimensiones de arena blanca poco frecuentada por el público, en gran parte formado por pescadores.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (447, 'Gargantera', 'Playa en forma de concha compuesta por rocas. El acceso es bastante complicado y no ofrece ningún equipamiento por lo que no es muy frecuentada por el público.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (448, 'Llumeres', 'El color rojizo de esta playa le viene dado por unas antiguas minas de hierro que se ubicaban en ella. Es frecuentada por pescadores.', 33025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (509, 'El Oso', 'Playa tranquila con baja ocupación rodeada de altos acantilados que configuran un paisaje de interés pero que hacen complicado el acceso a pie.', 33055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (510, 'La Franca', 'Situada en la desembocadura del río Cabra, cuenta con arena fina blanca, gran afluencia de público y un buen nivel de servicios.', 33055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (511, 'Mendía', 'Se encuentra rodeada de acantilados y sólo se puede acceder a esta tranquila playa en bajamar. No dispone de equipamientos', 33055);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (558, 'El Puntal', 'Playa de reducido tamaño en la ría de Villaviciosa, declarada Espacio Natural. Está compuesta por arena dorada y rocas y posee una zona de arbolado.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (559, 'España', 'Enclavada en la desembocadura del río España, está rodeada de acantilados y se caracteriza por su fuerte oleaje y por la alta afluencia de público.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (560, 'Merón', 'Pequeña playa con forma de concha formada por arena y grava.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (561, 'Misiego', 'Está situada en la ría de Villaviciosa, por lo que disfruta de aguas tranquilas y arena dorada. No dispone apenas de infraestructuras.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (562, 'La Ñora', 'Arenal de reducidas dimensiones flanqueado por acantilados en uno de sus lados. Ofrece un nivel medio de servicios y un alto grado de ocupación.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (563, 'Rodiles', 'Extensa formación de arena adyacente a la ría de Villaviciosa, Espacio Natural de gran valor. Tiene una zona de arbolado compuesta por pinos y eucaliptus.', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (564, 'Tazones', 'Ubicada en el bello pueblo pesquero de Tazones, es un centro turístico de interés y su playa ofrece un buen nivel de equipamientos', 33076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2327, 'Cales Coves', 'Cales Coves es una pequeña cala al sur de la isla que presenta unos acantilados con gran cantidad de cuevas a las que se puede acceder andando.', 7002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2328, 'Cala''n Porter', 'Cala''n Porter es una playa equipada con los servicios típicos de una playa urbanizada y que acoge a gran cantidad de visitantes y residentes de la urbanización del mismo nombre. ', 7002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2329, 'Son Bou', 'Es una de las playas más visitadas del sur de la isla, por la calidad de la arena, su gran extensión, la oferta turística que ofrece y su excelente equipamiento. ', 7002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2480, 'Alcudia', 'Posiblemente la playa más frecuentada de esta zona de la isla, de gran extensión, entorno agradable con vegetación de pinos, totalmente equipada y con arena y aguas de gran calidad. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2481, 'Alcanada', 'Pequeña playa rodeada de vegetación, muy aconsejable para fondear los barcos y para la práctica de los deportes náuticos. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2482, 'Coll Baix', 'Playa virgen de difícil acceso a través de caminos de tierra, en una zona protegida como Área Natural de Especial Interés, pero carente de servicios e instalaciones. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2483, 'Sant Joan', 'Playa de arena blanca y gruesa, muy frecuentada debido al buen acceso que presenta, con servicios de playa y fuertemente explotada. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2484, 'Sant Pere', 'Playa muy frecuentada por los residentes de urbanizaciones cercanas, con los servicios más elementales de una playa. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2485, 'Sa Marina d''Alcudia', 'Playa de arena negra, muy cercana a la carretera, que carece de atractivo para los visitantes. ', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2486, 'Cap des Bou', 'Esta playa, aunque dispone de arena y entorno de baja calidad, es frecuentada por personas que practican deportes náuticos como windsurf y kitesurf.', 7003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2405, 'Cala En Cucó', 'Cala Cucó es una de las calas pertenecientes al Parque Natural de Sa Dragonera, pequeña isla perteneciente al término de Andraitx. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2406, 'Cala Basset', 'Esta cala se localiza frente al faro de la Isla Sa Dragonera y goza de unas aguas transparentes muy apropiadas para la práctica del snorkeling y para el fondeo de los barcos. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2407, 'Es Descarregador', 'Playa con pequeñas edificaciones que prácticamente se meten en el agua, cuyos residentes son los únicos que la frecuentan. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2408, 'Sant Elm', 'Es la playa más grande localizada en el núcleo urbano de Sant Elm que recibe gran afluencia de visitantes y dispone de gran cantidad de servicios e instalaciones. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2409, 'Cala Conills', 'Cala de muy reducido tamaño localizada frente a la Illa Sa Dragonera, declarada Parque Natural. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2410, 'Cala Egos', 'Cala aislada, de difícil acceso y bajo grado de ocupación, carente de servicios e instalaciones. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2411, 'Cala Marmassén', 'Playa de carácter semiurbano pero de ambiente muy tranquilo, frecuentada por los residentes de una lujosa urbanización cercana. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2412, 'Cala Llamp', 'Playa localizada al pie de una ladera que alberga lujosas casas unifamiliares.', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2413, 'Camp de Mar', 'Playa muy frecuentada por el turismo que dispone de todo tipo de equipamientos e instalaciones para el uso del público. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2414, 'S''Algar', 'Pequeña playa que recoge gran cantidad de algas, por lo que debido a su estado no se presenta nada deseable para los bañistas. ', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2415, 'Cala Fonoll', 'Pequeña cala de carácter urbano carente de servicios e instalaciones.', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2553, 'Cala Blanca', 'Playa de canto rodado y piedra. Para aceder a ella hay que salvar un gran desnivel por una senda serpenteante.', 7005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2476, 'Cala Torta', 'Es una de las playas de tipo familiar más conocidas de Europa, que unido a las aguas tan puras y cristalinas la convierte en un lugar muy atractivo.', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2477, 'Cala Mitjana', 'Rústica cala de arena.', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2523, 'Cala Estreta', 'Esta cala de piedra es un lugar ideal para el buceo, dada la claridad de sus aguas y riqueza de fauna marina. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2524, 'Cala Dèntol', 'Se trata de una entrada de piedra, con difícil acceso, donde la vegetación, rocas y mar conforman un fantástico paisaje. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2525, 'Cala es Matzoc', 'Playa totalmente virgen de arena y piedras de color dorado, a menudo cubierta de Posidonia y rodeada de uno de los pinares mejor conservados de la zona. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2526, 'Sa Font Salada', 'Profunda lengua de arena donde desemboca el torrente de Es Castellot, donde se llega caminando bordeando la abrupta costa. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2527, 'S''Arenalet d''Aubarca', 'Playa ubicada en las proximidades de Cabo Farrutx, zona con espectaculares acantilados. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2528, 'Es Caló', 'Se trata de un sector, dentro de la bahía de Alcudia, de acantilado bajo con pequeñas ensenadas con cuevas que le dan un encanto especial, con arenas finas y blancas mezcladas con gravas de tonalidades grises.', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2529, 'Cala Mata', 'Se trata de una calita en forma de herradura, con unos 250 metros de longitud y escasa anchura. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2530, 'Caló d''En Sureda', 'Entrantes y salientes de rocas a modo de pequeñas ensenadas con escaso fondo y poca ocupación. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2531, 'Caló D''Es Cans', 'Ensenada abierta formada en la desembocadura del torrente d''Es Cocó, formando una playa de cantos rodados, con la vegetación al mismo borde del agua. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2532, 'Cala Estret', 'Cala Estret es una amplia cala de cantos rodados y arena gruesa. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2533, 'Caló d''Es Parral', 'Pequeña playa urbana de arena gruesa y cantos formada en la desembocadura del torrente d''Es Parral, a continuación de Cala Estret. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2534, 'Sa Cánova', 'La Playa de Sa Cánova es una de las últimas grandes playas vírgenes de Mallorca. Se encuentra en ejecución el Proyecto de Ordenación del uso público y protección del litoral y dunas de Sa Canova. ', 7006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2416, 'Cala Fornells', 'Cala rodeada de vegetación con gran ocupación hotelera, donde pueden encontrarse embarcaciones turísticas de visión submarina. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2417, 'Peguera', 'Playa urbana que acoge gran cantidad del turismo de la zona y que dispone de instalaciones y servicios de todo tipo, así como una gran oferta de ocio en sus alrededores. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2418, 'Cala de Santa Ponça', 'Playa urbana que recoge una afluencia masiva de turistas durante la época estival, y que está totalmente equipada para ello con instalaciones, servicios, hoteles, restaurantes, etc. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2419, 'Cala Vinyes', 'Playa que goza de un entorno agradable a pesar de estar preparada para el turismo. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2420, 'Magalluf', 'Playa muy conocida por el turismo que frecuenta la zona, ya que está totalmente equipada y dispone de gran oferta hotelera y de ocio en sus alrededores.', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2509, 'Palma Nova', 'Esta playa recibe el mismo nombre que el núcleo residencial donde se ubica, donde puede encontrarse todo tipo de servicio, infraestructura, oferta de ocio y alojamiento que pueda demandar el turismo playero. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2510, 'Oratori de Portals', 'Puerto Portals es el núcleo cercano a la playa, muy frecuentado por el turismo de la isla, ya que se encuentra totalmente equipada y presenta un ambiente muy atractivo para los visitantes de la zona. ', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (300702, 'Cala Penyas Rotges', 'Playa ubicada en las inmediaciones del Port Adriano en la urbanización del Toro', 7011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2343, 'Ses Estanques', 'Es la última playa del término municipal de Campos, lindando con el Hotel Marqués del Palmer y la playa del mismo nombre, con arena de tonalidades doradas y muy poca pendiente. ', 7013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2442, 'S''Arenal de Sa Rápita', 'Es una de las tres playas ubicadas en la Ensenada de Sa Rápita, junto con la Playa de Ses Covetes y la Playa d''Es Trenc, una gran extensión de arena blanca. ', 7013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2443, 'Ses Covetes', 'Ses Covetes es la playa más pequeña de las tres que se encuentran en la Ensenada de Sa Rápita, intermedia entre las playas del S''Arenal de Sa Rápita y Es Trenc. ', 7013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2444, 'Es Trenc', 'Es la playa más larga de la Ensenada de Sa Rápita, formada por un extenso arenal de arena blanca, rústica y aislada, ya que apenas existe ninguna construcción. ', 7013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2556, 'Es Perengons Petits', 'Playa situada al final de la playa d''Es Trenc, en dirección este, antes de llegar a la playa de Ses Estanques. ', 7013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2471, 'Canyamel', 'Se trata de una playa con un buen equipamiento que presenta un elevado grado de ocupación durante el verano, sobre todo turismo extranjero. ', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2472, 'Sa Font de Sa Cala', 'Playa que, rodeada de vegetación, dispone de servicios e  infraestructuras y goza de un entorno muy agradable para el visitante.', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2473, 'Son Moll', 'Playa con buenas infraestructuras y servicios que confirman el alto grado de ocupación que presenta.', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2474, 'Cala Agulla', 'Esta playa dispone de servicios e instalaciones para su uso público, pero no se encuentra urbanizada, por lo que presenta un aspecto rústico muy apreciado en la zona. ', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2475, 'Cala Mesquida', 'Es una de las playas de la zona que dispone de infraestructuras y servicios y presenta un alto grado de ocupación.', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2519, 'Cala Rotja', 'Pequeña cala de carácter semiurbano con bajo grado de ocupación.', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2520, 'Cala Auberdans', 'Cala ubicada a escasos metros de otra de similares características conocida como Cala Rotja. ', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2521, 'Cala Gat', 'Situada al final del casco urbano de Cala Rajada, en el camino del Faro de Capdepera, con forma de hoz.', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2522, 'Cala Moltó', 'Ensenada de piedra con fondos arenosos, muy apreciada para fondear barcos de recreo, que disfruta de los servicios de la playa contigua, Cala Agulla. ', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200703, 'Cala Lliteras', 'Pequeña cala urbana de roca y arena', 7014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2335, 'Cala''n Bosch', 'Cala muy cercana a la urbanización del mismo nombre y muy frecuentada por sus residentes, que disponen de alquiler de sombrillas, hamacas y una excelente calidad de arena. ', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2336, 'Cala Blanca', 'Cala muy turística que dispone de un buen equipamiento y que toma su nombre de la urbanización cercana, así como del color blanco de su excelente arena.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2337, 'Cala Santandria', 'Playa de carácter semiurbano, muy bien equipada y que presenta un elevado grado de ocupación.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2334, 'Son Xoriguer', 'Esta playa es conocida con el nombre de la urbanización cercana de Son Xoriguer, y presenta un alto grado de ocupación y una gran oferta de servicios. ', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2338, 'Cala''n Blanes', 'Playa con gran número de infraestructuras y servicios, muy cercana al núcleo de Ciutadella de Menorca, punto de obligada visita de los turistas de la isla.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2339, 'Cala En Forcat', 'Esta cala es típica por la estrechez de su orilla, por lo que aunque acoge a un reducido número de visitantes, su grado de ocupación es elevado. ', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2340, 'Cales Piques', 'Playa de reducido tamaño, con grandes cortados a los dos lados, que presenta un elevado grado de ocupación. ', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2341, 'Cala Carbó', 'Playa muy rústica ubicada en la zona norte de la isla, que se caracteriza por el color oscuro de su arena y su bajo grado de ocupación.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2342, 'Cala del Pilar', 'Excelente playa de arena fina dorada y aguas tranquilas situada en una finca perteneciente a Parques Nacionales de gran valor natural y paisajístico.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200713, 'Cala Morell', 'Cala situada en la urbanización homónima, muy frecuentada por embarcaciones que buscan resguardo. Posee plataformas de baño artificiales y ruinas talayóticas muy próximas a la playa.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200714, 'Algaiarens', 'Playa situada al norte de Ciutadella famosa entre los aficionados al surf. Arena fina y aguas tranquilas cuando no sopla el viento de Tramuntana.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200715, 'Degollador', 'Cala situada en pleno núcleo urbano de Ciutadella. Es la más frecuentada por los vecinos de Ciutadella y está perfectamente adaptada.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200716, 'Sa Caleta d''en Gorries', 'Cala estrecha pero con abundante arena. Aguas muy tranquilas y de poca profundidad.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200717, 'Son Saura', 'Playa virgen situada al suroeste de Menorca. De gran longitud y protegida por un gran sistema dunar.', 7015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2377, 'Cala Gració', 'Playa totalmente equipada que acoge a gran cantidad de turistas y vecinos de urbanizaciones próximas. ', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2378, 'Caló des Moro', 'Playa urbana con instalaciones y servicios disponibles. ', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2379, 'Es Puetó', 'Playa urbana de arena fina y pendiente muy suave situada a dos kilómetros de  Sant Antoni de Portmany, con alto grado de ocupación y con los servicios propios de una playa urbana.', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2380, 'San Antonio', 'Otra de las playas del núcleo urbano de Sant Antoni de Portmany, con elevado grado de ocupación.', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200723, 'Cala Saladeta', 'Pequeña playa junto a Cala Salada', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200724, 'Cala Grasioneta', 'Pequeña playa junto a Cala Gració', 7046);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2464, 'Cala Moreia', 'Playa urbana rodeada de edificios de apartamentos que goza de los servicios típicos de una playa de ciudad.', 7051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2465, 'Sa Coma', 'Playa bien equipada, muy aparente para disfrutarla con niños debido a la superficie llana de su arena y la poca pendiente que presenta.', 7051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2466, 'Cala Millor', 'Excepcional playa que dispone de todo tipo de instalaciones, servicios y rodeada de gran oferta turística, por lo que recibe una gran afluencia de público. ', 7051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2515, 'Cala Nau', 'Pequeña ensenada en la zona norte de Punta Amer, totalmente equipada y con un elevado grado de ocupación. ', 7051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2516, 'Sant Llorenç', 'Playa de gran calidad totalmente equipada con servicios e infraestructuras. ', 7051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2344, 'Cala Galiota', 'Pequeña playa de arena blanca y piedras, de unos 50 metros de longitud por 12 metros de fondo, situada en el casco urbano de la Colonia de Sant Jordi. ', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2345, 'Playeta d''Es Delfí', 'Pequeñísima playa de arena y piedras entre la Playa d''Es Dolç y la de Ses Roquetes, poco frecuentada ya que suele estar cubierta de posidonia la mayor parte del año. ', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2346, 'Es Carbó', 'Esta playa se extiende desde Cala Delfí hasta Punta de Na Tianeta, en forma de S, y es muy frecuentada por los vecinos de la Colonia que se alejan de las aglomeraciones producidas por el turismo. ', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2445, 'Es Port', 'Playa localizada en el puerto de la Colonia de Sant Jordi, muy frecuentada por el turismo al estar situada en una zona muy céntrica del núcleo urbano.', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2446, 'Es Dolç', 'Esta playa recibe gran cantidad de visitantes, sobre todo residentes del núcleo cercano de la Colonia de Sant Jordi. ', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2447, 'Es Marques', 'Playa con un alto grado de ocupación que tiene disponibles varios servicios en alquiler. ', 7059);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2330, 'Sant Tomas', 'Playa muy amplia que presenta un elevado grado de ocupación, dispone de un buen equipamiento y goza de un ambiente muy tranquilo para el visitante. ', 7902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2331, 'Sant Adeodato', 'Playa muy cercana a la playa de Sant Tomas, con idénticas características en cuanto a su equipamiento y tranquilidad, desde donde se pueden ver una de las puestas de sol más bonitas de Menorca. ', 7902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200711, 'Cala Trebaluger', 'Playa de complicado acceso por tierra pero de gran belleza por su arena fina y sus aguas transparentes.', 7902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200712, 'Binigaus', 'Playa de arena dorada y sus aguas transparentes muy abierta al mar. De gran longitud y escasa anchura. Fácil de llegar y de gran tranquilidad al no existir edificaciones significativas.', 7902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2828, 'Risco', 'Playa abierta de arena y bolos que se encuentra localizada junto al barrio del Risco del municipio de Agaete, en el noroeste de la isla de Gran Canaria. Esta playa suele recibir un oleaje bastante fuerte, y a diferencia de la mayoría de las playas del municipio, cuenta con fácil acceso.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2829, 'Faneroque', 'Faneroque, también conocida como la Playa del Faneque o la Playa de Tamadaba, es una cala volcánica de arenas negras, situada al pié del inmenso Risco Faneque, de poco más de 1000 metros de altura, a unos 300 metros al (NO) de la Playa del Risco, en el noroeste de Gran Canaria.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2830, 'Sotavento', 'Playa de arena y piedras que suele recibir un oleaje y viento fuerte constante. Se  localiza muy cerca de Playa de Guayedra, en el municipio de Agaete, isla de Gran Canaria. Acceso a través del barranco de Guayedra, el cual puede hacer tanto a pie como en vehículo.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2831, 'Guayedra', 'Playa de Guayedra es una playa de arena y piedras que suele recibir un oleaje y viento fuerte constante. Se encuentra localizada en el municipio de Agaete, isla  de Gran Canaria. Su acceso se realiza a través del barranco de Guayedra, el cual puede hacer tanto a pie como en vehículo.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2832, 'Las Nieves II', 'La playa Las Nieves II situada en Agaete es una playa de arena y bolos de 210 metros de longitud. Lllamada también playa del Muelle o de Adelante, se encuentra localizada junto al antiguo muelle de Agaete, en el Noroeste de la isla de Gran Canaria. Playa de oleaje moderado.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2833, 'Las Nieves I', 'La Playa de las Nieves se encuentra localizada frente al antiguo muelle, en Agaete, Gran Canaria. Esta playa se caracteriza por ser una playa de bolos de 220 metros de longitud.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2834, 'Las Salinas', 'Playa de Las Salinas es una playa de piedras que suele soportar un oleaje fuerte. Esta playa se encuentra ubicada en la desembocadura del Barranco de Agaete, y su acceso puede hacerse a pie desde la Avenida Paseo de los Poetas, como en coche por el propio barranco.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2835, 'Turman', 'Playa con peligro de desprendimientos.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2853, 'Punta Gorda', 'Playa que se encuentra situada en una zona virgen enmarcada por acantilados, está localizada dentro del municipio de Agaete, y al noroeste de la isla de Gran Canaria. Esta pequeña playa rocosa tiene fuerte oleaje.', 35001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2837, 'Vargas', 'La playa Vargas situada en Agüimes es una playa de bolos de 1300 metros de longitud.', 35002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2838, 'El Cabrón', 'La playa El Cabrón situada en Agüimes es una playa de arena de 290 metros de longitud. ', 35002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2839, 'Arinaga', 'La playa Arinaga situada en Agüimes es una playa de arena de 700 metros de longitud. ', 35002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2840, 'Balos', 'La playa Balos situada en Agüimes es una playa compuesta de arena y bolos de 1000 metros de longitud. ', 35002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2958, 'Caleta de Fuste', 'La playa Caleta de Fuste situada en Antigua es una playa de arena de 700 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 35003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2959, 'El Muellito', 'La playa El Muellito situada en Antigua es una playa compuesta de arena y bolos de 180 metros de longitud. ', 35003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2960, 'Pozo Negro', 'La playa Pozo Negro situada en Antigua es una playa compuesta de arena y bolos de 310 metros de longitud. ', 35003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3015, 'El Castillo', 'La playa El Castillo situada en Arrecife es una playa de arena de 30 metros de longitud.', 35004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3016, 'El Reducto', 'La playa El Reducto situada en Arrecife es una playa de arena de 470 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3017, 'El Cable', 'La playa El Cable situada en Arrecife es una playa de arena de 315 metros de longitud. ', 35004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3018, 'La Concha', 'La playa La Concha situada en Arrecife es una playa de arena de 250 metros de longitud. ', 35004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203505, 'La Arena', 'La playa La Arena situada en Arrecife es una playa compuesta de arena y grava de 115 metros de longitud. Encajada dentro de la zona portuaria.', 35004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2841, 'Playa de las Arenas', 'Situada bajo las farallones del Andén Verde, entre la Punta de La Aldea al (O) y la Playa del Risco al (NO), es sin duda un lugar idóneo donde encontrar un ambiente muy tranquilo, en uno de los pocos entornos salvajes y casi vírgenes que quedan en la isla, de inigualable belleza.', 35005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3009, 'El Castillo', 'La playa El Castillo situada en La Oliva es una playa compuesta de arena, grava y bolos de 190 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3010, 'Marfolín', 'La playa Marfolín situada en La Oliva es una playa de arena de 950 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3011, 'Chica', 'La playa Chica situada en La Oliva es una playa de arena de 200 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203534, 'Los Verilitos', 'Playa de arena dorada, en zona residencial de Corralejo.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203535, 'De Corralejo viejo', 'Playa de arena dorada, en zona residencial de Corralejo.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203536, 'Playa del Hierro', 'Playa ventosa frecuentada por surfistas.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203537, 'Playa de los mallorquines', 'Playa de arena dorada, de difícil acceso, ventosa y aislada.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203538, 'Playa del Aguila', 'Playa de arena dorada, de difícil acceso (escalera en ml estado), ventosa y aislada.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203539, 'Playa de Esquinzo', 'Playa de arena dorada, de difícil acceso, ventosa, aislada, con una duna de arena hasta la parte superior del acantilado, frecuentada por surfistas.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203540, 'Playa del Tebeto', 'Playa de arena dorada, de difícil acceso, ventosa y aislada.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203533, 'El Jablito', 'Playa de arena blanca de reducidas dimensiones. Frecuentada por la gente del lugar y de práctica de submarinismo.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2988, 'La Lajita', 'La playa La Lajita situada en Pájara es una playa compuesta de arena y bolos de 915 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2989, 'Matas Blancas', 'La playa Matas Blancas situada en Pájara es una playa compuesta de arena, grava y bolos de 1500 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2990, 'Sotavento', 'La playa Sotavento situada en Pájara es una playa de arena de 1100 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2991, 'Butihondo', 'La playa Butihondo situada en Pájara es una playa de arena de 1500 metros de longitud.', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2992, 'Morro Jable', 'La playa Morro Jable situada en Pájara es una playa de arena de 4325 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2993, 'Las Coloradas', 'La playa Las Coloradas situada en Pájara es una playa compuesta de arena y bolos de 230 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2994, 'Morro de Potala', 'La playa Morro de Potala situada en Pájara es una playa compuesta de arena, grava y bolos de 300 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2995, 'El Puertito', 'La playa El Puertito situada en Pájara es una playa compuesta de arena, grava y bolos de 545 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2996, 'El Cofete', 'La playa El Cofete situada en Pájara es una playa de arena de 13700 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2997, 'El Viejo Rey', 'La playa El Viejo Rey situada en Pájara es una playa de arena de 800 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2998, 'La Pared', 'La playa La Pared situada en Pájara es una playa de arena de 250 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2999, 'Ugan', 'La playa Ugan situada en Pájara es una playa compuesta de arena, grava y bolos de 300 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3000, 'La Solapa', 'La playa La Solapa situada en Pájara es una playa de arena de 425 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3001, 'Ajuy', 'La playa Ajuy situada en Pájara es una playa compuesta de arena, grava y bolos de 270 metros de longitud. ', 35015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3002, 'Tarajalejo', 'La playa Tarajalejo situada en Pájara es una playa compuesta de arena, grava y bolos de 1370 metros de longitud. ', 35015);
