INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3102, 'Blanca', 'La playa Blanca, situada en Yaiza, es una playa de arena y roca de 130 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3103, 'Flamingo', 'La playa Flamingo, situada en Yaiza, es una playa de arena de 250 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3085, 'Quemada', 'La playa Quemada, situada en Yaiza, es una playa de arena de 310 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3086, 'La Arena', 'La playa La Arena, situada en Yaiza, es una playa compuesta de arena y grava de 330 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3087, 'El Pozo', 'La playa El Pozo, situada en Yaiza, es una playa compuesta de arena y grava de 345 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3088, 'El Valle de la Casa', 'La playa El Valle de la Casa, situada en Yaiza, es una playa compuesta de arena y grava de 160 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3104, 'La Mulata', 'La playa La Mulata, situada en Yaiza, es una playa compuesta de arena, grava y bolos de 80 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3105, 'La Campana', 'La playa La Campana, situada en Yaiza, es una playa compuesta de arena, grava y bolos de 140 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3106, 'Montaña Roja', 'La playa Montaña Roja, situada en Yaiza, es una playa de arena de 260 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3107, 'Janubio', 'Las salinas de Janubio son las mayores de la isla de Lanzarote. Escenario natural protegido', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3108, 'Montaña Bermeja', 'A 500 metros en dirección Sur se encuentran Los Hervideros, lugar de intererés donde el mar rompe con fuerza contra las rocas', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3109, 'Charco de los Clicos', 'La playa Charco de los Clicos, situada en Yaiza, es una playa compuesta de arena y grava de 500 metros de longitud y varadero de barcas de pesca, separada por la playa del Charco de los Clicos por un peñón.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3110, 'El Golfo', 'Playa aislada de grava y arena', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3111, 'Paso', 'Situada en el Parque Nacional de Timanfaya. Prohibido el acceso con vehículos', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203524, 'Caleta del Fuego', 'La playa Caleta del Fuego, situada en Yaiza, es una playa compuesta de arena, grava y bolos de 27 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203525, 'Barranco de las Pilas', 'La playa Barranco de las Pilasa, situada en Yaiza, es una playa de arena, grava y bolos de 250 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203526, 'La Colorada', 'Playa situada entre el Barranco de las Pilas y la playa del Cohon.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203527, 'El Cohon', 'La playa El Cohon, situada en Yaiza, es una playa de arena, grava y bolos de 35 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203528, 'Caleta Larga', 'La playa Caleta Larga, situada en Yaiza, es una playa de arena, grava y bolos de 350 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203529, 'El Pasito', 'La playa El Pasito, situada en Yaiza, es una playa de arena, grava y bolos de 200 metros de longitud.', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203530, 'Playa del Cochino', 'Playa situada en el Parque Nacional de Timanfaya. Prohibido el acceso con vehículos', 35034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2842, 'San Andrés', 'Playa compuesta de arena y bolos de 450 metros de longitud. La cantidad de arena depende mucho de las corrientes y la época del año. En invierno suele contar con menos áridos que en verano. Suele ser una playa tranquila muy usada por los vecinos de Arucas.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2843, 'Los Enanos', 'La playa Los Enanos, situada en Arucas, soporta un fuerte oleaje, como toda la costa de Arucas. De arena y callaos depende de la época del año, es una playa bastante frecuentada en comparación con las de los alrededores. Sobre todo acuden a ella los surferos.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2844, 'El Peñón', 'La playa El Peñón situada en Arucas es una playa de roca y bolos de 150 metros de longitud. Soporta un fuerte oleaje que la hace atractiva para la práctica de deportes sobre olas. Un rincón agradable para disfrutar en mareas bajas de charcos naturales y del deporte de la pesca.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2845, 'Quintanilla', 'La playa Quintanilla situada en Arucas es una playa compuesta de arena y bolos de 160 metros de longitud. Es una playa de arena negra, que con la marea baja se puede pasar una estupenda tarde muy tranquila para relajarse y disfrutar de puestas de sol maravillosas.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2846, 'Los Marrajos', 'La playa Los Marrajos situada en Arucas es una playa compuesta de arena y bolos de 110 metros de longitud.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2847, 'La Fuente', 'La playa La Fuente situada en Arucas es una playa de arena de 170 metros de longitud. ', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2848, 'Las Coloradas', 'La playa Las Coloradas situada en Arucas es una playa de bolos de 170 metros de longitud.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2849, 'Los Charcones', 'En las proximidades del Puertillo de San Andrés se encuentran los Charcones. La playa Los Charcones situada en Arucas es una playa compuesta de arena, grava y bolos de 175 metros de longitud.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2850, 'El Puertillo', 'La playa El Puertillo situada en Arucas es una playa de arena de 120 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2851, 'Charco las Palomas', 'La playa Charco las Palomas es una zona de baño rocosa en la escarpada costa de Arucas.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2852, 'Las Salinas', 'Las Salinas es un lugar de baño entre riscos en la escarpada costa de Arucas. Situada en una zona virgen, al pie de una antigua salina, para llegar a este paraje, hay que salvar un trecho caminando.', 35006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2942, 'Pagador', 'La playa Pagador situada en Moya es una playa de bolos de 310 metros de longitud.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2943, 'El Roque', 'La playa El Roque situada en Moya es una playa de bolos de 410 metros de longitud.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2944, 'El Altillo', 'La playa El Altillo situada en Moya es una playa de bolos de 120 metros de longitud.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2945, 'Boquini', 'La playa Boquini situada en Moya es una playa de bolos de 480 metros de longitud.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2894, 'San Lorenzo', 'La playa San Lorenzo situada en Moya es una playa de bolos de 920 metros de longitud. El oleaje en esta zona es bastante fuerte por lo que es recomendable tener precaución en el baño.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2895, 'Charco San Lorenzo', 'La playa Charco San Lorenzo situada en Moya es una playa de roca de 75 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3003, 'Blanca', 'La playa Blanca situada en Puerto del Rosario es una playa de arena de 875 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3004, 'Puerto Escondido', 'La playa Puerto Escondido situada en Puerto del Rosario es una playa de arena de 200 metros de longitud. ', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3005, 'Carrión', 'La playa Carrión situada en Puerto del Rosario es una playa compuesta de arena, grava y bolos de 305 metros de longitud. ', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3006, 'El Puertito', 'La playa El Puertito situada en Puerto del Rosario es una playa compuesta de arena, grava y bolos de 200 metros de longitud. ', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3007, 'Janubio', 'La playa Janubio situada en Puerto del Rosario es una playa compuesta de arena y grava de 230 metros de longitud. ', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203531, 'Playa Chica', 'Playa situada en el casco urbano de Puerto del Rosario, de arena blanca, y dotada de servicios para discapacitados, duchas y salvamento.', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203532, 'Puerto Lajas', 'Playa situada en el casco urbano de Puerto Lajas, de arena gris y dotada de servicios.', 35017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2929, 'Tasarte', 'La playa Tasarte situada en La Aldea de San Nicolás es una playa compuesta de arena, grava y bolos de 710 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2930, 'Aneas', 'La playa Aneas situada en La Aldea de San Nicolás es una playa de arena de 60 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2931, 'Tasartico', 'La playa Tasartico situada en La Aldea de San Nicolás es una playa de arena de 465 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2932, 'Descojonado', 'La playa Descojonado situada en La Aldea de San Nicolás es una playa de bolos de 50 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2933, 'Lioguicha', 'La playa Lioguicha situada en La Aldea de San Nicolás es una playa de arena de 240 metros de longitud.', 35020);
