INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2936, 'La Aldea', 'La playa La Aldea situada en La Aldea de San Nicolás es una playa de bolos de 720 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2937, 'Puerto La Aldea', 'La playa Puerto La Aldea situada en La Aldea de San Nicolás es una playa de bolos de 30 metros de longitud.', 35020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2939, 'Roque Prieto', 'La playa Roque Prieto situada en Santa María de Guía de Gran Canaria es una playa de roca de 40 metros de longitud.', 35023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2940, 'Punta del Angosto', 'La playa Punta del Angosto situada en Santa María de Guía de Gran Canaria es una playa de bolos de 175 metros de longitud.', 35023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2941, 'San Felipe', 'La playa San Felipe situada en Santa María de Guía de Gran Canaria es una playa compuesta de arena y bolos de 450 metros de longitud. ', 35023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3080, 'La Madera', 'La playa La Madera, situada en Tinajo, es una playa compuesta de arena y grava de 85 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3081, 'Las Malvas', 'La playa Las Malvas, situada en Tinajo, es una playa compuesta de arena y grava de 180 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3082, 'Teneza', 'La playa Teneza, situada en Tinajo, es una playa compuesta de arena y grava de 90 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3083, 'La Ría de la Santa', 'Ría transformada en laguna al cerrarse sus dos bocas. Adecuada para la iniciación al windsurf.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3084, 'La Boca de Abajo', 'La playa La Boca de Abajo, situada en Tinajo, es una playa compuesta de arena y grava de 200 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203519, 'Piedra Mansa', 'La playa Piedra Mansa, situada en Tinajo, es una playa compuesta de arena y roca de 300 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203520, 'Pico Alto', 'La playa Piedra Mansa, situada en Tinajo, es una playa compuesta de arena y roca de 130 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203521, 'Barranco del Burro', 'La playa Barranco del Burro, situada en Tinajo, es una playa compuesta de arena,roca y bolos de 70 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203522, 'La Santa (Pueblo)', 'La playa La Santa (Pueblo), situada en Tinajo, es una playa compuesta de arena y roca de 130 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203523, 'Los Risquetes', 'La playa Los Risquetes, situada en Tinajo, es una playa compuesta de arena,bolos y roca de 600 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203518, 'Caleta del Mariscadero', 'La playa Caleta del Mariscadero, situada en Tinajo, es una playa compuesta de arena, roca y grava de 600 metros de longitud.', 35029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203814, 'El Beril', 'Playa de bolos y grava fina, de aguas tranquilas, anexa a la playa del Duque, sin ningún tipo de servicios.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (615, 'Ajabo', 'Pequeña playa rodeada de urbanizaciones que disfruta de aguas tranquilas para el baño, pero no ofrece ningún tipo de servicio.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (616, 'Las Galgas', 'Playa pequeña rodeada de altas edificaciones y con multitud de instalaciones hoteleras en los alrededores.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (617, 'El Pinque', 'Playa de reducido tamaño enclavada en una zona altamente urbanizada, que presenta un crecimiento imparable.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (618, 'Las Salinas', 'Playa pequeña situada en las inmediaciones de un gran complejo hotelero. Ofrece aguas tranquilas que permiten disfrutar del baño.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (619, 'El Puertito', 'Playa de arena, resguardada, por lo que disfruta de aguas tranquilas.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (620, 'Diego Hernández', 'Agradable playa de aguas tranquilas y arena dorada a la que se suele acceder en barco, aunque el acceso a pie no es complicado.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (621, 'Los Morteros', 'Playa aislada y tranquila sin ningún tipo de equipamiento pero enclavada en un agradable entorno', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (622, 'La Caleta', 'Playa de la población de La Caleta, que disfruta de aguas tranquilas propicias para el baño.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (623, 'El Duque', 'Playa rodeada de instalaciones hoteleras por lo que presenta una alta afluencia de visitantes. Ofrece todo tipo de servicios que hacen de esta playa una buena elección.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (624, 'Fañabé', 'Playa muy visitada que ofrece todo tipo de servicios al público. Se encuentra en una zona altamente urbanizada.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (625, 'Torviscas', 'Playa unida a la de Fañabe, dotada de excelentes equipaciones y muy visitada por los bañistas, que encuentran en esta zona todo tipo de comodidades.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (626, 'El Bobo', 'Pequeña playa de arena oscura con buenos servicios, ubicada en una zona dotada de todo tipo de equipamientos.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (627, 'La Pinta', 'Resguardada playa con todo tipo de infraestructuras, que la convierten en uno de los principales focos de turismo de esta zona de la isla', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (628, 'Las Américas', 'Playa con un alto nivel de equipamientos y rodeada de todo tipo de infraestructuras hoteleras, lo que la convierte en uno de los núcleos turísticos de la isla.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (629, 'El Varadero', 'Pequeña cala de bolos y arena que no ofrece ningún tipo de servicios y que presenta un bajo grado de ocupación.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (630, 'La Enramada', 'Amplia playa ubicada en una zona que está sometida a un continuo proceso de urbanización.', 38001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (565, 'San Marcos', 'Situada a escasa distancia del núcleo urbano, es una playa resguardada de arena negra. No ofrece ningún tipo de equipamiento', 38002);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203816, 'Las Ceras', 'Playa de bolos y grava, sin ningún tipo de servicio.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (631, 'El Río', 'Amplia playa en un paraje aislado que no ofrece ningún tipo de servicio. Presenta escasa afluencia de público.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (632, 'Callao Hondo', 'Playita de rocas y grava, tranquila y poco utilizada por los bañistas. Sin equipamientos.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (633, 'Tajao', 'Playita del pequeño pueblo de Tajao, resguardada por el pequeño muelle del puerto. No dispone de equipamientos.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (634, 'Los Abrigos', 'Playa cercana a la urbanización de Abades, de arena dorada y aguas tranquilas adecuadas para el baño.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (635, 'Cardones', 'El agua limpia y cristalina de esta playa hace que las condiciones para el baño sean óptimas. Presenta un bajo nivel de ocupación.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (636, 'Cueva de la Arena', 'Playa pequeña, aislada y de aguas cristalinas, que goza de una gran tranquilidad. Cercana al faro de Abona.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (637, 'Grande', 'Situada en las inmediaciones del faro de Abona se encuentra esta playa de arena dorada, que suele estar azotada por el viento.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (638, 'Poris', 'Playa de la población Poris de Abona, que ofrece aguas tranquilas y suele mostrar bastante afluencia de bañistas', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (639, 'El Bonito', 'A esta playa se accede a pie dando un largo paseo, por lo que suele presentar una escasa afluencia de visitantes. No dispone de infraestructuras', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (640, 'El Sombrerito', 'A esta pequeña playa se accede dando un paseo, ya que en coche no se puede llegar hasta ella. Presenta una escasa afluencia de público', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (641, 'Aguadulce', 'A esta playa se accede por un camino de arena desde la carretera cercana. No dispone de equipamiento alguno.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203819, 'Abades', 'Playa de grava y bolos anclada en bello entorno de cardones y tosca, muy frecuentada por los campistas.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203820, 'Las Maretas', 'Playa de oleaje moderado, de bolos y sin nigún equipamiento', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203817, 'El Caletón', 'Playa de bolos, grava y rocas, sin servicio alguno. Frecuentada por los surfistas por estar ubicada en zona ventosa.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203818, 'Las Caletillas', 'Pequeña cala de grava fina. No cuenta con ningún tipo de servicio.', 38005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203813, 'El Callao', 'Playa de bolos y grava', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (642, 'Troya', 'Extensa playa del término de Arona, en una de las zonas turísticas por excelencia de la isla de Tenerife.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (643, 'El Camisón', 'Playa resguardada por los espigones que la rodean, y dotada con todo tipo de equipamientos que hacen que presente una elevada afluencia de bañistas.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (644, 'Las Vistas', 'Extensa playa dotada de todo tipo de servicios e instalaciones hosteleras, situada en una de las zonas más visitadas por el turismo.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (645, 'Los Cristianos', 'Playa de un importante centro turístico, por lo que dispone de todo tipo de servicios y facilidades para sus usuarios.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (646, 'El Palmar', 'Esta playa está un tanto alejada de los centros turísticos de la zona, por lo que permite disfrutar de una cierta tranquilidad.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (647, 'El Callao', 'Pequeña playa que presenta una escasa afluencia de público y no dispone de equipamiento alguno.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (648, 'Los Enojados', 'Playa de arena oscura poco visitada por los bañistas y que no ofrece ningún servicio', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (649, 'Las Galletas', 'Playa resguardada por el espigón del puerto de Las Galletas, por lo que disfruta de aguas tranquilas. Presenta un buen nivel de servicios.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (650, 'La Ballena', 'Pequeña playa de arena oscura situada en el pueblo de Las Galletas. Dispone de Club Náutico y zona reservada para submarinismo', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203824, 'Playa de Los Tarajales', 'Playa de arena, grava y rocas, anexa a la de Los Cristianos y que carece de servicios.', 38006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (750, 'Fajana de Barlovento', 'Zona de baño rocosa a la que se accede en coche y dispone de aparcamiento, aseos y duchas.', 38007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (752, 'Los Cancajos', 'Amplia playa de arena oscura, muy frecuentada por el público y dotada de buenos equipamientos.', 38009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (652, 'Los Barqueros', 'Playa que presenta un fuerte oleaje y que no ofrece ningún tipo de servicio,  por lo que es poco frecuentada por el público.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (653, 'Las Arenas', 'Playa característica por su microclima, que la protege de los vientos del noroeste, y por ser de arena desde Junio hasta Noviembre, para en invierno perderla convirtiéndose en una playa de bolos.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (654, 'Las Mujeres', 'Fuertes olas rompen contra las rocas que rodean esta playa, que se halla ubicada en una zona de cultivos.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (655, 'El Fraile', 'Las condiciones para el baño se complican por el fuerte oleaje y las rocas que presenta esta playa, que no es muy frecuentada por los bañistas.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (656, 'La Ballenita', 'Playa rústica de arena y grava con un grado de ocupación medio. Es una playa aislada que no tiene paseo marítimo.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (657, 'Juan López', 'Próxima a la desembocadura del barranco de Masca, se halla en un paraje virgen y aislado de la costa de Buenavista del Norte. Está enclavada en una zona protegida.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203541, 'Playa del Valle', 'Playa de arena oscura, con fuerte oleaje en zona semiurbanizada.', 35007);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2873, 'La Caleta de Arriba', 'La playa La Caleta de Arriba situada en Gáldar es una playa de roca y bolos de 40 metros de longitud.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2836, 'Juncal', 'Caleta, entre los municipios de Galdar y Agaete, configurada por un espolón a su entrada, el final del barranco en el fondo, y la imponente pared que vuelve a salir al mar abierto. Destaca por sus aguas tranquilas y cristalinas.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2854, 'La Guancha', 'Otra de las pequeñas calas localizada al noroeste del municipio de Gáldar, Isla de Gran Canaria, situada en un paraje virgen y aislado, se llega a ella a pie. Se trata de una playa rocosa, ventosa y de fuerte oleaje, donde hay que tomar precauciones a la hora de bañarse.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2855, 'Lagarto', 'La playa Lagarto situada en Gáldar es una de las pequeñas calas localizadas al noroeste del municipio Gáldar, isla de Gran Canaria, accesible por un camino de tierra. Sus transparentes aguas son óptimas para practicar el submarinismo.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2856, 'Arrastradero', 'La playa Arrastradero es otra de las pequeñas calas  localizada al noroeste del municipio de Gáldar, Isla de Gran Canaria. Situada en un paraje virgen y aislado, se llega a ella a pie. Playa ventosa y de fuerte oleaje, donde hay que tomar precauciones a la hora de bañarse.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2857, 'Risco Partido', 'La Playa de Risco Partido es una playa pequeña localizada en el municipio de Gáldar, isla de Gran Canaria, accesible por un camino de tierra y después hay que caminar un poco, su bajada es peligrosa, pero su encanto está en el fondo marino de la zona.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2858, 'Martorell', 'La playa Martorell situada en Gáldar es una playa pequeña, localizada en el municipio de Gáldar, isla de Gran Canaria, se halla situada en el borde de la ensenada que baña a la localidad de Sardina.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2859, 'Sardina', 'Playa, situada en el noroeste de la isla de Gran Canaria, protegida de los vientos alisios por la bella bahía flanqueada por el Farallón de Tábata al suroeste y por el Lomo del Faro al noroeste. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2860, 'El Muelle', 'La Playa del Muelle es una playa pequeña de arena y bolos. Está localizada en el municipio de Gáldar, isla de Gran Canaria, entre playa Sardina y el puerto de Sardina. La playa cuenta con servicios básicos como aseos y aparcamiento.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2861, 'El Roquete', 'Playa localizada en el municipio de Gáldar, isla de Gran Canaria. La ondulante línea costera traza someros arcos, que sirven para formar recoletas playas. La de El Roquete se asienta bajo los acantilados que la constriñen, después del puertito de la playa de El Muelle.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2862, 'Paso del Salgo', 'Es una resguardada y rocosa zona de baño en la costa de Gáldar, a pesar de que la zona es ventosa y hay un oleaje moderado. Situada en una zona virgen y aislada, a la que solo se puede acceder a pie o en barca.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2863, 'Punta del Faro', 'La zona cuenta con pequeñas piscinas naturales que se llenan con las mareas. En caso de fuerte oleaje es conveniente no bañarse en esta playa ya que al ser roca, cualquier golpe de mar puede suponer un peligro. Tiene unos fondos muy transparentes para realizar submarinismo.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2864, 'Caletón de los Cangrejos', 'Situada en una zona virgen y aislada, a la que sólo se puede acceder a pie, son pequeñas piscinas naturales que se llenan con las mareas. Compuesta de riscos, se trata de una playa ventosa y de fuerte oleaje.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2865, 'Punta Galdar', 'Es una playa de riscos, ventosa y de fuerte oleaje, que carece de servicios.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2866, 'Caleta de Abajo', 'Se conforma en una breve ensenada de este sinuoso tramo de costa', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2867, 'Punta del Clavo', 'Los acantilados de elevada altura marcan el linde costero de una meseta concurrida de cultivos, invernaderos y poblados, que pugnan por ocupar el borde del mismo mar.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2868, 'Furnia', 'La playa Furnia está situada en el municipio de Gáldar, en la isla de Gran Canaria. Se encuentra en un paraje virgen, situada entre riscos y formada por rocas y bolos. Las aguas son cristalinas, aunque la playa soporta un fuerte oleaje.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2869, 'Dos Roques', 'La playa de Dos Roques es otra de las pequeñas calas que jalonan la costa de Gáldar. Es de arena dorada de grano medio combinada con callaos. Dispone de paseo marítimo como único equipamiento.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2870, 'Boca Barranco', 'La playa Boca Barranco situada en Gáldar es una playa compuesta de arena fina y dorada y bolos.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2871, 'El Agujero', 'La playa El Agujero situada en Gáldar es una playa de arena de 150 metros de longitud.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2872, 'La Redonda', 'La playa La Redonda situada en Gáldar es una playa de roca de 45 metros de longitud.', 35009);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3028, 'Caleta del Guincho', 'La playa Caleta del Guincho situada en Haría es una playa de arena de 70 metros de longitud.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3029, 'Caleta de José María', 'La playa Caleta de José María situada en Haría es una playa compuesta de arena, grava y bolos de 180 metros de longitud.', 35010);
