INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3023, 'Caleta González', 'La playa Caleta González situada en Haría es una playa compuesta de arena y bolos de 140 metros de longitud.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3024, 'El Banquito', 'La playa El Banquito situada en Haría es una playa compuesta de arena y bolos de 75 metros de longitud. ', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3025, 'Caleta del Mojón', 'La playa Caleta del Mojón situada en Haría es una playa compuesta de arena y grava de 200 metros de longitud.', 35010);
