INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3027, 'Caleta de las Escamas', 'La playa Caleta de las Escamas situada en Haría es una playa de arena de 40 metros de longitud.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3031, 'Las Sebas', 'En la actualidad no existe playa. Se construyó una rampa para varada de embarcaciones.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3032, 'Caleta del Espino', 'La playa Caleta del Espino situada en Haría es una playa de arena, bolos y grava de 55 metros de longitud. La arena se pierde.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3033, 'Caleta del Campo', 'La playa Caleta del Campo situada en Haría es una playa compuesta de roca y bolos de 50 metros de longitud. No tiene arena.', 35010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3034, 'El Charcón', 'La playa El Charcón situada en Haría es una playa de arena y roca de 15 metros de longitud.', 35010);
