INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2883, 'Puerto Rico', 'La playa Puerto Rico situada en Mogán es una playa de arena de 284 metros de longitud, que cuenta con numerosos servicios de restauración.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2884, 'Amadores', 'La playa Amadores situada en Mogán es una playa de arena de 488 metros de longitud, que cuenta con con numerosos bazares y servicios de restauración.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2885, 'Tauro', 'La playa Tauro situada en Mogán es una playa compuesta de arena, grava y bolos de 440 metros de longitud, situada en la desembocadura de barranco de Tauro.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2886, 'El Cura', 'La playa El Cura situada en Mogán es una playa pqueña y tranquila compuesta de arena oscura de 193 metros de longitud.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2887, 'Medio Almud', 'La playa Medio Almud situada en Mogán es una playa compuesta de arena  grava y bolos de 87 metros de longitud, situada en la desembocadura de un barranco con entorno seminatural agradable.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2888, 'Tiritaña', 'Pequeña playa de arena negra flanqueada por acantilados, en la desembocadura del pequeño barranco de Tiritaña. Posee un entorno natural muy agradable.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2876, 'Marañuela', 'La playa Marañuela situada en Mogán es una playa compuesta de arena oscura de 279 metros de longitud.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2877, 'Costa Alegre', 'Pequeña playa con dique artificial. La playa Costa Alegre situada en Mogán es una playa de arena y grava de 55 metros de longitud.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2878, 'La Carrera', 'La playa La Carrera situada en Mogán es una playa compuesta de arena, grava y bolos de 40 metros de longitud. ', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2879, 'Patalavaca', 'La playa Patalavaca situada en Mogán es una playa de arena de 303 metros de longitud, idónea para el baño, que cuenta con numerosos servicios de restauración.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2880, 'Aquamarina', 'La playa Aquamarina situada en Mogán es una playa de arena de 70 metros de longitud, apta para el baño.', 35012);
