INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2890, 'Taurito', 'Playa con oleaje y corrientes moderadas que exigen extremar las precauciones en el baño cuando hay mar de fondo. De arena negra, con numerosos servicios náutico-deportivos.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2891, 'Mogán', 'Playa urbana con numerosos serviios de restauración.', 35012);
