INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203503, 'Los Frailes', 'Pequeña playa tranquila de arena, grava y bolos con una rasa marina interesante.', 35012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203504, 'Perchel', 'Playa de bolos en entorno natural muy agradable.', 35012);
