INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2973, 'Punta Prieta', 'La playa Punta Prieta situada en La Oliva es una playa compuesta de arena y bolos de 600 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2974, 'Puerto Remedios', 'La playa Puerto Remedios situada en La Oliva es una playa compuesta de arena y bolos de 700 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2975, 'Medano', 'La playa Medano situada en La Oliva es una playa de arena de 700 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2976, 'El Pozo', 'La playa El Pozo situada en La Oliva es una playa de arena de 450 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2977, 'El Viejo', 'La playa El Viejo situada en La Oliva es una playa de arena de 1000 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2978, 'El Caserón', 'La playa El Caserón situada en La Oliva es una playa de arena de 300 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2979, 'El Bajo Negro', 'La playa El Bajo Negro situada en La Oliva es una playa de arena de 500 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2980, 'Larga', 'La playa Larga situada en La Oliva es una playa de arena de 800 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2981, 'Los Martos', 'La playa Los Martos situada en La Oliva es una playa de arena de 900 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2982, 'El Dormidero', 'La playa El Dormidero situada en La Oliva es una playa de arena de 440 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2983, 'El Moro', 'La playa El Moro situada en La Oliva es una playa de arena de 560 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2984, 'El Rosadero', 'La playa El Rosadero situada en La Oliva es una playa compuesta de arena y bolos de 450 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2985, 'Alzada', 'La playa Alzada situada en La Oliva es una playa de arena de 840 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2987, 'Calas del Puertito', 'La playa Calas del Puertito situada en La Oliva es una playa compuesta de arena y bolos de 140 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (3008, 'El Aljibe ', 'La playa El Aljibe  situada en La Oliva es una playa compuesta de arena y grava de 1210 metros de longitud.', 35014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (744, 'Barranco Seco', 'Amplia cala aislada a la que sólo se puede acceder en barco o caminando por el barranco que desemboca en la misma. El entorno que la rodea es magnífico y las aguas limpias y cristalinas.', 38040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (666, 'La Garañona', 'Extensa playa dentro de una zona declarada Espacio Natural Protegido, de acceso complicado por encontrarse al pie de un acantilado.', 38041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (745, 'El Rincón', 'Playa que ofrece unas condiciones aceptables para el baño, pero que no dispone de ningún tipo de infraestructura.', 38043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (746, 'El Sargo', 'Pequeña playa que cuenta con área de fondeo, poco frecuentada por los bañistas', 38043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (747, 'El Pris', 'Playa de reducidas dimensiones cuyas condiciones para el baño son complicadas debido al fuerte oleaje que presenta, por lo que está poco frecuentada por los bañistas', 38043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (748, 'La Arena', 'Playa de arena negra y fina de origen volcánico, se encuentra bajo unos acantilados. Ofrece aguas tranquilas al resguardo de las corrientes marinas.', 38043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (749, 'El Camello', 'Playa aislada compuesta por rocas, poco apta para el baño. No cuenta con ningún tipo de infraestructuras.', 38043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (777, 'Tazacorte', 'Playa de la localidad de Tazacorte con paseo marítimo y que dispone de aparcamiento.', 38045);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (778, 'Puerto de Tazacorte', 'Está ubicada en la localidad de Tazacorte, anexa al puerto. Cuenta con aparcamiento y accesos para discapacitados', 38045);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (779, 'Lago de las Damas', 'Playa rocosa aislada y con escasa afluencia de público. No dispone de ningún tipo de equipamiento.', 38045);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (780, 'Girre', 'Está ubicada en una zona de cultivos. Dispone de aparcamiento y de accesos señalizados.', 38045);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (792, 'Nueva', 'Pequeña playa aislada y poco frecuentada que no ofrece ningún tipo de servicio.', 38045);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (781, 'El Jorado', 'Está situada a los pies de un impresionante barranco, por lo que el acceso a pie es muy complicado y está poco frecuentada', 38047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203802, 'La Veta', 'Pequeña playa con baja afluencia', 38047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (608, 'Pozo de las Calcosas', 'Piscina natural, utilizada como lugar de veraneo de la población cercana, de difícil acceso por un estrecho sendero que baja al acantilado.', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (609, 'Charco Manso', 'Pequeña cala de tipo volcánico, con fuerte oleaje y sin servicios.', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (610, 'El Tamaduste', 'Playa situada en un entorno volcánico y que ha pasado de ser una zona de pescadores a convertirse en un lugar de veraneo para los habitantes del Municipio, cuenta con algunos servicios.', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (611, 'La Caleta', 'Pequeña playa situada en una zona desarrollada como núcleo de segunda residencia para los habitantes de la zona.', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (612, 'Puerto de la Estaca', 'Playa situada junto al Puerto, utilizado como refugio de pescadores', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (613, 'Timijiraque', 'Próxima al Puerto de la Estaca, es una de las pocas playas de arena de la Isla. Suele ser frecuentada por surfistas.', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (614, 'Las Playas', 'Al inicio de la bahía de Las Playas aparece la imponente figura del Roque de la Bonanza, una formación rocosa que se alza verticalmente 200 metros sobre el suelo oceánico. Es uno de los motivos más fotogénicos de la isla', 38048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (590, 'Vallehermoso', 'Pequeña playa de roca y grava con grado medio de ocupación. Dispone de duchas.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (591, 'Arguamul', 'Amplia playa rocosa y de fuerte oleaje. Poco frecuentada por los bañistas. No dispone de servicios.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (592, 'El Trigo', 'Cala de pequeño tamaño compuesta por rocas que se encuentra encajada entre acantilados de difícil acceso.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (593, 'Alojera', 'Playa semiurbana de arena y rocas a la que se accede fácilmente a pie. No dispone de infraestructuras.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (594, 'Argaga', 'Playa de pequeño tamaño cercana al núcleo urbano de Valle Gran Rey, formada por rocas y de aguas tranquilas. No dispone de equipamientos.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (595, 'Las Arenas', 'Pequeña cala aislada situada al pie del acantilado, con escasa afluencia de bañistas y de difícil acceso. No ofrece ningún tipo de servicio.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (588, 'La Sepultura', 'Playa formada por rocas y arena que presenta una escasa afluencia de bañistas. No ofrece ningún tipo de servicios.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (589, 'Tamargada', 'Pequeña playa solitaria formada por rocas y de fuerte oleaje. No ofrece ningún tipo de servicios.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (596, 'La Rajita', 'Encajada al final de un barranco, esta playa disfruta de aguas tranquilas y de un bajo grado de ocupación, lo que le otorga una gran tranquilidad.', 38050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (782, 'La Cangrejera', 'Pequeñas casas rodean esta playa, a la que se accede en coche y presenta un grado medio de ocupación. Sin equipamientos.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (783, 'El Pozo Norte', 'Es una playa de reducidas dimensiones en la que se asientan pequeñas casas. No dispone de equipamientos.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (784, 'Piedra Nueva', 'Playa aislada y poco frecuentada, que no ofrece ningún tipo de servicio.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (785, 'El Pocito', 'Está ubicada en una zona de cultivos y es poco frecuentada. Dispone de aparcamiento.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (786, 'La Bajita', 'Playa semiurbana situada en el barrio de Lodero, en las inmediaciones del aeropuerto. No dispone de equipamientos.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (788, 'Martín', 'Playa de pequeño tamaño, aislada y con escasa afluencia de público. De difícil acceso a pie.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (789, 'El Poris', 'Playa a la que se accede en coche,que presenta una escasa afluencia de público y no está dotada de equipamientos.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (790, 'Las Salineras', 'Pequeña playa rocosa que disfruta de aguas claras y transparentes, rodeada de pequeñas edificaciones y con un grado medio de ocupación.', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (791, 'El Burro', 'Playa de pequeñas dimensiones ubicada en una zona rocosa y de aguas transparentes. No ofrece ningún tipo de servicio', 38053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (597, 'La Restinga', 'Playa situada en el pueblecito de pescadores de La Restinga, en el extremo sur de la isla, siendo la base de la flota pesquera de la isla. Sus centros de buceo deportivo permanecen abiertos todo el año.', 38901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (598, 'Puerto Naos', 'Pequeña playa de aguas tranquilas, en la que se practica la pesca.', 38901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (599, 'Tacorón', 'Al sur de El Pinar, y en pleno Mar de Las Calmas, está la pequeña cala de Tacorón. Cuenta con instalaciones para asar con fuego y sus cristalinas aguas invitan al baño en cualquier época del año.', 38901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (600, 'Muellito de Orchilla', 'En esta pequeña cala se encuentra el Faro de Orchilla, el más occidental de Europa. Hace 2000 años este punto significaba el fin del mundo conocido y durante 1700 años se consideró que por él pasaba el meridiano cero', 38901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (566, 'La Negra', 'Cala de pequeño tamaño encajada al final de un espectacular barranco, ofrece aguas limpias y cristalinas. Se suele acceder a ella en barco.', 38003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (567, 'La Cantera', 'Situada a los pies de un barranco, a esta cala sólo se puede acceder en barco, lo que permite disfrutar del bello entorno en un ambiente tranquilo.', 38003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (568, 'Ereses', 'Cala aislada y rocosa situada al fondo de un barranco y de complicado acceso a pie, por lo que se suele acceder a ella en barco. ', 38003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (569, 'Santiago', 'Playa de aguas claras y limpias muy frecuentada en verano. La zona cuenta con numerosos hoteles, restaurantes, etc.', 38003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (751, 'Bajamar', 'Playa de arena oscura, que presenta una moderada afluencia de público. Dispone de aseos y duchas.', 38008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (668, 'Los Roques', 'Esta playa recibe su nombre de los dos roques que la flanquean. En la zona se puede encontrar algún establecimiento hostelero.', 38012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (669, 'El Abrigo', 'Playa del término municipal de Fasnia, cercana a una urbanización, pero poco visitada por el público.', 38012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (667, 'Las Eras', 'Playa de la población de Las Eras, de arena oscura, y que no dispone de infraestructuras salvo el parking cercano.', 38012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (671, 'Caletón de Garachico', 'Conjunto de piscinas naturales y seminaturales formadas tras la erupción volcánica que sepultó la ciudad a comienzos del siglo XVIII. Su pequeño tamaño hace que presente una alta ocupación', 38015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (672, 'El Muelle', 'Playa situada junto al Puerto Pesquero, siendo algunas partes de éste también utilizadas para el baño. Reúne buenas condiciones para los bañistas por lo que en verano está muy frecuentada.', 38015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (673, 'La Caleta de Interián', 'Tranquila playa rodeada de pequeñas edificaciones que presenta unas aceptables condiciones para el baño.', 38015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (674, 'Las Aguas', 'Playa estrecha y rocosa con moderada afluencia de público y sin ningún tipo de equipamiento.', 38015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203815, 'Aguadulce', 'Playa anexa a la de San Juan, de bolos y grava. No tiene ningún servicio.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (684, 'Punta Blanca', 'Playa frecuentada por campistas, que disfruta de un entorno agradable en el que abundan los cultivos.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (685, 'Alcalá', 'Playa del pueblo de Alcalá que ofrece un agradable paseo marítimo y aguas tranquilas para disfrutar del baño.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (686, 'Méndez', 'Playita de la población de Alcalá compuesta por bolos que no ofrece ningún tipo de servicio a los bañistas.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (687, 'Baja Larga', 'Playa ubicada en un entorno algo degradado y rodeada de pequeñas urbanizaciones, a pesar de lo cual no presenta una alta afluencia de público.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (688, 'San Juan', 'Amplia playa adyacente al puerto y resguardada por el muelle, lo que hace que se vean en ella numerosas embarcaciones.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (689, 'Abama', 'Esta playa recientemente remodelada se encuentra en una zona que forma parte del complejo turístico del Hotel Abama. Aun así, el acceso a la playa es completamente libre y gratuito.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203825, 'Callao Chico', 'Pequeña playa de arena y grava, sin servicios y de alta afluencia en verano.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203827, 'Fonsalia', 'Playa de bolos y grava fina, de aguas tranquilas, ubicada en un entorno de fincas y plataneras sin ningún tipo de servicios.', 38019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (697, 'Troche', 'Playa de bolos que no ofrece infraestructura alguna.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (698, 'El Navío', 'Playa de fuerte oleaje que no ofrece ningún tipo de servicio, poco frecuentada por los bañistas.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (699, 'Arenisco', 'Playa con paseo marítimo, buen nivel de servicios y todo tipo de establecimientos hosteleros en las inmediaciones. ', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (700, 'El Roquete', 'Es una playa que denota una moderada afluencia de público. Servicios hosteleros en las inmediaciones.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (701, 'Arenal', 'Extensa playa que bordea el acantilado. No ofrece ningún tipo de servicio y presenta unas condiciones de baño complicadas.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (702, 'San Juan', 'Playa bordeada por un agradable paseo marítimo por el que dar largos paseos. Dotada de buenas infraestructuras', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (703, 'El Apio', 'Playa ubicada en una zona de plantaciones que sufre un fuerte oleaje, lo que hace que haya que tomar ciertas precauciones a la hora del baño.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203826, 'Juan Negrín', 'Espectacular playa de arena fina negra, anclada a pie de un acantilado. Sin servicios, con difícil acceso a pie.', 38023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (715, 'Martianez', 'Concurrida playa del Puerto de la Cruz, rodeada de un bello entorno de piscinas naturales. Dispone de completos y variados servicios.', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (716, 'San Telmo', 'Esta playa es una pequeña cala situada en el Paseo de San Telmo, entre rocas volcánicas. Entre las rocas se forman pequeños charcos cuando baja la marea.', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (717, 'El Muelle', 'Playa de reducido tamaño ubicada en los muelles del Puerto de la Cruz. En los alrededores se puede encontrar todo tipo de servicios de hostelería.', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (718, 'Playa Jardín', 'Bonita playa de arena negra. Ofrece un excelente nivel de servicios que hacen que esta playa sea muy frecuentada por el público.', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (726, 'Playa Chica', 'Playa anexa a Playa Jardín, de arena negra. Ofrece un excelente nivel de servicios que hacen que esta playa sea muy frecuentada por el público.', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203806, 'Playa Punta Brava', 'Playa anexa a playa Chica, de arena negra. Ofrece un excelente nivel de servicios que hacen que esta playa sea muy frecuentada por el público', 38028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (774, 'El Varadero', 'Cala pequeña poco frecuentada por el público y que no ofrece ningún tipo de equipamiento.', 38033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (775, 'Charco Azul', 'Es una playa que presenta una moderada afluencia de público y ofrece algunos servicios como aseos y duchas.', 38033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (776, 'Puerto Espíndola', 'Playa rocosa, rodeada de pequeñas edificaciones y con moderada afluencia de público. No dispone de equipamientos. ', 38033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (581, 'La Cueva', 'Playa de arena negra situada en las inmediaciones del puerto de San Sebastián de la Gomera, que ofrece al visitante un buen número de equipamientos.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (582, 'Avalo', 'Playa de fácil acceso a pie, pero enclavada en un entorno un tanto degradado. No dispone de ningún tipo de servicio.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (583, 'Aguila', 'Pequeña playa rocosa, bastante aislada y de fuerte oleaje, lo que hace que sea poco frecuentada. Se accede habitualmente en barco.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (584, 'Zamora', 'Playa de reducidas dimensiones y de muy difícil acceso, puesto que se llega a ella en barco. Sufre un fuerte oleaje y presenta una escasa afluencia de público.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (572, 'Tapahuga', 'Playa cercana al núcleo urbano de Santiago, que disfruta de aguas tranquilas. No está dotada de infraestructuras.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (573, 'El Medio', 'Situada entre barrancos, esta pequeña cala goza de tranquilidad pero no ofrece al visitante ningún tipo de servicio.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (574, 'Chinguarime', 'Encajada al fondo de un barranco, a esta playa sólo se puede acceder en barco. A cambio permite disfrutar del entorno en un ambiente tranquilo.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (575, 'Suárez', 'Cala rodeada de un bello entorno a la que se accede solamente en barco. Disfruta de aguas limpias y cristalinas.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (576, 'El Guincho', 'Enclavada al fondo de uno de los barrancos que caracterizan esta zona, el acceso sólo se puede realizar en barco, lo que le confiere una gran tranquilidad.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (577, 'La Roja', 'Playa aislada de difícil acceso (sólo por barco), sin servicios, poco frecuentada por los bañistas.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (578, 'El Cabrito', 'Cala amplia que se abre al final de un barranco. Disfruta de un agradable entorno y dispone de aseos y duchas.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (579, 'La Guancha', 'Playa ubicada al fondo de un barranco, por lo que se suele acceder a ella en barco. Disfruta de aguas tranquilas y transparentes.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (580, 'San Sebastián', 'Amplia playa situada en el núcleo urbano de San Sebastián de la Gomera. Ofrece un nivel aceptable de servicios y zona de fondeo para embarcaciones.', 38036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (712, 'El Gomero', 'Playa rocosa que presenta un fuerte oleaje que obliga a tomar ciertas precauciones a los bañistas. No dispone de equipamientos.', 38042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (713, 'Agua Dulce', 'Pequeña playa cercana a la población de Los Silos, que no suele ser muy frecuentada por los bañistas. Hay épocas en que presenta gran cantidad de arena negra.', 38042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (714, 'Charco de la Araña', 'En las inmediaciones se pueden encontrar algunas instalaciones hosteleras y una piscina municipal.', 38042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (585, 'El Inglés', 'Situada al pie de un acantilado, y de oscura arena, esta playa presenta un grado medio de ocupación y no dispone de equipamientos.', 38049);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (586, 'Valle Gran Rey', 'Extensa playa enclavada en un atractivo paisaje, que disfruta de aguas tranquilas y una moderada afluencia de público.', 38049);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (587, 'Vueltas', 'Pequeña playa urbana de arena oscura que es utilizada para el fondeo de barcos. No dispone de infraestructuras.', 38049);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103901, 'El Cándano', 'Pequeña playa situada en frente de la playa de Ris sin equipamientos.', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (794, 'Los Barcos', 'Playa colindante con la de Ris, de arena fina dorada. Cuenta con paseo marítimo y presenta un nivel medio de servicios', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (795, 'El Sable', 'Pequeña playa urbana de arena fina dorada y protegida por las rocas que la rodean. Presenta una alta afluencia de público y un nivel medio de servicios.', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (796, 'Los Franceses', 'Playa rocosa de pequeño tamaño, de arena fina dorada y de acceso complicado a pie. No ofrece ningún tipo de infraestructura .', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (797, 'La Arena', 'Playa enclavada en un bonito entorno rocoso con vegetación. Presenta una escasa afluencia de público y no ofrece ningún tipo de servicio.', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (798, 'La Arena', 'Playa semiurbana con un grado medio de ocupación. Ofrece arena fina dorada y algunos servicios como ducha y teléfono.', 39006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (799, 'Cuberris', 'Playa ventosa con fuertes corrientes, muy ancha y compuesta por una arena fina dorada de calidad. Cuenta con un paseo marítimo y ofrece un escaso número de servicios.', 39011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (800, 'Antuerta', 'Pequeña playa colindante a la de Cuberris, enclavada en un entorno rocoso. Tiene fuertes corrientes y es muy frecuentada por surfistas. No ofrece ningún tipo de servicio.', 39011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (801, 'Dicido', 'Pequeña playa aislada y tranquila formada por bolos, y que presenta un fuerte oleaje. No dispone de equipamientos. ', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (802, 'El Berrón', 'Playa ventosa de fuerte oleaje compuesta por bolos. Presenta un nivel bajo de equipamientos.', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (803, 'Brazomar', 'Playa de arena dorada que presenta una alta afluencia de público. Ofrece un buen nivel de servicios y la posibilidad de realizar diversos deportes acuáticos.', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (804, 'Ostende', 'Playa extensa de arena oscura, que presenta un alto grado de ocupación. Ofrece un buen nivel de equipamientos.', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (805, 'Arenillas', 'Pequeña playa de arena fina dorada, y aguas tranquilas poco frecuentada por el turismo. No ofrece apenas equipamientos', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (806, 'Oriñón', 'Playa de más de un kilómetro de longitud de arena dorada y que presenta una alta afluencia de público. No dispone de equipamientos.', 39020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (807, 'Comillas', 'Playa situada en el pueblo de Comillas que presenta una alta afluencia de público. Ofrece arena dorada, un agradable paseo marítimo y todo tipo de servicios. ', 39024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (808, 'La Salvé', 'Playa de gran tamaño situada en Laredo, pueblo muy frecuentado por turistas en la época estival. Presenta un excelente nivel de servicios: duchas, aseos, alquiler de hamacas y Club Náutico.', 39035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (809, 'Regatón', 'Extensa playa de aguas más tranquilas que La Salvé. Ofrece arena dorada y presenta un bajo nivel de ocupación. No dispone de equipamientos.', 39035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (810, 'Aila', 'Pequeña playa aislada y rocosa de fuerte oleaje y vientos. Presenta una escasa afluencia de público y no dispone de equipamientos', 39035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (811, 'Arenal de Sonabia', 'Playa de pequeño tamaño que ofrece al visitante tranquilidad y una arena fina y dorada de calidad.', 39036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (812, 'San Julián', 'Playa de reducido tamaño compuesta por fina arena dorada. No dispone de equipamientos y no es muy frecuentada, lo que la convierte en una playa tranquila.', 39036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (817, 'Los Caballos', 'Playa rodeada de altos acantilados, compuesta por arena dorada y que presenta un bajo nivel de ocupación. No ofrece ningún tipo de equipamiento.', 39044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (818, 'Cuchia', 'Playa de arena dorada dotada de rampas de acceso para discapacitados.', 39044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (814, 'Mogro', 'Playa urbana de arena dorada que presenta una alta afluencia de público. Dispone de paseo marítimo, aseos, duchas y aparcamiento.', 39044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (815, 'Robayera', 'Pequeña y aislada playa formada por arena dorada y grandes rocas. Hay que tener precaución a la hora del baño por ser una playa ventosa y de fuerte oleaje.', 39044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (816, 'Usgo', 'Playa enclavada en un atractivo entorno, tranquila y con escasa afluencia de público. Presenta un bajo nivel equipamiento. ', 39044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (821, 'Somocuevas', 'Playa con escasa afluencia de público que está protegida por un saliente rocoso. No dispone de infraestructuras', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (822, 'Canallave', 'Playa de mar abierto, ventosa y con fuertes corrientes, lo que hace que sea bastante peligrosa. Presenta un grado medio de ocupación y ofrece algunos servicios. Es muy frecuentada por surfistas.', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (823, 'Valdearenas', 'Playa ubicada en el Parque Natural de las Dunas de Liencres. Hay que tener precaución a la hora del baño ya que está en mar abierto, tiene fuertes corrientes y se generan remolinos.', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (824, 'Arnia', 'Está situada en un atractivo entorno rocoso, aislada y presenta un bajo nivel de ocupación. No dispone de equipamientos.', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (825, 'Portio', 'Pequeña playa semiurbana, protegida por las grandes rocas que la rodean, algunas de las cuales sobresalen del agua. No ofrece ningún tipo de equipamiento.', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (826, 'Cerrias', 'Pequeña playa semiurbana, protegida por las grandes rocas que la rodean, a pesar de lo cual tiene fuertes vientos. No ofrece ningún tipo de servicio.', 39052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (829, 'Langre I', 'Playa muy extensa enclavada en un atractivo entorno montañoso. Es una playa con fuertes corrientes y ventosa, lo que hace que sea muy frecuentada por surfistas. No dispone de equipamientos. Se accede a ella a través de la colindante Langre II.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (830, 'Langre II', 'Playa a la que se accede por unas largas escalerillas y que está enclavada en un atractivo entorno. Tiene fuertes corrientes y no dispone de equipamientos.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (831, 'Los Tranquilos', 'Pequeña playa de arena dorada, que cuenta con paseo marítimo y presenta una escasa afluencia de público. No ofrece equipamientos.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (827, 'Galizano', 'Playa aislada enclavada en un entorno rocoso con vegetación, de arena fina dorada y fuerte oleaje. Presenta un grado medio de ocupación y un bajo nivel de equipamientos.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (828, 'Arenilla', 'Pequeña playa aislada y tranquila, compuesta por arena y bolos y de fuertes vientos. El acceso a pie es bastante complicado. ', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (832, 'Loredo', 'Playa muy extensa de arena dorada y fuerte oleaje. Se celebra en ella la tradicional carrera de caballos, conocida como Derby de Loredo.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (833, 'Somo', 'Playa de dos kilómetros de longitud de arena fina dorada y fuerte oleaje. Presenta una ocupación media, cuenta con paseo marítimo y ofrece variedad de servicios. ', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (834, 'El Puntal', 'Playa extensa de arena dorada y fuerte oleaje, desde la que se tienen bonitas vistas a la bahía de Santander. No dispone de equipamientos.', 39061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (842, 'Magdalena', 'Playa urbana que ofrece arena dorada, aguas tranquilas y multitud de servicios: aseos, duchas, alquiler de hamacas y la posibilidad de realizar diversos deportes acuáticos.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (843, 'Los Peligros', 'Playa urbana que denota una alta afluencia de público. Ofrece arena dorada, aguas tranquilas, zona de fondeo y multitud de servicios: aseos, duchas, alquiler de hamacas y la posibilidad de realizar diversos deportes acuáticos.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (844, 'Los Bikinis', 'Playa enclavada en la bahía de Santander, a la que se accede a través de los jardines de la Magdalena. Ofrece arena fina dorada y aguas tranquilas y un nivel aceptable de servicios.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (845, 'El Camello', 'Playa urbana de arena dorada, que cuenta con un agradable paseo marítimo y presenta una alta afluencia de público en los meses estivales.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (846, 'La Concha', 'Playa urbana que ofrece arena dorada, oleaje moderado, paseo marítimo y varios servicios: aseos, duchas, aparcamiento y alquiler de sombrillas.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (847, 'Sardinero I', 'Playa urbana que ofrece arena dorada de calidad, un bonito y popular paseo marítimo, y multitud de servicios: aseos, duchas y alquiler de hamacas y sombrillas. ', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (848, 'Sardinero II', 'Playa que ofrece al visitante una arena dorada de calidad, un bonito y popular paseo marítimo, y multitud de servicios: aseos, duchas y alquiler de hamacas y sombrillas. ', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (849, 'Molinucos', 'Playa de reducido tamaño compuesta por arena y bolos. Presenta un bajo grado de ocupación y no ofrece ningún equipamiento.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (850, 'Mataleñas', 'Playa enclavada en un entorno atractivo, que a pesar de encontrarse aislada presenta una alta afluencia de público. Cuenta con aguas limpias y un agradable paseo marítimo. ', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (851, 'El Bocal', 'Playa de reducidas dimensiones, aislada y que denota escasa afluencia de público. Presenta arena dorada, oleaje moderado y un bajo nivel de equipamientos.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (852, 'La Maruca', 'Playa formada por bolos, rocas y arena situada en la desembocadura de la ría de San Pedro.', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (853, 'Virgen del Mar', 'Playa aislada enclavada en un entorno rocoso y situada al lado de la Ermita del mismo nombre. Ofrece escasos equipamientos', 39075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (854, 'Santa Justa', 'Playa de reducido tamaño compuesta por arena y bolos. Tiene escasa afluencia de público y no ofrece ningún tipo de equipamiento, excepto un pequeño aparcamiento.', 39076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (855, 'San Martín', 'Playa de aguas tranquilas formada por una extensa y estrecha franja de arena a lo largo del pueblo de Santoña. Dispone de paseo marítimo y zona de fondeo.', 39079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (856, 'Berria', 'Extensa playa semiurbana de arena dorada que ofrece un buen nivel de servicios: aseos, duchas, teléfonos, y alquiler de hamacas.', 39079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (857, 'La Riberuca', 'Playa aislada que presenta una escasa afluencia de público. Ofrece aguas tranquilas, pero no dispone de equipamiento alguno.', 39085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (858, 'La Ribera', 'Pequeña playa urbana que presenta un grado medio de ocupación. Ofrece arena dorada, aguas tranquilas y un nivel medio de servicios.', 39085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (859, 'La Concha', 'Playa de un kilómetro de longitud situada en el pueblo de Suances. Dispone de paseo marítimo y un nivel aceptable de servicios.', 39085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (860, 'Los Locos', 'Playa aislada enclavada a los pies de un acantilado que configura un paisaje de interés. Está compuesta por arena y bolos y presenta vientos y un fuerte oleaje.', 39085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (861, 'El Sable', 'Pequeña playa arenosa que presenta escasa afluencia de público. Ofrece algunos servicios: aparcamiento, duchas y teléfonos.', 39085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (868, 'Oyambre', 'Playa muy extensa ubicada dentro del Parque Natural de Oyambre, en la que se combinan las dunas con la vegetación. Se encuentra bastante aislada a pesar de lo cual está bastante frecuentada.', 39091);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (862, 'Barnejo', 'Playa de reducidas dimensiones encajada por las rocas que la rodean que configuran un paisaje de interés. Está compuesta por fina arena blanca y presenta un bajo grado de ocupación. ', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (863, 'El Sable', 'Playa aislada de arena dorada. No dispone de equipo de vigilancia.', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (864, 'Amió', 'Playa extensa, de fuertes vientos, compuesta por arena dorada y bolos. Presenta un bajo nivel de servicios.', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (865, 'Aramal', 'Pequeña playa aislada con escasa afluencia de público debido probablemente al acceso complicado que tiene. No posee equipo de vigilancia y no ofrece ningún tipo de servicio.', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (866, 'Las Arenas', 'Playa enclavada en un entorno atractivo, aislada pero muy frecuentada sobre por los turistas del camping que está situado junto a ella. Su superficie es de arena y bolos, y presenta vientos y fuerte oleaje.', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (867, 'El Pedrero', 'Playa situada en la ría de Tina Mayor, compuesta por arena y grava y con escasa afluencia de público. No ofrece ningún tipo de equipamiento', 39095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (793, 'Luaña', 'Playa de arena fina dorada que denota un grado medio de ocupación. Ofrece un nivel aceptable de servicios', 39001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (813, 'El Rostro', 'Playa de reducido tamaño con escasa afluencia de público, que disfruta de arena dorada y aguas tranquilas. No ofrece ningún tipo de servicio.', 39040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (819, 'Tregandín', 'Playa extensa enclavada en un magnífico paisaje montañoso. Presenta un grado medio de ocupación y está dotada con múltiples servicios, incluida la posibilidad de realizar diversos deportes acuáticos.', 39047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (820, 'Ris', 'Playa de arena dorada y fuertes vientos enclavada en un entorno agradable. Presenta un buen nivel de equipamientos: duchas, aseos, alquiler de hamacas y alquileres náuticos. ', 39047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (840, 'San Juan de la Canal', 'Playa semiurbana de arena dorada y de fuertes vientos. Cuenta con un agradable paseo marítimo y un nivel medio de servicios.', 39073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (841, 'Covachos', 'Playa aislada y tranquila a la que se accede difícilmente a pie, enclavada en un entorno muy atractivo. Disfruta de una arena dorada de calidad y aguas muy limpias', 39073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (835, 'El Cabo', 'Playa aislada muy frecuentada por surfistas debido al fuerte oleaje y los vientos que la caracterizan. No ofrece al visitante ningún tipo de servicio.', 39080);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (836, 'Merón', 'Playa semiurbana con un grado medio de ocupación. Ofrece fina arena blanca, y está dotada con todo tipo de servicios.', 39080);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (837, 'El Rosal', 'Playa semiurbana que ofrece fina arena dorada, y está dotada con todo tipo de servicios. Existe la posibilidad de realizar diferentes deportes, incluidos los acuáticos.', 39080);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (838, 'La Maza', 'Playa de reducido tamaño que se encuentra situada antes de entrar a la población de San Vicente de la Barquera. Disfruta de arena fina dorada y aguas tranquilas. No dispone de equipamientos.', 39080);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (839, 'La Fuente', 'Playa de pequeño tamaño de arena dorada y bolos que presenta una escasa afluencia de público. No dispone de ningún tipo de equipamiento', 39080);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (869, 'La Musclera', 'Playa en al que se protege la vegetación autóctona del litoral arenoso, mediante la delimitación de un espacio de protección de 1.500 m2 donde se pueden observar especies como el rave de mar, el passacamins marí o el jull de platja.', 8006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (870, 'La Picordia', 'Playa protegida semiurbana sin paseo marítimo, que presenta unos alrededores algo descuidados. Principalmente compuesta por rocas y arena dorada. El estado habitual de la mar es aguas tranquilas. El nivel medio de ocupación es bajo.', 8006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (872, 'El Cavaió', 'Playa dotada de gran cantidad de servicios.', 8006);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100801, 'Platja de l?Estació', 'Playa localizada en pleno casco urbano de Badalona, con vistas de la central térmica, pero que cuenta con todos los servicios de una playa urbana, incluidas unas piscinas municipales.', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100802, 'Platja dels Patins de Vela', 'Playa localizada en pleno casco urbano de Badalona, delante del CN Badalona.', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100803, 'Platja dels Pescadors', 'La Platja dels Pescadors, situada en Badalona, es una playa de arena de 470 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100804, 'Platja del Pont d?en Botifarreta', 'Playa localizada entre la Riera Matamoros y la Riera de Canyadó', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100805, 'Platja del Cristall', 'Playa situada entre la Riera Canyadó y el Torrente de Vallmajor', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100806, 'Platja de la Barca Maria', 'Playa localizada entre el Torrente de Vallmajor y el límite con Montgat', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (873, 'Platja de la Mora', 'Playa situada entre el límite de Sant Adrià y el Puerto', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (874, 'Platja del Coco', 'Playa localizada entre la Plaza dels Patins de Vela y la Calle Cervantes', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (875, 'Platja del Pont de Petroli', 'Playa ubicada entre la Avenida de Sant Ignasi de Loiola y la Plaza de los Patines de Vela', 8015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200801, 'Sant Miquel', 'Playa urbana de arena dorada', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200802, 'Somorrostro', 'Playa urbana de arena dorada y aguas tranquilas', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100807, 'Llevant', 'La playa de Llevant pertenece al Distrito de Sant Martí.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (880, 'La Mar Bella', 'Playa situada entre la Nova Mar Bella y Bogatell, con características muy similares a las de las playas de la zona, donde se concentran los aficionados de la práctica del Wind-Surf.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (881, 'La Nova Mar Bella', 'Es la playa más alejada de la ciudad de Barcelona, pero dispone de todos los servicios propios de una playa urbana y su paseo marítimo se prolonga hasta el famoso barrio de la Barceloneta.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (876, 'Sant Sebastià', 'Esta playa dispone de todo tipo de infraestructuras, así como buenos accesos adaptados para personas con alguna discapacidad. Se encuentra ubicada muy cerca de la Dársena industrial y los muelles relacionados con el comercio marítimo.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (877, 'La Barceloneta', 'Playa de Barcelona por excelencia que toma su nombre del antiguo barrio marinero, La Barceloneta, y dispone de todos los servicios propios de una playa urbana.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (878, 'La Nova Icària', 'La Playa de la Nova Icària presenta un alto grado de ocupación y está ubicada junto al Puerto Olímpico de Barcelona, separada de las playas colindantes por pequeños espigones, enlazándose con el paseo marítimo de la Barceloneta.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (879, 'El Bogatell', 'Esta playa urbana se localiza muy cerca del Puerto Olímpico de Barcelona y su paseo marítimo se prolonga hasta la Playa de Sant Sebastiá, en el Barrio de la Barceloneta.', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200813, 'Zona banys Fòrum', 'Pertenece al Distrito de Sant Martí', 8019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (882, 'Cabrera', 'La Playa de Cabrera, junto con la Playa de Poniente, son las dos playas de  mayor longitud del término municipal. Presentan un elevado grado de ocupación.', 8029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (885, 'Les Roques', 'Playa formada por varias calitas con grandes rocas desde donde puede practicarse la pesca con caña.', 8035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (886, 'Garbí', 'La Playa de Garbí constituye una continuación de la Playa Grande de Calella de Mar, por lo que goza de los servicios e infraestructuras de la playa vecina, pero resulta algo más tranquila y recomendable.', 8035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (887, 'Platja Gran', 'Es la playa más concurrida de la zona, con gran cantidad de oferta hotelera, multitud de infraestructuras y servicios playeros que atraen mucho turismo, sobre todo extranjero', 8035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (888, 'El Cavaió', 'Playa dotada con gran cantidad de infraestructuras y servicios, incluidos accesos acondicionados para personas discapacitadas.', 8040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (889, 'Canet de Mar', 'Playa de gran extensión muy frecuentada por turistas, con un gran paseo marítimo con palmeras muy frecuentado durante la época estival.', 8040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (890, 'Castelldefels', 'La Playa de Castelldefels es una playa muy bien equipada, con mucho ambiente juvenil, que alberga un Club Náutico y varias escuelas de vela para la práctica de cualquier deporte relacionado con el viento reinante.', 8056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100808, 'Platja de les Salines', 'La playa Platja de les Salines, situada en Cubelles, es una playa de arena de 450 metros de longitud. Cuenta con servicios básicos como aseos y aparcamiento.', 8074);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100809, 'Les Gavines', 'La playa Les Gavines, situada en Cubelles, es una playa de arena de 250 metros de longitud.', 8074);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (891, 'Mota de Sant Pere', 'Playa ubicada en una zona industrial, en construcción,  donde se encuentran más aficionados a la caña que bañistas.', 8074);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (892, 'Cubelles', 'La Playa de Cubelles es una de las más frecuentadas de toda una serie de pequeñas playas separadas por espigones de piedras, comunicadas todas por un paseo marítimo.', 8074);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100810, 'Playa de la Punta de la Tordera', 'La playa Playa de la Punta de la Tordera, situada en Malgrat de Mar, es una playa de arena de 1.045 metros de longitud.', 8110);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100811, 'Platja de l''Astillero', 'La playa Platja de l''Astillero, situada en Malgrat de Mar, es una playa de arena de 1000 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 8110);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (898, 'Malgrat de la Conca', 'Playa que goza de unas características inmejorables para practicar el vuelo de la cometa, el Wind-Surf y cualquier otro deporte de vela.', 8110);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (897, 'Malgrat Centre', 'Playa urbana de gran extensión, con buenos servicios, pero su cercanía a las vías del tren le resta calidad.', 8110);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (893, 'Masnou', 'La Playa de Masnou se conoce como el rincón de los surfistas de esta zona. Dispone de una gran explanada para aparcar el coche, donde se ubica el acceso a la playa a través de una paso subterráneo.', 8118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (894, 'Ocata', 'La Playa de Ocata, de gran extensión y anchura, es una buena playa ubicada en pleno casco urbano del municipio y que cuenta, además, con una zona acondicionada para distintos deportes, con un Club Náutico y un club de vela: Ocata Vent.', 8118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100812, 'De Ponent', 'La playa de Ponent, situada en Mataró, es una playa compuesta de arena y rocas de 180 metros de longitud.', 8121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (901, 'Sant Simó', 'Playa de gran extensión y carácter urbano, muy frecuentada en uno de sus extremos, al contrario que en el otro, conocido como El Fortí, al no disponer de buenos accesos.', 8121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (899, 'El Varador', 'La Playa del Varador es una de las más urbanas y frecuentadas de Mataró ya que posee unos servicios e infraestructuras que la hacen inmejorable para su uso, sobre todo para las familias con niños.', 8121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (900, 'El Callao', 'Pequeña playa de calidad,continuación de la Playa del Varador', 8121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (902, 'Les Moreres', 'Pequeña playa de arena dorada', 8126);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (903, 'Sant Joan', 'Playa de arena dorada y aguas tranquilas', 8126);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (904, 'Pla de Montgat', 'Playa de arena dorada y oleaje moderado', 8126);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100813, 'Playa dels Pescadors', 'La playa Playa de los Pescadores, situada en Pineda de Mar, es una playa de arena de 1100 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 8163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100814, 'Playa de La Riera', 'La Playa de La Riera, situada en Pineda de Mar, es una playa de arena de 580 metros de longitud.', 8163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100815, 'Playa de Poblenou', 'Playa que comparten los municipios de Pineda y Calella de Mar', 8163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (905, 'Playa del Pins', 'Extensa playa que, aunque presenta un elevado grado de ocupación, resulta mucho más tranquila que las playas de alrededor y dispone del mismo equipamiento.', 8163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (906, 'Platja de Ponent', 'Esta playa constituye un pequeño paraíso para los que quieren disfrutar de la práctica del surf.', 8172);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (658, 'Masca', 'Cala enclavada en un bello entorno, a la que hay que acceder en barco o a pie descendiendo el barranco del mismo nombre. Disfruta de aguas cristalinas y de una total tranquilidad.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203803, 'Playa el Carrizal', 'Playa de difícil acceso que se encuentra en un lugar aislado lejos de las urbanizaciones.', 38010);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203809, 'Playa de Punta Larga', 'Playa urbana de arena fina y bolos.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203811, 'El Pozo', 'Playa de callaos de granulometría pequeña insertada en un refugio pesquero.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (659, 'La Viuda', 'Playa aledaña a un polígono industrial, enclavada en un entorno un tanto degradado. No dispone de infraestructuras.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (660, 'Candelaria', 'Playa del bonito pueblo de Candelaria que suele ser bastante visitada por el público. Está formada por arena oscura, como la mayoría de las playas de la isla.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (661, 'La Hornilla', 'Playa urbana, de arena oscura. Ofrece un nivel medio de equipamientos y es bastante frecuentada por los bañistas.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (662, 'Punta Larga', 'Extensa playa rodeada de edificaciones y de un agradable paseo marítimo. Posee un buen nivel de equipamientos', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (663, 'Las Caletillas', 'Resguardada playa en un entorno altamente urbanizado pero agradable. Ofrece un bonito paseo marítimo para pasear.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203810, 'Olegario', 'Pequeña playa de arena, bolos y grava resguardada por un pequeño espigón de piedras.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203807, 'Cho Vito', 'Pequeña playa de bolos y gravas de oleaje moderado.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203808, 'Playa del Alcalde', 'Pequeña playa situada frente al Ayuntamiento y el puerto pesquero, por lo que está totalmente resguardada del oleaje por medio de los espigones del puerto.', 38011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (601, 'Arenas Blancas', 'Playa de arena que no cuenta con servicios.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (602, 'El Verodal', 'Una de las mayores playas de la isla de El Hierro, con arena roja y fuerte oleaje.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (603, 'Charco Azul', 'Pequeña cala cerca de uno de los pueblos más pintorescos de la isla, con casas antiguas bien conservadas, del más puro estilo herreño.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (604, 'Charco Azul', 'Cala de pocos metros, cerca de bonitas casas con jardines cubiertos de flores.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (605, 'Charco de los Sargos', 'Playa aislada, típicamente volcánica, de escasa ocupación.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (606, 'La Maceta', 'Zona con diques formando piscinas, con gran afluencia de gente los fines de semana en verano.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (607, 'Punta Grande', 'Sobre un solitario embarcadero azotado por las olas, frente a los míticos Roques de Salmor, unos islotes rocosos habitados hasta mediados del presente siglo por una especie de lagartos gigantes de origen prehistórico, emerge el hotel más pequeño del mundo.', 38013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (787, 'Los Roquitos', 'Playa de arena, bolos y grava de difícil acceso a pie que presenta una moderada afluencia de público.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (753, 'La Zamora', 'Pequeña playa de arena oscura situada en el municipio de Fuencaliente.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (754, 'Punta Larga', 'Playa de reducidas dimensiones rodeada de pequeñas edificaciones a la que se accede en coche. Ofrece escasos equipamientos.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (755, 'Abadejos', 'Pequeña cala a la que se puede acceder a pie, que se encuentra en una zona de cultivos. Presenta un bajo nivel de ocupación.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (756, 'Echentive', 'Playa formada en 1971 a raíz de la erupción del Teneguía. Se encuentra junto a la Galería de la Fuente Santa y dispone de charcas naturales de gran belleza.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (757, 'El Faro', 'Playa del faro de Fuencaliente, el cual se encuentra en restauración. Está próxima a las salinas de Fuencaliente. Se accede en coche.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (758, 'Las Cabras', 'Es una playa de reducidas dimensiones, aislada y poco frecuentada por el público. No dispone de equipamiento alguno.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (759, 'El Puertito', 'Cala aislada, situada en el municipio de Fuencaliente, de reducido tamaño y que no ofrece ningún tipo de servicio.', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (760, 'El Río', 'Playa rodeada de pequeñas edificaciones, a la que se accede en coche. No dispone de equipamiento alguno', 38014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (761, 'Fajana de Franceses', 'Zona de baño rocosa, con escasa afluencia de público. El acceso a pie es muy complicado. No dispone de equipamientos.', 38016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203801, 'Callejoncitos', 'Pequeña playa con baja afluencia', 38016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (675, 'La Mareta', 'Apartada playa en la que es posible disfrutar de una gran tranquilidad, pero que no ofrece ningún tipo de servicio.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (676, 'El Confital', 'Playa de arena que se encuentra aislada, por lo que es poco frecuentada por el público.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (677, 'La Tejita', 'Playa de un kilómetro de longitud enclavada en el Paraje Natural Protegido que conforma la llamativa Montaña Roja', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (678, 'Montaña Roja', 'A los pies de la Montaña Roja encontramos esta recoleta playa, que permite disfrutar de un entorno agradable dentro de un Paraje Natural Protegido.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (679, 'El Médano', 'Playa dotada de todo tipo de servicios, paseo marítimo y zona de fondeo. Es bastante frecuentada por el público.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (680, 'La Jaquita', 'Pequeña playa de arena dorada que ofrece al visitante un buen nivel de servicios y cierta tranquilidad.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (681, 'La Pelada', 'Playa enclavada dentro de una zona declarada Paraje Natural, que no ofrece ningún tipo de servicio.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (682, 'El Tanque del Vidrio', 'Playa tranquila, en cuyas inmediaciones se puede ver una central eólica debido a los vientos que azotan la zona.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (683, 'El Medio', 'Playa muy amplia totalmente aislada por lo que presenta una escasa afluencia de bañistas. No ofrece equipamiento alguno.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203821, 'El Cabezo', 'Esta playa se encuentra un poco más alejada de lo que es el centro de El Médano, donde da comienzo la zona residencial propia del veraneo. Es de arena oscura y donde se celebran campeonatos de windsurf y kitesurf.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203822, 'Playa Chica', 'Como su nombre indica, es una pequeña playa situada en el centro urbano de El Médano, frente al puerto pesquero. De arena oscura, esta playa en pleamar desaparece prácticamente.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203823, 'Leocadio Machado', 'Playa muy extensa, de arena fina, situada en el casco urbano de El Médano. Esta playa es un paraíso para los amantes de los deportes de vela y surferos.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203828, 'Los Abrigos', 'Pequeña pero acogedora playa de arena y grava, sin servicios, de oleaje moderado.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203812, 'La Rajita', 'Pequeña cala de arena aislada.', 38017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (696, 'Santo Domingo', 'Se encuentra al final de una carretera que desciende el acantilado. No ofrece ningún tipo de servicio.', 38018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (690, 'La Enramada', 'Esta playa se encuentra situada al lado de la carretera, y se accede a ella bajando unas escaleras en no muy buen estado. Presenta un fuerte oleaje, por lo que se deben tomar ciertas precauciones a la hora del baño.', 38020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (691, 'Callao', 'Amplia playa cercana al puerto de Guímar, sin ningún tipo de equipamiento y poco utilizada por los bañistas.', 38020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (692, 'El Puertito', 'Playa pequeña situada en el puerto de Guímar, que dispone de paseo marítimo y ofrece aguas tranquilas al numeroso público que la visita.', 38020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (693, 'El Socorro', 'Playa de más de un kilómetro de longitud que presenta un fuerte oleaje y no es muy frecuentada por los bañistas.', 38020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (570, 'La Caleta de Hermigua', 'Pequeña cala de arena negra, situada en las cercanías del casco urbano, que presenta un bajo grado de ocupación. Cuenta con aseos y duchas.', 38021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (571, 'Hermigua', 'Playa amplia con bajo grado de ocupación y de fuerte oleaje. No ofrece ningún tipo de servicio.', 38021);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (694, 'El Monis', 'Enclavada en un paraje bastante degradado, esta playa no reúne muy buenas condiciones para el baño.', 38022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (695, 'San Marcos', 'Recogida playa urbana, dotada de paseo marítimo y de otros variados servicios, lo que contribuye a la alta afluencia de público que presenta.', 38022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (762, 'Murgas', 'Pequeña cala cercana a la localidad de Puerto Naos, poco frecuentada y que no ofrece ningún tipo de servicio.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (763, 'Puerto Naos', 'Playa de Puerto Naos, dotada de buenos equipamientos, aparcamiento y accesos para discapacitados.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (764, 'Pelota Bayana', 'Zona de baño en las inmediaciones de Puerto Naos, poco frecuentada y sin ningún equipamiento.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (765, 'Las Monjas', 'Playa de arena oscura cercana a Puerto Naos. Se accede fácilmente a pie.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (766, 'El Charco Verde', 'Playa de fácil acceso, bastante frecuentada, que dispone de aparcamiento.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (767, 'El Remo', 'Playa rodeada de pequeñas casas y cultivos. Accesos señalizados y aparcamiento.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (768, 'La Bombilla', 'Playa rocosa, rodeada de pequeñas edificaciones. No dispone de equipamientos.', 38024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (704, 'El Caletón', 'Pequeña playa urbana que cuenta con área de fondeo para barcos y que presenta una moderada afluencia de público', 38025);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (705, 'El Ancón', 'El acceso a esta playa es complicado al estar ubicada al fondo de un acantilado. Las condiciones para el baño son poco favorables.', 38026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (706, 'Los Patos', 'Playa de unos  900 m. de longitud ubicada a los pies de un acantilado protegido, en una zona de propiedades privadas dedicadas al cultivo.', 38026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (707, 'El Bollullo', 'Playa en un entorno muy agradable a la que se accede caminando por un sendero desde el parking cercano. Precaución a la hora del baño debido al fuerte oleaje que presenta.', 38026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (769, 'Poris de Puntagorda', 'Zona de baño a la que se accede mediante unas pasarelas. Presenta una escasa afluencia de público.', 38029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (770, 'Martín Luis', 'Zona de baño rocosa, situada a los pies de un acantilado. Es poco frecuentada, probablemente debido al difícil acceso que presenta.', 38030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (771, 'Puerto Trigo', 'Zona de baño aislada, poco frecuentada. No dispone de ningún tipo de equipamiento.', 38030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (772, 'Nogales', 'Playa de arena, resguarda por la pared del acantilado. Se accede a ella en coche y dispone de aparcamiento y accesos señalizados.', 38030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (773, 'La Galga', 'Playa rocosa aislada y con escasa afluencia de público.', 38030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (708, 'El Roque', 'Playa que presenta unas condiciones poco apropiadas para el baño, por ser muy rocosa y tener un fuerte oleaje.', 38031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (709, 'El Socorro', 'Bonita playa muy frecuentada por los bañistas que dispone de paseo marítimo y parking. Presenta un fuerte oleaje.', 38031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (710, 'Playa Gordejuela', 'Playa rodeada de rocas que sobresalen del agua, que conforman un paisaje agradable. Permite disfrutar del entorno en un ambiente tranquilo.', 38031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (711, 'Castro', 'Playa de Castro es una playa que está situada en un entorno aislado prácticamente virgen de unos 200 metros, de bolos y arena negra de origen volcánico y aguas tranquilas y limpias.', 38031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203804, 'Playa La Grimona', 'Playa anexa a la del Socorro, compuesta de bolos, que en algunas épocas del año tiene gran cantidad de arena negra.', 38031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (664, 'Tabaiba', 'Playa de reducidas dimensiones que disfruta de aguas tranquilas y de aceptables infraestructuras.', 38032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (665, 'La Nea', 'Playa aledaña al Puerto Deportivo de Radazul.', 38032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203830, 'Radazul', 'Dos pequeñas playas de reciente creación, con solarium y accesos al mar, de arena fina. Cuenta con todos los servicios.', 38032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (719, 'Las Aguas', 'Rocosa playa no muy frecuentada por sufrir un fuerte oleaje que complica las condiciones para el baño.', 38034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203805, 'Los Roques', 'La Playa de los Roques es una playa pequeña de bolos accesible por un camino de tierra. La playa está cercana a la zona urbanizada', 38034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (651, 'Amarilla', 'Pequeña cala enclavada a los pies de una montaña, de cuyo color recibe su nombre. Presenta unas aguas limpias y cristalinas.', 38035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (720, 'Los Colmenares', 'Aislada y tranquila playa que no ofrece ningún tipo de servicio, pero que por el contrario permite disfrutar de ella en una total tranquilidad.', 38035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (721, 'El Barranco', 'Playa cercana a unas urbanizaciones de edificaciones bajas, a pesar de lo cual presenta una baja afluencia de público.', 38035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (722, 'San Blas', 'Playa rocosa de aguas tranquilas que no dispone de equipamientos y es poco frecuentada por los bañistas.', 38035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (723, 'Valleseco', 'Pequeña playa situada al fondo del muelle del puerto de Santa Cruz de Tenerife y al lado de la refinería.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (724, 'Las Teresitas', 'Centro turístico por excelencia. Ofrece todo tipo de equipamientos y un gran número de servicios hosteleros.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (725, 'Las Gaviotas', 'Enclavada al fondo de una montaña, esta playa situada muy cerca de Santa Cruz de Tenerife no ofrece apenas servicios.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (727, 'El Balayo', 'Situada al fondo de un barranco.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (728, 'El Burro', 'Playa aislada al pie de una escarpada montaña. No está dotada de infraestructuras y es poco visitada por el público.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (729, 'El Llano', 'Playa cercana al núcleo de Igueste, de arena oscura, a la que sólo puede accederse a pie y que no ofrece ningún tipo de servicio.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (730, 'La Bruja', 'Playa que presenta una escasa afluencia de público, al no disponer de infraestructuras.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (731, 'Antequera', 'Playa ubicada a los pies de una montaña que configura un impresionante paisaje. El acceso a ella se realiza en barco.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (732, 'Casas Blancas', 'Playa situada en un entrono de gran belleza, y que disfruta de aguas limpias y cristalinas. Se accede a ella en barco.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (733, 'Roque Bermejo', 'Situada a los pies de un impresionante acantilado, esta playa goza de aguas cristalinas. El acceso a ella se realiza en barco.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (734, 'El Draguillo', 'A los pies de un acantilado donde el agua rompe con fuerza, se encuentra esta playa a la que sólo se puede llegar en barco.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (735, 'Benijo', 'Playa enclavada en un impresionante paraje protegido.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (736, 'Fabián', 'El acceso a esta playa enclavada al fondo de un impresionante acantilado, donde rompen las olas fuertemente, es bastante complicado.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (737, 'Almaciga', 'Playa que sufre un fuerte oleaje, ubicada en un entorno rocoso protegido. No ofrece ningún tipo de equipamiento', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (738, 'Roque de las Bodegas', 'Esta playa se encuentra rodeada de altos acantilados, dentro de una zona protegida. Las condiciones de baño son complicadas debido al oleaje que sufre.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (739, 'Tachero', 'En esta playa, como en casi todas las de la zona, el oleaje es fuerte, lo que complica las condiciones del baño. Presenta una escasa afluencia de público.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (740, 'Tamadite', 'Situada al fondo de un barranco, el acceso a pie a esta playa es bastante complicado. Las condiciones del oleaje hacen que haya que tener precaución a la hora del baño.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203829, 'Playa Chica', 'Playa de arena fina, enclavada en el fondo de una montaña. Semiurbana de baja ocupación. No ofrece ningún servicio.', 38038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (741, 'Los Guíos', 'Playa famosa por el acantilado que la rodea con paredes superiores a 300 m y un puerto deportivo con todo tipo de embarcaciones.', 38040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (742, 'Santiago', 'Playa de reducidas dimensiones en un entorno altamente urbanizado.', 38040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (743, 'La Arena', 'Centro turístico del municipio con un buen nivel de servicios.', 38040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (907, 'La Descàrrega', 'Pequeña playa a la que se accede a través de un paso subterráneo y que tiene un aparcamiento muy cercano a la playa.', 8172);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (908, 'Pla de l''Os', 'Playa urbana localizada al norte de la Playa de Bellamar que presenta un alto grado de ocupación.', 8172);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (909, 'Bellamar', 'La Playa de Bellamar, junto al Club Náutico de Premià de Mar, se corresponde con el primer tramo de un largo arenal dividido en varias zonas, siendo éste el más resguardado por uno de los espigones del Club.', 8172);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (910, 'Platja de Llevant', 'Playa de arena a la que se accede a través de un paso subterráneo que salva las vías del tren y la carretera, muy cercanas a la playa.', 8172);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100816, 'El Fórum', 'La playa El Fórum, situada en Sant Adrià de Besòs, es una playa de arena de 460 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados y aparcamiento.', 8194);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (911, 'Platja del Litoral', 'Esta gran playa se encuentra entre la Central Térmica y el río Besós.', 8194);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (953, 'Platja de Ponent', 'Es una de las playas más largas del término de Vilassar de Mar, junto con la Playa de Cabrera, ambas de carácter urbano y con unas condiciones tranquilas para el baño.', 8219);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (954, 'L''Astillero', 'Playa de carácter urbano compuesta de rocas y arena, que se localiza en el mismo casco urbano de Vilassar de Mar.', 8219);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (955, 'L''Almadrava', 'La Playa de La Almadraba es una playa urbana de pequeña extensión localizada en el mismo casco urbano de Vilassar de Mar.', 8219);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100817, 'La Roca Grossa', 'La playa Roca Grossa, situada en Sant Pol de Mar, es una playa de arena de 749 metros de longitud.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (915, 'Roques Blanques', 'Playa de aspecto rústico debido a la existencia de un macizo rocoso. Muy cercana a la carretera N-II y a la vía del tren. Se encuentra poco equipada de servicios e infraestructuras.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (916, 'La Murtra', 'Playa de arena y carácter aislado que dispone de servicios de alquiler de sombrillas y hamacas.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (918, 'Can Villar', 'Esta playa se encuentra cerca del pueblo de Sant Pol de Mar y ofrece unas bonitas vistas del casco urbano.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (919, 'Platja de les Barques', 'Playa ubicada en pleno casco urbano de Sant Pol de Mar, situada dentro del Club Náutico del pueblo.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (920, 'Les Escaletes', 'El acceso a esta playa debe realizarse a través de escaleras y se caracteriza por resultar una playa de ambiente muy familiar. Dependiendo de los temporales esta playa desaparece.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (921, 'La Platjola', 'Una roca grande divide esta playa de la Playa del Morer, ambas con las vías del tren a sus espaldas. Cuenta con acceso para discapacitados.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (922, 'El Morer', 'Playa muy concurrida en su mayoría por extranjeros, con aguas muy tranquilas y limpias.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200808, 'Sant Pol', 'Playa urbana frente a la escollera de la vía del tren.', 8235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100818, 'Platja de Llevant', 'La playa Platja de Llevant, situada en Santa Susanna, es una playa de arena de 815 metros de longitud. La playa cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 8261);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100819, 'Platja de les ?Caletes?', 'La playa Platja de les Caletes, situada en Santa Susanna, es una playa de arena de 445 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 8261);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (924, 'Platja de les Dunes', 'Se extiende a lo largo de toda su línea de costa, resultando muy amplia, cómoda y con gran cantidad de servicios disponibles.', 8261);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (925, 'Platja de L?Home Mort', 'Playa que se une a la Playa de Roses y está rodeada de acantilados.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (926, 'Platja de la Desenrocada', 'Playa ubicada en un entorno natural, de carácter aislada, sin ningún tipo de servicios e infraestructuras para el público.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (927, 'Les Coves', 'Playa estrecha', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (929, 'Les Anquines', 'Es una playa artificial. Su existencia se debe al Hotel Terramar que la creó como un área de servicio del hotel en los años 20. Se caracteriza por estar rodeada por dos espigones en forma de cangrejo, de manera que queda muy protegida de los temporales. ', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (930, 'Terramar', 'Playa situada delante de la zona de Terramar, en un sector residencial. También tiene 4 isletas para la protección de la arena.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (931, 'La Barra', 'Playa urbanizada que se caracteriza por los dos grandes bloques de piedras ubicados en medio de la ensenada cerrada al mar por falsos diques de piedras a ambos lados.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (932, 'La Riera Xica', 'Playa ubicada en un entorno urbano, algo alejada del pueblo de Sitges, con un entorno muy cuidado y con servicios disponibles.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (933, 'L''Estanyol', 'Playa situada delante del sector residencial del Vinyet y del Paseo Marítimo. Dispone de un club de natación ubicado en la misma playa', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (934, 'La Bassa Rodona', 'Playa donde se respira un ambiente singular, frecuentada mayoritariamente por hombres. Dispone de todos los servicios excepto chiringuito.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (935, 'La Ribera', 'Es una de les playas más populares, concurridas y cosmopolitas gracias a su ubicación, en el centro neurálgico del núcleo urbano. Dispone de todos los servicios.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (936, 'La Fragata', 'Situada bajo la misma Iglesia de Sant Bartomeu y Santa Tecla. Comparte el espacio con el Club Náutico. No dispone de servicio de tumbonas, toldos ni sombrillas', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (937, 'Sant Sebastià', 'Se encuentra en pleno núcleo urbano, enclavada en un antiguo barrio de tradición marinera. Dispone de todos los servicios y esta adaptada para personas con movilidad reducida.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (938, 'Els Balmins', 'Playa formada por tres calitas. Se encuentra a poniente del Puerto de Aiguadolç, entre el Puerto y el núcleo urbano. Dispone de todos los servicios y está adaptada para discapacitados.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (939, 'Aiguadolç', 'Playa situada a levante del Puerto Deportivo de Aiguadolç, delante de la zona de la Marina d?Aiguadolç. Dispone de todos los servicios', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (942, 'Vallcarca', 'Pequeña playa formada al pie de una cementera con un pequeño embarcadero industrial, nada recomendable para uso turístico', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (943, 'Cala Morisca', 'Playa localizada en la Costa de Garraf.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (945, 'Garraf', 'Playa muy frecuentada durante los meses estivales, dominada por las montañas que conforman la Sierra de Coma Roja, en la Costa de Garraf.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (946, 'Cala Ginesta', 'Situada dentro de Port Ginesta, el puerto deportivo con más amarres de Cataluña. Es una playa sin servicios debido al valor medioambiental de la zona, con surgencias de agua dulce provocada por las corrientes existentes en el fondo marino. Destaca la fauna que habita en los acantilados', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (947, 'Les Botigues', 'La playa más grande de todo el término municipal de Sitges. Se encuentra en el núcleo urbano de las Botigues.', 8270);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200809, 'Platja de la Murtra', 'Playa de baja afluencia', 8301);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200810, 'Platja de la Pineda', 'Amplia playa de baja afluencia', 8301);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200811, 'Platja de Cal francesc', 'Playa de arena dorada', 8301);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200812, 'Platja del Remolar', 'Amplia playa de arena dorada', 8301);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (100820, 'S?Adarró', 'La playa S?Adarró, situada en Vilanova i la Geltrú, es una playa de arena de 780 metros de longitud. Cuenta con servicios básicos como acceso para discapacitados, aseos o aparcamiento.', 8307);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (949, 'Platja Llarga d?Ibersol', 'Playa en forma de ensenada, con pequeños espigones de piedras y con una excelente arena dorada. Está situada entre el término municipal de Cubelles y antes de la playa de Sant Gervasi. Un 60% de esta playa es un espacio natural.', 8307);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (950, 'Sant Gervasi', 'Playa protegida con diques de piedras a ambos lados, lo que le dota de unas tranquilas aguas para el baño, y con poca profundidad.', 8307);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1052, 'Tamariu', 'Playa totalmente equipada con servicios e instalaciones de todo tipo, muy transitada durante le época estival.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1053, 'Aigua Gélida', 'Playa carente de servicios pero que dispone de una zona reservada para la práctica del submarinismo, ya que goza de unas aguas cristalinas donde se refugia una fauna marina de gran belleza.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201707, 'Cala Sant Roc', 'Playa rústica con acceso a través de unas escaleras.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201708, 'Platgeta', 'Pequeña cala urbana que dispone de servicios básicos', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201709, 'El Cau', 'Pequeña playa de baja afluencia que no dispone de servicios', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201710, 'Cala Pedrosa', 'Pequeña cala poco visitada y de oleaje moderado', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1055, 'Cala de Morro del Vedell', 'Playa visitada por aficionados a la pesca, tanto deportiva como submarina, más que por bañistas y turistas.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1056, 'Cala Margarida', 'Típica playa rodeada de pequeñas casas de pescadores, compuesta de bolos y piedras donde se encuentran las barcas de pesca.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1057, 'La Fosca', 'Esta playa, muy equipada y visitada, toma su nombre de una gran roca que la separa de otra playa conocida como San Esteve de la Fosca.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1058, 'Sant Esteve de la Fosca', 'Playa con un alto grado de ocupación que dispone de los equipamientos que comparte con su playa vecina de La Fosca.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1059, 'Cala S''Alguer', 'Pequeña playa carente de servicios que está compuesta de grava y rocas poco recomendables para el baño.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1060, 'El Castell', 'Playa con una gran calidad de arena, un entorno agradable exento de construcciones y buenos servicios que justifican su alto grado de ocupación.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1061, 'Cala Estreta', 'Bonita cala de difícil acceso muy apropiada para fondear las embarcaciones de recreo y disfrutar de la transparencia de sus aguas.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1062, 'Cala Bona', 'Pequeña cala carente de servicios y a la que se accede a pie por un camino entre pinos y rocas.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1063, 'Cap de Planes', 'Cala recóndita con difícil acceso a la que acuden los amantes del buceo y la pesca submarina', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1054, 'Gran de Palamós', 'Playa totalmente equipada, con un elevado grado de ocupación y que dispone de alquileres de cualquier tipo de embarcación náutica.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (351701, 'Sa Tamardia', 'Esta playa, actualmente recuperada, era utilizada como varadero de barcas.', 17118);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1064, 'Pals', 'Extensa playa de arena muy frecuentada por el turismo de la zona y sobre todo por los amantes de los deportes de vela.', 17124);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1065, 'Claper', 'Playa inhóspita rodeada de grandes acantilados rocosos y con difícil acceso, fuerte oleaje y sometida a fuertes vientos, donde el único atractivo son sus excelentes fondos rocosos y aguas cristalinas perfectas para la pesca submarina.', 17138);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1066, 'Portbou', 'Playa totalmente equipada, con acceso para discapacitados, donde es común la práctica de deportes de vela y el kayak, además de las inmersiones para disfrutar de los fondos rocosos.', 17138);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1067, 'Tres Platgetes', 'Playa de arena y grava, carente de servicios e instalaciones con poca afluencia de visitantes, únicamente para realizar inmersiones y disfrutar de las aguas cristalinas y los fondos rocosos.', 17138);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1068, 'Del Pi', 'Playa muy recogida e íntima donde apenas acuden visitantes, salvo para practicar inmersiones en sus excelentes aguas cristalinas y observar sus fondos rocosos.', 17138);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1069, 'Santa Margarida', 'Playa muy concurrida y muy bien equipada.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1070, 'Salatar', 'Playa turística rodeada de apartamentos y hoteles que dispone de todo tipo de servicios e infraestructuras.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1071, 'Rastrell', 'Excelente playa que dispone de todo tipo de servicios e infraestructuras y de un paseo marítimo rodeado de palmeras muy propicio para caminar.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1072, 'La Perola', 'Playa artificial que dispone de todo tipo de equipamientos, incluido acceso para discapacitados, y servicios de alquileres propios de este tipo de playa.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1073, 'Els Palangrers', 'Playa ubicada junto al puerto pesquero de Canyelles, por lo que resulta poco atractiva para el turismo de playa.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1074, 'Canyelles Petites', 'Playa muy frecuentada por los bañistas que se alojan en hoteles y apartamentos cercanos, disponiendo de servicios e infraestructuras.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1075, 'L''Almadrava', 'Playa con ambiente tranquilo y de estancia agradable, que dispone de servicios y equipamientos de calidad.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1076, 'Cala Murtra', 'Cala compuesta de piedras y arena ubicada en una zona aislada de todo núcleo urbano y a la que hay que acceder a pie. Agua cristalina.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1077, 'Cala Rostella', 'Playa virgen de difícil acceso que goza de unas aguas cristalinas pero con un fondo de piedras algo dificultoso para el baño.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1078, 'Cala Montjoi', 'Cala ubicada junto a un complejo turístico que le proporciona servicios e infraestructuras, así como una escuela de submarinismo.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1079, 'Cala Calitjàs', 'Pequeña cala compuesta de arena y rocas.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1080, 'Cala La Pelosa', 'Playa poco turística, aunque muy frecuentada por la gente de la zona por su fácil acceso, pero carente de instalaciones y servicios.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1081, 'Cala Canadell', 'Cala aislada ubicada dentro del espacio protegido del Cabo de Creus con muy poco afluencia de visitantes.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1082, 'Cala Joncols', 'Playa rústica conocida por los aficionados al submarinismo por disponer de un centro de buceo que realiza inmersiones para visitar los fondos marinos de la zona.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201717, 'La Punta', 'Playa urbana con todos los servicios, alquileres y equipamientos junto al puerto deportivo.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201718, 'Bonifaci', 'Playa de arena dorada y gruesa, muy bonita y tranquila, sin servicios, a la que se accede por el camino de ronda.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201719, 'Cala Lladó', 'Pequeña cala entre rocas, poco concurrida pero muy visitada por mar. Dificultosa para el baño.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201720, 'Cala Calis', 'Playa arrinconada junto a la Cala Montjoi.', 17152);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1083, 'Canyerets', 'Playa con mucha animación en la época estival ubicada muy cerca de la urbanización Rosamar, muy recomendable para disfrutar en familia. El acceso es por la Urb. Rosamar', 17160);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1084, 'Sant Feliu', 'Playa con marcado carácter turístico equipada con todo tipo de servicios e infraestructuras', 17160);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1085, 'Sant Pol', 'Playa totalmente equipada, ubicada en una bahía donde atracan gran cantidad de barcos.', 17160);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1086, 'Sant Pere Pescador', 'Extensa franja de arena fina muy recomendable para la práctica de todos los deportes relacionados con el viento.', 17178);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1091, 'Mas Pinell', 'Playa de gran dimensión compuesta de arena gruesa, que dispone de accesos para discapacitados, un chiringuito en la misma playa y servicio de alquileres náuticos.', 17199);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1092, 'L''Estartit', 'Playa urbana desde donde pueden verse las Islas Medes, Parque Natural Subacuático, muy interesante para la práctica del buceo.', 17199);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1094, 'Porto Pí', 'Playa aislada y tranquila a la que se accede desde la playa vecina de Llorell, mucho más visitada que ésta. Playa dentro de Urbanización Sta. Maria de Llorell, el acceso es restringido.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1095, 'Santa María de Llorell', 'Playa muy animada con bonitas vistas a la bahía, con mucha vegetación y que dispone de servicios e infraestructuras y de un club de deportes.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1096, 'Cala d''en Carlos', 'Cala esta dentro del Camping Llevado. Destaca por la transparencia de sus aguas.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1097, 'Cala Llevadó', 'Pequeña cala que ofrece la posibilidad de la práctica de una amplia gama de deportes náuticos.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1098, 'El Codolar', 'Playa urbana situada al lado de la Fortificación de Tossa de Mar', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1099, 'Platja Gran', 'Es la playa por excelencia de Tossa de Mar, donde acuden turistas y veraneantes a disfrutar de todo tipo de servicios, infraestructuras y oferta de ocio.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1100, 'La Palma', 'Playa que cuenta con todos los servicios propios de una playa urbana y con una gran oferta de alquileres náuticos y deportivos.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1101, 'Cala Bona', 'Cala recóndita con un acceso algo incómodo que como único servicio cuenta con un chiringuito de playa. Cala muy pequeña entre montañas', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1102, 'Cala Pola', 'Pequeña cala aislada desde donde salen excursiones en pequeñas embarcaciones para ver los fondos marinos y las calas de alrededor. Está dentro del Camping', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1103, 'Cala Giverola', 'Cala de arena de carácter semiurbano que presenta un alto grado de ocupación.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1104, 'Cala de Sa Futadera', 'Excelente cala de difícil acceso, muy recomendable para acudir a pasar el día, fondear el barco y disfrutar de las vistas de unos escarpados acantilados llenos de vegetación.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1105, 'Cala Salionç', 'Cala semiurbana rodeada de montañas y mucha vegetación que acoge a gran cantidad de visitantes. El acceso es por la urbanización Cala Salions', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201704, 'Cala de L''Ull de Vidre', 'Cala de arena dorada y de textura gruesa.', 17202);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1002, 'Empúriabrava', 'Playa totalmente equipada que acoge mucho turismo durante la época estival', 17047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1003, 'La Robina', 'Playa de carácter aislado, muy azotada por el viento, por lo que goza de excelentes características para la práctica del Wind-Surf y demás deportes relacionados con el viento.', 17047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201714, 'Can Comas', 'Larguísima playa de arena dorada fina. Situada en un paraje aislado, limitado en parte en ciertas épocas del año por estar en pleno Parque Natural del Aiguamolls de l''Emporda. Reserva de aves.', 17047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1031, 'Cala Morisca', 'Cala aislada de reducidas dimensiones y con un bajo grado de ocupación.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1033, 'Santa Cristina', 'Playa de arena de excelente calidad, muy bien equipada y que goza de unas aguas muy limpias donde puede practicarse el submarinismo.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1034, 'La Boadella', 'Playa de arena fina rodeada de rocas y vegetación', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1035, 'Fenals', 'Playa totalmente equipada, con gran afluencia de gente y mucha animación durante el verano, donde se puede practicar algún tipo de deporte.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1036, 'Cala Banys', 'Cala compuesta únicamente por rocas, donde más que de un baño puede disfrutarse de la pesca y de un bonito paseo por un entorno rocoso.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1037, 'Platja de Lloret', 'Playa urbana de gran extensión que cuenta con todo tipo de equipamientos e infraestructuras, y en sus inmediaciones dispone de una gran oferta de ocio.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1038, 'Sa Caleta', 'Pequeña playa de arena protegida por unas rocas sobre las que se erige un castillo medieval.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1039, 'Cala dels Frares', 'Cala de piedras carente de servicios e infraestructuras y muy incómoda para el baño.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1040, 'Cala d''en Trons', 'Cala rocosa desde donde se observa la ladera de un monte repleta de excelentes villas unifamiliares y más que para bañarse es recomendable para la pesca y el buceo.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1041, 'La Tortuga', 'Playa aislada de difícil acceso compuesta de rocas y carente de cualquier tipo de servicios para el uso del público.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1042, 'Canyelles', 'Playa que dispone de un pequeño puerto y de un Club Náutico.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201703, 'Cala Rajols', 'Pequeña playa aislada de arena dorada y textura gruesa.', 17095);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1010, 'Taballera', 'Cala con un acceso por tierra muy difícil, encontrándose aislada y muy poco visitada.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1011, 'Cala Tamariua', 'Playa situada entre dos montañas, aislada de cualquier construcción y en estado totalmente virgen.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1012, 'El Pas', 'Playa de excelente calidad que registra un alto grado de ocupación.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1013, 'De Sota', 'Playa urbana carente de infraestructuras y con poco atractivo para el turismo', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1014, 'La Ribera', 'Playa muy bien equipada, incluyendo acceso para discapacitados, donde se dan cita tanto la pesca en barca como el submarinismo, el esquí acuático y cualquier deporte relacionado con el viento.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1015, 'L''Arola', 'Playa de piedras poco visitada por turistas y bañistas, pero muy frecuentada por pescadores, buceadores y embarcaciones de recreo que fondean por la zona.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1016, 'Port de la Vall', 'Playa carente de servicios e infraestructuras pero muy frecuentada por extranjeros que se alojan en un camping muy cercano.', 17140);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1087, 'Vallpresona', 'Playa de difícil acceso por el bosque, carente de servicios, pero con un entorno natural precioso.', 17181);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1088, 'Senyor Ramón', 'Bonita playa de arena donde acuden muchas embarcaciones para fondear.', 17181);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1089, 'Playa de la Corcollada', 'Playa de bolos con un bajo grado de ocupación, muy recomendable para fondear.', 17181);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1090, 'Canyet', 'Playa rodeada de acantilados con mucha vegetación donde aparecen gran cantidad de piedras sobresalientes en el agua. Acceso por Urbanización Rosamar', 17181);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201705, 'Punta Canyerets', 'Pequeña playa de arena dorada con servicios básicos', 17181);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1106, 'La Fonda', 'Playa aislada, de difícil acceso y con un bajo grado de ocupación.', 43004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1107, 'Maricel', 'Playa compuesta de grava y arena, aislada de núcleos urbanos y con total ausencia de instalaciones y servicios.', 43004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1108, 'El Ciment', 'Esta playa recibe el nombre de El Ciment por estar situada junto a una fábrica de cemento que caracteriza el entorno donde está ubicada.', 43004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1117, 'El Marjal', 'Playa de grava de gran longitud que presenta un bajo grado de ocupación debido a su escasa disponibilidad de servicios.', 43004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1118, 'Les Cases d''Alcanar', 'Playa con un alto grado de ocupación y que está dotada con acceso para discapacitados.', 43004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1206, 'Altafulla', 'Playa que dispone de acceso para discapacitados y alquileres de embarcaciones náuticas.', 43012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1207, 'Cala Canyadell', 'Pequeña cala de arena ubicada en una zona semiurbana que presenta un bajo grado de ocupación.', 43012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1120, 'Los Eucaliptos', 'Esta playa se caracteriza por ser virgen a la acción del hombre, de espacios abiertos, arena fina, flora peculiar y autóctona y las singulares dunas de arena, que hacen del Delta un paraje insólito.', 43014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1221, 'Calafell', 'Playa de arena dorada con una extensión aproximada de un kilómetro ubicada en una zona urbana con un alto grado de ocupación.', 43037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1222, 'Mas Mel', 'Esta playa dispone de alquiler de sombrillas, hamacas, embarcaciones náuticas y todo tipo de instalaciones para el uso del público.', 43037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1223, 'Segur de Calafell', 'Esta playa alberga el Puerto Marítimo de Segur de Calafell y presenta gran cantidad de servicios disponibles.', 43037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1177, 'L''Ardiaca', 'Playa de carácter urbano compuesta de grava y arena que dispone de variedad de servicios y alquileres de hamacas y sombrillas.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1178, 'La Llosa', 'Playa de grava y arena con inmejorables servicios.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1179, 'L''Horta de Santa María', 'Pequeña playa de arena que goza de todo tipo de servicios e instalaciones.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1180, 'Prat d''En Fores i Regueral', 'Playa ubicada al norte del Puerto de Cambrils que dispone de un gran paseo con palmeras y servicios inmejorables.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1181, 'El Cavet', 'Playa de grava y arena de carácter semiurbana que goza de unas tranquilas aguas y servicios más esenciales para su uso público.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1182, 'L''Esquirol', 'Playa compuesta de arena dorada y ubicada en una zona semiurbana.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1183, 'Vilafortuny', 'Playa dotada con unos servicios e instalaciones inmejorables.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1184, 'Cap de Sant Pere', 'Esta playa de arena y aguas tranquilas presenta un alto grado de ocupación y dispone de alquiler de hamacas y sombrillas.', 43038);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1211, 'Creixell', 'Playa de unos dos kilómetros de longitud de arena fina que dispone de todo tipo de servicios e instalaciones.', 43050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1224, 'Cunit', 'La Playa de Cunit es la única playa de este término municipal, aunque se extiende a lo largo de dos kilómetros y medio de arena dorada donde se puede disfrutar de instalaciones y servicios múltiples.', 43051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1134, 'Cala Buena', 'Playa de reducidas dimensiones de arena y grava fina ubicada en una zona semiurbana y tranquila.', 43104);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1135, 'Santa Llúcia', 'Playa con un alto grado de ocupación compuesta de arena dorada y gravilla ubicada en una zona semiurbana. En esta playa se sitúa el conocido Morro del Gos, un islote de dimensiones reducidas que forma un tómbolo de arena, dándole más amplitud a dicha playa.', 43104);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1136, 'Cala Moros', 'El Perelló ofrece unas playas tranquilas y aisladas, caracterizadas por su gran belleza natural y aguas cristalinas.', 43104);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1137, 'Platja de l?Àliga', 'El Perelló ofrece unas playas tranquilas y aisladas, caracterizadas por su gran belleza natural y aguas cristalinas.', 43104);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1212, 'Platja Llarga', 'Playa con un elevado grado de ocupación durante la temporada estival que dispone de servicios e instalaciones para su uso público.', 43131);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1213, 'Punta de la Guineu', 'Playa urbana donde pueden alquilarse hamacas y embarcaciones deportivas y que dispone de un club náutico en la misma playa.', 43131);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1214, 'La Pelliseta', 'Esta playa presenta un elevado grado de ocupación.', 43131);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1215, 'Les Guineus', 'Playa de arena ubicada en una zona urbana y donde pueden alquilarse embarcaciones deportivas náuticas.', 43131);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1216, 'El Francàs', 'La Platja del Francàs es la última playa del término municipal de Roda de Barà, ubicada en una zona urbana con alto grado de ocupación.', 43131);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1109, 'Suizo', 'Playa semiurbana de tamaño muy reducido compuesta de arena dorada y con unas aguas tranquilas para el baño.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1110, 'Les Delicies', 'Playa ubicada en el núcleo urbano, con alto grado de ocupación.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1111, 'El Faro', 'Playa compuesta de arena ubicada en una zona urbana y con un elevado grado de ocupación.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1112, 'Aldea Blanca', 'Playa de apenas cien metros de longitud que presenta un elevado grado de ocupación, arena fina y aguas tranquilas.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1113, 'Aiguassera', 'Pequeña playa compuesta de arena dorada, ubicada en una zona urbana y con un alto grado de ocupación.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1114, 'Capri', 'Playa muy pequeña de arena dorada, ubicada en una zona urbana y con una afluencia de público elevada.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1115, 'Juanito', 'Playa de arena y aguas tranquilas para el baño que dispone de una gran afluencia de visitantes.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1116, 'El Garbi', 'Playa que dispone de todo tipo de alquiler de servicios y náuticos.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1119, 'El Trabucador', 'Playa de gran longitud compuesta por arena dorada, bañada por aguas tranquila y ubicada en una zona aislada de núcleos urbanos.', 43136);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1208, 'Barrio Marítimo', 'Playa situada en el antiguo barrio de pescadores y va desde la plaza de Narcís Monturiol hasta el Club Marítimo y a su lado esta ubicado el Paseo Marítimo.', 43153);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1209, 'El Muntanyans', 'Playa de gran extensión que alberga un ecosistema dunar típico de costa con dunas semimóviles y lagunas de agua salada, por lo que está incluida en el Plan de Espacios de Interés Natural.', 43153);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1210, 'La Paella', 'Playa situada en la urbanización dels Munts que alberga el puerto deportivo y pesquero y tiene una zona destinada a la práctica deportiva. Dispone de servicios e instalaciones de calidad.', 43153);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1217, 'El Francàs', 'Playa de arena fina y aguas tranquilas de algo más de un kilómetro de extensión, ubicada en una zona urbana y con un alto grado de ocupación.', 43163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1218, 'Coma-Ruga', 'La Playa de Coma Ruga dispone de todo tipo de servicios e instalaciones, así como el Puerto Deportivo en la misma playa y un Club Náutico.', 43163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1219, 'Sant Salvador', 'Playa de arena de carácter urbano, equipada con gran cantidad de instalaciones y servicios para el uso del público.', 43163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1220, 'Les Madrigueres', 'La Platja de les Madrigueres dispone de instalaciones y servicios para el uso del público a lo largo de todo el paseo marítimo.', 43163);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1195, 'La Pineda', 'Playa de gran extensión, con inmejorables servicios e instalaciones de todo tipo, incluida una zona reservada para la práctica del submarinismo.', 43171);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1123, 'Riomar', 'Playa ubicada a unos ocho kilómetros del núcleo urbano de Deltebre, en el mismo Parc Natural del Delta D''Ebre, que goza de todo tipo de servicios.', 43901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1124, 'La Marquesa', 'Playa extensa y tranquila, sin masificaciones, ubicada en un bello paraje natural.', 43901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1125, 'Punta del Fangar', 'Sus características geográficas y naturales la convierten en una de las playas más singulares de la zona por la gran belleza de este inmenso paraje.', 43901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1126, 'Balsa de la Arena', 'Playa virgen, extensa y aislada, de arena fina y aguas tranquilas, ubicada entre la Playa de Riomar y Playa de la Marquesa.', 43901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (304301, 'Playa de la Isla de Buda', 'Playa de arena que presenta un bajo grado de ocupación.', 43902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1121, 'El Serrallo', 'Playa de gran extensión, de carácter aislado y con un bajo grado de ocupación.', 43902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1122, 'Migjorn', 'Playa de arena que presenta un bajo grado de ocupación.', 43902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1194, 'El Reguerot de Claveguer', 'Cala aislada y de difícil acceso compuesta de grava y rodeada de rocas que presenta una baja afluencia de visitantes.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1185, 'Playa de Poniente', 'Playa natural de fina y dorada arena de suave pendiente que confiere gran seguridad para los bañistas y los niños. Dispone de una zona infantil para juegos y de una zona reservada para los deportes náuticos.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1186, 'Playa de Levante', 'Es la playa natural de mayor extensión del municipio que dispone de acceso para discapacitados, zona infantil para juegos, zona deportiva y deportes náuticos, además de un gran número de servicios e instalaciones.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1187, 'Els Capellans', 'Es una pequeña playa situada en el núcleo urbano, de suave pendiente y muy segura. Dispone de gran cantidad de servicios e instalaciones, así como de una zona reservada para deportes náuticos.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1188, 'Cala Llengüadets', 'Pequeña cala a la que solo se puede acceder a pie, rodeada de naturaleza, lo que le confiere una gran belleza.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1189, 'Platja Llarga', 'Playa de gran belleza natural al estar rodeada de pinos y naturaleza que dispone de alquileres náuticos, sombrillas y hamacas.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1190, 'Penya Tallada', 'Es una pequeña cala de gran belleza natural que está situada al lado de la Punta Roja y a la que sólo puede accederse a pie desde la calle del mismo nombre.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1191, 'Cala Font', 'Pequeña cala de arena situada en una zona urbana que presenta un alto grado de ocupación y dispone de alquiler de hamacas, sombrillas y embarcaciones náuticas.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1192, 'Cala Vinya', 'Cala de reducidas dimensiones pero que dispone de todo tipo de alquiler de servicios y que goza de un alto grado de ocupación.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1193, 'Cala Crancs', 'Es una de las playas más atractivas del término municipal de Salou ya que se encuentra rodeada de vegetación y sus límites son naturales.', 43905);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1140, 'Cala Santes Creus', 'Cala aislada ubicada en una zona de costa con un perfil abrupto y rodeada de vegetación mediterránea.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1141, 'Port Olivet', 'Playa de bolos y grava ubicada en una zona aislada y con un bajo grado de ocupación.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1142, 'Puerto de L''Estany Gras', 'Esta playa de grava y arena presenta un pequeño puerto natural que da origen a su nombre.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1143, 'Cala Bon Capó', 'Esta playa se encuentra ubicada al pie del nuevo Hotel L''Ametlla de Mar.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1144, 'Bon Caponet', 'Playa de reducidas dimensiones y con ausencia total de servicios e instalaciones.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1138, 'Cala de l?Estany Podrit', 'Estas pequeñas calas de la costa de l''Ametlla presentan un perfil abrupto, con bellos acantilados, rodeadas de una vegetación típicamente mediterránea.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1139, 'Cala Leña', 'Pequeña cala aislada rodeada de vegetación mediterránea y compuesta de rocas, bolos y arena.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1145, 'Ribes Altes', 'Prácticamente no existe playa.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1146, 'Cala Pepo', 'Cala de pequeñísimo tamaño ubicada en una zona urbana, compuesta de grava y arena que goza de unas aguas tranquilas.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1147, 'L''Alguer', 'Playa de arena dorada ubicada en el mismo casco urbano de L''Ametlla.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1148, 'Pixavaques', 'Esta pequeña playa de carácter urbano se encuentra localizada al pie del camping Nautic y presenta un alto grado de ocupación.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1149, 'L''Estany Tort', 'Esta playa de arena fina y dorada se caracteriza por sus aguas poco profundas, ideales para el disfrute del turismo familiar.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1150, 'Chelin', 'Playa que presenta poco grado de ocupación, compuesta de grava y bolos, rodeada de rocas y vegetación. Habilitada zona de aparcamiento y merendero.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1151, 'Torrent del Pi', 'Esta playa, como todas las de l''Ametlla, es de reducido tamaño y se encuentra rodeada de vegetación y zona de humedal.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1152, 'Cala Moscas', 'Zona rocosa sin playa.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1153, 'Cala Forn', 'Estas calas de dorada y fina arena son las principales protagonistas de esta costa, donde se puede oler el aroma de los pinares que acarician el agua.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1154, 'Cala Vidre', 'Estas calas de dorada y fina arena son las principales protagonistas de esta costa, donde se puede oler el aroma de los pinares que acarician el agua.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1155, 'Sant Jordi', 'Esta pequeña playa se encuentra emplazada al pie del castillo medieval de Sant Jordi de Alfama. Paseo, zona de aparcamiento, merenderos y zona infantil.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1156, 'Cala Trebol', 'Estas calas de dorada y fina arena son las principales protagonistas de esta costa, donde se puede oler el aroma de los pinares que acarician el agua.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1157, 'Cala Calafató', 'Esta pequeña cala semiurbana de areana está ubicada junto a la playa que recibe el mismo nombre.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1158, 'Playa de Calafat', 'A esta playa se accede por la entrada principal al puerto. Si se accede en coche se tiene que abonar parking del mismo. Dispone de servicio de bar en la playa.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1159, 'Cala Llobeta', 'Estas calas de dorada y fina arena son las principales protagonistas de esta costa, donde se puede oler el aroma de los pinares que acarician el agua.', 43013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1165, 'Punta del Riu', 'Playa de arena y aguas tranquilas donde pueden practicarse todo tipo de deportes náuticos.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1166, 'Platja de Cristall', 'Playa de arena donde pueden practicarse deportes náuticos y el submarinismo.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1167, 'Cala de los Angeles', 'Pequeña cala de difícil acceso con un bajo grado de ocupación compuesta de arena dorada.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1168, 'Cala Bot', 'Cala reducida a la que se accede únicamente a pie, pero que presenta un alto grado de ocupación.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1169, 'Cala Misteri', 'Cala tranquila.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1170, 'Cala del Solitari', 'Bonita cala de arena dorada, rodeada de vegetación que le confiere un aspecto muy natural.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1171, 'Cala de las Sirenas', 'Cala rodeada de rocas a la que se accede a pie o a través del mar y que presenta un grado de ocupación muy bajo.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1172, 'Cala Vieneses', 'Esta pequeña cala tiene acceso únicamente a pie o en barco y se encuentra rodeada de rocas y vegetación natural.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1173, 'L''Estany Gelat', 'Esta playa de gran dimensión se encuentra aislada de núcleos urbanos y dispone de alquileres de tipo náutico.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1174, 'La Porquerola', 'Playa muy extensa compuesta de arena y rocas a la que se accede a pie o en barco, por lo que presenta un bajo grado de ocupación.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1175, 'Rifà', 'Playa aislada de acceso a pie o a través del mar, con un bajo grado de ocupación, compuesta de arena y rocas.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1176, 'La Peixerota', 'Playa extensa de carácter semiurbano compuesta de arena y grava, que presenta los servicios más esenciales para el uso del público.', 43092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1196, 'El Milagro', 'Playa de fina arena y suave pendiente que goza de unas aguas tranquilas.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1197, 'L''Arrabassada', 'Playa de carácter semiurbano que presenta un elevado grado de ocupación durante la temporada alta.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1198, 'La Savinosa', 'Playa compuesta de fina arena dorada donde puede disfrutarse de unas tranquilas aguas y un entorno de vegetación natural.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1199, 'Los Capellanes', 'Pequeña playa de arena, aislada de núcleos urbanos, que presenta un bajo grado de ocupación.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1200, 'Playa Larga', 'Playa de gran extensión dotada con todo tipo de servicios e instalaciones disponibles para el uso público.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1201, 'Platja Fonda', 'Playa aislada, de difícil acceso y carente de cualquier servicio e instalación para el público.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1202, 'Rocas Planas', 'Playa de arena de pequeña extensión, carente de servicios para el público que presenta un bajo grado de ocupación.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1203, 'La Mora', 'Playa compuesta de arena fina y que dispone de alquiler de embarcaciones acuáticas.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1204, 'Cala Tobera', 'Pequeña cala aislada, con bajo grado de ocupación, compuesta de arena dorada y rodeada de vegetación natural.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1205, 'Tamarit', 'Playa de bolos bañada por unas tranquilas aguas que dispone de servicios elementales para su uso público.', 43148);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1160, 'L''Almadrava', 'Playa extensa de arena dorada ubicada en una zona semiurbana, que se caracteriza por sus aguas tranquilas.', 43162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1161, 'Cala Justell', 'Pequeña cala aislada compuesta de arena y rocas que no presenta una gran afluencia de visitantes.', 43162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1162, 'El Torn', 'La Platja del Torn se caracteriza por su entorno natural que representa un paraíso para las vacaciones naturistas de las familias que buscan la tranquilidad, naturaleza y servicios de alto nivel.', 43162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1163, 'L''Arenal', 'Extensa playa de fina arena oscura y aguas tranquilas donde puede disfrutarse de los deportes náuticos.', 43162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1164, 'Punta del Riu', 'Playa urbana de arena que dispone de gran cantidad de servicios para el uso público.', 43162);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (104301, 'Platja dels Pinets', 'La playa Platja dels Pinets es una tranquila playa de 40 metros de longitud', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1131, 'Baconet', 'Playa de pequeñas dimensiones y piedras características de coloración blanca y negra que forman un conjunto atractivo en contraste con el azul del mar.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1132, 'Cala María', 'Cala de piedras de pequeño tamaño y reducidas dimensiones, donde puede disfrutarse de un paisaje entrañable por los verdes pinares y la peñas rojizas que la rodean.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1133, 'Cap Roig', 'Playa de gran calidad, que forma parte de una ruta ideal para los amantes de los paseos a la orilla del mar.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1127, 'El Arenal', 'Destaca por su arena fina y dorada típica de las playas del Delta. Debido a su situación, es una playa ideal para los niños por su poca profundidad. Conocida como la playa de la calma.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1128, 'El Arquitecto', 'Pequeña playa localizada al abrigo del Puerto Deportivo de L''Ampolla, al final del paseo marítimo.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1129, 'Cala Avellanes', 'Pequeña playa ubicada en el centro urbano que destaca por su arena y aguas tranquilas.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1130, 'Els Capellans', 'Playa de reducidas dimensiones al norte del casco urbano, con piedras características blancas y negras que contrastan con la vegetación circundante.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204301, 'Platja Perales', 'Esta playa está situada en el límite de dos términos y en la salida del barranco de Cap Roig.', 43906);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1564, 'Chanteiro', 'Playa semiurbana dotada con la mayoría de los servicios, como servicio de limpieza de playas y duchas.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1565, 'Ribada', 'Esta playa presenta una pared escarpada de difícil acceso, al igual que su playa vecina Estacas.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1566, 'Estacas', 'Esta playa presenta una pared escarpada de difícil acceso, al igual que su playa vecina Ribada.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1567, 'Ares', 'Es la playa del nucleo urbano de Ares, tranquila y bien equipada. Con numerosos accesos para personas con movilidad reducida.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1568, 'Seselle', 'Extensa playa equipada con bastantes servicios y zonas de fondeo frecuentada por barcos de recreo.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1569, 'Raso', 'Muy bien equipada y frecuentada por residentes en la zona.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1570, 'Sabadelle', 'Aislada playa poco recomendable para el baño.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1571, 'Redes', 'Playa urbana carente de servicios y con un estado de conservación del entorno natural algo deficiente.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201527, 'As Mirandas', 'El lecho de la playa alterna roca y arena.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201528, 'Centeas', 'El lecho de la playa alterna roca y arena.', 15004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1572, 'El Matadero', 'Playa ubicada en las cercanías de una industria que contribuye al mal estado de conservación del entorno natural.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1573, 'Suevos', 'Ubicada en la zona de afección de una industria que contribuye al mal estado de las aguas de la zona.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1574, 'Area Pequeña', 'Playa con aguas poco aconsejables para el baño debido al estado deficiente de su calidad.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1575, 'Sabón', 'En el entorno de esta playa se encuentra la central térmica de Sabón. La anchura de la playa en su parte izquierda es de 30 m., mientras que en la parte derecha alcanza los 80 m.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1576, 'La Salsa', 'Pequeña cala de aguas limpias bastante concurrida y de fácil acceso', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1577, 'La Hucha', 'Playa que presenta un oleaje variable, incluso fuerte, con aguas muy limpias.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1578, 'Valcobo', 'Playa muy peligrosa para el baño por sus grandes corrientes y fuerte oleaje.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1579, 'Combouzas', 'Esta playa se encuentra junto a la playa de Barrañán, y resulta bastante peligrosa para el baño.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1580, 'Barrañán', 'Aunque esta playa resulta muy peligrosa y ventosa, su grado de ocupación es elevado.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1581, 'Santa Irene', 'Pequeña cala poco concurrida, con fuerte oleaje, que puede catalogarse como playa incómoda.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1582, 'Porto Chas', 'Playa carente de arena por lo que la afluencia de bañistas es prácticamente nula.', 15005);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1583, 'El Pedrido', 'Playa situada en la desembocadura del río Mandeo, sometida a las variaciones de la marea.', 15008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1584, 'Regueiro', 'Playa de grava y arena con bajo grado de ocupación y ausencia total se instalaciones y servicios.', 15008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1585, 'Gandarío', 'Playa bien equipada y con gran afluencia de visitantes que practican diversas actividades deportivas.', 15008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201522, 'Cabana', 'Pequeña playa que desaparece en pleamar', 15008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1610, 'Ribademar', 'Playa aislada y de difícil acceso, por lo que presenta un bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1586, 'Costadal', 'Playa semiurbana que presenta un bajo grado de ocupación, buen estado de conservación y aguas tranquilas.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1587, 'O Porto', 'Playa de arena blanca situada en una zona urbana con bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1588, 'Barraña', 'Playa con elevado índice de ocupación en época estival, con aguas limpias y tranquilas, con oferta de buenos servicios y cuidado arenal que se hace muy extenso en bajamar.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1589, 'Rebordelo', 'Buen estado de conservación, aguas tranquilas y bajo grado de ocupación', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1590, 'Area do Río', 'Playa urbana de aguas tranquilas', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1591, 'Corviño', 'Playa muy degradada por los constantes vertidos incontrolados que se producen.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1592, 'Ribeira Grande', 'Playa de tamaño intermedio situada en una zona urbana (Cabo de Cruz), pero con bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1593, 'Piñeirón', 'Playa de tamaño reducido situada en zona urbana y carente de servicios.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1594, 'Gabiotea', 'La playa de Gabiotea dispone de aguas tranquilas y arena en buen estado de conservación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1595, 'Carragueiros', 'Playa muy cuidada desde el punto de vista medioambiental. Lugar atractivo de disfrute en época estival, por lo que el grado de ocupación es elevado. Arenas blancas y bien cuidadas y aguas limpias.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1596, 'A Retorta', 'Playa muy bien equipada que presenta un elevado grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1597, 'Chazo', 'Presenta un estado de conservación regular y un bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1598, 'Ladeira do Chazo', 'Tiene carencias de estacionamiento de vehículos, aunque su grado de ocupación es medio debido a sus limpias aguas y cuidado arenal.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1599, 'Mañóns', 'Es uno de los arenales más amplios del Concello de Boiro.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1600, 'Fontenla', 'Playa con nulo nivel de ocupación en época estival', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1601, 'Portomouro', 'Playa sin acondicionamientos ni servicios, con bajo grado de ocupación, situada en la localidad de Portomouro', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1602, 'Suigrexa', 'Playa de difícil acceso con aguas tranquilas, arena blanca y bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1603, 'Supicho', 'Carece de servicios y su entorno presenta un estado algo mejorable.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1604, 'Agañán', 'Medio kilómetro de playa de arena blanca, aguas tranquilas y bajo grado de ocupación debido a la falta de servicios y a la calidad del entorno algo deficiente.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1605, 'Bodión', 'Playa muy degradada por las industrias conserveras y los servicios situados en sus inmediaciones, que hacen que sus aguas no sean aptas para el baño.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1606, 'Agoeiros', 'Al igual que la playa vecina de Budión, sus aguas no son aptas para el baño debido a la degradación de las mismas por la cercanía de industrias conserveras y de un centro de producción de energía.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1607, 'Area Basta', 'Playa sin accesos directos a la misma, de forma que para acceder hay que cruzar fincas particulares, a menudo entre frondosa vegetación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1608, 'Lóbrigo', 'Playa con bajo nivel de ocupación que es utilizada como zona de varada de embarcaciones pesqueras.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1609, 'Quinteiro', 'Presenta un estado de conservación de su entorno natural algo deficiente y bajo grado de ocupación.', 15011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201517, 'Cala Chamoso', 'Pequeña playa aislada de arena dorada.', 15015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1616, 'Cabanas', 'Playa de gran calidad, tanto por sus características de agua, arena y amplitud como por sus instalaciones y servicios disponibles.', 15015);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (951, 'Ribes Roges', 'Playa dotada con gran cantidad de servicios e infraestructuras, indicada para los niños debido a la tranquilidad de sus aguas y poca profundidad.', 8307);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (952, 'El Far de Sant Cristófol', 'La Platja del Far le debe su nombre a un faro situado al lado del puerto y resulta excelente para acudir con niños por su excelente arena, sus tranquilas aguas y su disponibilidad de servicios.', 8307);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (883, 'Els Tres Micos', 'La Platja dels Tres Micos se localiza frente a una urbanización de viviendas unifamiliares en un entorno muy arbolado y agradable, estando muy bien equipada.', 8032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (884, 'Platja del Bassiot', 'Playa muy cuidada que disfruta del encanto que le otorgan las barcas de los pescadores concentradas en uno de sus extremos.', 8032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (896, 'Gavà', 'Extensa playa de arena dorada, que dispone de los servicios más esenciales para el uso del público.', 8089);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200804, 'Protegida sector II', 'Amplia playa de arena dorada y oscura', 8169);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200805, 'Platja Equipada', 'Playa de arena dorada y oscura', 8169);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200803, 'Els Militars', 'Playa con poca afluencia', 8169);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200806, 'Platja Naturista', 'Playa aislada de arena dorada y oscura', 8169);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200807, 'Protegida sector I', 'Amplia playa con baja afluencia', 8169);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (912, 'L''Estació', 'Playa de reducidas dimensiones ubicada bajo la Estación de tren de Sant Andreu de Llavaneres y frecuentada generalmente por los residentes de la zona, más que por los turistas.', 8197);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (913, 'Les Barques', 'Pequeña playa aneja a la Playa de Sant Andreu de Llavaneres, a la que se puede llegar andando, y muy cercana a las vías del tren.', 8197);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (914, 'El Balís', 'Pequeña playa de apenas 50 metros de longitud junto al Puerto de Balis que se extiende hasta la Riera de Gironella, donde se encuentra el límite de este término municipal.', 8197);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (923, 'Sant Vicenç de Montalt', 'Playa muy ancha localizada junto al Puerto de Balís que dispone de gran cantidad de servicios de calidad que le dan un buen ambiente, y que por otra parte es un buen ejemplo de limpieza.', 8264);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (956, 'Aiguablava', 'Playa ubicada en un bonito entorno de montañas con mucha vegetación, que forma una pequeña bahía muy frecuentada por embarcaciones de recreo.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (957, 'Port d''Esclanyà', 'Playa muy recogida entre grandes piedras, frecuentada por los residentes de una urbanización cercana.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (958, 'Platja d''en Malaret', 'Playa de carácter semiurbano compuesta de rocas y arena, de dimensiones muy reducidas, y con poco atractivo turístico.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (959, 'Playa Fonda', 'Playa de arena gris oscuro, ubicada entre paredes rocosas con vegetación de pinos, con un bonito entorno natural, pero que carece de equipamientos.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (960, 'Sa Tuna', 'Playa de carácter semiurbano que acoge gran cantidad de barquitas de los pescadores de la zona', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (961, 'Aiguafreda', 'Esta playa carece de arena y esta acondicionada para el amarre de los barcos deportivos que frecuentan la zona.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (962, 'Sa Riera', 'Es una de las playas más atractivas de la zona, muy bien equipada incluyendo acceso para discapacitados.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (963, 'L''Illa Roja', 'Playa aislada ubicada en un bonito entorno de rocas y pinos y a la que se accede desde la playa vecina del Racó.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (964, 'El Racó', 'Playa turística, muy bien equipada y con un alto grado de ocupación.', 17013);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101701, 'Treumal', 'Esta al lado de la Playa de Santa Cristina de Lloret de Mar que tiene todos los servicios. Esta playa destaca por la calidad de su arena y el buen estado de su entorno natural. Colindante con el T.M. de Lloret de Mar.', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (965, 'S''Abanell', 'Aunque se trata de una playa que dispone de un equipamiento completo, la cantidad de gente que acude a ella durante la época estival le resta atractivo a la playa.', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (966, 'Blanes', 'Playa regenerada, muy bien equipada y con gran afluencia de público durante el verano', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (967, 'Els Capellans', 'Playa de bolos y arena, muy cerca del Puerto de Blanes y de la Punta de Santa Ana, de donde toma su segundo nombre y donde puede practicarse el submarinismo.', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (968, 'Cala de Sant Francesc', 'Pequeña cala con excelente equipamiento y que destaca por la limpieza de sus aguas y de su arena.', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201701, 'Cala Forcanera', 'Acantilados con accesos por fincas particulares, o caminando borde del mar', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201702, 'Cala S''Agulla', 'Acantilados con accesos por fincas particulares, o caminando borde del mar', 17023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (969, 'Sa Conca', 'Playa ubicada al sur de Cadaqués con el único encanto de estar situada junto a uno de los núcleos urbanos más pintorescos de la Provincia.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (970, 'Es Sortell', 'Playa situada junto al emblemático núcleo de Cadaqués y que goza de unas bonitas vistas de su iglesia y de su entorno.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (971, 'Llané Gran y Petit', 'Playa urbana rodeada de las pintorescas casas del pueblo de Cadaqués, donde se agolpan gran cantidad de barcas sobre la superficie de grava y arena oscura.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (972, 'Port d''Alguer', 'Playa ubicada en el mismo centro de Cadaqués, frente a la iglesia del pueblo, con el único atractivo de disfrutar de las vistas y el ambiente del entorno.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (973, 'Gran y Esportal', 'Es la playa principal de Cadaqués donde se concentra la mayoría del turismo y la gente de la zona.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (974, 'Es Poal', 'Playa de grava situada cerca del pueblo de Cadaqués donde, más que de un baño, puede disfrutarse de las vistas de las pintorescas casas blancas del pueblo.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (975, 'Es Pianc', 'Playa urbana situada en el mismo núcleo de Cadaqués con vistas a la bahía, donde la grava y la arena de la que está compuesta se encuentra ocupada por pequeñas barcas.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (976, 'Ses Oliveres', 'Playa de carácter semiurbano, donde más que bañistas se encuentran infinidad de barcas amarradas en la orilla.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (977, 'Ros', 'La playa del Ros es otra de las playas de Cadaqués más frecuentadas por embarcaciones de pesca y de recreo que de bañistas.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (978, 'Portlligat', 'Playa de grava y arena oscura que no recibe gran afluencia de bañistas pero si de embarcaciones de recreo que fondean en la zona', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (979, 'S''Alqueria Petita', 'Playa de rocas y arena donde acude gran cantidad de bañistas y donde existe gran afición a la pesca con caña y submarina.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (980, 'S''Alqueria Gran', 'Playa de rocas y grava con un alto grado de ocupación, carente de servicios e infraestructuras.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (981, 'Cala Portaló', 'Cala aislada y de acceso difícil, perteneciente al espacio protegido del Cabo de Creus, con poca afluencia de visitantes.', 17032);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (982, 'Comptat de Sant Jordi', 'Segunda playa del término municipal de Calonge, presenta un carácter aislado pero es muy frecuentada por la gente del lugar.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (983, 'Cap Roig', 'Playa rodeada de rocas y vegetación, de aguas muy tranquilas y de ambiente sosegado.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (984, 'Cala de Ses Torretes', 'Playa semiurbana, de ambiente tranquilo que ofrece todo tipo de alquileres, hamacas, sombrillas y embarcaciones náuticas.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (985, 'Can Cristus', 'La Playa de Can Cristus presenta una alto grado de ocupación, buenas instalaciones y todo tipo de alquileres, hamacas, sombrillas y embarcaciones náuticas, a pesar de su entorno escasamente urbanizado', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (986, 'Cala del Forn', 'Playa carente de servicios, muy adecuada para la práctica de la pesca submarina y el buceo', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (987, 'Cala dels Esculls', 'Esta cala, al igual que otras dos muy cercanas, son muy recomendables para practicar el buceo y la pesca submarina.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (988, 'Cala de la Roca del Paller', 'Cala con un ambiente tranquilo para el baño, a la que se accede por unas pequeñas escaleras hasta pie de playa.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (989, 'Roques Planes', 'Esta playa esta compuesta casi exclusivamente de rocas por lo que resulta más propicia para el buceo y la pesca que para el baño.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (990, 'Racó dels Hornes', 'Playa que carece de servicios y que es frecuentada por gente del lugar más que por turistas.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (991, 'Torre Valentina', 'Playa urbana, totalmente equipada que recibe una gran afluencia de gente.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (992, 'Sant Antoni', 'Es la playa más larga del municipio. Muy familiar, formada por tres bahías separadas por espigones, cuenta con todo tipo de servicios e infraestructuras.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (993, 'Es Monestri', 'Excelente playa desde el punto de vista turístico, ya que cuenta con buena arena, servicios e infraestructuras y una gran oferta de ocio a lo largo del paseo marítimo.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1000, 'Belladona', 'Es la primera playa del término municipal de Calonge, presenta un carácter aislado pero es muy frecuentada por la gente del lugar.', 17034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (994, 'Sa Conca', 'Excelente playa turística pero que guarda un entorno muy atractivo a pesar del alto grado de ocupación que presenta.', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (995, 'Cala Pedrosa', 'Pequeña cala ubicada en una zona rocosa que alberga lujosos chalets unifamiliares. Acceso camino de ronda de S''Agaro', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (996, 'Platja d''Aro', 'Es la playa más conocida y turística del término municipal, totalmente equipada y muy concurrida', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (997, 'Cala Rovira', 'Playa formada por un ancho arenal dorado.', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (998, 'Sa Cova', 'Playa ubicada en un acantilado, que presenta un elevado grado de ocupación debido al camping del mismo nombre localizado a pie de playa.', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (999, 'Cala del Pi', 'Cala de impresionante belleza que destaca por sus aguas cristalinas y sus atractivos fondos, muy recomendables para visitarlos.', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201706, 'Punta Els Canyers', 'Playa de bolos rodeada de vegetación de todo tipo', 17048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101702, 'D?en Carbassó', 'Playa aislada a la cual se llega a través una bonita travesía ', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1004, 'Punta d''Es Borró', 'Esta playa se encuentra aislada de todo núcleo urbano, con un bajo grado de ocupación..', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1005, 'Playa del Borró', 'Playa aislada ubicada en un entorno árido, donde la poca gente que acude a ella lo hace en busca de tranquilidad.', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1006, 'Garbet', 'Playa rústica de arena gruesa y piedras, bastante concurrida debido a la proximidad de la carretera que facilita su acceso.', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1007, 'Colera', 'Playa situada en el mismo núcleo urbano de Colera, contigua al puerto pesquero y donde es constante el trasiego de barcas de pesca, muchas veces amarradas en la orilla.', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1008, 'En Goixa', 'Se trata de la playa de Colera más visitada, de piedras y arena gris oscura y rodeada de altos acantilados.', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1009, 'Rovellada', 'Playa frecuentada por la gente que reside en la urbanización cercana, que recibe el mismo nombre que la playa, y donde es común la caña de pescar, la piragua y el submarinismo.', 17054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101703, 'Cala Montgó', 'Delimita media playa de Torroella de Montgri y media playa de L''Escala. Esta situada junto al Monte del Montgó, desde donde se observan los acantilados de alrededor y donde se puede disfrutar de unas cristalinas aguas.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101704, 'Cala Illa Mateua', 'La playa Cala Illa Mateua situada en L''Escala es una playa de bolos de 170 metros de longitud.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101705, 'Moll Grec', 'La playa Moll Grec, situada en L''Escala, es una playa de arena de 500 metros de longitud. Le da el nombre los restos del antiguo muelle griego/fenicio que quedan, de una altura de unos 6 metros', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1017, 'Riells', 'Es la playa más turística de L''Escala, con servicios de calidad y que cuenta con acceso para discapacitados.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1018, 'Port d''en Perris', 'Playa urbana compuesta de pequeñas piedras acondicionada de manera que forma parte del núcleo urbano en el que está ubicada.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1019, 'La Platja', 'Playa ubicada en el casco urbano de L''Escala, con un alto grado de ocupación y con los servicios propios de una playa urbana.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1020, 'Cala de la Creu', 'Cala de arena carente de infraestructuras donde el viento sopla con fuerza y se produce un fuerte oleaje. Es muy emblemática porque encontramos barcas y barracas de pescadores.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1021, 'El Rec del Moli', 'Playa ubicada a las afueras de L''Escala muy frecuentada por los que viven en la zona.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1022, 'El Portitxol', 'Playa muy turística que está equipada con acceso para discapacitados.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1023, 'Les Muscleres', 'Playa de gran calidad muy adecuada para acudir con la familia..', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1024, 'Sant Martí d''Empúries', 'Playa que dispone de todo tipo de servicios e infraestructuras, incluso acceso para discapacitados.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1025, 'El Riuet', 'Playa de arena ubicada muy cerca de las ruinas de la antigua ciudad de Ampurias, principal atractivo de la zona.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201711, 'El Codolar', 'Playa de guijarros a la que se accede por una escalera desde el Paseo Marítimo (Calle Ll. Albert)', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201712, 'Cala Mar d''en Manassa', 'Playa urbana de pequeños guijarros, muy expuesta al temporal y a la que se accede por una escalera.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201713, 'Cala del Pedrigolet', 'Pequeña cala de guijarros, recóndita y a resguardo de la tramontana. Muy cerca de la Ruinas de Empuries.', 17062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1026, 'Cau del Llop', 'Playa semiurbana de grava y arena oscura muy frecuentada, tanto por bañistas como por embarcaciones de recreo que fondean por la zona.', 17092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1027, 'La Farella', 'Playa con un alto grado de ocupación, de ambiente tranquilo y que presenta gran cantidad de rocas donde practicar la pesca y el buceo.', 17092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1028, 'El Port', 'Playa ubicada en el puerto pesquero, compuesta de arena oscura con textura gruesa y ocupada principalmente por gente de la zona.', 17092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1029, 'Grifeu', 'Playa muy concurrida y con un ambiente familiar equipada con los servicios e infraestructuras suficientes para que la playa resulte muy agradable. ', 17092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1030, 'Canyelles', 'Playa ubicada junto a la urbanización que le da nombre, carente de infraestructuras y frecuentada por la gente de la zona.', 17092);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1043, 'Cala de Crit', 'Preciosa cala aislada, con difícil acceso, muy recomendable para la práctica del submarinismo', 17110);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1044, 'El Golfet', 'Playa rústica, con acceso a través de unas escaleras, que dispone de unas aguas cristalinas donde practicar el buceo.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1045, 'Els Canyers', 'Playa urbana carente de servicios, rodeada de rocas y casas de pueblo con poco interés turístico', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1046, 'Port Pelegrí', 'Playa donde antiguamente faenaban los pescadores de la zona, ubicada en el casco antiguo de Palafrugell.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1047, 'En Calau', 'Playa urbana situada en el núcleo de Calella de Palafrugell, muy frecuentada por gente de la zona y con mucho ambiente en el paseo marítimo.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1048, 'Port Bo', 'Playa urbana utilizada por los pescadores de la zona para amarrar sus pequeñas embarcaciones', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1049, 'Malaspina', 'Playa situada en el casco urbano de Calella de Palafrugell, rodeada de casas de pueblo a pie de playa.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1050, 'Canadell', 'Es una de las playas ubicadas en el núcleo urbano de Calella de Palafrugell, muy frecuentadas por los habitantes de la zona.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1051, 'Llafranc', 'Playa urbana totalmente equipada, que presenta un alto grado de ocupación y muy recomendable para vacaciones familiares.', 17117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1767, 'Barreiros', 'Barreiros y Loureiro son dos playas contiguas de medio tamaño con características muy similares.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1768, 'Espiñeirido', 'Playa de rocas con bajo grado de ocupación.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1769, 'O Coido', 'Está compuesta de rocas y arena, situada en la zona urbana de Muxia.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1770, 'A Cruz', 'Praia da Cruz está situada al norte del núcleo de Muxia, frecuentada por gente de la zona', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1771, 'Lourido', 'Playa situada en Punta Lourido, de donde toma su nombre, muy cerca del municipio de Muxia.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1772, 'Arnela', 'Playa ventosa que carece de servicios e infraestructuras.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1773, 'Moreira', 'Playa ventosa y con fuerte oleaje, carente de equipamiento para el uso público, situada al lado de Punta Moreira', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1774, 'Nemiña', 'Es la última playa del término de Muxia, a los pies de un monte del mismo nombre, junto a una piscifactoría.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1760, 'O Ariño', 'Carece totalmente de servicios e infraestructuras.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1761, 'Barreira', 'La playa dispone de servicio de limpieza. Cuenta con un camping cercano.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1762, 'O Lago', 'Playa de tamaño medio frecuentada por residentes de la zona.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1763, 'As Raias', 'Esta playa presenta un difícil acceso y se encuentra aislada de núcleos urbanos.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1764, 'O Coto', 'Playa aislada con buen estado de conservación del entorno pero con acceso algo dificultoso.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1765, 'Os Muiños', 'Arena blanca, aguas tranquilas y mucho viento.', 15052);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201501, 'Lopesa', 'La playa Lopesa desaparece en pleamar.', 15054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201502, 'A Hortiña', 'La playa A Hortiña desaparece en pleamar.', 15054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201503, 'Castelo', 'La playa Castelo desaparece en pleamar.', 15054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201504, 'O Casal', 'La playa O Casal desaparece en pleamar.', 15054);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1779, 'Cabalo', 'Esta playa es muy frecuentada por el turismo de la zona, junto con la playa de Boa, más al sur, colindante con el Concello de Porto do Son.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1780, 'Boa', 'Esta playa, junto con la playa de Cabalo, son las más visitadas por el turismo de la zona.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1775, 'Barquiña', 'Esta playa se encuentra en malas condiciones ambientales, tanto el agua como el entorno que la rodea.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1776, 'Abruiñeiras', 'Las playas de esta zona costera se encuentran en condiciones algo deficientes desde el punto de vista medioambiental.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1777, 'Testal', 'Esta playa es una de las más concurridas de la zona, con más de un kilómetro de longitud.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1778, 'Debesa', 'Playa con carácter semiurbano que presenta una arena blanca y aguas tranquilas para el baño.', 15057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1781, 'Canabal', 'Playa de poca longitud pero con un arenal que alcanza gran anchura, situada en la ensenada de Canaval. Se caracteriza por sus aguas tranquilas', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1782, 'Espiñeiro', 'Playa con alto grado de ocupación que dispone de los servicios más elementales para el uso del público.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1783, 'Mera', 'Es la playa del núcleo urbano de Mera, muy visitada por residentes de la zona.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1784, 'Santa Ana', 'Playa ubicada junto al núcleo de Mera y al puerto del mismo nombre.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1785, 'Portelo', 'Esta playa de acceso dificultoso no dispone de ningún servicio playero.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1786, 'Canide', 'Aislada playa compuesta de rocas y arena que presenta un bajo grado de ocupación.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1787, 'Camposa', 'Playa sometida a fuertes variaciones debido a la marea.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1788, 'Atalaya', 'Playa semiurbana de fácil acceso pero que registra un grado de ocupación medio.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1789, 'Naval', 'Apenas treinta metros de arena y grava ubicados en Punta do Corbo, frente al castillo de Santa Cruz.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1790, 'Santa Cruz', 'Playa de grava y arena que dispone de los servicios propios de una playa urbana.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1791, 'Bastiagueiriño', 'Carece de servicios e instalaciones al encontrarse aislada y con acceso dificultoso', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1792, 'Bastiagueiro', 'Excelente playa con una franja ancha de arena dorada de buena calidad que presenta muy poco desnivel.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1793, 'Santa Cristina', 'Playa de gran extensión ubicada en la ría do Burgo que le confiere una forma muy característica.', 15058);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1794, 'O Picón', 'Playa con gran desnivel y acceso a través de unas escaleras construidas por el Ministerio de Agricultura, Alimentación y  Medio Ambiente.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1795, 'Bimbiero', 'En esta playa desemboca un pequeño riachuelo que hace variar su conformación.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1796, 'Eiron', 'Playa separada de las playas de Bimbieiro y San Antonio por dos salientes rocosos. El acceso se realiza a pie por ambas playas.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1797, 'San Antonio de Espasante', 'Esta playa dispone de un acceso peatonal y un mirador construidos por el Ministerio de Agricultura, Alimentación y Medio Ambiente.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1798, 'Orbeiro', 'Desde la misma playa se accede, mediante unas escaleras, a unas termas romanas existentes en las inmediaciones.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1799, 'A Concha', 'Playa situada en el casco urbano de Espasante, con el puerto en la misma playa.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1800, 'Ladrido', 'Esta playa presenta escasez de arena y prácticamente solo la utilizan los vecinos del lugar.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1801, 'Morouzos', 'Playa en la que normalmente solo se utiliza el tercio central y que dispone de una gran extensión dunar con un pinar dotado con un área recreativa.', 15061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1802, 'Siavo', 'Playa de tamaño medio formada por arena y rocas que presenta un bajo grado de ocupación.', 15062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1803, 'Broña', 'Situada en Punta Broña, de donde toma su nombre, con acondicionamientos de reciente construcción.', 15062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1804, 'Picouto', 'Playa de unos cien metros de longitud, aislada y con ausencia de servicios.', 15062);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201533, 'San Antonio', 'Playa de aguas tranquilas', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1549, 'Corna', 'Playa rodeada de un amplio campo dunar en el que crece vegetación propia de los ecosistemas costeros. Aguas limpias y tranquilas, con ausencia de fuertes vientos.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1550, 'A Illa', 'Presenta aguas limpias y tranquilas en ausencia de vientos.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1551, 'Lombiña', 'Playa con elevado nivel de ocupación en época estival debido a los buenos servicios que oferta, calidad excelente de sus aguas y arenas blancas y finas.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1552, 'Cabío', 'Playa lindando con Playa Lombiña, por lo que los servicios son comunes a ambas, con aguas limpias y tranquilas y un grado de ocupación alto en época estival.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1553, 'Agronovo', 'Playa aislada con aguas limpias y tranquilas, de baja ocupación comparado con Lombiña y Cabío', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1554, 'Niñeiriños', 'Su grado de ocupación se ha visto incrementado notablemente al igual que otras playas vecinas como la de Agronovo.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1555, 'Arenal', 'Playa extensa situada en el casco urbano de A Pobla do Caramiñal que ofrece buenas condiciones para la práctica de deportes náuticos.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1556, 'San Lázaro', 'Playa con escaso nivel de ocupación, aguas tranquilas aunque no muy limpias debido a los vertidos de la industria conservera próxima.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1557, 'Raposiños', 'Al igual que la playa vecina de San Lázaro, es de aguas tranquilas pero no se encuentran muy limpias debido a los vertidos de la industria conservera próxima.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1558, 'La Merced', 'Playa con bajo nivel de ocupación por la dificultad para el aparcamiento de vehículos y la ausencia de servicios, en contraste con la buena calidad de sus aguas y de la conservación de su arenal.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1559, 'Riveiriña', 'Esta playa presenta un grado de ocupación medio ya qye es utilizada sobre todo por los habitantes del lugar, cuyas casas se encuentran próximas a la playa.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1560, 'Toxal', 'Playa de carácter semiurbano con bajo grado de ocupación.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1561, 'La Poza', 'Cien metros de playa de arena que presenta un bajo grado de ocupación.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1562, 'Campo', 'La construcción del reciente paseo marítimo, así como las actuaciones promovidas por el Ministerio de Medio Ambiente y Demarcación de Costas del Estado para la recuperación del borde litoral en esta playa, hacen de la misma una zona de gran valor paisajístico de la ría', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1563, 'Conchido', 'Playa de aguas tranquilas que limita con el Concello de Boiro.', 15067);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201514, 'Niñóns', 'Playa aislada con oleaje moderado', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201515, 'Barda Pequeña', 'Pequeña cala de acceso muy difícil y muy próxima a «A Barda».', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201516, 'Niño do Corvo', 'Pequeña cala de difícil acceso. Casi inexistente en pleamar.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1805, 'O Morro', 'Pequeña playa compuesta de rocas y arena, sometida al fuerte oleaje de la zona.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1806, 'Santa Mariña de Brantuas', 'Muy próxima a Rampa-Varadeiro de Santa Mariña de Brantuas, pero con difícil acceso.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1807, 'A Barda', 'Ubicada en una ensenada donde fondean pequeñas embarcaciones de pesca.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1808, 'Arnela', 'Playa urbana de fácil acceso pero carente de servicios disponibles.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1809, 'Osmo', 'Esta playa incluye la praia da Furna que se integra en praia Osmo.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1810, 'Ermida', 'Playa de mediano tamaño, aislada de núcleos urbanos, pero muy visitada por gente de la zona.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1811, 'Balarés', 'Esta playa comprende dos playas: Balarés Grande y Balarés Pequeña.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1812, 'Barra do Medio', 'Rústica playa en la desembocadura del Río Anllóns que adopta una superficie muy característica.', 15068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1813, 'Centroña', 'Cala aislada y pequeña playa muy cercana al ferrocarril que cruza la ría de Ares.', 15069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1814, 'Paredes', 'Playa aislada, de difícil acceso y carente de servicios e instalaciones.', 15069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1815, 'Ber', 'Muy frecuentada por gente de la zona por la buena calidad de conservación y servicios que ofrece.', 15069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201518, 'Insua', 'Pequeña playa de aguas tranquilas.', 15069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201519, 'Andahio', 'Playa muy visitada por el turismo de la zona', 15069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1838, 'A Torre', 'Playa con buen entorno, aguas tranquilas y bastante frecuentada por gente de la zona. Regenerada en 2008', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1839, 'Pazo', 'Industrias conserveras y astilleros en sus inmediaciones. Regenerada en 2008.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1840, 'Quenxo', 'Anexa a la playa de Tanxil.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1841, 'Tanxil', 'Playa con elevado grado de ocupación debido al buen equipamiento que presenta. Regenerada en 2008.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1842, 'Tronco', 'Pequeña playa de cien metros de longitud, arena blanca, aguas tranquilas y carente de servicios.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1843, 'Pereira Torta', 'Playa de setenta metros de longitud situada en una zona semiurbana, con bajo grado de ocupación.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1844, 'Porrón', 'Playa con buen estado de conservación de su entorno natural.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1845, 'As Cunchas', 'Esta playa ofrece la posibilidad de la práctica de deportes náuticos y está bien equipada.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1846, 'Aceveira', 'Se presenta con un bajo grado de ocupación y una buena conservación natural.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1847, 'Tres Cruces', 'Es una playa virgen sin ningún tipo de contaminación debido al bajo índice de ocupación y ausencia de viviendas o industrias que deterioren su entorno, resultando atractiva paisajísticamente y estando la vegetación integrada en su arenal.', 15072);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1856, 'Lagoa de Vixan', 'Playa integrada en el Parque Natural del Complejo Dunar de Corrubedo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1857, 'Area Basta', 'Forma parte de un conjunto de playas: Area Basta, O Couso, Penisqueira, Celeirans y Rego das Cargas, de reducido tamaño y aisladas al sur de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1858, 'Couso', 'Forma parte de un conjunto de playas: Area Basta, O Couso, Penisqueira, Celeirans y Rego das Cargas, de reducido tamaño y aisladas al sur de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1859, 'Penisqueira', 'Forma parte de un conjunto de playas: Area Basta, O Couso, Penisqueira, Celeirans y Rego das Cargas, de reducido tamaño y aisladas al sur de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1860, 'Celeiráns', 'Forma parte de un conjunto de playas: Area Basta, O Couso, Penisqueira, Celeirans y Rego das Cargas, de reducido tamaño, aisladas y con nulo interés turístico al sur de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1861, 'Rego das Cargas', 'Forma parte de un conjunto de playas: Area Basta, O Couso, Penisqueira, Celeirans y Rego das Cargas, de reducido tamaño y aisladas al sur de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1862, 'Tasca', 'Tasca y O Castro son dos grandes playas urbanas separadas por un espigón de gran longitud.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1863, 'O Castro', 'Tasca y O Castro son dos grandes playas urbanas separadas por un espigón de gran longitud.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1864, 'Castiñeiras', 'Playa urbana frecuentada por residentes de la zona.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1865, 'Mosqueiros', 'Trescientos metros de playa de arena con los servicios propios de una playa urbana.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1866, 'A Ameixida', 'Dispone de las instalaciones propias de una playa urbana.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1867, 'Área Secada', 'Playa algo separada del núcleo urbano pero en una zona donde aún existen construcciones.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1848, 'Espiñeirido', 'Playa que se encuentra en el límite de los términos municipales de Porto do Son y Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1849, 'Valieiros', 'Playa formada por Playa Portiñas, Playa As Barreiras y Playa de Balieiros.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1850, 'El Prado', 'En esta playa la zona urbana se presenta a pie de playa. Situada al lado del Puerto de Corrubedo', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1851, 'Ribeira Grande', 'Ribeira Grande y Ribeiriña son dos playas urbanas de muy pequeño tamaño al abrigo del espigón del puerto de Corrubedo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1852, 'Ribeiriña', 'Ribeira Grande y Ribeiriña son dos playas urbanas de muy pequeño tamaño al abrigo del espigón del puerto de Corrubedo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1853, 'As Furnas', 'Playa urbana con bajo grado de ocupación.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1854, 'A Ladeira', 'Playa integrada en el Parque Natural del Complejo Dunar de Corrubedo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1855, 'Vilar', 'Playa integrada en el Parque Natural del Complejo Dunar de Corrubedo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1868, 'Touro', 'Pequeña playa urbana que carece de instalaciones y servicios.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1869, 'Gavoteira de Fontan', 'Playa urbana de trescientos metros de longitud que no dispone de servicios.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1870, 'Carolinas', 'Esta playa está ubicada a la izquierda del mismo puerto de Ribeira.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1871, 'Coroso', 'Playa de gran extensión totalmente equipada y que acoge a una gran cantidad de visitantes, siendo la playa más cercano al núcleo urbano de Ribeira', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1872, 'Río Azor', 'Esta playa semiurbana dispone de ciertos servicios como duchas, papeleras y kioscos durante la temporada estival.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1873, 'Insuela', 'Playa de grava algo incómoda para el baño.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1874, 'A Cambra', 'Carece de servicios disponibles, aunque está ubicada en una zona urbana.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1875, 'O Baluarte', 'Apenas diez metros de playa urbana que dispone de duchas y otros servicios elementales.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1876, 'Cruces', 'Playa de doscientos metros de longitud visitada por pequeños barcos de fondeo.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1877, 'A Corna', 'Bien equipada y con alto grado de ocupación.', 15073);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1878, 'Sada', 'Esta playa urbana ha sido ampliada de forma artificial, acondicionando un paseo marítimo con formas geométricas.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1879, 'Morazón', 'Situada detrás del puerto de Sada, en Punta de Fontán.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1880, 'Lobos', 'Pequeña playa compuesta de rocas y escasa arena, sobre todo en pleamar.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1881, 'Arnela', 'Esta playa se sitúa entre Lobos y Armenteiro, de características muy similares, aisladas, con rocas y escasez de arena.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1882, 'Armenteiro', 'Ubicada junto a la playa de Arnela, con idénticas características, escasez de arena, aisladas y carentes de servicios.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1883, 'Lourido', 'Pequeña playa de difícil acceso en la falda de una ladera con densa vegetación, en Punta Lourido.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1884, 'San Pedro', 'Semiurbana, junto al núcleo urbano del mismo nombre, con instalaciones y servicios disponibles.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1885, 'Cirro', 'Se trata de dos pequeñas playas separadas por un conjunto de rocas, con idénticas características.', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201534, 'Sada, A Nova', 'Playa nueva de Sada', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201535, 'Arnela A Vella', 'Playa/cala de difícil acceso', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201536, 'As Fontiñas', 'Cala de difícil acceso. Bajada por sendero estrecho con cuerdas', 15075);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1636, 'Figueiras', 'Playa con dos accesos peatonales que presenta un alto grado de ocupación.', 15901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1637, 'A Postiña', 'A esta playa se accede desde la playa de Fornos cuando hay marea baja y desde la de Figueiras cuando hay media marea.', 15901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1638, 'Fornos', 'La playa de Fornos, por la calidad de sus aguas, arena y entorno, posiblemente sea una de las mejores playas de Galicia.', 15901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1639, 'A Concha', 'Esta playa está dividida en dos partes por un espigón. La zona sur, conocida como A Basteira, está situada fuera del casco urbano y de la zona portuaria, tiene una considerable zona dunar y es más óptima para el baño.', 15901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1640, 'Cala de O Peiral', 'Esta cala, casi desconocida para los forasteros, es muy utilizada por los vecinos del pueblo de Cariño y es idónea para la zambullida desde los acantilados y la práctica del submarinismo.', 15901);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1611, 'A Orixeira', 'Playa sometida a mucha variación en su anchura debido a la marea.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1612, 'Navaliños', 'Ubicada en una zona donde fondean pequeñas embarcaciones de pesca.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1613, 'Area das Vacas', 'Presenta un acceso dificultoso debido al mal estado del camino, presentando un bajo grado de ocupación.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1614, 'Rebordelo', 'Aislada pero bastante frecuentada por visitantes de la zona.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1615, 'San Pedro', 'Playa de difícil acceso, aislada y poco visitada por el turismo.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201511, 'As Maseiras', 'Playa de difícil acceso, aislada y poco visitada por el turismo.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201512, 'O Curro', 'Playa de difícil acceso, aislada y poco visitada por el turismo.', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201513, 'O Lodeiro', 'Pequeña playa urbana', 15014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1538, 'Oza', 'La Playa de Lazareto está situada al sur del gran puerto de A Coruña, en uno de los extremos.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1539, 'San Amaro', 'Muy cercana a Punta Herminia se ubica esta playa que registra un elevado grado de ocupación', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1540, 'As Lapas', 'Playa de arena de reducidas dimensiones que se encuentra en buen estado de conservación.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1541, 'Las Amorosas', 'Esta playa ubicada al pie de la Torre de Hércules está formada exclusivamente por rocas, con ausencia total de arena.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1542, 'Matadero', 'La playa de Matadero se encuentra situada junto a la playa de Orzán, en pleno casco urbano de A Coruña', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1543, 'Orzán', 'El conjunto se playas Orzán-Riazor, junto con la de Matadero en uno de sus extremos, son las playas de A Coruña por excelencia.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1544, 'Riazor', 'Orzán-Riazor son las playas urbanas de A Coruña. Están  totalmente equipadas y tienen un elevado grado de ocupación.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1545, 'Lino', 'Se trata de una pequeña cala a pie de paseo muy incómoda para el baño, de arena muy gruesa, mar fuerte y muy peligrosa.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1546, 'La Cetárea', 'Se trata de una pequeña cala situada al lado de una cetárea de donde toma su nombre, y que carece de todo servicio.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1547, 'La Cetárea', 'Playa encajada en el puerto de Visma, donde el baño resulta peligroso', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1548, 'Bens', 'Arenal de escasa ocupación debido a la contaminación de sus aguas.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201523, 'La Cala', 'Pequeña playa de arena blanca y alta afluencia', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201524, 'Los Moros', 'Pequeña playa de arena blanca', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201525, 'Bolera de Punta Herminia', 'Playa aislada de baja afluencia', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201526, 'San Roque', 'Pequeña playa con gran afluencia de bañistas.', 15030);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1707, 'Salseira de Caracoleiro', 'Playa muy concurrida prácticamente dentro del pueblo de Caión, muy tranquila para el baño y con unas aguas muy limpias.', 15041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1734, 'Ancoradoiro', 'Situada en Punta de Lens, en el enclave conocido como Porto de Ancoradoiro.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1735, 'Area Maior', 'Playa virgen de arena blanca a los pies de Monte Louro.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1736, 'Fogareiro', 'La playa de Fogareiro es de carácter semiurbano con bajo grado de ocupación.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1737, 'Goday', 'Playa muy visitada por barcos de recreo que fondean en la zona.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1738, 'San Francisco', 'Playa urbana con un kilómetro de longitud de arena blanca y rocas, siendo una de las más concurridas de la zona.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1739, 'A Bouga', 'Esta es la continuación de la playa de San Francisco, hasta Punta da Bouga', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1740, 'La Prudencia', 'Playa de rocas, nada recomendable para el baño.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1741, 'Praia da Rocha', 'Playa que se encuentra en pleno casco urbano de la localidad de Muros.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1742, 'Ventin', 'Playa de carácter semiurbano que presenta un bajo grado de ocupación.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1743, 'Liñares', 'La playa de Liñares carece de acondicionamientos para el uso público.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1744, 'Bornalle', 'Semiurbana y poco frecuentada por el turismo.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1745, 'Aldosén', 'Compuesta de rocas y arena blanca, pero con un estado de conservación algo deficiente.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1746, 'Arruso', 'Aislada y muy poco frecuentada por visitantes.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1747, 'Salgueiro', 'Unas de las muchas playas aisladas de la ría de Muros y Noia.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1748, 'Cirqueiros', 'Se trata de un pequeño arenal compuesto de rocas y arena de poca importancia.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1749, 'Coido', 'Pequeña playa aislada con algo más de cincuenta metros de longitud de la ría de Muros y Noia.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1750, 'Area do Medio', 'Situada en la ría de Muros con poca importancia como playa turística.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1751, 'Porto Cabanas', 'Playa pequeña y aislada, sin importancia turística.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1752, 'Cabanas', 'Playa semiurbana pero carente de servicios.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1753, 'Raimundo', 'Playa de poco interés desde el punto de vista del turismo.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1754, 'Fontenla', 'Apenas cien metros de arena y rocas con bajo grado de ocupación', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1755, 'Somorto', 'Presenta bajo grado de ocupación y regular estado de conservación del entorno natural.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1756, 'Agracobo', 'Playa semiurbana que carece de servicios.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1757, 'Esteiro', 'Playa con una longitud de casi medio kilómetro con disponibilidad de duchas.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1758, 'Uhía', 'Pequeña playa urbana apenas visitada por bañistas.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1759, 'Parameán', 'Es la última playa del término municipal de Muros compuesta de arena blanca y grado medio de ocupación.', 15053);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201520, 'Abelleira', 'Pequeña playa aislada de arena dorada.', 15064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201521, 'Xurela', 'Pequeña playa aislada de aguas tranquilas.', 15064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1816, 'As Seiras', 'De arena dorada y gran extensión.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1817, 'Rio Sieira', 'Casi un kilómetro de playa aislada compuesta de rocas y arena.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1818, 'Xuño', 'Playa de un kilómetro de longitud pero con ausencia de infraestructuras y servicios.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1819, 'Areas Longas', 'Gran extensión de arena con carácter aislado y bajo grado de ocupación.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1820, 'Serans', 'Playa ventosa y fuerte oleaje aislada de núcleos y construcciones urbanas.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1821, 'Recaveira', 'Playa virgen y desierta entre los términos de Ribeira y Porto do Son.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1822, 'Rio Maior', 'Incluida en la Red Natura 2.000 y de carácter aislado.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1823, 'Telleira', 'Playa muy estrecha, con poca arena y algunas rocas, colindante con el Concello de Noia', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1824, 'Ornanda', 'Playa rústica con arena blanca, extensa y muy frecuentada por el turismo de la zona.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1825, 'Gafa', 'Esta playa se localiza junto al Club Náutico de Portosin, tiene un tamaño pequeño y acoge gran cantidad de bañistas.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1826, 'Coira', 'Extensa playa de arena que se extiende hasta el mismo puerto de Portosín', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1827, 'Pozo Pequeña', 'Esta playa de ciento cincuenta metros de longitud se encuentra aislada de núcleos urbanos y carente de servicios.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1828, 'Pozo', 'Playa semiurbana de rocas y arena con un grado de ocupación rmedio.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1829, 'Aguieira', 'Playa rústica de gran extensión con arena blanca de gran calidad y muy equipada.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1830, 'As Vellas do Pozo', 'Situada en Punta Aguieira como continuación de la playa de Aguieira.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1831, 'Cabeiro', 'Esta playa, totalmente equipada, toma su nombre del pequeño montículo junto al que se encuentra, así como del saliente rocoso Punta Cabeiro, donde se localiza el faro Cabeiro', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1832, 'Herbas Pitas', 'Playa bien equipada pero con baja afluencia, situada al lado de punta da Herbas Pitas', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1833, 'Suigrexas', 'Playa ventosa con baja afluencia de gente.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1834, 'O Son', 'Se encuentra situada en pleno casco urbano de Porto do Son y resulta muy visitada, aún siendo poco extensa.', 15071);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1835, 'Fonforrón', 'Aunque dispone de escasa arena, es muy visitada por gente de la zona.', 15071);
