INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2168, 'Onza Sur', 'Playa ubicada en una de las islas cuyo conjunto conforman el Parque Nacional marítimo-terrestre de las Islas Atlánticas.', 36004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2152, 'Beluso', 'Playa frecuentada por barcos de recreo que fondean por la zona. ', 36004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1617, 'Camelle', 'Playa urbana que disfruta de aguas tranquilas para el baño pero considerada como playa ventosa.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1618, 'Arou', 'Dispone de escasos servicios aunque se trata de una playa urbana con un grado de ocupación de tipo medio.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1619, 'Lobeiras', 'Lobeiras carece de servicios e infraestructuras por tratarse de una playa aislada y con bajo grado de ocupación.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1620, 'Santa Mariña', 'Pequeña playa de arena que presenta un oleaje moderado y algo de viento propio de esta zona.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1621, 'Trece', 'Más de un kilómetro de arena donde se intercalan rocas, caracterizada por el viento reinante de la zona y un fuerte oleaje.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1622, 'Reira', 'Conjunto de cuatro pequeñas playas vírgenes: Reira, Area Longa, Balea y Pedrosa, de características muy similares, situadas al norte de Cabo Vilán.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1623, 'Area Longa', 'Conjunto de cuatro pequeñas playas vírgenes: Reira, Area Longa, Balea y Pedrosa, de características muy similares, situadas al norte de Cabo Vilán.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1624, 'Balea', 'Conjunto de cuatro pequeñas playas vírgenes: Reira, Area Longa, Balea y Pedrosa, de características muy similares situadas al norte de Cabo Vilán.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1625, 'Pedrosa', 'Conjunto de cuatro pequeñas playas vírgenes: Reira, Area Longa, Balea y Pedrosa, de características muy similares situadas al norte de Cabo Vilán.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1626, 'Lago Norte', 'Es una de las playas situadas en la ría de Camariñas, de carácter aislado y bajo grado de ocupación. En sus inmediaciones se ubica una catárea.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1627, 'Area da Vila', 'Playa de tamaño medio con los servicios de playa más elementales.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1628, 'Lingunde', 'Playa semiurbana compuesta de bolos y arena blanca, con algunos servicios disponibles.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1629, 'Sandría', 'Playa rústica que dispone únicamente del servicio de limpieza de playas.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1630, 'Area Blanca', 'Playa rústica situada en la ría de Camariñas, que se encuentra totalmente rodeada de vegetación.', 15016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1631, 'Leira', 'Playa de un kilómetro de longitud, aislada y con bajo nivel de ocupación.', 15019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1632, 'Pedra do Sal', 'Playa de rocas y arena incluida en la Red Natura 2.000, como muchas playas de la zona.', 15019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1633, 'Baldaio', 'Extensa playa de arena ubicada dentro del entorno natural de Marismas de Baldaio.', 15019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1634, 'Razo', 'Playa de arena próxima al entorno natural de Marismas de Baldaio, que constituye la prolongación de la Praia de Baldaio.', 15019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1635, 'Santa Mariña', 'Esta playa de arena y rocas queda prácticamente cubierta con marea alta.', 15019);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1658, 'Simprón', 'Las playas de Simprón y Ardeleiro son dos playas vírgenes totalmente aisladas, desiertas y con poco atractivo para el turismo.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1659, 'Ardeleiro', 'Las playas de Simprón y Ardeleiro son dos playas vírgenes totalmente aisladas, desiertas y con poco atractivo para el turismo.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1660, 'Susiños', 'Las playas de Susiños, Sureseco y Porto dos Botes son tres playas de rocas y escasa arena poco recomendables para el baño.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1661, 'Sureseco', 'Las playas de Susiños, Sureseco y Porto dos Botes son tres playas de rocas y escasa arena poco recomendables para el baño.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1662, 'Porto dos Botes', 'Las playas de Susiños, Sureseco y Porto dos Botes son tres playas de rocas y escasa arena poco recomendables para el baño.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1663, 'Lariño', 'Extenso arenal que conforma una rústica playa al sur de Lariño.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1655, 'Porto Ancho', 'Mar de Lira, Portocubelo, Tras de Punta, Porto Ancho y Gabota son cinco playas contiguas de pequeño tamaño, rústicas, de arena y rocas y poco frecuentadas por visitantes.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1656, 'Gabota', 'Mar de Lira, Portocubelo, Tras de Punta, Porto Ancho y Gabota son cinco playas contiguas de pequeño tamaño, rústicas, de arena y rocas y poco frecuentadas por visitantes.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1657, 'Porto da Barca', 'Esta playa dispone de espigón y punto de atraque para pequeñas embarcaciones.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1641, 'San Pedro', 'Cerca del núcleo de O Pindo, con poca longitud pero gran anchura de banda de arena', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1642, 'Quilmas', 'Playa semiurbana dotada con duchas, pero con bajo grado de ocupación.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1643, 'Pedrullo', 'Tres playas contiguas de tipo rústico: Pedrullo Corna Becerra y Salomba, compuestas de rocas y arena poco frecuentadas por bañistas.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1644, 'Corna Becerra', 'Tres playas contiguas de tipo rústico: Pedrullo Corna Becerra y Salomba, compuestas de rocas y arena poco frecuentadas por bañistas.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1645, 'Salomba', 'Tres playas contiguas de tipo rústico: Pedrullo Corna Becerra y Salomba, compuestas de rocas y arena poco frecuentadas por bañistas.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1646, 'Area Blanca', 'Area Blanca y Porto Negros son dos playas vírgenes de características similares, de rocas y escasa arena con afluencia de visitantes prácticamente nula.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1647, 'Porto Negros', 'Area Blanca y Porto Negros son dos playas vírgenes de características similares, de rocas y escasa arena con afluencia de visitantes prácticamente nula.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1648, 'Insuela', 'Aislada playa de arena y rocas con poco interés para el turismo.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1649, 'Caldebarcos', 'Playa rústica en la desembocadura del río Valdebois junto a una zona húmeda protegida como espacio natural.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1650, 'Carnota', 'Playa rústica y protegida como espacio natural, de gran tamaño y arenas blancas', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1651, 'Cons', 'Playa pequeña y con poco interés turístico.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1652, 'Mar de Lira', 'Mar de Lira, Portocubelo, Tras de Punta, Porto Ancho y Gabota son cinco playas contiguas de pequeño tamaño, rústicas, de arena y rocas y poco frecuentadas por visitantes.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1653, 'Portocubelo', 'Mar de Lira, Portocubelo, Tras de Punta, Porto Ancho y Gabota son cinco playas contiguas de pequeño tamaño, rústicas, de arena y rocas y poco frecuentadas por visitantes.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1654, 'Tras de Punta', 'Mar de Lira, Portocubelo, Tras de Punta, Porto Ancho y Gabota son cinco playas contiguas de pequeño tamaño, rústicas, de arena y rocas y poco frecuentadas por visitantes.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201532, 'Malladoira', 'Pequeña y con poco interés turístico.', 15020);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1664, 'Sonreiras', 'Pequeña playa ubicada en las cercanías del puerto de Cedeira.', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1665, 'Area Longa', 'Playa con elevado grado de ocupación junto al puerto de Cedeira.', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1666, 'Playa de la Madalena', 'Playa urbana con un color de arena gris oscuro muy característico', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1667, 'Mi Señora', 'Pequeña cala situada en la Punta de la Robaleira.', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1668, 'Burbujas', 'Playa localizada en la Ensenada de Esteiro sometida a fuertes mareas por situarse en la desembocadura del río das Mestas.', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1669, 'Cerdeiras', 'Ubicada en la Ensenada de Esteiro, en la misma desembocadura del río das Mestas.', 15022);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1670, 'Estorde', 'Esta playa se encuentra situada entre los términos municipales de Fisterra y Corcubión, al sur del término de Cée.', 15023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1671, 'A Concha', 'Playa urbana en forma de concha rodeada de avenidas del mismo núcleo de Cée.', 15023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1672, 'Ameixenda', 'Playa urbana, de pequeño tamaño y sin equipamientos ni servicios disponibles.', 15023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1673, 'Caneliñas', 'Esta playa resulta poco frecuentada por bañistas, pero muy utilizada por pequeños barcos que fondean en la zona.', 15023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1674, 'Gures', 'La Praia de Gures presenta un acceso con cierta dificultad, de ahí su bajo grado de ocupación.', 15023);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1675, 'Quenxe', 'Quenxe es la playa urbana del núcleo de Corcubión, la única con la que cuenta este término municipal.', 15028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1676, 'Ezaro', 'Única playa de este término municipal en la ensenada de Ezaro, donde desemboca el río Jallas.', 15034);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201529, 'O Coido', 'El lecho de la playa alterna arena y conchas.', 15035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1677, 'Río Sandeu', 'Pertenece al término municipal de Fene, pero se encuentra muy cercana al núcleo urbano de Redes, término de Ares.', 15035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1678, 'Almieiras', 'Playa con carácter semiurbano, pero poco frecuentada por bañistas.', 15035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1679, 'Río Castro', 'Se trata de una pequeña playa situada en el mismo límite de los términos de Fene y Cabanas.', 15035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1680, 'Ponzos', 'Extensa playa de carácter aislado sometida a un fuerte oleaje y al viento reinante en la zona.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1681, 'Medote', 'Cala ventosa sometida a un fuerte oleaje que presenta un bajo grado de ocupación.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1682, 'Sartaña', 'Playa situada en una zona ventosa y sometida a un fuerte oleaje.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1683, 'As Fontes', 'Pequeña playa de difícil acceso que desaparece en pleamar.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1684, 'Santa Comba', 'Playa de mil quinientos metros de longitud de arena dorada y sometida a un fuerte oleaje y viento de la zona.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1685, 'O Porto', 'Praia do Porto está compuesta de bolos, rocas y arena y se encuentra rodeada de vegetación.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1686, 'Cabaliño', 'Pequeña playa con un grado de ocupación nulo.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1687, 'Vilar Grande', 'Playa que presenta un elevado grado de ocupación.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1688, 'Fragata', 'Playa frecuentada por el turismo de la zona que dispone de instalaciones e infraestructuras para el turismo.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1689, 'Esmelle', 'Esta playa comparte lecho con la playa de San Jorge, separándose por el arroyo de O Xuncal.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1690, 'San Xurxo', 'Esta playa comparte lecho de playa con Esmelle, de la que se separa por el arroyo de O Xuncal.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1691, 'Lobadiz', 'Playa aislada con bajo grado de ocupación compuesta de rocas y arena.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1692, 'Doniños', 'Playa con una extensión de unos dos kilómetros de longitud que acoge a gran cantidad de visitantes.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1693, 'Lumebo', 'Esta playa presenta un difícil acceso, sobre todo en uno de sus extremos.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1694, 'Cariño', 'Tranquila playa de carácter semiurbano compuesta de arena y rocas.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1695, 'San Cristobal', 'Aislada playa carente de servicios e instalaciones.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1696, 'Detrás do Castillo', 'Pequeña playa situada entre la playa de Cariño y el puerto de la Graña.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1697, 'San Felipe', 'Playa semiurbana con aguas tranquilas y un estado de conservación del entorno natural algo deficiente.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1698, 'A Graña', 'Playa regenerada con arena ubicada en el mismo puerto del Ferrol.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1699, 'Os Olmos', 'Playa situada en la ría de Ferrol poco aconsejable para el baño debido a las deficientes condiciones del agua y del entorno.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1700, 'Caranza', 'Playa artificial bien equipada muy frecuentada por el turismo de la zona.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201505, 'O Vilar', 'Pequeña playa con fuerte oleaje', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201507, 'Canteira Marracoi', 'Pequeña playa situada entre la playa de Cariño y el puerto de la Graña.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201508, 'A Caseta', 'Pequeña playa situada entre la playa de Cariño y el puerto de la Graña.', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201506, 'Pena Roiba', 'Pequeña playa con fuerte oleaje', 15036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201531, 'Talón', 'Playa abrigada de los vientos del norte', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1701, 'O Rostro', 'Playa muy extensa con fuerte oleaje, carente de servicios y poco frecuentada por el turismo.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1702, 'Arnela', 'Playa bastante protegida por el accidente rocoso que constituye Punta de Arnela, de donde toma su nombre.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1703, 'Mar de Fora', 'Playa de arena aislada de núcleos urbanos con una longitud que alcanza los 700 metros.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1704, 'Langosteira', 'Playa semiurbana que goza de aguas tranquilas para el baño y una gran extensión de arena.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1705, 'Sardiñeiro', 'Aunque se trata de una playa urbana, carece de servicios y presenta un bajo grado de ocupación.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1706, 'Restrelo', 'Pequeña playa de arena blanca frecuentada por residentes de fincas particulares en la zona.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (201530, 'A Ribeira', 'Pequeña playa urbana.', 15037);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1708, 'Laxe', 'Playa de gran belleza de arenas blancas y finas con una longitud de kilómetro y medio, y equipamientos propios de una playa urbana.', 15040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1709, 'Soesto', 'Esta playa de gran belleza presenta un bajo grado de ocupación, aunque es frecuente que se realicen campeonatos de surf', 15040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1710, 'Arnado', 'Pequeña playa de arena de carácter aislado y con baja afluencia de visitantes.', 15040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1711, 'Traba', 'Rústica playa localizada en la desembocadura de varios arroyos, formándose una pequeña laguna y un gran arenal.', 15040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1712, 'As Torradas', 'Esta playa en marea baja constituye una misma playa con la de Riás.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1713, 'Riás II', 'Playa de muy difícil acceso que prácticamente desaparece con la marea alta.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1714, 'Riás III', 'Playa con bajo grado de ocupación que carece de instalaciones y servicios.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1715, 'San Miro', 'Playa pequeña y aislada compuesta de rocas y arena con bajo grado de ocupación, situada en la parroquia de San Miro', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1716, 'Reixa Grande', 'Esta playa aislada resulta prácticamente inaccesible por tierra por lo que presenta un grado de ocupación nulo.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1717, 'Reixa Chica', 'Esta playa, como su vecina Reixa Grande, resulta prácticamente inaccesible por tierra por lo que presenta un grado de ocupación nulo.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1718, 'Maior de Malpica', 'Es la playa de Malpica por excelencia, en pleno casco urbano y bien equipada.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1719, 'Canido', 'Playa situada a continuación de praia Maior de Malpica, con la que forma una única playa.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1720, 'Seaia', 'Playa rodeada de dunas, de carácter aislado y oleaje moderado, situada al lado de Punta do Boi.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1721, 'Beo', 'Playa compuesta de arena y rocas, aislada y con bajo grado de ocupación.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1722, 'Seiruga ', 'Playa carente de servicios compuesta de arena y rocas.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1723, 'Barizo', 'Playa sin equipamientos muy próxima al puerto del mismo nombre, porto de Barizo, limitando ya con el Concello de Ponteceso.', 15043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1724, 'Vilela', 'Rústica playa situada muy cerca de la Punta de la Estaca de Bares,en una bonita zona del norte de A Coruña, cerca ya de la provincia de Lugo.', 15044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1725, 'Bares', 'Esta playa queda dividida en dos partes con la marea alta, una parte en la zona urbana y portuaria y la otra conocida como Iglesia Vella, con una extensa zona dunar y dividida a su vez por un saliente elevado y rocoso.', 15044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1726, 'Esteiro', 'Playa con fuerte oleaje en una zona y otra con aguas tranquilas en la desembocadura del río Esteiro, idónea para el baño de niños.', 15044);
