INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103604, 'Das Moscas', 'La playa Das Moscas situada en Cangas es una playa de arena. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103605, 'Do Medio', 'Playa situada entre Congorza y Areamilla', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103606, 'Massó', 'Playa situada en las inmediaciones de la antigua fabrica de Massó', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103607, 'Do Salgueirón', 'La playa Do Salgueirón situada en Cangas es una playa de arena. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103608, 'Xan da Garda', 'Playa situada entre las playas de Alemans y Canabal', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1963, 'Couso', 'Playa de rocas en Punta de Couso, Espacio Natural protegido. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1964, 'Melide', 'Bonito enclave virgen localizado entre Cabo Home y Cabo Pequeño, Espacio Natural protegido.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1965, 'Barra', 'Playa formada por un excelente arenal blanco muy apropiado para pasear.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1966, 'Viñó', 'Rústica playa de la ría de Vigo protegida como Espacio Natural. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1967, 'Nerga', 'Playa aislada de tipo rústico con similares características a las colindantes, todas protegidas como Espacio Natural. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1968, 'Os Castros', 'Os Castros y Temperáns, dos playas unidas de unos doscientos metros cada una en Punta Corbeiro, cerca de Playa Limens.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1969, 'Temperáns', 'Temperáns y Os Castros, dos playas unidas de unos doscientos metros cada una en Punta Corbeiro, cerca de Playa Limens.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1970, 'Liméns', 'Playa de carácter semiurbano que recibe gran cantidad de visitantes.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1971, 'Santa Marta', 'Unida a playa Limens y con sus mismas características. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1972, 'O Porto', 'Playa semiurbana junto a Playa Limens. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1973, 'Areamilla', 'Playa rústica protegida como Espacio Natural. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1974, 'A Congorza', 'Generalmente esta playa no es utilizada por bañistas. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1975, 'Rodeira', 'Es la playa de Cangas por excelencia, en el mismo núcleo urbano, muy cerca del puerto y bien equipada.', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1976, 'Os Alemáns', 'Rústica playa situada en Punta Rodeira, frente a Islas Ratas. ', 36008);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2230, 'Panxón', 'Bien equipada y con elevado grado de ocupación. ', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2231, 'América', 'Playa cosmopolita que ocupa gran parte de la ría de Baiona. ', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2225, 'Patos', 'Ubicada en la Ensenada de Carreira, con 1.700 metros de longitud y muy bien equipada.', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2226, 'Portocelo', 'Portocelo, Ribas Blancas y Area Fofa, tres pequeñas playas compuestas de rocas y arena al norte de la ría de Baiona.', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2227, 'Arribas Blancas', 'Portocelo, Ribas Blancas y Area Fofa, tres pequeñas playas compuestas de rocas y arena al norte de la ría de Baiona. ', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2228, 'Area Fofa', 'Portocelo, Ribas Blancas y Area Fofa, tres pequeñas playas compuestas de rocas y arena al norte de la ría de Baiona. ', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2229, 'Madorra', 'Playa de tamaño intermedio situada en una zona urbana de la ría de Baiona. ', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103668, 'La Calita', 'Playa con mucha roca y de difícil acceso al norte de la playa de Patos', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103669, 'Xeixos Negros', 'Portocel, Ribas Blancas, Xeixos Negros y Area Fofa, son cuatro pequeñas playas compuestas de rocas y arena al norte de la ría de Baiona', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103670, 'Do Cabalo', 'Pequeña playa con mucha roca en monte Lourido', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (103671, 'Castaño ', 'Pequeña playa con mucha roca en monte Lourido', 36035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2110, 'Nanín', 'Playa compuesta por arena blanca localizada en uno de los extremos de Playa Areas.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2111, 'Areas', 'Playa muy bien equipada con alto grado de ocupación. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2112, 'Dos Mortos', 'Pequeña playa separada de Playa Areas por un saliente rocoso. Reciente construcción de senda peatonal', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2090, 'Lapa', 'Playa rústica situada al final de la Lanzada, frecuentada por residentes de construcciones cercanas.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2091, 'Areagorda', 'Rústica playa separada de su vecina, de características similares, por un saliente rocoso denominado Punta Lapa. Ocupación media', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2092, 'Nosa Señora', 'Pequeña playa de carácter semiurbano que presenta un grado de ocupación medio-bajo.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2093, 'Foxos', 'Bonita playa de arena blanca de gran calidad muy visitada por gente de la zona.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2094, 'Fontenla', 'Playa de apenas cien metros de longitud cercana a la playa de Foxos. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2095, 'Pociñas', 'Playa virgen ubicada al pie de acantilados de poca altura. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2096, 'Major', 'Extenso arenal blanco muy agradable para realizar largos paseos. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2100, 'Paxariñas', 'Playa muy frecuentada, ubicada al pie de un acantilado y a la que se accede a través de unas escaleras.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2101, 'Canelas', 'Excelente playa totalmente equipada muy cercana al núcleo de Portonovo.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2102, 'Caneliñas', 'Pequeña playa urbana situada en la misma localidad de Portonovo. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2107, 'Lavapanos', 'Rústica playa de pequeño tamaño rodeada de viviendas unifamiliares. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2108, 'Carabuxeira', 'Playa degradada por la construcción del Puerto Deportivo de Sanxenxo', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2109, 'Barreiros', 'Playa de difícil acceso debido a su restricción por parte de la propiedad privada.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2113, 'Agra', 'Situada en un entorno de gran belleza muy típico de esta zona gallega, con pequeños acantilados y vegetación, donde acuden barcos de recreo que fondean por la zona.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2114, 'Pampaído', 'Pequeña playa ubicada al pie de una ladera totalmente cubierta de eucaliptus, conocido como costado Dos Bois. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2115, 'Santa Mariña', 'Representa la última playa del término de Sanxenxo, límite con el de Poio. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2097, 'Pragueira', 'Constituye el final de la Praia Major, donde se intercala la arena blanca con los fondos rocosos. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2098, 'Bascuas', 'Playa ubicada en un bonito entorno de pequeños acantilados cubiertos de vegetación.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2099, 'Montalvo', 'Una de las playas de la zona más conocidas y frecuentadas por el turismo playero, con gran cantidad de servicios disponibles. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2103, 'Portonovo', 'Típica playa urbana al abrigo de un espigón que acoge barcos de fondeo. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2104, 'Silgar', 'Totalmente equipada, es la playa más cosmopolita de Sanxenxo. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2105, 'Os Barcos', 'Playa urbana junto al espigón que alberga el Club Náutico del puerto deportivo de Sanxenxo. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2106, 'Panadeira', 'Pequeña playa situada frente al puerto deportivo de Sanxenxo. ', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203601, 'Espiñeiro', 'Playa rústica frecuentada por residentes de las construcciones cercanas.', 36051);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1993, 'Illa Cortegada', 'Se trata de una pequeña isla declarada Espacio Natural, donde sólo puede accederse en barco. La longitud se refiere al contorno total de zona de las playas (Balouredo, Sartaxes,Muelle-Aldea y Batel).', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1987, 'Carril', 'Pequeña playa situada a las afueras de Vilagarcía de Arousa, aunque no es la más frecuentada. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1988, 'Compostela', 'La Playa de Compostela y A Concha son las playas de Vilagarcía por excelencia. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1989, 'A Concha', 'La Playa de A Concha se presenta como una continuación de la Playa de Compostela, una de las más frecuentadas de Vilagarcía.', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1990, 'Canelas', 'Playa de reducido tamaño que pasa casi desapercibida en una zona con gran movimiento marítimo. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1991, 'De Bouzas', 'Playa de arena con unas condiciones poco favorables para la afluencia del turismo, tanto por el entorno que la rodea como por su estado. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1992, 'Sartaxe', 'Pequeña playa situada al sur de Vilagarcía, poco recomendable para el baño. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1986, 'Bamio', 'Playa situada junto al núcleo urbano de Bamio, de donde toma su nombre. ', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (303601, 'Preguntoiro', 'Playa aislada de aguas tranquilas.', 36060);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1225, 'El Tarajal', 'Playa colindante con la aduana de su mismo nombre, que separa España de Marruecos.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1226, 'Tramaguera', 'Playa cercana a la frontera del Tarajal.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1227, 'Miramar', 'Está situada en la zona suroccidental de Ceuta.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1228, 'El Chorrillo', 'Se extiende dividida por escolleras en la vertiente meridional de la ciudad y linda con la zona monumental, con el foso y una de sus murallas. Cerca de la misma se pueden encontrar los célebres bonitos y volaores de Ceuta.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1229, 'La Ribera', 'Es la playa del centro de la ciudad y por lo tanto la más concurrida. En ella están el Foso y las Murallas Reales.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1230, 'Cala del Sarchal', 'Playa con impresionante acantilado y vistas espectaculares a la bahía sur de Ceuta y al país vecino Marruecos.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1231, 'El Desnarigado', 'Cala del contorno sur del monte Hacho. Bajo los taludes el monte que le abriga, puede apreciarse la transparencia de sus aguas. Arriba y en un borde se halla la fortaleza que da nombre a la playa, convertida en museo militar.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1232, 'San Amaro', 'Situada en la zona norte del monte Hacho, se recuesta en el exterior del muelle de Levante.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1233, 'Benítez (primer tramo)', 'Es la playa más concurrida de la bahía Norte y está adosada al muelle de Poniente.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1234, 'Calamocarro', 'Playa situada fuera del casco urbano de Ceuta. Está circunvalada por montes de pinos y disfruta de aguas muy azules, transparentes y frías. ', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1235, 'Punta Blanca', 'Situada fuera del casco urbano de Ceuta, la carretera del norte que bordea el monte cubierto de pinos conduce a esta playa que ofrece una panorámica que aglutina las costas de dos continentes.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1236, 'Benzú', 'Se halla junto a un poblado a cuyas espaldas verdes montañas jaspeadas finalizan abruptamente. Es la última playa por la bahía del norte, frontera con Marruecos. Desde ella en los despejados días de poniente se ve con claridad la Península.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205101, 'Benítez (segundo tramo)', 'Es la playa más concurrida de la bahía Norte y está adosada al muelle de Poniente.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205102, 'Playa Santa Catalina', 'Playa situada al inicio del Monte Hacho', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205103, 'Juan XIII', 'Playa situada junto a los tradicionales secaderos de bonito y volaores de Ceuta', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205104, 'Almadraba', 'Está situada en la zona de la Almadraba, junto a la Playa de Miramar.', 51001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205203, 'Alcazaba', 'Playa de nueva creación en la zona Norte de la ciudad, a mar abierto.', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1237, 'San Lorenzo', 'Pequeña playa contigua al espigón Sur del puerto deportivo, con buenos servicios y equipamientos.', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1238, 'Los Cárabos', 'Playa urbana, de arena dorada, que cuenta con buenos servicios. ', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1239, 'Hipódromo', 'Es la playa más larga de la ciudad de Melilla, con alto grado de ocupación y buenos servicios. ', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1240, 'La Hípica', 'Playa con alto grado de ocupación y que cuenta con buenos servicios. ', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205204, 'Horcas Coloradas', 'Playa de nueva creación en la zona Norte de la ciudad, a mar abierto.', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205201, 'Trápana', 'Playa bajo acantilado a mar abierto.', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (205202, 'Ensenada de los Galápagos', 'Playa bajo acantilados.', 52001);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1241, 'La Mina', 'Cerca del Faro de Punta Albir se localizan tres pequeñas calas aisladas, de gran belleza. La Mina, El Metje y la Cala del Amerador.', 3011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1242, 'Casa del Médico', 'Tres pequeñas calas aisladas cercanas al Faro de Punta Albir, El Metje, La Mina y El Amerador.', 3011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1243, 'Cala del Amerador', 'La Cala del Amerador, El Metje y La Mina son pequeñas calas aisladas en las proximidades del Faro de Punta Albir.', 3011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1244, 'El Albir', 'Esta playa de cantos rodados tiene todo tipo de servicios y concentra gran parte de la oferta de ocio de la localidad. ', 3011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1260, 'El Soyo', 'Esta pequeña cala de rocas y piedras negras no presenta gran afluencia de bañistas debido a la constante aparición de algas en sus tranquilas aguas, y a la falta de servicios de los que dispone.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1261, 'La Olla', 'La Playa de La Olla, aunque dispone de una estrecha franja de rocas y grava con ausencia de arena, aparece como una de las más concurridas de Altea, desde donde puede observarse la pequeña islita que recibe el mismo nombre.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1262, 'Solsida', 'Altea acaba en la punta del Mascarat y la Sierra de Bernia, donde aparecen calas de gravilla como esta de La Solsida, las playas de Mascarat y la Cala de La Barra Grande.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1257, 'Cap Blanc', 'La Playa de Cap Blanc, al sur del pueblo de Altea, es la de mayor extensión de su término, fundiéndose con la Playa del Albir, en el término vecino, permitiendo disfrutar de grandes zonas de baño de dorada arena alternándose con cantos y grava.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1258, 'La Roda', 'La Playa de La Roda, ubicada junto al casco urbano de Altea, aparece como playa urbana donde se dispone de todo tipo de servicios para disfrutar de una gran extensión de arena y grava y de sus tranquilas aguas.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1259, 'Cap Negret', 'Situada al norte del término de Altea aparece esta playa de gravilla, azotada en ocasiones por el temporal, que acaba en una pequeña cala de piedra negra llamada Cala del Soyo.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1263, 'Mascarat Sur', 'Altea acaba en la punta del Mascarat y la Sierra de Bernia, donde aparecen calas de gravilla como ésta al sur de Mascarat, también llamada La Barreta, la playa de La Solsida y la Cala de La Barra Grande.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1264, 'Mascarat Norte', 'Altea acaba en la punta del Mascarat y la Sierra de Bernia, donde aparecen calas de gravilla como ésta, ubicada al norte del poblado de Mascarat, la playa de La Solsida y la Cala de La Barra Grande', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1265, 'Cala de la Barra Grande', 'Altea acaba en la punta del Mascarat y la Sierra de Bernia, donde aparecen calas de gravilla como ésta de la Barra Grande, la última playa de Altea, la playa de La Solsida y las playas de Mascarat.', 3018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1266, 'Playa de Poniente', 'La Playa de Poniente ocupa desde el casco antiguo hasta la vecina Cala de Finestrat. Esta playa también goza de la finura de su arena, la limpieza diaria y la calidad de sus servicios, como la Playa de Levante, playa de Benidorm por excelencia, aunque resulta ser bastante más tranquila.', 3031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1267, 'Cala del Mal Pas', 'Entre la Playa de Poniente y el casco antiguo se encuentra esta pequeña calita conocida como Cala del Mal Pas a la que se accede desde el puerto o desde unas escaleras que bajan directamente desde el Castillo.', 3031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1268, 'Playa de Levante', 'La Playa de Levante, con dos kilómetros de extensión, destaca por la finura de su arena y la calidad de sus servicios. Desde La Plaza del Castillo se puede acceder a esta playa por típicas calles estrechas de blancas paredes.', 3031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1269, 'Cala Tío Ximo', 'Esta pequeña cala ubicada en el Rincón de Loix se presenta como el contrapunto a la espectacular extensión de arena fina de las playas de que dispone Benidorm, gran centro turístico de la Costa Blanca.', 3031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200301, 'Cala Almadraba', 'Esta pequeña playa ubicada en el Rincón de Loix se presenta en contrapunto a la espectacular extensión de arena fina de las playas de que dispone Benidorm, gran centro turístico de la Costa Blanca', 3031);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1270, 'La Fustera', 'Pequeña playa de arena oscura y todo tipo de servicios, que dispone de acceso especial para discapacitados.', 3041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1271, 'Els Pinets', 'Esta playa de reducidas dimensiones alterna la arena fina con rocas y presenta un alto grado de ocupación.', 3041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1272, 'La Llobella', 'Playa aislada, de difícil acceso, con carácter rocoso y peligro de desprendimientos.', 3041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1273, 'El Abogat', 'Esta playa presenta un carácter rocoso, como muchas de los alrededores, donde la ausencia de arena es la principal característica.', 3041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1274, 'El Baladrar', 'Playa con ausencia de arena, aislada de núcleos urbanos.', 3041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1278, 'Cala El Collao', 'Esta playa aislada se localiza en el extremo sur de la Sierra de Toix y tiene acceso desde el mar o por una senda peatonal de difícil acceso.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1279, 'Cala Gasparet', 'Esta playa ubicada en el Morro de Toix, está situada a Levante de la Sierra de Toix y sólo tiene acceso a través del mar.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1280, 'Cala Les Urques', 'Esta playa de rocas, localizada en una zona semiurbana, no dispone de ningún tipo de servicio, aunque es apta para la práctica del submarinismo y la pesca.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1281, 'Puerto Blanco', 'Playa ubicada en las inmediaciones del puerto', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1282, 'Cala La Manzanera', 'Cala de arena y grava que no se caracteriza por una gran afluencia de público, debido quizá a su deficiente disponibilidad de servicios.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1283, 'Arenal-Bol', 'Playa de arena fina y gran extensión, caracterizada por sus inmejorables instalaciones y disponibilidad de servicios.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1284, 'Morelló', 'Playa urbana de reducidas dimensiones que presenta una gran afluencia de público.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1285, 'Cantal Roig', 'Esta playa situada en las inmediaciones del Puerto de Calpe presenta una gran afluencia de público debido a sus excelentes instalaciones', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1286, 'Cala El Racó', 'Cala de apenas setenta metros de longitud, carente de arena, de carácter semiurbana, situada junto al espigón sur del Puerto de Calpe.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1287, 'Cala del Penyal', 'Playa aislada que se localiza en el Peñón D''Ifach, orientada al norte, apropiada para la práctica del submarinismo, la pesca y excursiones náuticas y senderismo.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1288, 'Playa de La Fossa', 'Seguramente la playa de Calpe con mayor afluencia de público y mejores instalaciones de topo tipo en la misma playa y alrededores', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1289, 'Cala Calalga', 'Esta pequeña playa de grava y arena dispone de servicios de alquileres náuticos para disfrutar de sus tranquilas aguas.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1290, 'Cala del Mallorquí', 'Playa de rocas con ausencia de servicios y una baja calidad del entorno natural. ', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1291, 'Cala de les Bassetes', 'La Cala de les Bassetes, de pequeña dimensión y constituida por rocas, representa uno de los extremos de la bahía calpina, junto con el Morro de Toix al otro lado.', 3047);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1316, 'Cala Lanuza', 'La Cala Lanuza está ubicada al norte de la Cala Baeza, separada por un espigón y compuesta de arena oscura, sin servicios disponibles.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1317, 'Cala Monte Lanuza', 'La Cala Monte Lanuza se encuentra a continuación de la Cala Lanuza, recibiendo ambas el nombre del Alto Lanuza, paralelo al litoral costero.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1315, 'Cala Baeza', 'La Cala Baeza, también conocida como Cala d''Or o La Merced, de arena oscura, se encuentra ubicada al abrigo del espigón, en el litoral perteneciente a El Campello.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1305, 'Muchavista', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1306, 'Carrer del Mar', 'El núcleo de Carrer del Mar que da nombre a esta playa se encuentra en la costa, a 2 km. del pueblo de El Campello. Es aquí donde antiguamente estaba ubicado el barrio de pescadores y que en la actualidad concentra la zona más turística de este término.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1307, 'Banyets de la Reina', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1308, 'La Almadraba', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1309, 'El Amerador', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1310, 'Cala del Puerto', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1311, 'Cala de En Medio', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1312, 'Cala Piteras', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1313, 'Cala del Barranco de Aguas', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1314, 'Cala del Cuartel', 'El Campello dispone de más de 20 km. de litoral con playas de todo tipo, desde Muchavista, lindando con San Juan en Alicante, hasta las pequeñas calas rocosas del Barranco de Aguas o Cala del Cuartel, o calas de arena oscura como Baeza y Piteras.', 3050);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1292, 'Cala de Aigua Dolç', 'Cala ubicada en un acantilado, con acceso a través de una escalera, próxima al Parque Natural El Montgó y a la Reserva Marina del Cabo de San Antonio.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1293, 'Les Rotes', 'Les Rotes, localizada al sur de Denia, constituye unas pequeñas calas con parajes de increíble belleza.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1294, 'El Marge Roig', 'Playa semiurbana que presenta una estrecha franja de arena oscura y aguas tranquilas', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1295, 'La Marineta Casiana', 'Playa con un alto grado de ocupación donde pueden practicarse deportes náuticos.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1296, 'Playa Nova', 'Playa con un alto grado de ocupación donde pueden practicarse deportes náuticos.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1297, 'Les Marines', 'La Platja de les Marines presenta la característica de las playas de la zona norte de Denia, de arena fina y muy extensas.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1298, 'Les Bovetes', 'Playa de arena dorada y aguas tranquilas.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1299, 'Molinos y Palmeras', 'Playa al norte de Denia, caracterizada por su gran extensión de fina arena dorada', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1300, 'Racó de la Alberca', 'Playa semiurbana de arena dorada, bañadas por aguas tranquilas.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1301, 'L''Estanyo', 'Playa semiurbana de gran extensión compuesta de arena, aunque algo escasa de servicios.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1302, 'La Almadraba', 'Playa situada al norte de Denia, caracterizada por su gran extensión, generalmente de turismo familiar.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1303, 'Sorts de Mar', 'Playa regenerada con arena de cantera.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1304, 'Les Devesses', 'Es la playa de mayor extensión del término de Denia, caracterizada por estar sometida a vientos de consideración, que posibilitan la práctica de deportes de vela.', 3063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1318, 'La Marina', 'Las playas de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas y multitud de servicios, así como de zonas de gran valor ecológico, como son los ecosistemas de dunas del litoral.', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1319, 'El Pinet', 'El sur de Elche dispone de dos playas de características similares, El Pinet y La Marina, amplias bandas de arena dorada.', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1320, 'Carabassí', 'Las playas del norte de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas, así como de zonas de gran valor ecológico, como son los ecosistemas de dunas del litoral.', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1321, 'Arenales del Sol', 'Las playas del norte de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas, así como de zonas de gran valor ecológico, como son los ecosistemas de dunas del litoral', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1322, 'El Altet', 'Las playas del norte de Elx se presentan como grandes espacios de dorada arena en los que disfrutar de aguas tranquilas, así como de zonas de gran valor ecológico, como son los ecosistemas de dunas del litoral.', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1332, 'El Rebollo', 'La Playa del Rebollo es un ejemplo más de la diversidad de playas de este litoral costero, donde se combinan las playas aisladas con otras de elevada afluencia de visitantes.', 3065);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1324, 'Finestrat', 'Finestrat, típico pueblo mediterráneo del interior, posee este pequeño segmento de litoral que conforma su playa gracias a su contribución a la defensa del litoral contra los piratas berberiscos.', 3069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1334, 'La Granadella', 'Pequeña playa rodeada de pinos, muy adecuada para la práctica del submarinismo.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1335, 'El Ambolo', 'Playa de difícil acceso por tierra y a la que puede accederse desde el mar', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1336, 'Cala de la Barra', 'Pequeña cala de rocas, aislada, ubicada en el extremo del Cabo de la Nao.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1337, 'Portichol', 'Playa con un alto grado de ocupación desde donde puede verse la pequeña Isla del Portichol', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1338, 'Cap Marti', 'Esta playa de grava se encuentra aislada por su difícil acceso, aunque goza de un alto grado de ocupación por sus aguas tranquilas', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1339, 'Primera y Segunda Caletas', 'Playa que presenta una estrecha franja de bolos y rocas en la que se puede disfrutar de aguas tranquilas.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1340, 'Segundo Montañar', 'Playa rocosa de gran extensión, en la que se han acondicionado zonas para el baño.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1341, 'El Arenal', 'Es la playa más concurrida de Jávea, donde se levanta el único Parador Nacional que existe en la Costa Blanca', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1342, 'Primer Montañar', 'Playa urbana de gran extensión compuesta especialmente por rocas y grava, donde pueden practicarse deportes náuticos.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1343, 'La Grava', 'Esta playa se localiza en la zona urbana de Aduanas del Mar y presenta un alto grado de ocupación.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1344, 'Pope', 'Esta pequeña playa de grava esta enclavada en las proximidades de la Reserva Marina del Cabo de San Antonio.', 3082);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1345, 'Mil Palmeras', 'Playa natural ubicada en una zona urbana, donde se dispone de todo tipo de servicios necesarios para su uso.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1346, 'Barranco Rubio', 'Es una de las playas, junto con La Glea y Aguamarina, situadas en la llamada Dehesa de Campoamor, donde puede disfrutarse de todo tipo de servicios y un Puerto Deportivo para poder recorrer la costa.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1347, 'La Glea', 'Es una de las playas, junto con Barranco Rubio y Aguamarina, situadas en la llamada Dehesa de Campoamor, donde puede disfrutarse de todo tipo de servicios y un Puerto Deportivo para poder recorrer la costa.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1348, 'Aguamarina', 'Playa situada en la llamada Dehesa de Campoamor, donde puede disfrutarse de todo tipo de servicios y un Puerto Deportivo para poder recorrer la costa mar adentro.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1349, 'La Caleta', 'La Caleta está situada al sur de Cabo Roig y es conocida turísticamente como Playa de Cabo Roig, con inmejorables servicios.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1350, 'Cala Capitán', 'Cala Capitán está ubicada al norte del Cabo Roig, con inmejorables servicios.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1351, 'Cala del Bosque', 'Cala del Bosque y Cala Cerrada son conocidas como La Zenia por estar ubicadas en el centro del complejo urbanístico que le da nombre, dotando a estas playas de todo tipo de servicios.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1352, 'Cala Cerrada', 'Cala Cerrada y Cala del Bosque son conocidas como La Zenia, ubicadas en el complejo urbanístico del mismo nombre, presentando gran disponibilidad de servicios.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1353, 'Cala Estaca', 'Pequeña cala urbana, de arena fina y con todo tipo de servicios disponibles, sobre todo en la época estival.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1354, 'Cala La Mosca', 'La Cala La Mosca, de reducidas dimensiones, es una cala urbana de arena fina con todos los servicios disponibles', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1355, 'Calas del Cabo Peñas', 'Esta formación natural de difícil acceso se presenta como una cala aislada que dispone de aguas tranquilas y arena dorada.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1356, 'Punta Prima', 'Es la última playa al norte de la costa de Orihuela, en Punta Prima, rodeada de urbanizaciones y con todo tipo de servicios.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1367, 'Vista Mar', 'Esta playa es la última de Pilar de la Horadada, ubicada en una extensa franja conocida como Cañada Hermosa que continúa en el término vecino de Orihuela.', 3099);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1368, 'La Gola', 'Esta playa natural es una de las que forman la zona de costa colindante con el Paraje Natural Salinas de Santa Pola, zona de gran valor ecológico.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1369, 'Brac del Port', 'Playa natural que forma parte de la zona de costa colindante con el Paraje Natural Salinas de Santa Pola, zona de gran valor ecológico.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1370, 'Lisa', 'Esta playa natural es una de las que forman la zona de costa colindante con el Paraje Natural Salinas de Santa Pola, zona de gran valor ecológico.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1371, 'Gran Playa', 'Esta playa, del Golfo de Santa Pola es una de las que forman la zona de costa colindante con el Paraje Natural Salinas de Santa Pola, zona de gran valor ecológico.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1372, 'Playa de Levante', 'Esta playa natural con gran afluencia y muchos servicios.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1373, 'Calas I-II-III Santiago Bernabeu', 'Las Calas I, II y III Santiago Bernabéu , junto a la Playa de Levante en el puerto marítimo de Santa Pola, conforman un complejo espacio artificial al sur de la ciudad.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1374, 'Varadero', 'De la zona este del litoral de Santa Pola, la  Playa Varadero y Santa Pola del Este son zonas urbanas en las que se dispone de gran cantidad de servicios, sobre todo en la temporada estival.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1375, 'Santa Pola del Este', 'De la zona este del litoral de Santa Pola, esta playa y la de Varadero son zonas urbanas donde se dispone de gran cantidad de servicios, sobre todo en la temporada estival.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1376, 'Mare de Deu', 'De las playas del este de Santa Pola, la de Mare de Deu es la única que presenta unas características típicas de rocas y arena oscura, consecuencia de su exposición en el extremo del Cabo de Santa Pola.', 3121);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1377, 'El Andragó', 'Pequeña cala semiurbana carente de arena, donde hay zonas que sufren desprendimientos de rocas.', 3128);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1378, 'Les Playetes', 'Esta pequeña playa ofrece unas aguas transparentes y arena fina de color oscuro mezclada con rocas.', 3128);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1379, 'La Ampolla', 'La Ampolla es la playa más famosa de Teulada, situada junto al castillo, con arena fina y aguas transparentes.', 3128);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1380, 'El Portet', 'Playa cosmopolita, con un alto grado de ocupación y acceso para discapacitados.', 3128);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1381, 'Cala de las Piteras', 'En la zona sur, en el límite del término de Orihuela, en una zona semiurbana, se encuentra esta cala rodeada de rocas y con la vegetación típica del Mediterráneo, apta para la pesca.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1382, 'Cala Ferri', 'Lo más característico de esta cala es su tranquilidad, sus aguas limpias y cristalinas, y su entorno rodeado de dunas con abundante vegetación y palmeras.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1383, 'Playa de Poniente', 'Playa de fina arena en cuyo extremo sur se encuentra una zona rocosa apta para la pesca. En su extremo norte se encuentra el dique de poniente del Puerto de Torrevieja, que hace de esta playa un lugar de aguas tranquilas, recomendable para los deportes náuticos.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1384, 'El Acequión', 'Playa ubicada dentro del Puerto de Torrevieja, junto a la marina deportiva. situada a un kilómetro de las Salinas de Torrevieja, de interés turístico, donde diariamente se organizan visitas acompañadas por guías.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1385, 'El Cura', 'Situada en el corazón de la ciudad, la Playa del Cura es la más cosmopolita de Torrevieja', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1386, 'Cala del Palangre', 'Aunque se trata de una cala de reducido tamaño, dispone en sus inmediaciones de una zona de rocas muy visitada para la práctica de la pesca.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1387, 'El Salaret', 'Magnífica playa de arena ubicada al norte de Torrevieja, tras cruzar la Punta Carral, que dispone de todo tipo de servicios.', 3133);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1388, 'Cala de la Higuera', 'Esta cala, junto con otras situadas en sus cercanías, forman un conjunto accesible que destaca por sus aguas limpias y cristalinas.', 3133);
