INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1526, 'El Perelló', 'Playa urbana con servicios disponibles que presenta un punto negro de contaminación representado por la Gola del mismo nombre', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1527, 'Les Palmeretes', 'Les Palmeretes presenta un alto grado de ocupación, sobre todo en época estival, debido a su cercanía a una zona urbana y a la cantidad de servicios disponibles.', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1528, 'El Rey', 'Playa de arena situada en el Parque Natural de la Albufera con pocos servicios', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1529, 'Bega de Mar', 'Playa de arena con un bajo grado de ocupación y con escasas instalaciones.', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1530, 'Mareny Blau', 'Playa muy urbana que dispone de gran cantidad de servicios y paseo marítimo.', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204609, 'Pouet', 'El Pouet presenta, sobre todo en verano, un alto grado de ocupación debido a su cercanía a una zona urbana y la cantidad de servicios disponibles', 46235);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1532, 'Pinedo', 'Playa al sur de Valencia que dispone de accesos para discapacitados, además de servicios elementales para su uso público.', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1533, 'El Saler', 'Más de dos kilómetros de playa de arena ubicada en las proximidades del Parque Natural de la Albufera de Valencia.', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1534, 'La Devesa', 'Playa aislada situada en el corazón del Parque Natural de la Albufera de Valencia.', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1535, 'El Perellonet', 'Gran extensión de playa de arena ubicada en una zona residencial, donde muchos de los accesos a la playa son de carácter privado.', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1536, 'Malvarrosa', 'Playa de gran calidad ubicada al norte del puerto de Valencia, con excelentes instalaciones.', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204605, 'Cabanyal', 'Playa de gran calidad ubicada junto a la playa de la Malvarrosa, con excelentes instalaciones', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204606, 'L''Arbre del Gos', 'Playa que cierra la entrada de coches por la noche', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204607, 'La Garrofera', 'Playa con mucha vegetación, situada en el corazón del Parque Natural de la Albufera de Valencia', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204608, 'Vistabella', 'Playa aislada y poco frecuentada', 46250);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1491, 'Mareny de Sant Llorenç', 'Playa de gran extensión donde la gran mayoría de los accesos son de tipo privado y sin equipo de vigilancia ni señalizaciones de peligro.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1492, 'El Dosel', 'Playa situada en el Parque Natural de la Albufera, de afluencia media.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1493, 'El Faro', 'Playa que recibe su nombre por encontrarse cercana al faro de Cullera. Zona muy urbanizada.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1494, 'Los Olivos', 'Playa de calidad por su excelente arena y disponibilidad de servicios, muy concurrida en la época estival.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1495, 'Cap Blanc', 'Playa que acoge a gran cantidad de público durante la época estival.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1496, 'El Racó', 'Playa urbana con gran afluencia de público y con gran variedad de servicios disponibles', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1497, 'Sant Antoni', 'Es la playa más cercana al municipio de Cullera, con un alto grado de ocupación y servicios disponibles.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1498, 'El Marenyet', 'Playa al sur de Cullera, de carácter urbano y con los servicios más elementales para su uso público.', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1499, 'L''Estany', 'Playa con un bajo grado de ocupación', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1500, 'El Brosquill', 'Playa poco concurrida, con difíciles accesos y sin equipamientos', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204610, 'Playa Escollera', 'Es junto a la de San Antonio la más cercana al municipio de Cullera', 46105);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1537, 'Xeraco', 'Playa con mediana ocupación y gran cantidad de servicios disponibles.', 46143);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1510, 'Massamagrell', 'Playa de arena, aislada de zonas urbanas y carente de servicios ni instalaciones para el público.', 46164);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1508, 'La Pobla de Farnals', 'Playa urbana de arena y grava dotada de todo tipo de servicios de calidad, con un alto grado de ocupación.', 46199);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204603, 'Mareny', 'Playa de gran extensión', 46238);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1531, 'Tavernes', 'Playa con un tramo urbano, muy concurrida en fines de semana y verano. Dispone de multitud de servicios.', 46238);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204602, 'Goleta', 'Playa urbana de fácil acceso y familiar', 46238);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2632, 'La Carolina', 'Pequeña playa aislada, pero con un alto grado de ocupación. Fácil acceso debido a una carretera cercana. Playa ancha y larga, existen restos de escollera de antiguos cocederos de esparto', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2633, 'La Higuerica', 'Playa aislada y ancha, lo que permite realizar en ella, diferentes actividades o deportes. Existen restos de escollera de antiguos cocederos de esparto.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2634, 'Calarreona', 'Playa de ambiente familiar, con un alto grado de ocupación, pero bastante amplia, y con una arena de calidad.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2635, 'Calarreona', 'Playa con un alto nivel de ocupación. Está dotada con un buen número de equipamientos', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2636, 'Playa de los Cocederos', 'Cala de reducidas dimensiones, sin ningún tipo de equipamientos, a la que se accede fácilmente. Existen restos de escollera de los antiguos cocederos de esparto', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2637, 'Cueva de las Palomas', 'Playa enclavada en una zona virgen, pero que debido a sus malas condiciones de limpieza, pierde parte de su encanto. Existen restos de escollera de los antiguos cocederos de esparto', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2638, 'La Herradura', 'Pequeña y resguardada playa de poca arena. Presenta un aspecto algo descuidado.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2639, 'Matalentisco', 'Playa de aguas tranquilas, que presenta un aspecto descuidado. No ofrece ningún tipo de servicio.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2640, 'La Cañada del Negro', 'Playa virgen con una escasa afluencia de público. No ofrece equipamiento alguno. Aspecto descuidado.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2641, 'La Casica Verde', 'Playa regenerada. Dispone de un aparcamiento bastante grande.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2643, 'Poniente', 'Playa urbana de ambiente familiar. Está dotada con buenos equipamientos: lavapies y aseos. Chiringuitos', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2644, 'La Colonia', 'Playa urbana, de ambiente familiar, que ofrece bastantes equipamientos. Elementos deportivos, parques infantiles', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2645, 'Levante', 'Playa familiar, bien equipada. Existe la posibilidad de realizar en ella diferentes deportes: voley-playa, etc.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2646, 'Las Delicias', 'Esta playa cuenta con un agradable paseo marítimo, y un elevado nivel de edificación. Posibilidad de realizar deportes. Chiringuitos y alquiler de sombrillas', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2647, 'Cocedor', 'Pequeña playa con un bajo nivel de edificación y pocos equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2648, 'El Hornillo', 'Esta es una playa pequeña, pero con un alto nivel de urbanización.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2649, 'Playa del Cigarro', 'Playa rodeada de zona urbana, de fácil acceso  e idónea para el fondeo de barcos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2650, 'Todo Sol', 'Pequeña y tranquila playa, a la que se accede fácilmente desde la población cercana de Todosol.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2651, 'El Arroz', 'Playa pequeña y tranquila.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2652, 'El Pino', 'Cala pequeña y aislada, a la que se accede fácilmente por un camino de arena. Presenta un bajo grado de ocupación.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2653, 'La Cola', 'Larga playa con un alto grado de ocupación y con pocos equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2654, 'Cala de Canalicas', 'Pequeña cala muy urbanizada y con un alto grado de ocupación. No ofrece apenas equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2655, 'Calabardina', 'Playa de ambiente familiar, con un alto grado de urbanización. Cuenta con bastantes equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2656, 'La Ensenada de la Fuente', 'Pequeña playa rocosa, lo que la hace poco apta para los bañistas. No dispone de equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2657, 'Sombrerico', 'Pequeña playa rocosa, lo que la hace poco apta para los bañistas. No ofrece ningún tipo de servicio.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2658, 'El sombrerito', 'Pequeña playa virgen, de fina arena dorada. Apenas dispone de equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2659, 'El Charco', 'Pequeña playa, aislada, sin ningún tipo de equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2660, 'Rafal', 'Playa aislada, con un bajo nivel de ocupación y equipamientos. Zona de interés paisajístico', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2661, 'Playa Rambla Elena', 'Pequeña y tranquila playa, pero sin equipamientos. Zona de interés paisajístico.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2662, 'Pozo del Animal', 'Pequeña playa, aislada, de difícil acceso a pie. Se suele acceder a ella por barco. No ofrece ningún tipo de servicio.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2664, 'El Saladar', 'Playa aislada, sin ningún tipo de equipamientos. Zona interesante a nivel paisajístico.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2665, 'Pozo de Huertas', 'Esta playa por su orientación acumula siempre una pantalla de algas. Problemática para el baño.  ', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2666, 'Las Pulgas', 'Playa aislada, situada en una zona de aspecto desértico, sin ningún tipo de equipamientos.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2667, 'La Galera', 'Playa ubicada al levante con un islote que protege la regresión de la playa por lo que no sufre evolución alguna. Al encontrarse aislada, en una zona casi virgen, presenta un bajo grado de ocupación.', 30003);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2755, 'El Cabezo del Mojón', 'Playa semiurbana situada en las inmediaciones del peñón Cabeza del Mojón. Presenta un grado bajo de ocupación. No tiene servicios', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2756, 'El Corral', 'Playa situada en un entorno agradable. Compuesta por arena y grava. No ofrece ningún tipo de servicio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2757, 'Cala del Contrabando', 'Cala urbana pero tranquila, de arena dorada y tranquilas aguas. No dispone de equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2758, 'Maestro Romero', 'Cala de pequeñas dimensiones, muy urbanizada y con un grado medio de ocupación. Sin servicios.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2759, 'La Caleta', 'Playa pequeña de aguas tranquilas, utilizada principalmente para varar embarcaciones.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2760, 'Isla Plana', 'Playa urbana con elevada afluencia de público. Está compuesta por arena y grava y ofrece un nivel medio de equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2761, 'La Calera', 'Es una playa que se encuentra aislada, compuesta por grava, con un bajo nivel de equipamientos y una escasa afluencia de público.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2762, 'San Ginés', 'Playa urbana bastante concurrida, compuesta por arena y grava. Ofrece algunos servicios, como aseos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2763, 'La Chapineta', 'Tranquila playa urbana de un pequeño pueblo de pescadores, con moderada afluencia de público. Ofrece un nivel medio de servicios.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2764, 'Cala Cerrada', 'Cala aislada con escasa afluencia de público y difícil acceso a pie. Ofrece arena dorada y aguas tranquilas. No dispone de equipamiento alguno.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2811, 'La Gola', 'Playa urbana de La Manga del Mar Menor que disfruta de una arena fina y aguas tranquilas. Ofrece un buen nivel de servicios. Ambiente familiar. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2812, 'Puerto Bello', 'Playa urbana de La Manga del Mar Menor con un alto nivel de ocupación y ambiente familiar. Esta dotada con múltiples equipamientos, contando incluso con un Club Náutico en sus inmediaciones. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2813, 'El Vivero', 'Playa semiurbana de La Manga del Mar Menor, que disfruta de aguas tranquilas y de una escasa afluencia de público. No ofrece apenas servicios. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2814, 'Los Alemanes', 'Playa de La Manga del Mar Menor de carácter urbana, de arena fina y dorada, con un grado medio de ocupación, que se extiende desde el Cabo de la Plata al Cabo de Gracia. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2815, 'Paraíso', 'Playa semiurbana del Mar Menor colindante con las Salinas de Marchamalo, con gran afluencia de público. Ofrece un buen número de equipamientos, incluida la posibilidad de practicar deportes náuticos. Pendiente suave y aguas cálidas.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2816, 'Honda', 'Playa del Mar Menor altamente urbanizada con un bonito paseo marítimo. Está dotada con buenos equipamientos. Existe la posibilidad de realizar deportes acuáticos. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2826, 'El Carmolí', 'Playa del Mar Menor extensa, aislada, con un bajo grado de ocupación. El estado del entorno no es demasiado bueno y no ofrece ningún tipo de servicio. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2827, 'La Azohía', 'Playa urbana pero con un grado medio de ocupación.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2765, 'Cala Salitrona', 'Cala aislada enclavada dentro de un Espacio Natural Protegido que configura un paisaje de interés. Se suele acceder a ella en barco. Sin ningún equipamiento.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2766, 'Pozo de la Avispa', 'Cala espléndida, enclavada en un agradable entorno que conforma el Espacio Natural Protegido de Cabo Tiñoso. Es de difícil acceso a pie, pero merece la pena la visita.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2767, 'Cala Bolete Grande', 'Fabulosa cala virgen dentro del Espacio Natural Protegido de Cabo Tiñoso. El acceso a pie es complicado, pero el entorno lo compensa. Zona idónea para la práctica del submarinismo.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2768, 'Cala El Bolete', 'Cala tranquila y agradable a la que se accede a través de senda (70-100m) desde el antiguo cuartel de Carabineros (en la actualidad propiedad privada), por lo que se suele llegar a ella en barco. Entorno excelente dentro del Espacio Protegido de Cabo Tiñoso.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2769, 'Cala Aguilar', 'Cala en la que se puede disfrutar plenamente de la tranquilidad. El acceso es complicado, por lo que se suele llegar hasta ella en barco. Disfruta de aguas limpias, y entorno perfecto. Merece la pena la visita.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2770, 'El Portús', 'Alta afluencia de público en temporada de baño. A tener en cuenta que junto con Cala Cortina son las únicas playas de baño cercanas a la ciudad de Cartagena', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2771, 'La Morena', 'Playa enclavada en un entorno rocoso que le aporta cierta tranquilidad.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2772, 'Cala del Gallito', 'Cala tranquila compuesta por grava y bolos, y que presenta un bajo grado de ocupación. No ofrece ningún tipo de servicio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2773, 'Fatares', 'Pequeña playa aislada y tranquila a la que se accede difícilmente a pie, por lo que se suele llegar a ella en barco. No ofrece ningún tipo de servicio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2774, 'Parajola', 'Playa pequeña y aislada a la que sólo se accede en barco, lo que hace que presente una escasa afluencia de público. No ofrece equipamiento alguno.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2775, 'Cala Cortina', 'Playa aislada pero que presenta un alto grado de ocupación. Está dotada de buenos equipamientos y posee un  paseo marítimo por el que dar agradables paseos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2776, 'El Gorguel', 'Playa aislada, con escasa afluencia de público. Pierde parte de su encanto, por el mal estado del entorno natural que la rodea.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2777, 'Cala del Barco', 'Pequeña cala semiurbana, muy concurrida y que ofrece un buen número de servicios: alquiler de hamacas y sombrillas, aseos, duchas, etc.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2778, 'Las Mulas', 'Es una playa tranquila, enclavada en un entorno rocoso y atractivo, a la que se puede acceder a pie por un camino largo o en barco. Sin servicios.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2779, 'Parreño', 'Playa de La Manga del Mar Mediterráneo de fina arena dorada, aislada y tranquila, con baja ocupación. No cuenta con ningún tipo de servicio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2780, 'Negrete', 'Playa del Mar Mediterráneo, aislada y tranquila de arena dorada, situada dentro del Parque Regional de Calblanque. No dispone de equipamientos, como las demás playas de la zona.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2781, 'Larga', 'Entorno privilegiado donde disfrutar de la tranquilidad y el silencio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2782, 'Las Cañas', 'Playa de La Manga del Mar Mediterráneo aislada, contigua a la playa de Melicena.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2783, 'Calblanque', 'Playa de La Manga del Mar Mediterráneo que se enclava dentro del Espacio Natural Protegido del Parque de Calblanque. Ofrece una arena dorada de calidad y la posibilidad de disfrutar de un entorno privilegiado.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2784, 'Cala Arturo', 'Cala situada en el Espacio Natural Protegido del Parque de Calblanque. Ofrece un entorno interesante, una fina arena dorada de calidad y la posibilidad de disfrutar de la tranquilidad.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2785, 'Cala Magre', 'Cala enclavada en el Parque de Calblanque declarado Espacio Natural Protegido en 1987. Ofrece una arena fina dorada y aguas tranquilas y limpias.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2786, 'Cala de los Dentones', 'Se accede por un camino que salva un gran desnivel.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2787, 'Cala Reona', 'Cala semiurbana con un grado medio de ocupación. A diferencia de otras de la zona, su superficie es de arena. No ofrece apenas equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2788, 'El Descargador', 'Playa de La Manga del Mar Mediterráneo con gran afluencia de usuarios que dispone de todo tipo de equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2789, 'Cala Flores', 'Cala compuesta por arena y grava, de aguas idóneas para practicar el buceo. Tiene gran afluencia de público. No ofrece ningún servicio.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2790, 'Cala Medina', 'Cala tranquila compuesta de grava y bolos. Disfruta de fondos marinos interesantes. No dispone de equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2791, 'Cala Avellan', 'Es una cala rocosa de pequeño tamaño con un bajo grado de ocupación. No dispone de equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2792, 'La Barra', 'Playa del Mar Mediterráneo urbanizada que se caracteriza por los dos grandes bloques de piedras ubicados en medio de la ensenada cerrada al mar por falsos diques de piedras a ambos lados.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2793, 'Las Melvas', 'Pequeña playa del Mar Mediterráneo semiurbana, situada en un entorno un tanto degradado. No ofrece ningún equipamiento.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2794, 'Cala Botella', 'Pequeña cala con bonitas vistas al faro. Disfruta de gran tranquilidad y de aguas limpias y claras.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2795, 'Cala del Muerto', 'Pequeña cala urbana formada por arena y grava, con escasa afluencia de público y sin equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2796, 'Cala Roja', 'Cala urbana de arena y grava con un bajo grado de ocupación, a la que se accede por unas escalerillas. No ofrece apenas servicios.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2797, 'Cala Fría', 'Cala de arena dorada rodeada de rocas, que conforman un entorno agradable. Aguas limpias idóneas para bucear. Escasos equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2798, 'Cala Túnez', 'Cala de arena dorada situada a los pies del faro. Disfruta de aguas tranquilas y limpias, pero dispone de escasos equipamientos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2799, 'Las Escalerillas', 'Playa del Mar Mediterráneo muy pequeña y rocosa, con un bajo grado de ocupación. Disfruta de aguas limpias y tranquilas donde practicar el buceo.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2800, 'La Galera', 'Playa del Mar Mediterráneo con una composición muy irregular, alternándose las piedras con la arena de color gris y la grava, y que recibe a un reducido número de bañistas.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2801, 'Levante', 'Playa del Mar Mediterráneo familiar, bien equipada. Existe la posibilidad de realizar en ella diferentes deportes: voley-playa, etc.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2802, 'Amoladeras', 'Playa de La Manga del Mar Mediterráneo urbana de arena dorada. Una parte de ella es un Espacio Natural Protegido. Ofrece algunos servicios: lavapies y aseos.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2803, 'Marchamalo', 'Playa de La Manga del Mar Mediterráneo urbana de arena fina dorada, y dotada con todo tipo equipamientos: alquiler de sombrillas y hamacas, lavapies, alquileres náuticos, etc.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2804, 'Galúa', 'Playa de La Manga del Mar Mediterráneo urbana, de arena fina dorada, y gran afluencia de público. Ofrece todo tipo de equipamientos y comodidades.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2805, 'Calnegre', 'Playa de La Manga del Mar Mediterráneo, de arena fina dorada. Aunque presenta un grado medio de ocupación, se puede disfrutar en ella de un ambiente tranquilo.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2806, 'Cala del Pino', 'Cala de La Manga del Mar Menor con gran afluencia de público. De fácil acceso, bien equipada, con pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2807, 'Gollerón', 'Playa de La Manga del Mar Menor de difícil acceso, compuesta de arena fina y que no cuenta con equipamientos. Ambiente tranquilo y familiar. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2808, 'Bahía de las palmeras', 'Pequeña playa de La Manga del Mar Menor muy urbanizada, de arena dorada y aguas tranquilas. Ofrece un nivel medio de equipamientos, entre los que destaca la existencia de un Club Náutico. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2809, 'Isla del Ciervo', 'Pequeña y aislada playa de La Manga del Mar Menor que goza de bastante tranquilidad, enclavada en un entorno natural de interés. No ofrece apenas servicios. Pendiente suave, aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2810, 'Cavannas', 'Playa de La Manga del Mar Menor de más de un kilómetro de longitud con una agradable arena fina dorada y dotada con todo tipo de equipamientos, alquileres náuticos incluidos. Pendiente suave, aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2817, 'Loma del Castillo', 'Playa del Mar Menor natural y con posibilidad de realizar deportes acuáticos. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2818, 'Lo Poyo', 'Playa del Mar Menor de más de tres kilómetros de longitud, de arena oscura y aguas tranquilas. Enclavada en un paisaje atractivo, no ofrece sin embargo ningún servicio. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2819, 'El Arenal', 'Playa del Mar Menor con aguas tranquilas y poco público. Pendiente suave y aguas cálidas.', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2820, 'Mar de Cristal', 'Playa urbana del Mar Menor con un agradable paseo marítimo, y un elevado grado de ocupación. Ofrece un buen nivel de servicios: alquileres de hamacas y sombrillas, lavapies, Club Náutico. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2821, 'Islas Menores', 'Playa urbana del Mar Menor con gran afluencia de público. Está dotada con buenos equipamientos, incluido el Club Náutico situado en uno de los extremos de la misma. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2822, 'Los Nietos', 'Playa del Mar Menor urbana, de arena oscura, y que presenta una gran afluencia de público. Presenta un buen nivel de equipamientos. Pendiente suave  y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2823, 'Perla de Levante', 'Playa del Mar Menor que cuenta con una arena de calidad y un paseo marítimo flanqueado por palmeras. Ofrece un nivel aceptable de servicios. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2824, 'Los Urrutias', 'Playa del Mar Menor de arena oscura y dotada con buenos equipamientos. Se pueden realizar diversos deportes acuáticos. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2825, 'Punta Brava', 'Playa del Menor urbana con alta afluencia de público. Ofrece arena oscura, aguas tranquilas y con poca profundidad y un nivel medio de equipamientos. Pendiente suave y aguas cálidas', 30016);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2709, 'Playa Larga', 'Playa aislada que presenta un bajo grado de ocupación. No ofrece ningún tipo de servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2710, 'Cala Blanca', 'Playa aislada que presenta un escasa afluencia de público. No ofrece ningún tipo de servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2711, 'Los Hierros', 'Pequeña playa aislada que no ofrece ningún tipo de servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2712, 'Cala Leña', 'Pequeña cala aislada situada en un entorno Natural Protegido. Presenta un bajo grado de ocupación y no ofrece ningún tipo de servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2713, 'Cala de la Gruta', 'Cala pequeña situada en un entorno rocoso de gran atractivo dentro de un Espacio Natural Protegido. No dispone de equipamientos.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2714, 'Cala Junquera', 'Cala de pequeñas dimensiones enclavada en un entorno montañoso dentro de un Espacio Natural Protegido. No presenta ningún tipo de equipamiento.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2715, 'Playa del Pelo', 'Pequeña y aislada playa de difícil acceso a pie, puesto se encuentra en una zona rocosa dentro de un Espacio Natural Protegido. No ofrece ningún servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2716, 'Playa Baja Mar', 'Cala de reducidas dimensiones de difícil acceso a pie por encontrarse situada en una zona rocosa, dentro de un Espacio Natural Protegido. No ofrece ningún servicio.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2717, 'Cala Honda', 'Cala de reducidas dimensiones de difícil acceso a pie por encontrarse situada en una zona rocosa, dentro de un Espacio Natural Protegido. No ofrece ningún equipamiento.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2718, 'Siscal', 'Playa aislada y pequeña de ambiente familiar, compuesta por arena y grava. Enclavada dentro de un Espacio Natural Protegido.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2719, 'San Pedro', 'Playa aislada que presenta un grado medio de ocupación. Se encuentra en una zona de difícil acceso a pie. No dispone de equipamientos.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2720, 'Baño de las Mujeres', 'Cala pequeña y tranquila, de ambiente familiar. Enclavada en un agradable entorno montañoso. Se accede fácilmente en coche.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2721, 'Calnegre', 'Playa ancha de arena fina dorada. Aunque presenta un grado medio de ocupación, se puede disfrutar en ella de un ambiente tranquilo.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2722, 'Puntas de Calnegre', 'Playa semiurbana que presenta una composición de arena y grava y un oleaje moderado. Ofrece escasos servicios.', 30024);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2701, 'Ensenada del Esparto', 'Playa de La Manga del Mar Mediterráneo amplia, en la que se acumulan gran cantidad de algas en la orilla.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2702, 'Los Alisios', 'Playa de la Manga del Mar Menor, tranquila, de ambiente familiar, pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2703, 'Optimis', 'Pequeña playa de La Manga del Mar Menor urbana de arena dorada con difícil acceso público. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2680, 'Pudrimel', 'Playa de La Manga del Mar Mediterráneo semiurbana, con un grado medio de ocupación. En su orilla se acumulan gran cantidad de algas.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2681, 'La Veneziola', 'Playa de La Manga del Mar Menor urbana que ofrece una gran cantidad de servicios. Dispone de zona de fondeo, por lo que se aprecia en su orilla un elevado número de embarcaciones. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2682, 'Pudrimel del Mar Menor', 'Playa de La Manga del Mar Menor urbana de pequeño tamaño, con un grado medio de ocupación. Pendiente suave y aguas cálidas.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2683, 'Matas Gordas', 'Playa de La Manga del Mar Menor semiurbana, que disfruta de aguas tranquilas y ofrece un elevado número de equipamientos. Se pueden realizar en ella gran variedad de deportes. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2684, 'Matasgordas', 'Playa de La Manga del Mar Menor urbana que disfruta de aguas tranquilas y ofrece un elevado número de equipamientos. Se pueden realizar en ella gran variedad de deportes. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2685, 'Primera del Pedrucho', 'Playa de La Manga del Mar Menor urbana que presenta afluencia media de público y ofrece gran cantidad de servicios. Posibilidad de realizar en ella distintos deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2686, 'Segunda del Pedrucho', 'Playa de La Manga del Mar Menor urbana que presenta un grado medio de ocupación y dispone de un número elevado de equipamientos. Posibilidad de realizar en ella distintos deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2687, 'Antillas', 'Pequeña playa urbana del Mar Menor de La Manga. Dispone de zona de fondeo, por lo que es habitual ver en ella numerosas embarcaciones. Pendiente suave y aguas cálidas.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2688, 'Euromangas', 'Playa de la Manga del Mar Menor extensa de fina arena gris con multitud de servicios. Ambiente familiar. Ofrece la posibilidad de realizar diferentes deportes en ella. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2689, 'Punta el Bolondo', 'Playa de la Manga del Mar Menor que disfruta de arena gris aguas tranquilas, que permiten realizar diferentes deportes acuáticos. Dispone de un elevado número de servicios. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2690, 'El Galán', 'Amplia y agradable playa de la Manga del Mar Menor, con un buen nivel de servicios. Posibilidad de realizar en ella deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2694, 'Hacienda dos Mares', 'Playa urbana de la Manga del Mar Mediterráneo con gran afluencia de público, situada entre las urbanizaciones Star Alfa y Villas del Mar', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2695, 'Snipe', 'Playa de La Manga del Mar Mediterráneo situada entre las urbanizaciones Villas la Mar y Eurovosa, de fina arena dorada y con un alto grado de ocupación. Ofrece variedad de servicios.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1360, 'El Puerto', 'Recibe su nombre debido a la ubicación en el mismo Puerto de Torre de La Horadada, que le caracteriza como playa urbana con un alto grado de ocupación.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1361, 'El Conde', 'Playa de pequeña dimensión situada cerca del puerto, de carácter urbano.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1362, 'Los Jesuítas', 'La Playa de la Torre, también conocida como la Playa de Punta del Gato, presenta gran variedad de servicios, con un alto grado de ocupación durante los meses de verano. ', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1363, 'Cala del Rincón', 'La Cala del Rincón es una de las playas de mayor calidad en los cuatro kilómetros de litoral de este término.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1364, 'Calas de Rocamar', 'Estas calas se localizan en la Punta del Gato y presentan un carácter aislado por su difícil acceso, con arena fina y tranquilas aguas.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1365, 'Río Seco', 'Playa con gran afluencia de visitantes, aunque alejada de zonas urbanizadas, donde puede disfrutarse de variedad de servicios durante la temporada de verano.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1366, 'Mil Palmeras', 'Playa natural que goza de servicios de todo tipo, incluida una zona reservada especialmente para discapacitados.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200302, 'Playa del Río', 'Playa natural que goza de servicios de todo tipo, incluida una zona reservada especialmente para discapacitados.', 3902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1254, 'San Juan', 'Extensa playa abierta de unos siete kilómetros de arena fina y una espléndida banda arenosa localizada en una zona residencial muy concurrida en los meses estivales y muy tranquila el resto del año, que dispone de servicios en primera línea de playa.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1255, 'Tabarca', 'El carácter subtropical de las aguas invita constantemente al baño y ofrece al buceador el panorama de abundantes bancos de peces, estrellas de mar y una gran diversidad de algas que forman una increíble gama de colores.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1256, 'Puerto Viejo (Isla de Tabarca)', 'Las aguas circundantes a la isla han sido declaradas Reserva Marina del Mediterráneo, en virtud de la excelente calidad de sus aguas y la biodiversidad de su fauna y su flora, y por ser un claro ejemplo de las comunidades marinas mediterráneas escasamente alteradas.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1249, 'La Albufereta', 'Esta preciosa playa de arena oscura y aguas tranquilas se sitúa al noroeste de la capital alicantina, en una zona urbana y dispone de servicios a lo largo de la época estival. ', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1250, 'La Almadraba', 'Pequeña playa de rocas y arena oscura que presenta una alto grado de ocupación debido a sus aguas tranquilas. ', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1251, 'Cala dels Jueus', 'Las calas ubicadas en el Cabo de las Huertas se encuentran situadas en una zona residencial y tranquila, y destacan por combinar roca y arena y ser de muy reducido tamaño. Algunas de ellas son naturistas, y en la mayoría se puede practicar el buceo, sobre todo en las más rocosas.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1252, 'Cala Cantalars', 'Las calas ubicadas en el Cabo de las Huertas se encuentran situadas en una zona residencial y tranquila. Son de muy reducido tamaño. Algunas de ellas son naturistas, y en la mayoría se puede practicar el buceo, sobre todo en las más rocosas.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1245, 'Los Saladares', 'Situada en el extremo sur de Alicante, en una zona residencial tranquila, en un área de humedales de alto interés medioambiental, antiguamente lugar de explotación salinera. Permite disfrutar de baños de sol y agua sobre una extensa superficie de fina arena, lejos del bullicio urbano.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1246, 'Agua Amarga', 'Esta playa, ubicada junto al Puerto de Alicante, se extiende en más de dos kilómetros entre rocas, bolos y grava, presentando un bajo grado de ocupación.  ', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1247, 'El Postiguet', 'Playa situada en pleno casco urbano alicantino, a los pies del castillo de Santa Bárbara, que toma su nombre de un pequeño postigo de acceso a la población. Bordeada por un paseo marítimo cuajado de palmeras presenta una ancha franja de dorada arena y aguas tranquilas.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1248, 'Serragrossa', 'Playa de rocas y difícil acceso, con ausencia de arena, fuerte oleaje y sometida a fuertes vientos, que no dispone de equipamientos ni servicios.  ', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1253, 'Cala de la Palmera', 'Las calas ubicadas en el Cabo de las Huertas se encuentran situadas en una zona residencial y tranquila, y destacan por combinar roca y arena y ser de muy reducido tamaño. Algunas de ellas son naturistas, y en la mayoría se puede practicar el buceo, sobre todo en las más rocosas.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (200303, 'Playa de San Gabriel', 'Paya adjunta al Puerto de Alicante en su parte de poniente que tiene un acceso a través de una pasarela metálica por encima del trazado del ferrocarril, junto al apeadero de San Gabriel.', 3014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1275, 'Llebeig', 'Playa situada entre los términos de Benitachell y Teulada a la que únicamente puede accederse desde el mar o a pie siguiendo el curso del barranco.', 3042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1276, 'Moraig', 'Benitachell dispone de dos únicas calas, Moraig y Los Tiestos, situadas en un litoral escarpado y difícil.', 3042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1277, 'Los Tiestos', 'Benitachell dispone de dos únicas calas, Moraig y Los Tiestos, situadas en un litoral escarpado y difícil.', 3042);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1325, 'Les Ortigues', 'Las Playas del Campo y Les Ortigues, una a continuación de la otra, constituyen una amplia franja de arena dorada que permite disfrutar de grandes paseos.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1326, 'El Campo', 'Las Playas del Campo y Les Ortigues, una a continuación de la otra, constituyen una amplia franja de arena dorada que permite disfrutar de grandes paseos', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1327, 'El Moncayo', 'De las magníficas playas del litoral guardamarenco, la Playa del Moncayo y la Playa de Los Tusales, junto a la desembocadura del Segura, son un buen ejemplo de playas vírgenes de gran calidad.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1328, 'La Roqueta', 'La Playa de la Roqueta y la Playa Centro son una representación de playa cosmopolita dentro de la gran variedad de playas en esta zona costera, todas ellas perfectamente equipadas para el uso público.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1329, 'Playa Centro', 'La Playa Centro y la Playa de la Roqueta son una representación de playa cosmopolita dentro de la gran variedad de playas en esta zona costera, todas ellas perfectamente equipadas para el uso público.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1330, 'Los Viveros', 'Esta playa recibe su nombre por la cercanía a multitud de viveros localizados en la zona, objeto de diferentes cultivos que caracterizan a esta tierra. ', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1331, 'Los Tusales', 'De las magníficas playas del litoral guardamarenco, la Playa del Moncayo y la Playa de los Tusales, junto a la desembocadura del Segura, son un buen ejemplo de playas vírgenes de gran calidad.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1333, 'Babilonia', 'Esta playa tiene como característica principal que a lo largo de toda su fachada marítima se encuentran las famosas casas de babilonia, pequeños y hermosos chalets a pie de playa.', 3076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1394, 'Carritxar', 'Esta playa representa el final del límite costero perteneciente a La Vila, con más de tres kilómetros y medio de litoral costero con abundantes y atractivas playas.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1395, 'El Charco', 'Esta playa de rocas y grava alberga una torre vigía que la caracteriza tanto como los constantes vientos que soplan en ella.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1396, 'La Caleta', 'Entre la diversidad de playas de esta zona que pertenecen a La Vila, la Playa del Bon Nou, La Caleta y El Asparalló destacan por la gran transparencia de sus aguas, al pie de acantilados y de difícil acceso las dos últimas.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1397, 'El Asparalló', 'La Playa del Asparalló es un tramo de costa al pie de acantilados, de difícil acceso y de aguas transparentes.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1398, 'El Bon Nou', 'Entre la diversidad de playas de esta zona que pertenecen a La Vila, la Playa del Bon Nou, La Caleta y El Asparalló destacan por la gran transparencia de sus aguas.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1399, 'El Parais', 'La Playa del Parais, junto con la Playa Centro son las dos playas principales en los más de tres kilómetros y medio de zona costera de La Vila.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1400, 'Cala Mallaeta', 'Entre todas las playas pertenecientes a La Vila, la Cala Mallaeta se presenta como un signo de distinción frente al resto de sus playas, gozando de un espectacular litoral acantilado.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1401, 'Playa Centro', 'La Vila Joiosa disfruta de más de tres kilómetros de playas de arena y aguas tranquilas, destacándose ésta, la Playa Centro, donde se celebra el famoso desembarco moro.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1402, 'La Almadraba', 'La Almadraba es la playa más concurrida de Villajoyosa, donde puede disfrutarse de una finísima grava y condiciones excelentes de limpieza.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1403, 'Estudiantes', 'La Playa Estudiantes, junto con la Playa del Tío Roig, son las que conforman el litoral al norte de la ciudad de La Vila.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1404, 'El Tío Roig', 'La Playa del Tío Roig, junto con la Playa Estudiantes, son las que conforman el litoral al norte de la ciudad de La Vila.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1405, 'El Torres', 'Entre las numerosas playas de las que disfruta La Vila Joiosa, la del Torres tiene el atractivo añadido de ser allí donde se levanta la torre romana-funeraria de Hércules.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1406, 'Cala Fonda', 'Estas playas de la zona norte de Villajoyosa se caracterizan por sus grandes acantilados, donde las calas son de reducido tamaño y de difícil acceso, aunque de una gran belleza.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1407, 'Raco Conill', 'Estas playas de la zona norte de Villajoyosa se caracterizan por sus grandes acantilados, donde las calas son de reducido tamaño y de difícil acceso, aunque de una gran belleza.', 3139);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1409, 'Serradal', 'Playa libre de equipamientos y servicios instalados, con un bajo grado de ocupación.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1410, 'Mañetes', 'Playa de excelente características que tiene un elevado grado de ocupación.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1411, 'Tres Playas', 'Esta playa no está acondicionada para el uso público por la ausencia de servicios elementales.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1412, 'El Moro', 'Playa muy concurrida durante la época estival.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1413, 'La Romana', 'La Playa de la Romana dispone de excelentes equipamientos y servicios, incluidos accesos destinados a personas discapacitadas.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1414, 'El Carregador', 'Playa con un alto grado de ocupación gracias a la excelente calidad de sus servicios.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1415, 'Las Fuentes', 'Playa de excelente calidad, con gran cantidad de servicios y con puerto deportivo en la misma playa.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1416, 'Cala Blanca', 'Playa aislada con ausencia total de servicios.', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1417, 'Cala Mundina', 'Playa aislada sin servicios ni equipamientos disponibles', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1418, 'Ribamar', 'Playa aislada de grava y rocas, sin ningún tipo de equipamiento', 12004);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1421, 'Playa Casablanca', 'La Playa de Casablanca está localizada en el límite del término provincial de Castellón y Valencia, en una zona urbanizada.', 12011);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101201, 'Playa de la Caracola', 'Playa totalmente acondicionada para el baño, de arena gruesa y agradable firme. Se da la circunstancia que esta unida a la playa norte de Peñíscola', 12027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101202, 'Fondalet', 'Extensa playa de grava no acondicionada para el baño, aunque si apta para el mismo.', 12027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1422, 'Gururú', 'Playa de arena y grava, con carácter urbano que presenta un grado medio de ocupación durante la época de verano.', 12027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1423, 'Morrongo', 'Playa urbana totalmente acondicionada para su uso público.', 12027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1424, 'Mar Xica', 'Extensa playa de grava ubicada al norte del casco urbano de Benicarló que no goza de gran afluencia de público.', 12027);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1425, 'Playa Heliópolis', 'Playa con servicios y equipamientos de calidad.', 12028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1426, 'Els Terrers', 'Playa con servicios y equipamientos de excelente calidad', 12028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1427, 'Torre Sant Vicent', 'Playa que cuenta con servicios y equipamientos de calidad y con un elevado grado de ocupación.', 12028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1428, 'L''Almadrava', 'Playa con todo tipo de servicios disponibles y posibilidad de la práctica de cualquier tipo de deporte náutico.', 12028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1429, 'Voramar', 'Playa con excelentes equipamientos y alquileres náuticos de todo tipo.', 12028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1431, 'Torre de la Sal', 'Playa localizada en una zona residencial, apta para la práctica de todo tipo de deportes náuticos.', 12033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1432, 'Cudolá', 'Playa aislada, con ausencia de cualquier servicio.', 12033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1433, 'Cuartel Vell', 'Playa de gran extensión, de arena y grava carente de servicios y equipamientos.', 12033);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1434, 'El Pinar', 'Esta playa se encuentra ubicada junto al Puerto de Castellón, de carácter urbano, y con un alto grado de ocupación y equipamientos.', 12040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1435, 'El Gurugú', 'Playa semiurbana con una gran anchura de arena a lo largo de un kilómetro de longitud que dispone de todo tipo de servicios para su uso.', 12040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1436, 'El Serradal', 'Es una playa del término de Castellón aunque se encuentra ubicada más cerca de Benicasim, en una zona semiurbana con poca afluencia de público.', 12040);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1439, 'Playa de La Llosa', 'Playa aislada sin ningún tipo de equipamiento ni servicios esenciales para su uso público.', 12074);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1440, 'L''Estanyol', 'Esta playa semiurbana no dispone de ningún tipo de servicio ni equipamiento para el uso público', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1441, 'Beniesma', 'Playa aislada de rocas y grava sin disponibilidad de servicios.', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1442, 'Belcaire', 'Playa aislada, carente de arena y de servicios disponibles, con un bajo grado de ocupación y no apta para el baño', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1443, 'Masbo', 'La Playa de Masbo, junto con la Platja del Grau, son las más concurridas de Moncófar, ubicadas en zonas urbanas y con variedad de equipamientos', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1444, 'El Grau', 'La Platja del Grau, junto con la Playa del Masbo, son las más concurridas de Moncófar, ubicadas en zonas urbanas y con variedad de equipamientos.', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1445, 'Pedra Roja', 'Playa situada al norte de Moncófar con un alto grado de ocupación y con los servicios más elementales para su uso público.', 12077);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101208, 'Cala del Retor', 'Playa de dimensiones reducidas. Situada al norte del Puerto Deportivo', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1447, 'Platgetes de Bellver', 'Playa de carácter semiurbano, compuesta de grava y arena, con baja afluencia de público. A unas veintisiete millas se encuentra la Reserva Marina de las Islas Columbretes.', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1448, 'Renega', 'Playa de dimensiones reducidas, con ausencia total de servicios', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1449, 'Oropesa Vieja', 'Playa semiurbana.', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1450, 'La Concha', 'La Concha es la playa más concurrida de Oropesa del Mar, con todo tipo de servicios disponibles.', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1451, 'Morro de Gos', 'Playa totalmente equipada que se localiza al norte de la Punta dels Llances, en Oropesa del Mar', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1452, 'Els Ampláries', 'Playa de grava y arena que dispone de servicios y equipamientos de todo tipo, donde pueden practicarse los deportes náuticos.', 12085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101210, 'Playa del Campas', 'Playa aislada con poca afluencia y sin servicios.', 12117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1470, 'Sud de Torreblanca', 'Playa aislada.', 12117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1471, 'Torrenostra', 'Playa totalmente equipada, incluso con accesos para discapacitados.', 12117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (1472, 'Nord de Torreblanca', 'Playa con acceso adaptado para discapacitados y demás servicios públicos, ubicada en una zona urbana.', 12117);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (101211, 'Cala Puntal II', 'Playa de carácter urbano que dispone de los servicios más elementales para su uso.', 12138);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2696, 'Bellavista', 'Playa de La Manga del Mar Mediterráneo con un alto grado de urbanización, situada entre las urbanizaciones Eurovosa y Esmeralda. Ofrece arena fina y multitud de servicios.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2697, 'Tiro de Pichón', 'Playa de La Manga del Mar Mediterráneo agradable, situada entre la urbanización Esmeralda y el edificio Mónaco. Ofrece arena fina y multitud de servicios.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2698, 'El Pedrucho', 'Playa de La Manga del Mar Mediterráneo situada entre el edificio Mónaco y laurbanización Ibicencos. Amplia y de fina arena, es idónea para pasear. Cuenta además con buenos equipamientos.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2699, 'El Arena Pedrucho', 'Playa  del Mar Mediterráneo muy urbanizada y con un alto grado de ocupación, entre la urbanización Ibicencos y Puerto Cálido. Ambiente familiar.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2700, 'Estacio', 'Playa de La Manga del Mar Mediterráneo tranquila, de arena dorada, caracterizada por un paisaje de pequeñas dunas, que la diferencia del resto de playas de la zona.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2704, 'La Hita', 'Playa del Mar Menor pequeña y tranquila playa, situada dentro de un enclave declarado Espacio Natural Protegido. Ofrece aguas tranquilas y una agradable arena dorada. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2705, 'Barnuevo', 'Playa del Mar Menor que a pesar de su reducido tamaño ofrece un alto grado de ocupación, probablemente debido al elevado número de equipamientos que ofrece. Posibilidad de realizar diferentes deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2706, 'El Pescador', 'Playa del Mar Menor que a pesar de su reducido tamaño presenta un alto grado de ocupación, probablemente debido al elevado número de equipamientos que presenta. Ofrece la posibilidad de realizar diversos deportes náuticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2707, 'Colón', 'Agradable playa del Mar Menor flanqueada por palmeras que ofrece aguas limpias y tranquilas y una fina arena oscura, ideal para pasear. Ofrece la posibilidad de realizar deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2708, 'Castillico', 'Agradable playa del Mar Menor flanqueada por palmeras que ofrece aguas limpias y tranquilas y fina arena oscura. Ofrece la posibilidad de realizar deportes acuáticos. Pendiente suave y aguas cálidas', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203004, 'Hacienda dos Mares', 'Playa de La Manga del Mar Menor, tranquila, de ambiente familiar, pendiente suave y aguas cálidas. Con posibilidad de practicar en ella deportes acuáticos.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (303001, 'El Pedruchillo', 'Playa urbana ubicada en el Mar Menor, de aguas tranquilas y encastrada, por el norte, en un saliente rocoso urbanizado que le da abrigo a los vientos del norte, adquiriendo, hacia el sur, una configuración lineal paralela a la Gran Vía de La Manga.', 30035);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2668, 'La LLana', 'Esta playa se encuentra en la zona en la que se unen el Mar Menor y el Mar Mediterráneo. Cerca de ella se encuentran las salinas del Parque Regional Salinas y Arenales de San Pedro del Pinatar.', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2669, 'La Barraca Quemada', 'Esta playa se encuentra en la zona en la que se unen el Mar Menor y el Mar Mediterráneo. Cerca de ella se encuentran las salinas del Parque Regional Salinas y Arenales de San Pedro del Pinatar', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2670, 'La Playuela', 'Playa situada en las inmediaciones del Puerto de San Pedro del Pinatar. Dispone de escasos equipamientos.', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2671, 'Torre Derribada', 'Playa aislada y amplia, de fina arena, situada junto al Puerto de San Pedro del Pinatar.', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2672, 'El Mojón', 'Playa urbana de pequeño tamaño que presenta un nivel medio de equipamientos. En sus inmediaciones se práctica la pesca típica de la zona.', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2673, 'La Puntica', 'Playa del Mar Menor de pequeño tamaño. Cuenta con gran cantidad de equipamientos, y la posibilidad de realizar diversos deportes: vela, wind-surf, etc. Pendiente suave y aguas cálidas', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2674, 'Villananitos', 'Playa del Mar Menor que dispone de todo tipo de servicios y la posibilidad de realizar diferentes deportes: vela, wind-surf, etc., pendiente suave y aguas cálidas', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2675, 'La Mota / los Molinos', 'Playa del Mar Menor extensa y rectilínea. Se encuentra enclavada en el Espacio Natural Protegido de las Salinas del Cotorrillo, explotación heredada de los romanos, pendiente suave y aguas cálidas', 30036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203001, 'Portmán', 'Los primeros 5-10 metros de la playa son de arena, el resto se encuentra muy degrado, con arena compactada y restos estériles, en proceso de regeneración. Carrizales, arbustos, cañas, charcos,?.', 30041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203002, 'Lastre', 'Playa con mucha afluencia estable, con servicios', 30041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (203003, 'Cala del Caballo', 'Playa aislada, con escasa afluencia de público, con acceso por sendero desde Ctra. La Unión - Portmán', 30041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2750, 'Gachero', 'Playa con un bajo grado de ocupación compuesta por bolos, que disfruta de aguas cristalinas.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2751, 'El Alamillo', 'Esta playa no goza de la tranquilidad deseada debido a la cercana carretera que la rodea. Presenta un grado medio de ocupación.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2752, 'Negra', 'Aislada y atractiva playa. Se encuentra rodeada de montañas y palmeras, que configuran un paisaje de interés. Nivel bajo de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2723, 'Parazuelos', 'Playa formada por arena y bolos, aislada y  con escasa afluencia de público. No ofrece ningún equipamiento.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2724, 'El Palomarico', 'Playa resguardada por las rocas que la rodean. No ofrece al visitante ningún tipo de servicio.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2725, 'Minas', 'Playa que ofrece una arena fina de calidad. Está situada en un entorno muy agradable y se disfruta en ella de una gran tranquilidad.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2726, 'Percheles', 'Agradable playa rodeada de palmeras y con un arena de calidad. A pesar de estar aislada presenta una alta afluencia de público.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2727, 'Ballenato', 'Playa de reducidas dimensiones compuesta por arena, grava y bolos. No ofrece equipamientos de ningún tipo.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2728, 'Las Chapas', 'Playa aislada y con un bajo grado de ocupación, quizá debido a que su superficie está compuesta por bolos, lo que la hace un tanto incómoda. Sin equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2729, 'Las Covaticas', 'Playa aislada y con un bajo grado de ocupación. Está compuesta por bolos y arena, lo que la hace un tanto incómoda. No dispone de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2730, 'Cabezo de la Pelea', 'Playa grande,compuesta por arena y bolos y que presenta un oleaje moderado. No disfruta de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2731, 'Playa del Jondón', 'Playa aislada que presenta una composición de bolos, lo que hace que resulte un tanto incómoda. No ofrece equipamientos. Compuesta por grava y arena. Zona acantilada', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2732, 'Cala Leño', 'Cala pequeña y aislada compuesta por arena y bolos y enclavada dentro de un Espacio Natural Protegido. No posee equipamiento alguno.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2733, 'Barranco Ancho', 'Playa tranquila que presenta un bajo grado de ocupación. No ofrece equipamiento alguno.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2734, 'Cala Desnuda', 'Pequeña cala con escasa afluencia de público enclavada en un Paisaje Protegido. Sin equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2735, 'La Grúa', 'Playa que disfruta de un ambiente tranquilo dentro de un Espacio Protegido. No ofrece equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2736, 'Playa de La Puñeta', 'Playa que disfruta de un ambiente tranquilo dentro de un Espacio Protegido. No ofrece equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2737, 'Cueva de los Lobos', 'Playa que disfruta de un ambiente tranquilo dentro de un Espacio Protegido. No ofrece equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2738, 'Piedra Mala', 'Playa urbanizada de pequeño tamaño que presenta un grado medio de ocupación. No ofrece ningún servicio.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2739, 'El Rincón', 'Playa tranquila que ofrece aguas limpias y tranquilas, y una arena de calidad. No dispone de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2740, 'Bolnuevo', 'Extensa playa urbana de arena dorada y gran afluencia de público. Está dotada con un buen número de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2741, 'El Castellar', 'Playa con más de un kilómetro de longitud, compuesta por arena y grava, y bien equipada. Muestra gran afluencia de público.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2742, 'Nares', 'Playa muy agradable, de pequeño tamaño, con un alto nivel de ocupación y un nivel medio de servicios. Ofrece un paisaje de interés.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2743, 'La Pava', 'Playa de reducidas dimensiones, urbanizada y de ambiente familiar. Ofrece un buen nivel de servicios. Mirador Cabezo del Gavilán', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2744, 'Junta de Los Mares', 'Playa urbana con gran afluencia de público y dotada con un buen número de servicios.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2745, 'Bahía', 'Playa situada junto al Club Náutico de Mazarrón. Disfruta de aguas tranquilas y ofrece la posibilidad de realizar en ella diversos deportes acuáticos. Mirador Cabezo de la Cebada', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2746, 'La Ermita', 'Playa muy pequeña,de arena dorada, con una alta afluencia de público. Ofrece un buen nivel de equipamientos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2747, 'La Isla', 'Pequeña playa urbana de fina arena dorada. Presenta un buen nivel de servicios y disfruta de interesantes fondos marinos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2748, 'Puerto de Mazarrón', 'Playa urbana con un alto grado de ocupación. Presenta un buen nivel de equipamientos. Se pueden practicar en ella varios deportes acuáticos.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2749, 'El Rihuete', 'Playa urbana que cuenta con un agradable paseo marítimo flanqueado por palmeras. Está bien equipada.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2753, 'La Raja', 'Es una playa aislada compuesta por grava y bolos, que ofrece un bajo nivel de servicios.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2754, 'El Mojón', 'Playa aislada, con un grado medio de ocupación, compuesta por gravas y arena. No ofrece apenas servicios.', 30026);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2676, 'La Concha', 'Playa del Mar Menor muy agradable, de arena fina y aguas transparentes. Ofrece gran cantidad de servicios, incluido un Club Náutico. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2677, 'Carrión', 'Playa del Mar Menor, urbana con ambiente familiar. Ofrece unas aguas limpias y tranquilas. Pendiente suave y aguas cálidas.', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2678, 'Manzanares', 'Playa del Mar Menor, con un alto grado de ocupación. Aguas tranquilas y limpias. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2679, 'El Espejo', 'Playa del Mar Menor de fina arena que además cuenta con gran cantidad de servicios, lo que la convierte en una excelente opción. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2691, 'Las Palmeras', 'Playa del Mar Menor agradable, flanqueada por un paseo de palmeras, lo que la hace muy atractiva. Existe la posibilidad de realizar gran variedad de deportes. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2692, 'Los Narejos', 'Bonita playa del Mar Menor rodeada de palmeras. Disfruta de aguas limpias, muy recomendables para la práctica de los diferentes deportes acuáticos. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2693, 'Las Salinas', 'Playa del Mar Menor extensa y rectilínea. De arena fina, ofrece la posibilidad de realizar gran variedad de deportes. Pendiente suave y aguas cálidas', 30902);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2577, 'Hondarribia', 'Playa situada al Sudeste del cabo de Higer y al Noroeste de la desembocadura de la ría del Bidasoa, favoreciendo su formación un espigón que discurre lateralmente de Norte a Sur.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2578, 'Los Frailes', 'Pequeña playa de roca y canto rodado, situada en la ribera Este del cabo de Higer. Se practica submarinismo.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202001, 'Kapelaundi', 'Pequeña playa de cantos rodados y rocas, situada en la ladera del monte Jaizkibel, al Oeste del cabo Higer. Está constituida por dos pequeñas calas separadas por una roca.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202004, 'Sisurko', 'Pequeña playa de cantos rodados y rocas, situada al Oeste del cabo Higer en la ladera del monte Jaizkibel.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202005, 'Eretzin Zabala', 'Playa rocosa. Sus formaciones se asemejan a balones, verrugas y a focas petrificadas que descansan en sus losas en espera de la llegada del agua marina.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202002, 'Errota Sein', 'Pequeña playa de cantos rodados y rocas, situada en la ladera del monte Jaizkibel, al Oeste del cabo Higer.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202003, 'Artzuportu', 'Pequeña playa de cantos rodados y roca, situada en la ladera del monte Jaizkibel, al Oeste del cabo Higer, en la que se practica submarinismo.', 20036);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2587, 'Malkorbe', 'Playa situada al Sudeste del monte de San Antón, entre las puntas de Mazoparria y Altzoko-Arria. ', 20039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2588, 'Gaztetape', 'Playa situada al Suroeste del monte de San Antón, con buenas condiciones para la práctica del surf.', 20039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2589, 'Orruaga', 'Playa de cantos rodados, muy próxima a la carretera existente entre Getaria y Zumaia, con buenas condiciones para la práctica de surf.', 20039);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2599, 'Ondar-Beltz', 'Playa de arena situada en la desembocadura de la ría del Deba (margen izquierda), entre el espigón existente y la punta de Arrilaban.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2600, 'Alkolea', 'Situada entre la punta de Alkolea y la explanada de Arbe.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2601, 'Mutriku', 'Playa de arena situada al Norte del puerto de Mutriku, cuya configuración ha variado tras la realización de las obras de mejora del acceso marítimo al puerto de Mutriku.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2602, 'Burumendi', 'Playa situada entre la playa de Mutriku (playa del Pueblo) y la punta de Kardala.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2603, 'Siete Playas', 'Sucesión de playas situadas entre la punta de Kardala y la playa de Saturrarán, en un entorno predominantemente natural.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2604, 'Saturrarán', 'Playa de arena situada entre la regata de Mijoa y la punta de Saturrarán. Muy próxima al límite divisorio entre las provincias de Gipuzkoa y Bizkaia.', 20056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2584, 'Antilla', 'Playa de arena situada al Este de la desembocadura de la ría de Oria.', 20061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2585, 'Oribar-Zahar', 'Pequeña playa situada en la margen izquierda de la ría de Oria.', 20061);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2579, 'La Zurriola', 'Playa situada al Este de la desembocadura de la ría del Urumea y cercana a la punta de Monpas. Es habitual en ella la práctica del surf.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2580, 'La Concha', 'Playa situada en la Bahía de la Concha, entre el puerto pesquero de San Sebastián y el pico del Loro, que la separa de la playa de Ondarreta.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2581, 'Playa de la Isla', 'Pequeña playa situada en la isla de Santa Clara, en la bahía de la Concha.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2582, 'Ondarreta', 'Playa situada en la bahía de la Concha, entre el pico del Loro y el Peine del Viento.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2583, 'Agiti', 'Playa de cantos rodados situada en la falda del monte Igeldo, entre Munto-Aundi y Albitxulo.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202007, 'Murgita', 'Playa de rocas y cantos rodados situada en la ladera del monte Ulia, al Este del faro de la Plata.', 20069);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2586, 'Zarautz', 'Extensa playa de arena situada entre la desembocadura de la regata de Iñurritza o San Pelayo y la punta de Iteico, próxima a la carretera de comunicación entre Zarautz y Getaria. En su zona oriental existe una duna. Cuenta con condiciones óptimas para la práctica del surf.', 20079);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2590, 'Santiago', 'Playa de arena situada al Este de la desembocadura de la ría del Urola. Pertenece a los términos municipales de Getaria y Zumaia.', 20081);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2591, 'Itzurun', 'Playa de arena situada entre las puntas de Marianton y Algorri. Desde un punto de vista geológico constituye un marco único para el estudio de la geometría de sus estratos y sus estructuras sedimentarias (flysch). Son espectaculares sus acantilados.', 20081);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2592, 'Algorri', 'Playa de piedra formada en bajamar a continuación de la playa de Itzurun, en la ladera Este del monte de San Telmo. Llaman la atención sus acantilados y rasa mareal.', 20081);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2594, 'Aitzuri', 'Pequeña playa de piedra procedente del desgaste erosivo de los acantilados por el impacto de las olas. Situada entre las puntas de Sakoneta y Arantzako Portua. Llaman la atención sus acantilados y rasa mareal.', 20081);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202008, 'Inpernupe', 'Pequeña playa de rocas y cantos rodados situada en la ladera del monte, al Este de la playa de Itzurun, en el núcleo urbano de Zumaia.', 20081);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2593, 'Sakoneta', 'Pequeña playa de piedra procedente del desgaste erosivo de los acantilados por el impacto de las olas. Situada en la ladera del monte, entre las puntas de Sakoneta y Arantzako Portua. Son espectaculares sus acantilados y rasa mareal.', 20029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2595, 'Mendata', 'Pequeña playa de piedra procedente del desgaste erosivo de los acantilados por el impacto de las olas. Situada en la ladera del monte, entre Punta Mendata y Sonda-Beltza. Son espectaculares sus acantilados y rasa mareal.', 20029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2596, 'Itxaspe', 'Estrecha playa de canto rodado y piedra procedente del proceso de remoción del fenómeno de inestabilidad de los acantilados. Situada al Oeste de la punta de Aitzuri. Llaman la atención sus acantilados y rasa mareal.', 20029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2597, 'Lapari', 'Playa de arena situada a continuación de la playa de Deba.', 20029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2598, 'Deba', 'Playa de arena situada al Este de la desembocadura de la ría de Deba, entre el espigón de la margen derecha de la ría y la punta de Aitzgorri.', 20029);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (202006, 'Azabaratza', 'Pequeña playa de cantos rodados y rocas, situada al Oeste del cabo Higer. El uso de la ribera se compatibiliza con la recogida de algas.', 20064);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2615, 'Bakio', 'Playa urbana, que presenta un alto grado de ocupación. Dispone de un agradable paseo marítimo.', 48012);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2610, 'Barrika', 'Playa aislada a la que se accede bajando unas largas escalerillas. Está compuesta por rocas. Debido a la inestabilidad de los acantilados que la rodean, no se recomienda la estancia en la playa seca, aunque es apta para los deportes marinos de surf, buceo, etc.', 48014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2611, 'Muriola ', 'Playa pequeña y bien protegida, que fue generada artificialmente por la arena silícea de una cantera cercana.', 48014);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2617, 'Aritxatxu', 'Playa de reducidas dimensiones, muy protegida por las grandes rocas que la rodean. Se encuentra situada dentro de la Reserva de la Biosfera de Urdaibai.', 48017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2616, 'Arribolas', 'Playa perteneciente a Urdabai, Espacio Natural declarado Reserva de la Biosfera, en 1984. Es una playa aislada, de fuerte oleaje, compuesta por bolos. Frecuentada por pescadores.', 48017);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2629, 'Arrigorri', 'Playa urbana colindante con el puerto pesquero, que presenta una alta afluencia de público. Ofrece un buen nivel de equipamientos y la posibilidad de realizar en ella diversos deportes acuáticos.', 48018);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2624, 'Lapatza ', 'Playa de pequeño tamaño compuesta por bolos y rocas. Presenta fuerte oleaje, escasa afluencia de público y no dispone de equipamientos.', 48028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2625, 'Ea', 'Playa urbana en la desembocadura de la Ría del Municipio. Muy abrigada. Ofrece fina arena.', 48028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2631, 'Bedarona ', 'Playa aislada, compuesta por bolos y rocas, que presenta un bajo grado de ocupación. Es habitual en ella la práctica del surf. No ofrece ningún tipo de equipamiento.', 48028);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2619, 'Kanalape', 'Playa de pequeño tamaño, aislada. Pertenece al Espacio Natural de Urdaibai, declarado en 1984 Reserva de la Biosfera.', 48041);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204801, 'Las Arenas', 'Pequeño arenal ubicado en entorno urbano, cuenta con un club marítimo de gran tradición y numerosos servicios hoteleros', 48044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2607, 'Barinatxe ', 'Playa aislada y enclavada en un atractivo entorno montañoso. Disfruta de una arena fina dorada, y es muy frecuentada por surfistas.', 48044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2606, 'Gorrondatxe ', 'Playa enclavada en un entorno natural atractivo, con amplio fondo, compuesta por arena y rocas. Es frecuentada por surfistas.', 48044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204802, 'Ereaga', 'Este arenal está muy bien equipado de cara a la época estival. Son muchos los deportes que se practican en esta playa: surf, voleibol y vela.', 48044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (204803, 'Arrigunaga', 'Ubicada bajo los acantilados de La Galea, ofrece hermosas vistas al Abra y al Molino de Aixerrota.', 48044);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2622, 'Laida', 'Playa extensa, que presenta una gran afluencia de público. Ofrece un buen nivel de equipamientos, y la posibilidad de realizar diversos deportes acuáticos. Pertenece a la Reserva de la Biosfera de Urdaibai.', 48048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2623, 'Laga', 'Playa aislada, que presenta una alta afluencia de público, pero a pesar de esto goza de una cierta tranquilidad. Está enclavada dentro de la Reserva de la Biosfera de Urdaibai.', 48048);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2626, 'Ogeia ', 'Playa aislada, compuesta por bolos. Es habitual en ella la práctica del surf. ', 48049);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2614, 'Armintza ', 'Pequeña playa rocosa, que presenta una escasa afluencia de público, en su mayoría está compuesto por submarinistas atraídos por sus interesantes fondos marinos.', 48056);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2628, 'Karraspio', 'Playa de arena fina, que presenta una alta afluencia de público. Ofrece un buen nivel de equipamientos. ', 48063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2630, 'Karraspio Txiki ', 'Playa situada en la margen derecha de la desembocadura del Lea. Presenta un bajo nivel de ocupación y dispone de paseo marítimo. Poco equipada.', 48063);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2618, 'Laidatxu', 'Playa situada en la margen izquierda de la ría, y perteneciente a la Reserva de la Biosfera de Urdaibai. Disfruta de arena fina dorada y de aguas tranquilas.', 48068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (104801, 'Ondartzape', 'Playa situada en la margen izquierda de la ría y perteneciente a la Reserva de la Biosfera de Urdaibai. La principal característica de esta playa son sus rocas y su arena oscura, formando en bajamar una pequeña cala. En pleamar prácticamente desaparece.', 48068);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2620, 'Toña', 'Pequeña playa perteneciente a la Reserva de la Biosfera de Urdaibai. Presenta un alto grado de ocupación.', 48076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2621, 'San Antonio ', 'Playa situada en la margen izquierda de la ría, dentro de la Reserva de la Biosfera de Urdaibai. Ofrece arena fina, aguas tranquilas y un pequeño paseo marítimo.', 48076);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2608, 'Arrietara- Atxabiribil', 'Playa semiurbana, de fina arena dorada. Presenta un alto grado de ocupación y es muy frecuentada por surfistas, ya que es una de las playas de la Comunidad Autónoma del País Vasco más adecuada para la práctica de este deporte.', 48085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2609, 'Meñakoz', 'Pequeña playa compuesta por gravas y bolos. No ofrece ningún tipo de equipamiento, pero a cambio permite disfrutar de un entorno tranquilo.', 48085);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2605, 'La Arena ', 'Playa semiurbana, de arena oscura, que presenta un alto grado de ocupación. Está dotada con muchos equipamientos: baños, duchas, teléfonos.', 48913);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2613, 'Gorliz', 'Playa semiurbana que presenta un alto grado de ocupación. Presenta un buen nivel de servicios: duchas, aseos, y ofrece la posibilidad de realizar en ella diferentes deportes acuáticos.', 48043);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2627, 'Isuntza', 'Playa colindante con el puerto de Lekeitio, que presenta gran afluencia de público. Ofrece fina arena, aguas tranquilas, y un buen nivel de equipamientos.', 48057);
INSERT INTO PLAYA (ID, NOMBRE, DESCRIPCION, MUNICIPIO) VALUES (2612, 'Plentzia', 'Playa enclavada en la desembocadura de la ría. Presenta un alto nivel de ocupación. Ofrece una arena fina dorada.', 48077);
